UPDATE `broadcast_text_locale` SET `Text_lang` = '有了你的帮助，我就可以测量这些通道了。' WHERE `Id` = 4050 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让我们看看能否发现这些穴居人是从哪里来的……然后想办法阻止他们！' WHERE `Id` = 4051 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '太混乱了……简直一团糟……' WHERE `Id` = 4052 AND `Locale` = 'zhCN';
