UPDATE `broadcast_text_locale` SET `Text_lang` = '……太安静了。' WHERE `Id` = 4130 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看！在隧道那边！' WHERE `Id` = 4131 AND `Locale` = 'zhCN';
