UPDATE `broadcast_text_locale` SET `Text_lang` = '干得漂亮！我会组织人手发动进攻，以防止更多穴居人到达地表。' WHERE `Id` = 4329 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '异教徒！' WHERE `Id` = 4380 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你敢打断我们的祈祷？处决他们！' WHERE `Id` = 4381 AND `Locale` = 'zhCN';
