UPDATE `broadcast_text_locale` SET `Text_lang` = '<普瑞斯托女士怒视着你。>' WHERE `Id` = 4990 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我就站在你旁边，笨蛋。我知道你在找什么。' WHERE `Id` = 4992 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是说为了满足一个妄想狂的地方官和一群没准正在遭受中暑之苦的乌合之众的愿望，我们就得把世界各地的部队都调回来，然后给他派过去吗？' WHERE `Id` = 4994 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然不是，亲爱的$g小伙子:姑娘;。你这种“冒险者”类型的$c经常成为政治的牺牲品，被政治家玩弄于股掌之间而毫无察觉。$B$B我给你的建议，就是去做一些更加具体的事情：找份新工作。$B$B这个世界已经有太多的英雄了。' WHERE `Id` = 4996 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨，罗克诺特！' WHERE `Id` = 5000 AND `Locale` = 'zhCN';
