UPDATE `broadcast_text_locale` SET `Text_lang` = '你为何来此，$c？' WHERE `Id` = 8370 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的人民，他们就像你试图修复的遗物一样支离破碎。' WHERE `Id` = 8371 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '虽说没有东西可以改变过去，时间可以治愈所有伤口。谢谢你让我看到那是可能的，$n。我祝你顺利。' WHERE `Id` = 8372 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就位！' WHERE `Id` = 8395 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了伟大的母亲！' WHERE `Id` = 8396 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '暗夜的战士……集合！' WHERE `Id` = 8397 AND `Locale` = 'zhCN';
