UPDATE `broadcast_text_locale` SET `Text_lang` = '愿月神与你同在，$c。月亮神殿已经来帮助奥伯丁饱受煎熬的公民了。' WHERE `Id` = 8503 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们这些渣滓居然想要挑战我？你们会为你们的傲慢付出代价的！' WHERE `Id` = 8570 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '掩护我，士兵！我必须返回基地并让空军做好战斗准备！' WHERE `Id` = 8604 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈哈！成功了！' WHERE `Id` = 8605 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别浪费时间，士兵。我必须马上返回基地！掩护我！' WHERE `Id` = 8606 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '赶快！' WHERE `Id` = 8607 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '霜狼的战士们，来帮助我！是时候让他们感受元素的狂怒了！' WHERE `Id` = 8613 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s临死时发出的哀嚎惊动了附近的异种蝎巢穴！' WHERE `Id` = 8620 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们敌人的鲜血会洒落疆场的。伟大的元素会回应我们的呼唤并碾碎所有阻挡我们前进的东西。' WHERE `Id` = 8621 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s发出咯咯的笑声。' WHERE `Id` = 8622 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '冰雪之王会吞噬整个的联盟军队！' WHERE `Id` = 8623 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当血深入雪地时仔细看着，孩子。元素会附到我们身上的！' WHERE `Id` = 8625 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '结束了！冰雪之王来了！向部落的力量敬礼，蠢货！' WHERE `Id` = 8626 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '把你的能量引导到祭坛里！' WHERE `Id` = 8632 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得好，士兵。我需要回到大本营！你愿意掩护我吗？' WHERE `Id` = 8635 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你来的真是时候。怎么耽搁了这么久？啊，没关系。掩护我，士兵。我必须返回基地！' WHERE `Id` = 8637 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你不属于这些花园。你的肉身将会滋养我们美丽的作品！' WHERE `Id` = 8639 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '花园绝不能被弄脏！你死定了！' WHERE `Id` = 8640 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '还有很多工作要做，$n！继续消灭我们的敌人！' WHERE `Id` = 8642 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的，$n。元素很活跃。很快，我们就会将他们的能量释放到我们的敌人身上。他们会被彻底击垮的！' WHERE `Id` = 8644 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我已经做过接触了，$n。那是冰雪之王洛克霍拉。他认为我们的事业很有价值--我们给大地的祭品十分充足。他很快就来了……做好准备。' WHERE `Id` = 8646 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '绝不要直视指挥官的眼睛。' WHERE `Id` = 8654 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们直接受命于凯恩，$r。不要干预指挥官的工作。' WHERE `Id` = 8655 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '萨满指挥官可不能小瞧，$r。' WHERE `Id` = 8656 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很快，洛克霍拉就会出现……很快……非常，非常快……' WHERE `Id` = 8657 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '空军部队整装待发，$n。你必须带上火炬，把它放在战场中心的东部环形山中。在空军部队进行定位时，你必须好好保护火炬！' WHERE `Id` = 8659 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '舰队整装待命，$n。你必须带着这个信号灯并把它放置在中央战区西部的凹地里。保护信号灯不被攻击，直到舰队能够锁定它的坐标！' WHERE `Id` = 8668 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '战马现在准备好了！部落的战士们，我需要你们的帮助。' WHERE `Id` = 8673 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '杰斯托的骑士准备好了！部落的战士们，汇报你们的工作！' WHERE `Id` = 8674 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这片土地被污染了。必须召唤伊弗斯。' WHERE `Id` = 8731 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '卡尔·雷矛的战士，帮助并保护我们！森林之王已经许诺要保护我们。大门现在必须被打开了！' WHERE `Id` = 8732 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来，兄弟。' WHERE `Id` = 8733 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '前进！' WHERE `Id` = 8734 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果森林之王要来，我们必须集中思想于召唤法阵！我们需要赶紧！集中精力！' WHERE `Id` = 8735 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的信念指引着我的行动，$r。我知道伊弗斯会来的。' WHERE `Id` = 8750 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我迷失在梦里了。我感觉到了他的生命力，但是我的力量还不够强大，无法进行沟通。' WHERE `Id` = 8758 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的。$n。我已经查到了森林之王的位置。我们必须加倍努力！需要更多的水晶！' WHERE `Id` = 8760 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '森林之王已经知晓了这个山谷的毁灭，$n。很快我们就要到召唤法阵去了。做好准备！' WHERE `Id` = 8762 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我在此有命令从中场进攻联盟军队。我需要有人把它们带到攻击指挥那里。' WHERE `Id` = 8774 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们在奥特兰克山谷发动的战斗冷酷而血腥。太完美了。' WHERE `Id` = 8775 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这片森林容易使人迷路！要小心。' WHERE `Id` = 8777 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '士兵，你好。你是来帮我的吗？' WHERE `Id` = 8859 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '士兵，做得好。我们的马厩将塞满骑兵们的战斗坐骑！' WHERE `Id` = 8860 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我可没法教你战斗时如何保持优雅姿态，我只能教你如何使用武器。' WHERE `Id` = 8879 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我可以告诉你该找谁进行训练。你对哪类武器感兴趣？' WHERE `Id` = 8880 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨！你是来这儿学习新武器的吗？' WHERE `Id` = 8883 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你想要学习哪种武器？' WHERE `Id` = 8884 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们需要更多的狼！去马厩需求帮助吧！' WHERE `Id` = 8885 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '做得好，部落！马厩中有足够的霜狼可供我们的狼骑兵乘坐！' WHERE `Id` = 8886 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '马厩又满啦！我们的骑兵很快就可以乘坐啦！' WHERE `Id` = 8899 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '马厩是空的！我们必须为骑兵提供充足的坐骑。卡尔·雷矛马厩需要你的帮助！' WHERE `Id` = 8900 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '奥特兰克本地出产的山羊对我们的骑兵至关重要！' WHERE `Id` = 8909 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再有一些坐骑我们的马厩就满啦。士兵，让我来保管它们吧。我会从这儿牵走一些。' WHERE `Id` = 8910 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我和我的姐妹从石爪山脉来到这儿，想要终止数年来的悲剧。不幸的是，我们还不够强大，无法独立完成目标，想向你这样的人寻求帮助。$B$B如果你足够强大，我们就谈谈任务的详细情况，$c。如果你还不够强大，那么，为了你的安全着想，就到此为止吧。' WHERE `Id` = 8919 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，请看看我从洞穴中取出的维雷斯塔姆藤蔓的样本，这样你就知道自己要找什么了……' WHERE `Id` = 8920 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨，$n！很高兴你来看我。我们正准备对征战平原发动一场规模浩大的地面攻击！等到霜狼突击队队长一声令下，他和他的部队将给予联盟致命的攻击！$B$B你想传达这些命令吗，$n？加瑞克在征战平原等着你呢……' WHERE `Id` = 8987 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你怎么在这儿，$n？你怎么到这儿来啦？$B$B你不是带着攻击指令吗——征战平原的霜狼突击队队长还在等着发动进攻呢！去吧！' WHERE `Id` = 8988 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '能在奥特兰克山谷找到你这样经验丰富的家伙真好，$n。我们的军需不够，无法发动对奥特兰克山谷的地面攻击……跟我们的军需官谈谈——他会告诉你如何增加我们的军需储备。' WHERE `Id` = 8989 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨，$c！我们的军需已经增加，现在可以对征战平原发送地面攻击啦。要是你的声望再高一点，我一定会派你传达攻击命令的。$B$B去吧，为了联盟而战！证明你是一名值得信赖的、有能力的部落成员！' WHERE `Id` = 8990 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你！$n！你在山谷这儿游荡什么呢？在奥特兰克到处都是联盟的敌人！我们必须赶走它们！$B$B我们的军需不够，无法发动大规模的地面攻击,跟我们的军需官谈谈.他会告诉你如何增加我们的军需。' WHERE `Id` = 8991 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在面对强大的敌人时，即使是最勇敢的士兵也必须拥有充足的装备！' WHERE `Id` = 8993 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你向蓝龙要求什么？' WHERE `Id` = 9015 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我对这片森林非常熟悉，它们就像我身体的一部分……但是它们还蕴藏着很多值得学习的知识，当然也有很多危险。' WHERE `Id` = 9024 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的，我曾盼望你能回来。早些时候，我派科兰出去，她发现了达图尔的魔棒被遗弃在森林里。$B$B我们竭力想要找回它，$n。请你小心以后不要掉了它。' WHERE `Id` = 9026 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你已经完成了泰洛尼斯的任务，感谢你所做的一切，$n。' WHERE `Id` = 9027 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好！这间工场不是我的，不是！但是终有一天当我完成训练后，我将成为一名发明家，就像我崇拜的英雄玛尔冯·瑞文斯克那样。$B$B你从来没有听说过他吗？哦，碰巧他已经离开好长一段日子啦，他去研究远古巨魔废墟啦，他是乘坐地精飞艇走的……我也不是很清楚他究竟去了哪儿……$B$B塔纳拉辛？坦克利斯？塔纳里萨尼？$B$B<莉芙摇着头。>$B$B不，名字不是这样……' WHERE `Id` = 9028 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨。不，玛尔冯一定不在这儿，他还要好些时间才能回来呢。实际上，我有些担心他……$B$B我希望他能很快回来。有人寄了一只大箱子给他，我可没力气把这东西拖进去！我只能把它放在门口……' WHERE `Id` = 9029 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这地方……受到了诅咒。$B$B我刚刚设法逃脱，我可不想再进入那些地道啦。$B$B但是，我的兄弟姐妹……就没这么幸运了。他们被困在里面，恶魔花园散发的堕落烟雾令他们疯狂。$B$B你一定要帮帮他们。' WHERE `Id` = 9032 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，很高兴你已经回来啦，$n。$B$B我兄弟的灵魂已经从堕落中解脱啦，但是我得留在此地表示我的哀悼。$B$B非常感谢你的帮助，$n。' WHERE `Id` = 9033 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '需要物资供给吗？' WHERE `Id` = 9036 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这都是我说的闲话。' WHERE `Id` = 9142 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这都是我说的闲话。' WHERE `Id` = 9143 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个东西正在起作用。' WHERE `Id` = 9370 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '陌生人，离开这儿吧，免得送命，它会吃掉它接触到的一切东西的。' WHERE `Id` = 9379 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你知道上层精灵吗？你知道辛德拉古吗？' WHERE `Id` = 9381 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '辛德拉古是艾萨拉女王最器重的奥术学家。女王最重要的物品都在这些高大的城墙内秘密制造完成。$B$B永恒之井被破坏后，上层精灵陷入浑浑噩噩的境地，一支较小的暗夜精灵氏族，埃雷萨拉斯的王子托塞德林开始建造水晶塔，你可以在西侧的城墙那儿看到那些分散在各处的水晶塔。' WHERE `Id` = 9383 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '王子策划将拥有巨大力量的恶魔伊莫塔尔禁锢到一个巨大的力场中。水晶塔能将潜在的能量汇集到这个力场中。$B$B一旦被囚禁，恶魔将成为埃雷萨拉斯人民的能量来源。' WHERE `Id` = 9384 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '汲取的能量能维持上层精神的魔力，使埃雷萨拉斯的人民满足他们对魔法无尽而持续增长的渴求。$B$B数千年过去了，用于监禁恶魔伊莫塔尔以及维系埃雷萨拉斯人民生命的力量开始减弱。监禁恶魔所需的魔法就要超过所能汲取的魔法。曾经的能量机制已经不复存在。' WHERE `Id` = 9387 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你所见到的那些在埃雷萨拉斯的庭院和城墙附近游荡的上层精灵灵魂不是被戈多克食人魔或萨特所杀，而是死于王子之手！' WHERE `Id` = 9389 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '王子为了获得永恒的生命和无尽的力量，杀死了许多人。数千人的力量全部汇集到王子和辛德拉狂热者身上。那些少数的幸存者不停地向水晶塔输送能量来禁锢恶魔伊莫塔尔。$B$B如果恶魔挣脱束缚，它一定会毁掉这座曾经繁荣辉煌的魔法都市。' WHERE `Id` = 9391 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些是指令，$n。请迅速将它们交给霜狼突击队队长!' WHERE `Id` = 9428 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一旦我们拥有丰富的物资供给，霜狼突击队队长就会驻守在冰血要塞以北的征战平原，就在攻城机旁边。' WHERE `Id` = 9435 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '霜狼军需官就在这个工事的东面。进入碉堡，从右边的出口出去，不远处你就可以看到军需官。' WHERE `Id` = 9439 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，真恐怖！这是个悲剧！我们就要突破啦，但也有可能遭遇全军覆灭的惨剧。' WHERE `Id` = 9443 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '基尔达斯总是过分夸大。比如，“迦罗娜：潜行与诡计研究”已经被偷过400多次啦。$B$B神殿的标志保护着这本卷轴，防止任何人偷看。' WHERE `Id` = 9510 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s叹了口气。' WHERE `Id` = 9511 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们什么时候才能吸取教训？' WHERE `Id` = 9512 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愚蠢！你没有学过杜威十进制吗？至少你也已经为我们工作3000年啦！无能的家伙。' WHERE `Id` = 9513 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我再次失败了……' WHERE `Id` = 9648 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我现在就回去，我到这儿来无非是再次体验相同的悲惨遭遇罢了。' WHERE `Id` = 9649 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '痊愈吧！' WHERE `Id` = 9655 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '战争是有代价的，$c……这种代价常常被我们忽略。艾泽拉斯大地冲突迭起，到处都是失去双亲的孤儿。那些无家可归的孤儿没有别的地方可去，他们通常在这儿成长，到了自力更生的年龄才离开。$B$B部落将春季的某一周设为儿童周，为这些无辜的孩子赠送物品。' WHERE `Id` = 9656 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '战争是有代价的，$c……这种代价常常被我们忽略。艾泽拉斯大地冲突迭起，到处都是失去双亲的孤儿。那些无家可归的孤儿没有别的地方可去，他们通常在这儿成长，到了自力更生的年龄才离开。$B$B联盟将春季的某一周设为儿童周，为这些无辜的孩子赠送物品。' WHERE `Id` = 9659 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哎呀……你可真是好人。我听说你是儿童周的志愿者，是吗，$c？嗯，你会受到赞扬的。我们必须记得那些不幸的人——特别是那些孩子。$B$B我很高兴能给他签名。给你。' WHERE `Id` = 9665 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在守护者之周中成为一名孤儿的导师！哈哈！' WHERE `Id` = 9677 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在守护者之周中成为一名孤儿的导师！为了部落！' WHERE `Id` = 9678 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可怜的孩子，我为你难过。' WHERE `Id` = 9689 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '孩子们，停下来！别闹了！' WHERE `Id` = 9690 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '孩子们，一切都会好起来的。光明会庇佑我们的！' WHERE `Id` = 9691 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我相信你们这群孩子是我们的未来……' WHERE `Id` = 9692 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '孩子们，现在该我照顾你们啦。你们会成长为强壮的部落成员的！' WHERE `Id` = 9693 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别发牢骚了！' WHERE `Id` = 9694 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '把这儿打扫干净！我们可不能生活在这么糟糕的地方。' WHERE `Id` = 9695 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要么跟着我，要么去黄金之路。明白吗？' WHERE `Id` = 9696 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '赞美圣光，终于有人对召唤做出了回应。' WHERE `Id` = 9707 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '太多人已经倒下了，牧师。你必须集中精神！' WHERE `Id` = 9711 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<艾瑞斯点着头。>$B$B这只眼睛见证了许多恐怖和惊奇的事情。$B$B它会显现出观察者理应看到的场景。' WHERE `Id` = 9717 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的。眼睛绝不会弄错的。$B$B毕竟，你是一名牧师。如果眼睛向你展示了这段恐怖的记忆，那么你肯定是一名强大的牧师。$B$B你是来救赎的，但是你甚至还没有意识到这一点……对吗？' WHERE `Id` = 9719 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我知道你会的，$n。$B$B我也是一名牧师，与你不同的是，我已经辞世多年了，但是我的灵魂仍停留在此，跟这儿的数千个冤魂一样，我们是被疯狂的阿尔萨斯·米奈希尔王子和他的亡灵军团残忍杀害的。' WHERE `Id` = 9721 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我可没说你是到这儿来救赎你自己的，牧师。你是来解救我和那些在试图逃离斯坦索姆时丧命的无辜者的。$B$B我和那些无辜者的灵魂受到诅咒，被禁锢在这儿忍受无尽的轮回。' WHERE `Id` = 9723 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你必须完成我未做完的事情：保护逃离斯坦索姆的农夫。$B$B他们会走向光明，而你必须确保他们的安全。如果死去的人数量过多，我们将继续生活在诅咒之下——你的任务也会失败。$B$B这项任务将检验你学到的所有技能和法术。愿圣光保佑你，$n。' WHERE `Id` = 9725 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们得救了！农夫们逃脱了亡灵天灾的魔爪！' WHERE `Id` = 9728 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '多么幸福的活着的一天啊！朋友，看看你周围的美景吧。享受自然赋予你的一切！' WHERE `Id` = 9744 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s嘲笑你那愚蠢的请求。' WHERE `Id` = 9759 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如你所愿，$c。' WHERE `Id` = 9760 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我看起来像个傻子吗，凡人？因为只有傻子才会留在这儿，跟你和你的盟友交战。或许下一次……你会有勇气收回嘲讽的话。' WHERE `Id` = 9761 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s被毒针沉默了。' WHERE `Id` = 9762 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小偷！无赖！恶棍！来尝尝我的大枕头的滋味吧！' WHERE `Id` = 9810 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们选择了离开黑石深渊的保护出来探险……呃，我是说……嗯，我们这么做是对的，我们要探索整个世界。' WHERE `Id` = 9811 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在霜狼氏族的将军被击败了，我们可以派出一些军队来驻守冰斧要塞。$B$B但是我们还是要保持警惕！我们要小心那些部落的入侵者……' WHERE `Id` = 9823 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小心！$r$n正在攻击冰斧要塞！' WHERE `Id` = 9827 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不管我是不是瑟银兄弟会的，只要有个黑铁矮人敢靠近我，我一定会让他们尝尝我的厉害！现在，你想去哪里呢，$g小伙子:小姑娘;？' WHERE `Id` = 9828 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '只要那些矮人一直待在那里，我们就不会有麻烦。你现在要去哪里，$n？' WHERE `Id` = 9841 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，你！如果你想要赢得暗矛部族的尊重，那你可以向我们捐赠那些急需的资源！你要知道，布料和绷带不会从树上长出来。$B$B我们需要你在冒险中得到的那些布料，把它们捐给我们吧！这样你就可以得到暗矛部族的青睐！' WHERE `Id` = 9889 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在这个艰难的时期，捐赠布料对于那些不幸的人是非常重要的帮助手段。布料还可以制作装备和绷带——这对于战争十分重要！$B$B如果你想要为奥格瑞玛的兽人捐赠布料的话，我会欣然接受它们，你一定会受到我们的青睐。$B$B为了部落！' WHERE `Id` = 9890 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，你！如果你想要赢得铁炉堡矮人的尊重，那么你可以为我们捐赠有价值的资源！铁炉堡现在的布料和绷带的存储量很低！$B$B你可以捐赠各种你在冒险中得到的布料！这样一来，你就可以赢得铁炉堡矮人对你的尊重！' WHERE `Id` = 9895 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎来到恶齿村，陌生的$c。我是断齿族长，这里的领袖。' WHERE `Id` = 9976 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我出售各种神秘的货物，陌生人。' WHERE `Id` = 9978 AND `Locale` = 'zhCN';
