UPDATE `broadcast_text_locale` SET `Text_lang` = '我会教你锤系专精之道。你只需要恭恭敬敬地问我就可以了。' WHERE `Id` = 9987 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愿夜之祝福永远与你同在，我的朋友！我是艾蒂尔·月火，我是灰谷银翼哨兵部队的军需官。随着你在银翼哨兵中的声望不断提升，我可以为你提供一些可在战歌峡谷中使用的商品。如果你需要修理装备的话，我也可以提供这样的服务。' WHERE `Id` = 10020 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '希里克，赐予我复仇的翅膀！' WHERE `Id` = 10027 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '去死吧，渣滓！联盟会获得胜利的！' WHERE `Id` = 10054 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '把这些渣滓赶出奥特兰克！' WHERE `Id` = 10056 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎来到暗月马戏团，$c！$B$B我叫克莉·希克斯，我应该跟你握手致意的，但是恐怕我会把你的手捏碎，因为我是当今世上最强的女人！' WHERE `Id` = 10123 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨，$n！感谢你对我的帮助！现在我什么都不缺啦，但是未来会怎样，又有谁知道呢？$B$B享受生活吧，别忘记跟你的朋友谈谈暗月马戏团的趣闻！' WHERE `Id` = 10124 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '便宜的啤酒！到这儿来买啊，物超所值！' WHERE `Id` = 10129 AND `Locale` = 'zhCN';
