UPDATE `broadcast_text_locale` SET `Text_lang` = '你是来学习的？嗯，我或许会给你一些事儿做的。' WHERE `Id` = 10191 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '特洛克你饿了吗？我在给我们俩做吃的！' WHERE `Id` = 10251 AND `Locale` = 'zhCN';
