UPDATE `broadcast_text_locale` SET `Text_lang` = '很好，$n。我将使用这个被梦魇笼罩的东西召唤伊兰尼库斯。' WHERE `Id` = 11278 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '跟着我。' WHERE `Id` = 11279 AND `Locale` = 'zhCN';
