UPDATE `broadcast_text_locale` SET `Text_lang` = '这座城市不漂亮吗，$c？我们可以找到这么知心的暗夜精灵朋友，真让我感到温暖。' WHERE `Id` = 13487 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，我是守备官帕兰纳尔，一个信仰圣光的旅行圣骑士。我是来这里帮助暗夜精灵的。' WHERE `Id` = 13488 AND `Locale` = 'zhCN';
