UPDATE `broadcast_text_locale` SET `Text_lang` = '%s把日记交给了建筑师尼莫斯。' WHERE `Id` = 13905 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎来到林歌神殿,$c。如果有什么我可以为你效劳的，请随时告诉我。' WHERE `Id` = 13959 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$c。很少有客人会到我这里来。有什么我可以帮忙的吗？' WHERE `Id` = 14013 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '苏苏鲁斯正在等着你呢，$n。' WHERE `Id` = 14014 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我一直都期待着你的到来。' WHERE `Id` = 14016 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些象形文字叙述着一个故事。这个位于开端的图形，看上去就像那个我们在碧蓝岗哨遭遇的生物……' WHERE `Id` = 14030 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，这不可能……上面说这个生物自愿变成了燃烧军团的奴仆。他变身成为萨特，接受了燃烧军团的“祝福”。' WHERE `Id` = 14031 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们必须消灭这些萨特，$n。我们不能让燃烧军团出现在这片土地上。' WHERE `Id` = 14032 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈哈哈！那个白痴永远也不会知道我的计划！就算他知道了，对德莱尼人来说也太晚了！' WHERE `Id` = 14094 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些兽人都是蠢货！强大的力量唾手可得，但他们却视而不见，让别人占尽了先机！' WHERE `Id` = 14095 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我简直等不及要看这最后一批的实验结果了！' WHERE `Id` = 14096 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿弗恩敢跟我对着干？我要让他死无葬身之地！当我解决了德莱尼人之后，他们会后悔自己当年没有变成失落者！' WHERE `Id` = 14097 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你能不能先别修自己的指甲？就一小会儿行不行啊？说真的，没人关心你的指甲！' WHERE `Id` = 14098 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你饿了吗？我饿了。我一想起索尔塔什的烤火腿就忍不住了。啊！要是再来一些味美多汁的烤鹌鹑……' WHERE `Id` = 14099 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我需要一些新鲜空气，不是这沼泽地里的空气。我要出去走走，当我外出的时候，你记得打扫一下房间，明白吗？' WHERE `Id` = 14101 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你非要走到哪里都跟着我吗？<叹气>' WHERE `Id` = 14102 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看！她以为自己是谁啊？' WHERE `Id` = 14103 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你有什么话要对我说吗？' WHERE `Id` = 14106 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我想没有！' WHERE `Id` = 14107 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s仔细检查着箱子里的东西。' WHERE `Id` = 14113 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<艾拉兰看上去正在研究着某种毒草。>$B$B如果你在找人帮你制作爱情药水，那么你来错地方了。我的知识全都是关于配制致盲、致残甚至致命的毒药……你也有希望成为我这样的行家。' WHERE `Id` = 14189 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎来到公会注册处。有什么我可以为您效劳的吗？' WHERE `Id` = 14215 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，我的孩子。' WHERE `Id` = 14216 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可以更好地听你说话啊，孩子。' WHERE `Id` = 14218 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可以把你看得更清楚啊，孩子。' WHERE `Id` = 14220 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '感谢圣光，$n。我的腿已经痊愈了！' WHERE `Id` = 14223 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '请告诉古安我没事的，谢谢你。' WHERE `Id` = 14224 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '需要一些锻造物资吗？' WHERE `Id` = 14255 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$n。随着你在荣耀堡的声望不断提升，我将允许你使用一些我们库存的其它物品。' WHERE `Id` = 14257 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '自从坠毁之后，我看什么东西都是模糊一片。仿佛登上埃索达已经是很久很久以前的事情了。$B$B现在，我的世界中充满了变异的生物和无尽的血精灵。很快，也许我就不会记得任何别的东西了……' WHERE `Id` = 14302 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我回里面去了。要是有什么其它事情，告诉我一声。' WHERE `Id` = 14315 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这么多年来的研究……结果却是一场空！也许他们是对的，也许这是我们必须与之斗争一生的东西。' WHERE `Id` = 14318 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，赫米修斯，有我的新邮件吗？' WHERE `Id` = 14339 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '赫米修斯，有从埃索达寄给我的包裹吗？已经一个多星期了。' WHERE `Id` = 14340 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '赫米修斯，快点过来！我有一封非常紧急的邮件必须交给联盟远征军的人类上将。' WHERE `Id` = 14341 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的运送服务到底怎么回事？邮件从不及时送达，让我们怎么去履行职责？' WHERE `Id` = 14342 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你肯定是德莱尼人中最懒的信使了！' WHERE `Id` = 14343 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '似乎此地的鬼魂们并不欢迎你，$r。如果你能攻下这座哨塔，我可以考虑帮助你。' WHERE `Id` = 14364 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你会告诉任何我想知道的事情，你这渣滓。' WHERE `Id` = 14396 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的人都在哪里，混蛋？回答我！' WHERE `Id` = 14397 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你饿吗？渴吗？我可以帮你准备吃的和喝的——你所需要做的就是告诉我一些我想知道的情报。' WHERE `Id` = 14398 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果这两个家伙不马上开口说话，我就要违背我所说的话了。' WHERE `Id` = 14399 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '艾露恩祝福着你，有什么我能为你效劳的吗？' WHERE `Id` = 14411 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你，$c。你能来拜访我们实在是太好了。' WHERE `Id` = 14417 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '记住，$n！沿着黎明之路就可以走到精灵之门！' WHERE `Id` = 14433 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，不用担心巴迪。他不会伤害你的，他不过是喜欢这样抓来抓去而已。$B$B他只是一只又大又可爱的猫而已。$B$B不是吗，巴迪？可爱的小东西，我的小宝贝！' WHERE `Id` = 14437 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你觉得这地方怎么样？当然，如果你问我的话，我觉得挺乏味的。' WHERE `Id` = 14545 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是我没有在这个地方扭了脚，现在我就应该在那里，和朋友们在一起。嗯，让我先想想如何走出这里？' WHERE `Id` = 14548 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '该死的血精灵和他们不顾后果的魔法！' WHERE `Id` = 14593 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愿圣光屈从于你的意志。' WHERE `Id` = 14604 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在大自然中存在的所有东西都有着相互的联系，这被称作生态系统。如果我们小心地不去打扰它，通过简单的观察便可以了解到我们周围不同的生物体之间的复杂关系。$B$B一旦我们理解了这些，就可以采取适当的行动来保证所有生物的生存。反之，在没有这种认识的情况下去干预的话，就会引起破坏。$B$B我在这里观察孢子人和沼泽领主之间的复杂关系。' WHERE `Id` = 14605 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然，$n。' WHERE `Id` = 14607 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，让我们看看这个计划是否有效。过来，巴迪！' WHERE `Id` = 14608 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯，让我看看能否用那些你带回来的蘑菇制作一种食物喂给沼泽领主吃。' WHERE `Id` = 14609 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '巴迪，别闹了！看，这东西有效，真的有效！！现在我要做的就是在这里多培育一些这种蘑菇，我想那些沼泽领主会很可能会就此远离孢子人的。' WHERE `Id` = 14610 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，谢谢你，$n！你成功地从沼泽领主手中拯救了孢子人，同时从我们的愤怒中拯救了沼泽领主。' WHERE `Id` = 14611 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '等一会看看有什么事情发生！' WHERE `Id` = 14615 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '狂妄的孩子们，在你们快要见到你们的神明之前向他祈祷吧！' WHERE `Id` = 14666 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我在耐心等候命令，$c。' WHERE `Id` = 14667 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我来这里是为了感谢那位拯救我性命的英雄。' WHERE `Id` = 14677 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你可能不记得我了，但是你救了我的命。我最近才刚刚恢复健康，可以自己下地行走了。$B$B我想感谢你为我做的一切，并为我所说过的话道歉……谢谢你，$n。希望艾露恩永远保佑你。' WHERE `Id` = 14678 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s拥抱了你。' WHERE `Id` = 14679 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们不能让我们的卫兵倒下，$C。这个世界布满了燃烧军团的爪牙和同盟，如果你发现了任何奇怪的东西，就立即告诉我。' WHERE `Id` = 14695 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不知道你是谁，但是我欢迎你的到来。阿克蒙德和他的天灾军团随时都有可能向我们进攻，$C。你会和我们一起面对这些恶魔吗？' WHERE `Id` = 14697 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你，$c。好好准备一下。阿克蒙德正在行军，我们必须尽可能在这里坚守得更久一些。' WHERE `Id` = 14699 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不喜欢那个向艾泽拉斯求援的想法，但我们现在没有别的选择。' WHERE `Id` = 14700 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我告诉自己不要用远征队的问题去麻烦塞纳里奥议会，$n。然而，我们的军事力量太渺小了。这主要是因为，我们大部分都是学者和探险者。' WHERE `Id` = 14701 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这件事情实在太重大了。如果远征队不能遏制纳迦的嚣张气焰，那我们的存在又有何意义？必须把这个消息传达给议会的大德鲁伊们。' WHERE `Id` = 14702 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们必须继续守住这里，越久越好！战斗到底！' WHERE `Id` = 14704 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这与你所描述的暗泽湖中的建筑完全一样。是不是意味着纳迦们在抽取赞加沼泽的所有湖泊里面的水？' WHERE `Id` = 14706 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '纳迦们甚至在抽干他们自己湖里的水。他们到底有什么企图？' WHERE `Id` = 14712 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看！那些管道似乎都连接着那座建筑，但是那里面不可能存放所有他们偷来的水。他们究竟把水储存在哪里呢？' WHERE `Id` = 14713 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们看到的一切都说明了在死亡泥潭曾经发生过什么，那里曾经是一片湖泊。如果我们不阻止纳迦的行动，整个沼泽很快就会变成那个样子！' WHERE `Id` = 14714 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我是秘血岗哨的防务首领，有什么我可以帮你的吗？' WHERE `Id` = 14718 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，你是不是到这里来了解秘血岛事态的？' WHERE `Id` = 14720 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有什么我可以帮你的吗？' WHERE `Id` = 14721 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们无条件地为圣光效劳，也许你可能会对我们的目的感到好奇？' WHERE `Id` = 14722 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '前面安全吗？让我们离开这里吧，$n。' WHERE `Id` = 14724 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看起来没那么容易逃脱。做好准备！' WHERE `Id` = 14725 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '继续前进吧，这里并不安全！' WHERE `Id` = 14726 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小心，$n！敌人就在前面！' WHERE `Id` = 14727 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们快到庇护所了！加油。' WHERE `Id` = 14728 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我已经可以看到我的德鲁伊同伴了。感谢你，$n。我相信伊谢尔会奖励你的。' WHERE `Id` = 14729 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '长官！我们收到报告说，一个艾瑞达堕落者在西面被召唤了出来。我会派遣防御部队在通往秘血岗哨的路上拦截他。' WHERE `Id` = 14742 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$n。' WHERE `Id` = 14757 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在元素们陷入混乱的时刻，我们的人民怎么能战斗？难道他们不知道这个世界完全无法脱离元素的支持而存在？' WHERE `Id` = 14760 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让风指引你的路途吧，$n。' WHERE `Id` = 14777 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我一直喜欢有条理的事情。我想这是我母亲的遗传。' WHERE `Id` = 14781 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '秘血岗哨的防御者抵御着任何针对这座哨所的威胁。' WHERE `Id` = 14794 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '防御者们在这里抵御着来自炎鹰部队的威胁。' WHERE `Id` = 14795 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们最近听说有一个拥有巨大力量的生物在矢量感应器附近被召唤了出来。我们不畏惧任何威胁，我们会用自己的生命来捍卫这里！' WHERE `Id` = 14796 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '蠢货，你休想偷走箱子！' WHERE `Id` = 14847 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '提醒我，大使……你的人民会为我们做出什么样的贡献？' WHERE `Id` = 14854 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我想我们会在适当的时候看到你们的贡献。' WHERE `Id` = 14860 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '塔泰！' WHERE `Id` = 14862 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真正互利的同盟。' WHERE `Id` = 14864 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '德拉·符文图腾皱了下眉毛，但她还是继续保持沉默。' WHERE `Id` = 14866 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '告诉我们，克雷玛尔大使……血精灵们到底准备怎么样来帮助我们？' WHERE `Id` = 14870 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你的人民像你所宣称的那样强大，我深信你们会再次迈入辉煌的。' WHERE `Id` = 14885 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没人在问你，塔泰。' WHERE `Id` = 14887 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们不是亡灵天灾唯一的受害者。我们的希尔瓦娜斯女王很同情你们的遭遇。' WHERE `Id` = 14889 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我很遗憾。过去的几年对我们来说很艰难。' WHERE `Id` = 14890 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这座城市非常……奢华。但是它看上去似乎缺少些什么，我不能确切地指出到底缺什么……' WHERE `Id` = 14891 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '似乎大量的能量被用在了……琐碎的东西上……我希望你能宽恕我的用词。这样是不是，呃，太浪费了？' WHERE `Id` = 14892 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s用手指轻拍着她的下巴，陷入了沉思。' WHERE `Id` = 14896 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '塔泰，不要这样。我们是客人。' WHERE `Id` = 14898 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我可以理解你们的良苦用心。你们让所有人，不管是敌人还是同盟，都知道你们不再害怕使用你们的力量了。' WHERE `Id` = 14900 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '也许吧。但它始终看上去很浪费。' WHERE `Id` = 14903 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们选择的装饰真是引人入胜，克雷玛尔。告诉我，为什么要搞这些没用的东西？' WHERE `Id` = 14905 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '洛瑟玛·塞隆有空接见我们了吗？' WHERE `Id` = 14906 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们暂时接受你的解释，克雷玛尔。不过我们的耐心是有限的。' WHERE `Id` = 14910 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '巨魔，如果你的舌头不能使用礼貌的措辞，我会很高兴帮你去掉它的。' WHERE `Id` = 14912 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s耀武扬威地笑着。' WHERE `Id` = 14914 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我开始有点无聊了。' WHERE `Id` = 14915 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没关系，大使。我们可以等。' WHERE `Id` = 14916 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我想我们应该去和摄政王谈谈了，现在我甚至开始怀疑他是否真的存在了。' WHERE `Id` = 14917 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个地方的景致真是美不胜收……但是这些树和植物，仍然显得如此……不自然。' WHERE `Id` = 14918 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '塔泰，你应该早就习惯了。你还记得你被派来做这份工作的原因吗？' WHERE `Id` = 14927 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当你的保姆要比看着你更让我不爽。给我记住……要不是我的话，事情可能更糟糕。' WHERE `Id` = 14929 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '托尔加什相信他可以通过鸟的肠子或者通过摇骨头预测未来。但实际上，你所要做的就是询问那些灵魂。不过别告诉他这些，$n。他是个很固执的家伙。' WHERE `Id` = 14947 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = 'TugofWar Buffbot, 联盟' WHERE `Id` = 14948 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = 'TugofWar Buffbot, 联盟胜者' WHERE `Id` = 14949 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = 'TugofWar Buffbot, 部落胜者' WHERE `Id` = 14951 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = 'TugofWar Buffbot, 部落问候' WHERE `Id` = 14952 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要忘记当你在赞加沼泽的时候花点时间钓鱼。你从不知道什么时候你会再次看到水。' WHERE `Id` = 14959 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如此不可思议的奇观。我真后悔没有在年轻的时候看到它。' WHERE `Id` = 14963 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在泰雷多尔顶部观景真是华丽啊，难道不是吗？' WHERE `Id` = 14966 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '里维伊的脸皮就像科多兽那样厚！可笑的是，他并不觉得他的骚扰行为是这么的明显。我看到他直勾勾地盯着我，还自以为没人发现他。$B$B他让我觉得毛骨悚然，我真的希望暗影猎手德恩加没有派他和我们在一起。建造沼泽鼠岗哨原本是一个摆脱他的好机会。' WHERE `Id` = 14981 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，不，不！回到这边来！' WHERE `Id` = 15010 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '魔导师会杀了我的……' WHERE `Id` = 15011 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '过来，你这个小……' WHERE `Id` = 15012 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '唉唷。他们告诉我这些水晶可以完美运转！这帮奸商！' WHERE `Id` = 15013 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要挡着摄政王的路！我说真的！' WHERE `Id` = 15014 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是我抓住你，我会把你的零件都给分解掉，所以你最好……' WHERE `Id` = 15015 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我叫尼姆瑞达，小子。' WHERE `Id` = 15025 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '尼姆瑞达。' WHERE `Id` = 15027 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可能是你召唤了我，小术士，但是这并不代表你可以像对待宠物那样给我起名字。' WHERE `Id` = 15029 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你知道，我喜欢看着你乞求我……但是不行。' WHERE `Id` = 15031 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哼。有人可能会觉得你和我在一起的时候显得很害羞，主人。' WHERE `Id` = 15035 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '难道这有什么问题吗？那个女人在不停地回头看我。' WHERE `Id` = 15037 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s弯起眉毛看着克亚诺米尔，露出了迷人的微笑。' WHERE `Id` = 15039 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '“拜托？”你还有很多东西要学呢……主人。' WHERE `Id` = 15040 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我为你们感到可悲，小家伙们！' WHERE `Id` = 15050 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '搞定你了，对不对？' WHERE `Id` = 15051 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '怎么可能？啊，这真是个残酷的世界……' WHERE `Id` = 15052 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要对孩子这么刻薄，奥图鲁斯。记住是塞德瑞克亲自把他指派给你的。' WHERE `Id` = 15058 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '托托，你不会让这些家伙伤害我们的，对吧？' WHERE `Id` = 15066 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，托托，我们必须找到回家的路！那位老巫师是我们唯一的希望了！稻草人、狮子，还有铁皮人，你们能不能——呀，有人来了！' WHERE `Id` = 15067 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，我终于……终于可以回家啦！' WHERE `Id` = 15068 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '托托！不！你们杀了托托！' WHERE `Id` = 15069 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是个什么魔鬼，这样煎熬着我？' WHERE `Id` = 15070 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '离别是这样甜蜜的凄清。' WHERE `Id` = 15071 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '罗密欧，我来了！我为你干了这一杯！' WHERE `Id` = 15072 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来吧，可爱的黑颜的夜，把我的罗密欧给我！' WHERE `Id` = 15073 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，好刀子！这就是你的鞘子；你刺了进去，让我死了吧!' WHERE `Id` = 15074 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们的行为是不可饶恕的。' WHERE `Id` = 15079 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '抛弃一切堕落的杂念。' WHERE `Id` = 15080 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死亡来临了。你们自问无愧于良知吗？' WHERE `Id` = 15081 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊哈哈哈……' WHERE `Id` = 15082 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不纯的思想会导致亵渎的行为。' WHERE `Id` = 15083 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这样就没问题了。' WHERE `Id` = 15084 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '若是赫米特知道如何在射击猎物时避免打中机翼的话，我们就不会坠毁。$B$B不用担心，我会很快把它修好的。' WHERE `Id` = 15099 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我没有任何东西给像你这样的家伙，塞伊兰。像上次那样，滚出这个店。' WHERE `Id` = 15101 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，哈罗德。我拿到你的皮革了！' WHERE `Id` = 15102 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊！有人来救救我吗！' WHERE `Id` = 15104 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我很高兴那个邪恶的甘克雷·骨拳没能得逞！如果你想带点毛皮给哈罗德的话，我有很多。' WHERE `Id` = 15113 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我很高兴那个邪恶的甘克雷·骨拳没能得逞！' WHERE `Id` = 15138 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '盖亚安祖母，请喝点水吧。' WHERE `Id` = 15139 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿！我是不是以前给过你一捆皮革？$B$B不管怎样，能从那个坏蛋甘克雷·骨拳手下逃生，我很高兴。' WHERE `Id` = 15140 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '盖亚安祖母，有什么我可以效劳的吗？' WHERE `Id` = 15142 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '盖亚安祖母，加尔鲁什已经失去了信心。如果没有了您，我们就一无所有了。' WHERE `Id` = 15143 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会尽我所能照顾孩子们的，盖亚安祖母。' WHERE `Id` = 15144 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '盖亚安祖母让我们获得了升华。所有你遇到的玛格汉族人的生活都与盖亚安祖母有着某些特殊的联系。当她去世的时候，我们会非常怀念她的。' WHERE `Id` = 15149 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '盖亚安祖母曾跟我说，我的名字来自一位伟大的兽人英雄。' WHERE `Id` = 15152 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '最后的守护者，去死吧！' WHERE `Id` = 15171 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你别想挡我们的路！' WHERE `Id` = 15172 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '麦迪文会在今天死去！' WHERE `Id` = 15173 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们还没有完！' WHERE `Id` = 15174 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '微不足道的胜利……' WHERE `Id` = 15175 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们不会失败！' WHERE `Id` = 15176 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '末日就在眼前！' WHERE `Id` = 15177 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '又近了一步……' WHERE `Id` = 15178 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没有施舍，塞伊兰。' WHERE `Id` = 15204 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不会让你这么沉迷下去的。这又不是我的过错。滚出去！' WHERE `Id` = 15205 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '了解这些新植物的分类对我们远征队来说非常重要。这不只是为了医用或者食用。$B$B植物是很多其它生命存活的基础，了解它们可以让我们更好地了解整个大自然。' WHERE `Id` = 15302 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们赢得了宝贵的时间。现在必须撤退。' WHERE `Id` = 15309 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s开始施放一个群体传送法术。' WHERE `Id` = 15310 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很快就会结束了！' WHERE `Id` = 15332 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '[PH] Players! Go Stop Archimonde at the tree, we will hold the Undead off here!' WHERE `Id` = 15377 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得好，冒险者。雷基·冬寒的死让我们获得了一个短暂的喘息机会。好好利用这段珍贵的时间吧。治疗一下你的伤口，做好准备，很快阿克蒙德就会向我们派出更强大的部队。我的部队会在战斗再次开始时增援你的。' WHERE `Id` = 15392 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那么就让阿克蒙德再吃一场败仗吧！' WHERE `Id` = 15394 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '太棒了！你打败了安纳塞隆，延缓了阿克蒙德的计划，让我们离胜利更近了一步。但是，我的部队不能留在这里。他们都已经非常疲倦，现在是撤退的时候了。如果你还能支撑下去的话，就到东面去，找到萨尔的营地吧。那是我们的另外一个据点。保重。' WHERE `Id` = 15415 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们必须把那些补给箱给弄回来！' WHERE `Id` = 15422 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '部落不是这片森林里潜伏着的唯一危险。不要让它宁静的表象迷惑了你。' WHERE `Id` = 15429 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '非常感谢你来支援我们对抗燃烧军团的战斗。吉安娜·普罗德摩尔女士正需要你的帮助。' WHERE `Id` = 15497 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '非常感谢你继续帮助我们对抗燃烧军团。在这里的西面就是萨尔的营地，他可能会需要你们。' WHERE `Id` = 15498 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噩梦般的时刻就在眼前了，$c。阿克蒙德成功地靠近了诺达希尔，并开始吸取世界之树的能量。玛法里奥需要更多时间来准备他的计划，我们必须尽全力完成这几乎不可能的任务。在我的部队抵抗潮水般的燃烧军团部队时，你必须直接进攻阿克蒙德。' WHERE `Id` = 15499 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祝贺你！今天你赢得了一场伟大的胜利。' WHERE `Id` = 15512 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的工作是照顾那些可怜的灵魂。我愿意接受任何帮忙，无论他们是奥尔多还是占星者。$B$B我们太缺人手了，如果食人魔知道怎么扎绷带，我甚至愿意让他们帮忙。这座城市里的政治派系对我来说是个不小的麻烦。' WHERE `Id` = 15600 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你能相信吗？这个虚灵身上竟然没有一只蜥蜴眼！$B$B然而他们的首领竟然还有胆子自称为“走私大亨！”' WHERE `Id` = 15601 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s摇了摇头，对那些骚乱感到不胜其烦。' WHERE `Id` = 15631 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要走太远了，塞瑟。你知道妈妈不喜欢你走得太远。' WHERE `Id` = 15634 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我……我能看到了……' WHERE `Id` = 15636 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我还以为再也看不到我儿子的脸了。过来，塞瑟！让妈妈好好看看你！' WHERE `Id` = 15637 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '喝下这个，萨恩莉亚。那不像我希望的那样有效，但也许会有点帮助。' WHERE `Id` = 15639 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$n。我们是奥尔多，圣光的牧师和沙塔尔的仆人。$B$B我们随时欢迎你来这里。' WHERE `Id` = 15641 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '“生于圣光”应该是最接近沙塔尔这个词原意的翻译。那是我们给从伊利丹的爪牙手中夺取并重建沙塔斯城的纳鲁所起的名字。' WHERE `Id` = 15643 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '沙塔斯城不仅仅是个为了对抗燃烧军团和伊利丹而设立的运输中转站，还是给那些企图寻找庇护的人们的避难所。$B$B如果我们赶走那些难民的话，我们就是伪君子了。$B$B如果你想问的是占星者，那么我要说，虽然我不喜欢他们，也不喜欢他们首领那救赎愿景的疯狂想法，但是这并不能让我怀疑纳鲁的智慧。$B$B这是一个艰难的时刻，$n。我们需要团结一切可以团结的力量。' WHERE `Id` = 15645 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的兄弟姐妹们，听我说。我们必须开始关注自身的生存了。虽然我们在一场灾难中勉强幸存了下来，但是我担心下一场灾难会把我们彻底摧毁。' WHERE `Id` = 15673 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们看不到眼前正在发生些什么事情吗？睁开你们的眼睛，一切都明明白白展现在你们眼前。我们的新同盟是什么？为什么我们背叛了过去的盟友，却要与所有生命的大敌亲密相处？' WHERE `Id` = 15674 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '人类在我们最黑暗的时刻抛弃了我们！他们的王子亲自领导了对我们领土的袭击。' WHERE `Id` = 15677 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你把她当作朋友？你真是个蠢货。这个“黑暗女王”不是希尔瓦娜斯。' WHERE `Id` = 15680 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是来这里帮助奥尔多的吗？' WHERE `Id` = 15708 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我很感激你的援助和为此所做出的牺牲，$n。' WHERE `Id` = 15711 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是你让我们祖先的灵魂安息，我会永远感激你。' WHERE `Id` = 15712 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，没关系。我经常遇到这种事情。$B$B<泰拉看上去有些高兴又有些恼火。>$B$B我是个**高等**精灵，不是个血精灵。所以不要担心，我不会把你的所有法力吸个精光的。' WHERE `Id` = 15717 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那里有着大片的森林，$c。让萨满和灵魂们玩耍，让战士们耍他们的剑。泰罗卡森林是个要让我赚大钱的地方。' WHERE `Id` = 15721 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的同胞的命运随着黑暗之门的打开进入了新的篇章。在某种程度上来说，我的流放使我免于堕落。但是看到远行者把他们的命运都交给了凯尔萨斯……$B$B我不敢相信我以前的朋友可以做出这样的事情。$B$B我那回家的梦看来永远都不可能实现了，这片森林是我唯一的家。' WHERE `Id` = 15724 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当我最初来到这里时，我曾希望能和这个小镇所用名字的主人会面。$B$B<洛瑟蕾丝扫视着周围。>$B$B当年幼的高等精灵成长到学徒的年龄时，他们的脑袋里想的便不再是“我要成为一名远行者”，而是“我要当一名魔导师”。$B$B没有人会梦想成为一个女裁缝，但就像我母亲常常说的那样，我们不能让远行者就这么不穿衣服走来走去。' WHERE `Id` = 15725 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当我最初来到这里时，我曾希望能和这个小镇所用名字的主人会面。$B$B<洛瑟蕾丝扫视着周围。>$B$B当年幼的高等精灵成长到学徒的年龄时，他们的脑袋里想的便不再是“我要成为一名远行者”，而是“我要当一名魔导师”。$B$B说实话，我不觉得我曾经幻想过成为远行者。没有人会梦想成为一名女裁缝，但就像我母亲常常说的那样，我们不能让远行者就这么不穿衣服走来走去。' WHERE `Id` = 15726 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么？啊，当然，波尔泰姆，你的帽子做好了。我用了大量蓬松的、我所能找到的最华丽的羽毛制成了它。如果你愿意的话，我还可以为你量一量尺寸，做一双新的长筒袜——' WHERE `Id` = 15732 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可怜的波尔泰姆……' WHERE `Id` = 15735 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可怜的波尔泰姆……' WHERE `Id` = 15736 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '血？还有这些兽人，这些见风使舵的家伙？他们会帮我们吗？' WHERE `Id` = 15743 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看看这座神奇的城市！这就是魔法本身。' WHERE `Id` = 15747 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '魔导师们是叛徒！他们已经注定了我们的毁灭。' WHERE `Id` = 15750 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你会让我们像野蛮人那样生活的！' WHERE `Id` = 15752 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们竭尽全力挣扎奋斗，为的是求得生存的机会，而不是给自己带来真正的毁灭。' WHERE `Id` = 15754 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，年轻的$r。' WHERE `Id` = 15769 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，亲爱的。我是盖亚安，玛格汉的女族长。$B$B<盖亚安祖母咳嗽了一下。>$B$B你在这里，那及说明黑暗之门已经重新开启了。在这里的大部分兽人都太年轻或是太虚弱，以至于不能记起黑暗之门。$B$B<盖亚安祖母指了指她周围的兽人。>$B$B他们大部分是孤儿，或很快就会变成孤儿了。是的，这就是黑手酋长的做法，让体弱者远离健康者，只有强壮的兽人可以生存……' WHERE `Id` = 15771 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们在这里长大，我们让他们远离伤害。我尽可能地照顾他们的健康。很多都夭折了，但是更多的孩子茁壮成长了起来。就像加尔鲁什那样……$B$B<盖亚安祖母叹了口气。>$B$B你知道，他失去了他的信心。他告诉我，我是他的一切。如果失去了我，吞噬了他的父亲、诅咒了我们的人民的嗜血狂热会彻底占据他。' WHERE `Id` = 15773 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<盖亚安祖母虚弱地笑了笑。>$B$B当然不，亲爱的。但是这并不是我相不相信的问题……$B$B加尔鲁什有能力来领导玛格汉。他是个强壮又聪明的领袖，万灵都很支持他。他只是需要自信。他的心中充满了恐惧……他的恐惧太深了，如果不能善加引导，他的愤怒会毁灭他自己和他周围所有的人。' WHERE `Id` = 15775 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我希望我能知道该怎么做，亲爱的。他不会听你的，同样他也不会听我的。事实上，这就是我还在这里的原因，这就是我还没有和卡舒尔宗母一起离开的原因。他必须找回他的自信。如果没有合适的领导，我们的人民根本活不过这个冬天。' WHERE `Id` = 15777 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<盖亚安祖母笑了笑。>$B$B我老了，我的时日已经不多了。当我去世以后，我的灵魂会前往灵魂的国度。我会在那里与我的祖先们团聚。那就是我们关注着仍然活着的人民的地方。$B$B当加拉达还活着的时候，卡舒尔宗母的职责就和我现在的一样。' WHERE `Id` = 15779 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '部族母亲的职责就是倾听。倾听风、水、火和大地。从它们那里收集对氏族有用的信息，就像氏族中的其他人收集皮毛以供大家御寒一样。与我交流的正是灵魂……在我的梦里，卡舒尔宗母就像灵魂和她谈话那样对我谈话……当我去世之后，我会以相同的方式和德拉吉亚和塞雷斯蒂谈话。$B$B<盖亚安祖母微笑着。>' WHERE `Id` = 15781 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再次感谢，$n。没有你的帮助，我们不可能解决格兰戈瓦村的暗影议会成员。' WHERE `Id` = 15790 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们要找出那些家伙在格兰戈瓦村干些什么！' WHERE `Id` = 15791 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我肯定在某个地方做错了什么，才被分配到这里来。' WHERE `Id` = 15794 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我听说波尔泰姆为了他的最新发明收集了很多毛皮。他对你说是件披风，对吗？$B$B其实那些毛皮是用来作帽子的。他不可能他把用尽全力收集的毛皮做成一件在战斗中很快就会弄脏的东西！' WHERE `Id` = 15812 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿！你觉得你能帮我离开这吗？' WHERE `Id` = 15876 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿！我知道你是部落的人，而我是联盟这一边的，但你觉得这次我们是否可以把这些抛到脑后呢？我真的需要有人帮我离开这里。' WHERE `Id` = 15877 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿？帮个忙行不行？' WHERE `Id` = 15878 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<咳嗽><咳嗽>这里有个痛苦的年轻姑娘！' WHERE `Id` = 15879 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是有机会的话，你觉得你能让我离开这里吗？' WHERE `Id` = 15880 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要把我留在这里！要是你这么绝情，我做鬼也不会放过你……' WHERE `Id` = 15881 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，让我们离开这里。' WHERE `Id` = 15882 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你确信你准备好了？再等一会儿。' WHERE `Id` = 15883 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，我们出发吧！' WHERE `Id` = 15884 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊呀，坏精灵！' WHERE `Id` = 15885 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些家伙都是一根筋吗？' WHERE `Id` = 15886 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，我想我可以自己逃出这里了。很感谢你的帮助！' WHERE `Id` = 15887 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果我们作为一个整体来抗争，就不可能被忽视了！' WHERE `Id` = 15917 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '魔导师们会指引我们重获荣耀。' WHERE `Id` = 15920 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们会让联盟千倍偿还他们的背叛。我们永远也不会原谅和忘记这种耻辱。' WHERE `Id` = 15927 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些公开反对魔法的家伙都是潜在的敌人。' WHERE `Id` = 15928 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '自然和魔法和平相处。有了这两者，我们前途似锦。' WHERE `Id` = 15929 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们会报复联盟！我们永远也不会忘记，永远也不会原谅他们！' WHERE `Id` = 15930 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们刚刚抵达这里，却已经有许多战友和朋友在途中丧生了。' WHERE `Id` = 15938 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你到这里来不是为了帮忙，就滚出去。' WHERE `Id` = 15949 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我可以传授你一些裁缝方面的知识。' WHERE `Id` = 15963 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '萨尔，你逃出来了！' WHERE `Id` = 15979 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '感谢你们帮助萨尔逃脱，朋友们。现在我只希望你们同样能帮我。我早上醒来时，发现自己被囚禁在这个魔法监牢中。一个奇怪的巫师告诉我，我必须在这里待一段时间。' WHERE `Id` = 15987 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Who are you? Are you with the wizard? [PH]' WHERE `Id` = 15988 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = 'No, I''m not important right now. You have to go help Thrall escape. I was going to set a fire as a diversion, but with me in this magical prison you''ll have to do it instead. [PH]' WHERE `Id` = 15991 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的，朋友们。这个人不是达拉然的巫师。他的衣服看上去是外来的，还有他的口音我也不是很熟悉。他不停地说着什么时间这个、时间那个之类的话。你得找到那个巫师，让他来释放我。' WHERE `Id` = 15993 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '作为贫民窟的代表，我要在此提出我们的建议，那就是：必须扫清在奥金顿横行的暗影议会成员。这关系到我们是否能在未来阻止他们再次创造一个新的白骨荒野，制造一次更大的灾难！$B$B我们的人民已经承受了太多的痛苦。我在这里盼望着那些痛苦立刻停止！' WHERE `Id` = 15996 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎来到加拉达尔，陌生人。你在找一处可以休息的地方吗？' WHERE `Id` = 16022 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的鲜血将会涂满基尔索罗的围墙！' WHERE `Id` = 16062 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我自由了！感谢你们！' WHERE `Id` = 16082 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '萨尔，我以前从没有遇到过这些人。' WHERE `Id` = 16085 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们称你为怪物，但他们才是真正的怪物，你不是。保重，萨尔。' WHERE `Id` = 16090 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有印象吗，$c？' WHERE `Id` = 16109 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '请随便看看，如果你对什么感兴趣，就告诉我。' WHERE `Id` = 16116 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '请自便，看看这把武器。如果你想修理你的武器和装备，我们这里也提供周到的服务。' WHERE `Id` = 16121 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你需要寄放你的宠物吗？' WHERE `Id` = 16130 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你迷路了吗？这里大部分的商人都居住在城镇中心。' WHERE `Id` = 16132 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我有很多零碎的小东西。' WHERE `Id` = 16133 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很多年来，荣耀堡都在独自抵抗着地狱火半岛的敌人。现在，既然黑暗之门已经重新开启，援助者们像潮水一样从艾泽拉斯涌入，也许这个血腥的僵局将会被打破。' WHERE `Id` = 16140 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们在地狱火半岛的敌人非常多，遗憾的是，地狱火堡垒的兽人便是其中之一。$B$B但是……没有谁比这些兽人更适合用来历练部落的新兵了。' WHERE `Id` = 16141 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我是这里的军需官，你需要什么补给吗？' WHERE `Id` = 16142 AND `Locale` = 'zhCN';
