UPDATE `broadcast_text_locale` SET `Text_lang` = '有人叫我吗？' WHERE `Id` = 16315 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '找条路带我离开这里，$c。' WHERE `Id` = 16399 AND `Locale` = 'zhCN';
