UPDATE `broadcast_text_locale` SET `Text_lang` = '那些从天上滑落到坠星山的巨型水晶，隐藏着我们必须解读的迷团。' WHERE `Id` = 16427 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就要到了！让我们逃离这里！' WHERE `Id` = 16443 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '地狱火半岛是一个满目疮痍的区域——对那里的居民们来说，那是多么的残酷和艰难。确保在冒险前修理并囤积好补给品吧。' WHERE `Id` = 16451 AND `Locale` = 'zhCN';
