UPDATE `broadcast_text_locale` SET `Text_lang` = '他真是个可爱的小东西，真的。我想我会留住他的。' WHERE `Id` = 16539 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '加尔鲁什跟你说了些什么，$n？' WHERE `Id` = 16844 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不可能。他不能就这么放弃。为什么他会要求你取代他酋长的位置？' WHERE `Id` = 16846 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<盖亚安祖母点了点头，接受了你的回答。>$B$B我不能再和灵魂战斗了，$n。我的时日已经不多了。我必须再次感谢你所做的一切，虽然你也许无法改变加尔鲁什，但我的很多人民已经由于你的努力而重新树立了信心。他们现在非常希望能为我们氏族的生存而战。' WHERE `Id` = 16848 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<盖亚安祖母对你笑了笑。>$B$B你让我想起了我的儿子，$n。$B$B他曾是一座雄伟的山脉，一个代表着力量和荣誉的支柱。$B$B<盖亚安的眼睛里闪烁着泪花。>$B$B他为了我们的生存牺牲了自己，为了让兽人后代们可以出生在一个没有血之诅咒……没有古尔丹和他的黑暗部落的世界。$B$B<盖亚安凝视着远方，发着呆。>$B$B杜隆坦……我多么希望你能在这里啊，你的人民需要你……' WHERE `Id` = 16850 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<盖亚安祖母点了点头。>$B$B你认识我儿子？' WHERE `Id` = 16852 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<盖亚安祖母的那双紫罗兰色的眼睛盯着你。>$B$B而且……？' WHERE `Id` = 16854 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<盖亚安祖母泪如泉涌。>$B$B我……我……杜隆坦还有个孩子？德拉卡那孩子在他们离开前告诉我……他们最害怕的就是……让一个孩子在这样的世界中长大。那座门的对面曾是他们唯一的希望。我不敢告诉杜隆坦，但是暗地里，我祈求灵魂保佑他们——保佑他们的孩子，并赐予他们力量。$B$B我……我一定要看看我的孙子。我一定要看到他。请帮我这个忙，我太虚弱了。你必须在我离开这个世界前告诉他……' WHERE `Id` = 16856 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们不能让领袖失望！凯尔萨斯会拯救我们！' WHERE `Id` = 16861 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$C，不要打了，这只是个伪装！我是沙塔斯城贫民窟的间谍。$B$B我希望你是来这里帮我的！' WHERE `Id` = 16868 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '恕我直言，阿达尔派我来这里是为了调查凯尔萨斯的行动，而不是发动一次全力进攻。' WHERE `Id` = 16870 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我身边这些家伙都是白痴！' WHERE `Id` = 16874 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '魔导师会很高兴知道我对萨拉斯语很熟悉的。别摆出一副谦恭的模样，我不吃你这套。' WHERE `Id` = 16875 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '话过三句必跑题……我们应当把注意力放在这些法力熔炉上。我们需要知道敌人正在用它们做什么，以及为什么要这么做。' WHERE `Id` = 16876 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真酷。' WHERE `Id` = 16881 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘘……' WHERE `Id` = 16882 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们是非常开诚布公的！你忘了我们中的许多人都曾经是凯尔萨斯最信任的手下吗？' WHERE `Id` = 16883 AND `Locale` = 'zhCN';
