UPDATE `broadcast_text_locale` SET `Text_lang` = '%s拭去了眼泪。' WHERE `Id` = 17315 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，宝贝，爷爷去世了。一切都会好起来的。' WHERE `Id` = 17316 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我知道一切都会好起来的，宝贝。' WHERE `Id` = 17317 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '最终我们会团聚的，甜心。' WHERE `Id` = 17318 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '妈妈要确保你没事，宝贝。' WHERE `Id` = 17319 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '妈妈不会让任何人伤害你的，甜心。' WHERE `Id` = 17320 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你能相信虚灵的科技吗？！$B$B我当然愿意和他们待在这里。我会学到很多……也许还能给我自己弄一点！' WHERE `Id` = 17359 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我觉得你把肩部弄错了，不过看上去已经很不错了。' WHERE `Id` = 17439 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '采用这种技术进行工作让我非常头痛。所有东西都构造在一种怪异的方式上。' WHERE `Id` = 17469 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们没有教你们这些新来的家伙任何东西吗？这些法力熔炉是作为风暴要塞的一部分而建造的，用来吸取虚空中的能量。$B$B纳鲁用这个技术在旅途中给他们的飞船供给动力。有人说那技术在陆地上使用可能不安全，然而他们很快就沉默了。' WHERE `Id` = 17476 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '父亲？是你吗？' WHERE `Id` = 17518 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一个忽隐忽显的女性血精灵指挥官影像出现了。从周围的布置来看，她肯定在风暴要塞里。' WHERE `Id` = 17529 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那个血精灵看上去并不像一个魔导师，但是她很可能掌握着一些关于这座塔里诅咒的关键。' WHERE `Id` = 17530 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，亲爱的！这里发生了什么？' WHERE `Id` = 17536 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '时间流崩溃时，我们有五个特派员被困在里面。' WHERE `Id` = 17537 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '卡多雷的船呢？' WHERE `Id` = 17538 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '它在崩溃以后很快就撞毁了。我们正在检查它。' WHERE `Id` = 17539 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s点了点头。' WHERE `Id` = 17540 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '太迷人了。这是什么，安多尔姆？' WHERE `Id` = 17541 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '唔，他们正在破坏时间流吗？' WHERE `Id` = 17543 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我很讨厌你用那种态度和我说话。我和你在任何方面都是平等，兄弟。记住下次当你困在时间漩涡里的时候，不要哭着求我。' WHERE `Id` = 17546 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们应该这样希望吗？' WHERE `Id` = 17549 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s点了点头。' WHERE `Id` = 17551 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s在检查样品。' WHERE `Id` = 17556 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个样本正在逐渐消失。有什么东西或者什么人正在改变着时间流。' WHERE `Id` = 17557 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不能得到读数……有东西在妨碍我……' WHERE `Id` = 17558 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '流沙之鳞已经知道了吗？' WHERE `Id` = 17559 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们必须派出另一个观察者。必须维持平衡……' WHERE `Id` = 17560 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s请求支援！' WHERE `Id` = 17562 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '守住阵线！' WHERE `Id` = 17567 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……稳住……' WHERE `Id` = 17568 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阻止他们前进！' WHERE `Id` = 17570 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我似乎选择了个错误的日子来戒除法力吸取……' WHERE `Id` = 17571 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你，好心的$g先生:女士;！' WHERE `Id` = 17578 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我在这里，爸爸。你睡了一整天了。你一定是太累了！' WHERE `Id` = 17598 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s又去海滩玩耍了。' WHERE `Id` = 17599 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我从来没见过像虚空龙那样的生物。他们似乎继承了祖先的性格，但他们已经变得完全不同了。' WHERE `Id` = 17625 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$n。我会带你游览时光之穴。请跟紧我。' WHERE `Id` = 17656 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们不知道时光之穴是否一直都允许凡人进入。确切的说，我们不可能知道这一点，因为时光之王在永远地运动着，用他认为恰当的方式来改变我们的时间流。也许你现在所看到的东西，明天就不存在了。你也可能会在昨天醒来，然后对这个地方没有丝毫的印象。' WHERE `Id` = 17657 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这很奇怪，我知道……大部分凡人无法真正理解他们在这里看到的东西，他们所看到往往无法和他们的理解联系起来。' WHERE `Id` = 17658 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '作为时间的管理者，我们看管和照顾着诺兹多姆的领地。主人目前不在这里，这就意味着他正在尝试着剧烈地改变时间进程。主人向来不理会凡人的闲事，除了纠正其他人对时间的改变。他是非常反对这种行为的。' WHERE `Id` = 17659 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '对于普通的时间维护工作，时光守护者的力量是足够的。我们可以处理大部分普通的干扰。举个小例子来说，比如某些无赖法师们试图改变过去的一些东西来提升他们现在的身份和财富之类的事情，不在话下。' WHERE `Id` = 17660 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你看到的这些隧道被称为时间流。它们的数量是无穷的。当前在你们的现实中存在的那个就是主人所认为的“麻烦点”。这些麻烦点也许有着完全不同的内容，但是它们通常都有着相同的原因。它们的存在是同样的时间干扰所产生的结果，当你进入其中的一个麻烦点去冒险时，要牢记这一点……' WHERE `Id` = 17661 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '时间流目前是按照“小灾难”至“大灾难”的顺序排列着的。注意它们全部都是“灾难”，这意味着任何一个时间流的毁灭都会终结你们的世界，没有区别。我们把它们这样分类，只是为了让那些被派到这里来的英雄们和冒险者们知道自己的能力适合处理哪个时间流中的事务。' WHERE `Id` = 17662 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个时间流目前正处于极度的混乱中！我们派了一些人在里面努力恢复秩序。我所能告诉你的一点信息就是，萨尔的自由正在危难中。一个被称为永恒之龙的邪恶组织正在尝试阻止他的逃脱。我担心如果没有来自外界的帮助，一切都将无可挽回。' WHERE `Id` = 17663 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '关于这个时间流，我们只得到了很少的一点情报。萨艾特已经被派遣进去了。从和他的通信中，我们获知的情报是永恒之龙再次尝试改变时间。很可能他们的目标是破坏黑暗之门的开启？希望不是这样……' WHERE `Id` = 17664 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个时间流通向海加尔山，我们只知道这些。永恒之龙不顾一切地阻止我们的介入，因此我们对其它的事情丝毫没有头绪，凡人。索莉多米正在尝试着突破时间流的防守，但是迄今都没有成功。你或许是我们突破和解决这个冲突的唯一希望。' WHERE `Id` = 17665 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的时间正处在危险的边缘，$n。如果运气这种东西确实存在的话，我祝你好运。' WHERE `Id` = 17666 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在这里只有两条真理：首先，时间是混乱的，永远在不停地变化，并且可以完全改变。第二，感觉并不代表真实。' WHERE `Id` = 17667 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '请跟着我。' WHERE `Id` = 17668 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个时间流在塌缩后实现了重组，回归于往昔的斯坦索姆。什么样的事件正在其中上演呢？' WHERE `Id` = 17669 AND `Locale` = 'zhCN';
