UPDATE `broadcast_text_locale` SET `Text_lang` = '你好啊，$c。即使是现在，部落还在进攻战歌峡谷。你会和联盟并肩而战吗？' WHERE `Id` = 17747 AND `Locale` = 'zhCN';
