UPDATE `broadcast_text_locale` SET `Text_lang` = '别忘记去拜访虚空风暴52区的维克斯顿。作为热砂港搏击会的官方竞技场商人，他出售各种不可思议的物品给那些有着足够竞技场点数的家伙。' WHERE `Id` = 18290 AND `Locale` = 'zhCN';
