UPDATE `broadcast_text_locale` SET `Text_lang` = '安塔里恩说我是从大鸟上掉下来的，当我掉下来的时候他抓住了我……他真厉害！' WHERE `Id` = 20360 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '时光守护者感谢你的帮助。时间之王一定会为这个结果而感到高兴的……' WHERE `Id` = 20437 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死吧！等待你的只有死亡！' WHERE `Id` = 20449 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '给我们一个吻……' WHERE `Id` = 20450 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '外域的战争比我之前所经历过的任何战争都要惨烈。大部分受害者都是那些留在后方的孩子。$B$B现在，斯克提斯的鸦人对沙塔斯城的威胁进一步加剧，那里会有更多的孤儿需要照顾。这些孩子几乎已经看不到光明的未来。$B$B但是，你却有能力为他们做些什么。儿童周来了，$c，我恳求你给这些孩子的生活带来些乐趣和奇迹吧。' WHERE `Id` = 20451 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们到了吗？' WHERE `Id` = 20456 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈克乌！！！' WHERE `Id` = 20457 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '多尔南开始观察起这座石质建筑，并轻轻触摸起它的柱子来。' WHERE `Id` = 20458 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '感谢你带我到这里来看望哈克乌！' WHERE `Id` = 20461 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为什么外域不再叫作德拉诺了？' WHERE `Id` = 20462 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，哇喔！' WHERE `Id` = 20463 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '所有的冒险者都是都是从这里出发的吗？' WHERE `Id` = 20464 AND `Locale` = 'zhCN';
