UPDATE `broadcast_text_locale` SET `Text_lang` = '哦！好烫！' WHERE `Id` = 20486 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '多尔南缓缓走远。突然，她转过身来，带着敬畏的神情注视着对她施放了祝福的沃洛斯。' WHERE `Id` = 20487 AND `Locale` = 'zhCN';
