UPDATE `broadcast_text_locale` SET `Text_lang` = '多尔南在看到扎拉多姆时，下巴几乎都要碰到地上了。' WHERE `Id` = 20527 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哇，他真是个大家伙啊！嗯……怎么回事？救救我！' WHERE `Id` = 20528 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很高兴再次见到你，$c$n。多尔南一直在问起你。' WHERE `Id` = 20529 AND `Locale` = 'zhCN';
