UPDATE `broadcast_text_locale` SET `Text_lang` = '%s倒在了地上。' WHERE `Id` = 21317 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你在工程学上的造诣已经完全超越了我，我没有什么可以教你的了。我听说臭气熏天的奥格瑞玛里面有一位名叫罗克希克的工程师，他技艺精湛，应该能做你的老师。' WHERE `Id` = 21323 AND `Locale` = 'zhCN';
