UPDATE `broadcast_text_locale` SET `Text_lang` = '天空卫队需要长期补充以太鳐的储量。在你的帮助下，我们才能在天空翱翔。' WHERE `Id` = 21375 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得好！她各方面条件都挺不错的。谢谢你！' WHERE `Id` = 21376 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哇！更多需要训练的虚空鳐！' WHERE `Id` = 21377 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<安吉拉在地狱猎犬耳边低语着什么，直到她留意到你。>$B$B和其它地狱猎犬相比，基尔西的体型显得娇小许多，但是这并未影响到它。我相信外域会改变这一切的，基尔西，对吧？$B$B妈妈的小天使一定会成长为一头巨大凶猛的地狱猎犬！一定！' WHERE `Id` = 21417 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们必须在矿洞附近重建我们的要塞！' WHERE `Id` = 21452 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这一下是为了奈莎！' WHERE `Id` = 21489 AND `Locale` = 'zhCN';
