UPDATE `broadcast_text_locale` SET `Text_lang` = '太不走运了，哈尔弗丹。' WHERE `Id` = 22791 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈尔弗丹，你没有资格获得升华。你的灵魂将坠入湮灭的深渊！' WHERE `Id` = 22792 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '过来点，年轻人，我的耳朵已经不那么好用了，说话声音也不如以前洪亮了。' WHERE `Id` = 22807 AND `Locale` = 'zhCN';
