UPDATE `broadcast_text_locale` SET `Text_lang` = '这些都非常不错。非要从中选一个的话，真有点难以做决定。' WHERE `Id` = 22854 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好，我找到合适的号角啦。现在我要开始雕刻了，这恐怕会很难。我根本没听过雌雪人的叫声！' WHERE `Id` = 22855 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我已经把大部分基础图案雕刻好了，在完成雕刻之前需要测试一下。你愿意帮我测试吗，$n？' WHERE `Id` = 22856 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真高兴见到你！$B$B要做的工作还有很多，我们的时间偏偏不多了。' WHERE `Id` = 22878 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '雷管5000型超级大炮是一种代表世界最尖端技术水平的单人发射装置，它能以龙的速度将人发射出去。发明该设施的地精家族是家喻户晓的航空领域先驱，这种超级大炮已经成为了家族的荣耀！$B$B如果你想象鸟儿一样在空中翱翔，就去沙塔斯城的圣光广场找玛克希玛·雷管吧。她会把你发射到城外的小池塘去！' WHERE `Id` = 22886 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '伊雷娜低声呜咽着。' WHERE `Id` = 22908 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '菲纳特，嘘！' WHERE `Id` = 22985 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一切都会好起来的，菲纳特。别担心。' WHERE `Id` = 22986 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '菲纳特，别这样。我很担心亚伦的安危，你就别给我添乱了。' WHERE `Id` = 22987 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '对，我们都希望你能在要塞里安静地呆着。' WHERE `Id` = 22988 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '菲纳特！够了！' WHERE `Id` = 22989 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不如你试着独立完成那些工作，这样说不定你还能快点返回要塞呢。' WHERE `Id` = 22990 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '菲纳特，你给我安静一会儿。吵得我头痛。' WHERE `Id` = 22991 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '菲纳特，拜托！派特洛夫很快就会派帮手来了！' WHERE `Id` = 22992 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s显得非常虚弱！' WHERE `Id` = 23041 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你。我还以为我再也见不到我的姐妹啦！' WHERE `Id` = 23042 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我在哪里？发生了什么事？是你……救了我？' WHERE `Id` = 23043 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我就知道鲁莉尔蕾会派人来救我的！谢谢你，朋友，也帮我谢谢鲁莉尔蕾！' WHERE `Id` = 23044 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '探险者协会允许我跟他们一起来真是太好了。但是裂木森林和周边区域实在是太危险，我没带帮手就闯了进来，真是蠢到家了。' WHERE `Id` = 23052 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '把这些东西拼起来可真够难的！' WHERE `Id` = 23065 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '足骨……连接到髋骨！髋骨再……再连接到这里好了！嗯嗯……' WHERE `Id` = 23066 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '得把这些腐烂的部分切掉，我做东西只用最好的材料！' WHERE `Id` = 23067 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，别再弄丢了。' WHERE `Id` = 23069 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会很想念冬蹄营地的，但是我能理解灰烬图腾酋长做出的决定。我们没有能力永远维持家园这个温暖的港湾。' WHERE `Id` = 23073 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，你没看见我正要喝酒吗？' WHERE `Id` = 23085 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好，这个就行。我觉着……嗝儿。' WHERE `Id` = 23086 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小心我的钢锯，它会让你看到很多内在的东西，不是吗？' WHERE `Id` = 23089 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s呜咽着。' WHERE `Id` = 23118 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不！你不能这样！求你了！这是我们的孩子啊！' WHERE `Id` = 23120 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我……我会把它藏起来，直到我为它找到一个家，一个远离这里的家……' WHERE `Id` = 23122 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '需要为您准备好一切吗？' WHERE `Id` = 23152 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哇噢——你杀死了巨魔坏蛋不仅挽救了我的性命使我幼小而纯洁的灵魂免遭奴役还粉碎了他们企图利用我的力量来帮助他们统治艾泽拉斯世界的邪恶计划你冒着生命危险将我从死亡的边缘拉了回来因此不管你是谁也不管你从哪儿来我都要好好地报答你的救命之恩你相信我啦我会竭尽所能地报答你的……$b$b<阿什莉深深地吸了口气。>$b$b我希望你会喜欢糖果……' WHERE `Id` = 23153 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哇！你是怎么把那个大个子的巨魔坏蛋撂翻在地的呀可惜我连这个笼子的把手都够不着不然我肯定会跳到他身上狠狠地揍他一顿我要为那些惨死在他手中的俘虏报仇这个坏蛋可把我吓得够呛你帮了我这么大的忙我其实挺不好意思的不过能麻烦你过来打开牢笼吗？' WHERE `Id` = 23156 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哎咳……我觉得吧，在和那个恐怖的怪物艰难地打斗了这么久之后你花上点时间休息兼庆祝一番我绝对没有任何意见啊不过呢你最好别忘记我还在这里呢虽然我看上去个子玲珑不过我还是有能力报答你的恩情的……' WHERE `Id` = 23158 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我说……虽然我讨厌那种刚从死亡边缘捡回一条命就开始喋喋不休抱怨起来的家伙不过呢我也要提醒你我还被关在这个肮脏的笼子里呢如果你能放我出去的话我就可以和你一起分享打败那头恐怖的巨魔豹的喜悦啦……' WHERE `Id` = 23159 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我知道你们都在赶时间可能还需要去打败更大更危险的怪物不过如果你们肯费费神把我从这个笼子里放出去的话我一定会异常兴奋的所以要是你们愿意花上这么一点时间的话我就会很耐心……很耐心……很耐心地在这里等着哟……' WHERE `Id` = 23160 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '耶！我自由啦，自由啦！如果我现在就告诉你们我有多么喜欢你们应该不会太唐突吧我希望能快点找到我的包裹因为像你们这样当之无愧的英雄应该受到奖赏啦，你知道的，以此感谢你们这一路走来的艰辛……' WHERE `Id` = 23184 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '唔，或许是这个吧——顺便提一句，我有没有告诉过你“双响喇叭”法迪利克的事？有一次这家伙趁我搓火球时在我背后吓我。我们之所以叫他“双响喇叭”是因为，啊……当我没说吧。那次事件搞得妈妈非常生气，瞧，我的眉毛到现在也没长出来……' WHERE `Id` = 23185 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，酒保，再来一杯！' WHERE `Id` = 23186 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你洗过那个杯子吗……嗝儿？' WHERE `Id` = 23187 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '贾森，我能搅出更多的泡沫来。' WHERE `Id` = 23188 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯……你应该把这玩意儿送给派特洛夫制作炸弹！' WHERE `Id` = 23189 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '塞蕾丝，你这身衣服真漂亮。你太美啦。我爱你们……嗝儿！' WHERE `Id` = 23190 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我也爱你！' WHERE `Id` = 23196 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '莉丝安！莉丝安·怀特！她在哪儿？' WHERE `Id` = 23198 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别指望有谁会帮你！' WHERE `Id` = 23199 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '莉丝安！我敢打赌她又跑到井边做白日梦了！' WHERE `Id` = 23200 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<嘟囔>这身衣服真的很漂亮呢！<嘟囔>' WHERE `Id` = 23201 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我需要更多的铲齿鹿！' WHERE `Id` = 23202 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些码头工人又闹罢工了？！我需要那些补给物资！' WHERE `Id` = 23203 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s想要今天还有不少工作要做，不由地叹了口气。' WHERE `Id` = 23204 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你，甜心。我们也爱你。' WHERE `Id` = 23205 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，那里也没有——好吧，它一定在这附近啦。我有没有跟你说过离开那个臭烘烘的牢笼是件多么美妙的事情？笼子空间狭小不过我凭借灵巧的身段能在奔跑哟只是有时候我跑得太快了就跟飞檐走壁似的所以呢我决定在里面转圈子玩……' WHERE `Id` = 23206 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的包裹！终于找到啦这是我送你的礼物我真心希望你会喜欢它因为我要你们记住这刻美好时光一辈子都不要忘记啊我还希望你每次看到它的时候都能笑一笑要知道我是永远不会忘记你们的我迫不及待地想要回家告诉妈妈这次的冒险之旅啦……你觉得我这副耳环好看吗？' WHERE `Id` = 23207 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '孩子，看来你相当自信哦？如果你能在竞技场中占一席之地，我倒是可以送你点什么。是相当不错的东西呢，比克里希的那些破玩意儿好多啦。$b$b祝你好运。' WHERE `Id` = 23340 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦！差不多该有人来救我了……' WHERE `Id` = 23379 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我想我应该感激你。请收下这个。我不希望留着任何会让我想起这个地方的东西。' WHERE `Id` = 23380 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在我被抓住时，我从一名巨魔身上偷来了这枚咒符。或许你能利用它来对付这帮家伙。' WHERE `Id` = 23381 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我受够这个地方了。再见。' WHERE `Id` = 23382 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，终于！' WHERE `Id` = 23383 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在他们抓到我之前，我找到了这枚咒符。或许你能用得着……' WHERE `Id` = 23384 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我希望你能用得着它。必须阻止这群卑鄙的禽兽！' WHERE `Id` = 23385 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祝你好运！' WHERE `Id` = 23386 AND `Locale` = 'zhCN';
