UPDATE `broadcast_text_locale` SET `Text_lang` = '天哪，你就不能快点把水煮沸吗！' WHERE `Id` = 23399 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '该煮好的时候自然会煮好的！' WHERE `Id` = 23400 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯……苍蝇！好在现在我能尝尝它们的味道啦。' WHERE `Id` = 23405 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '能变回从前的样子真好，谢谢你。' WHERE `Id` = 23406 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '或许我这里有你感兴趣的东西？过来，看看有喜欢的吗？' WHERE `Id` = 23407 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我得走了，$n。再见。' WHERE `Id` = 23408 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '耶！我又变成女孩啦！' WHERE `Id` = 23411 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你救了我。我讨厌变成青蛙！' WHERE `Id` = 23412 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不喜欢和陌生人讲话，不过你看上去挺友善的。给，这是我被绑架前找到的小玩意儿。' WHERE `Id` = 23413 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我得走了。小心！' WHERE `Id` = 23414 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦！我恢复先前的美貌啦？太好了！我还以为要当一辈子青蛙呢。' WHERE `Id` = 23425 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '太可怕了。我的皮肤变得黏糊糊的，我的舌头还一直在舔着自己的眼珠！' WHERE `Id` = 23426 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你救了我。请收下这只巨魔货箱，就当作我们之间的回忆吧。' WHERE `Id` = 23427 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我再也不想看见这个肮脏的池塘了。谢谢你，$n。我永远都不会忘记你！' WHERE `Id` = 23428 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨！有什么我可以帮忙的吗？' WHERE `Id` = 23436 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯？这是什么？$B$B别浪费时间！' WHERE `Id` = 23456 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '奇怪，我还以为你从那些天灾军团成员身上找到了关闭瘟疫水晶的方法呢。$B$B$c，我建议你有所发现之前，返回海滩继续屠杀他们。' WHERE `Id` = 23458 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里是练习灭火技术的地方，为了被遗忘者！' WHERE `Id` = 23529 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好痛！好痛啊！！！' WHERE `Id` = 23531 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '亲爱的，我们得找到一块带温泉的好地方。' WHERE `Id` = 23605 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我可不希望在咱们的土地上遇见恐怖的狼、巨人或是丑陋的山羊。' WHERE `Id` = 23607 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我宁可屠宰那些骡子！我说，你为什么不带些牲畜来呢？' WHERE `Id` = 23609 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s摇了摇头。' WHERE `Id` = 23703 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们竟然如此对待那条地毯，可耻！' WHERE `Id` = 23704 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来，谷迪，我们去探险吧。' WHERE `Id` = 23709 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '威廉，山脊上长着一丛新鲜的草药。叫贝卡娜来采一下吧。' WHERE `Id` = 23712 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '拜托，叫她来呀。' WHERE `Id` = 23718 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，这些苹果实在太可口了！' WHERE `Id` = 23727 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的弟弟肯定想尝尝的。' WHERE `Id` = 23728 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨，威廉，什么事？' WHERE `Id` = 23730 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，谢谢你！我一会就去。' WHERE `Id` = 23731 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不用，我自己能搞定。谢谢你。' WHERE `Id` = 23732 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我最好在采集草药之前问清楚状况。我可不想再次被狼袭击。' WHERE `Id` = 23733 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '威廉真有趣。他常常脸红。' WHERE `Id` = 23734 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我相信，高贵的联盟士兵心里肯定惦念着其它更重要的事情。噢！艾蕾娜发现了一些草药，我去帮她采一下。' WHERE `Id` = 23735 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s将草药种植在附近。' WHERE `Id` = 23736 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯……好吧，小心点，他可能爱上你了。我也不太相信他那个姐姐……' WHERE `Id` = 23737 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，贝卡，把它们放在树丛旁的花园里就行了。要小心狼！' WHERE `Id` = 23738 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，愿艾露恩之光与你同在。' WHERE `Id` = 23767 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我非常乐意！

不要在我的墓碑前哭泣，
我不在那里，我没有长眠。

我是凛冽的寒风，
掠过诺森德的雪原。

我是温柔的春雨，
滋润着西部荒野的麦田。

我是清幽的黎明，
弥漫在荆棘谷的林间。

我是雄浑的鼓声，
飞越纳格兰的云端。

我是温暖的群星，
点缀达纳苏斯的夜晚。

我是高歌的飞鸟，
留存于美好的人间。

不要在我的墓碑前哭泣，
我不在那里，我从未长眠。' WHERE `Id` = 23769 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '亲爱的，快啦。你很快就会苏醒过来，艾泽拉斯世界将在恐惧中颤抖！' WHERE `Id` = 23795 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '苏醒吧，伊米隆国王。时机已经成熟，你很快就能重掌统治权。' WHERE `Id` = 23796 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '从沉睡中醒来吧，我的爱。有了巫妖王的支持，世界将因你而颤抖。' WHERE `Id` = 23797 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '仪式怎么要进行这么久？你的主子向我保证过，说有了你的帮助，仪式会快很多的！' WHERE `Id` = 23798 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '加倍努力！伊米隆国王很快就要苏醒了，接着他将登上王座！' WHERE `Id` = 23799 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '该死的泰坦诅咒了我们！伊米隆，我的国王，张开双眼吧！' WHERE `Id` = 23800 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是时候了，我的丈夫，我们的国王很快就能重新回到我们身边啦。我要和他一起铲除世间的蝼蚁！' WHERE `Id` = 23801 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '仪式进行得太慢啦。需要更多的祭品！' WHERE `Id` = 23802 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '“疯狗”约纳·斯特林要我整日整夜地打扫甲板。$B$B打扫甲板？！$B$B我是个法师，凭什么让我做这种杂事！就算要打扫，也该玩点新花样吧。' WHERE `Id` = 23814 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '安静点好吗？要是被人发现，我们就死定了。' WHERE `Id` = 23818 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，伙计！谁点了风味朗姆酒啊？小杰克，是你吗？' WHERE `Id` = 23819 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没事，甜心。这杯是免费的。' WHERE `Id` = 23820 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来点什么呢？朗姆酒？还是麦酒？$B$B或者你想尝尝别的？' WHERE `Id` = 23826 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你想公然和杰克叫板是吗？$B$B嘿，我得说着这绝对是个……愚蠢的决定。这会让你损失惨重的。我可不想冒着丢掉小命的危险去干这种一分钱都挣不来的破事。嗯，你最好等我跑远了再动手。' WHERE `Id` = 23828 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好啦，$n！这肯定管用！让我们好好打扫一下吧！' WHERE `Id` = 23831 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '瞧！一尘不染！' WHERE `Id` = 23832 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '约纳·斯特林这个蠢货迟早要害死我们。如果他多花点时间观察局势的话，就会明白在战争期间攻击职业海军是件多么愚蠢的事。' WHERE `Id` = 23852 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你最好快滚，$n。我不想和约纳的死扯上关系。$B$B他们还不知道我杀了以前的船长取而代之，我才能勉强坐稳头领的位置。' WHERE `Id` = 23853 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我非常伤心！就别开玩笑了！' WHERE `Id` = 23885 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没看见我正忙着吗？离我远点，别让科瓦斯基撞见了。' WHERE `Id` = 23954 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<高贵的弗拉斯卡萨赞许地对你点了点头。>' WHERE `Id` = 24010 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$r。$b$b我的商店终于开张了。希望你能找到你想要的东西！' WHERE `Id` = 24018 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好啊，$c。$B$B这里有很多事需要帮忙，不过在我得到所有必需的补给之前，我几乎什么都帮不了你。$B$B在我开始工作之前，必须得到足够的荆刺根须，不过目前只有$3223w%%的存量。你的帮助会对我的工作进展非常重要，真的。' WHERE `Id` = 24019 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '凯尔萨斯的军队就是从这里撤退到太阳之井的。他的一些走狗仍然残留在这里，燃烧军团以最不平常的方式奖赏着他们……' WHERE `Id` = 24022 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你有没有看到那些在岛上游荡的魔像守卫？只要对控制它们行动的水晶核心做一些小小的改动，就能让我们获得它们的控制权，用它们来保护战略要地。$b$b阳湾圣殿很快就会是我们的了，眼下我们的目标完成率已经达到了$3244w%%。' WHERE `Id` = 24023 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们成功地拿下了圣殿。我们可以继续转变这些魔像守卫，用它们来保护其它的战略要地。' WHERE `Id` = 24024 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的任务是在死亡之痕吸引敌人的注意力，这样我们的军队就可以拿下阳湾军械库了。虽然听上去并不像和恶魔直接交锋那么吸引人，但如果这能让我们赢下这场战争，那我一定会全力去做。$B$B我们的目标完成率已经达到了百分之$3233w。' WHERE `Id` = 24082 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们已经夺下了军械库，$n。尽管如此，我们仍然不能沾沾自喜，满足现状。燃烧军团不会就此停下他们的脚步。' WHERE `Id` = 24083 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎乘坐勇者号。不好意思，失陪……' WHERE `Id` = 24101 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我有点嫉妒维瓦·水歌了。为什么？他比我更优秀！' WHERE `Id` = 24105 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '对水手来说，这是个不幸的名字，是吗？' WHERE `Id` = 24109 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们发誓要全力保卫勇者号乘客。必须确保鲁瑟兰村至暴风城港口航道的安全。' WHERE `Id` = 24118 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不好意思，$r，我必须专心工作。' WHERE `Id` = 24134 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '对不起，除了与小精灵交流并向船长汇报我的发现之外，我没时间和其他人闲聊。请原谅。' WHERE `Id` = 24135 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$r。$B$B让我们开动起来！根本不要指望那些也许永远都到不了的补给。$B$B我需要一块铁砧才能为我们的军队提供装备，但是现在只完成了$3228w%%。$b$b等铁砧完成之后，我就可以为你锻造许多强大的武器装备了。' WHERE `Id` = 24149 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$n。$b$b我已经造好了铁砧，可以开始装备我们的军队了。这一步对我们来说非常重要，不过仍然有许多事需要去做。$B$B对你来说更重要的是：我可以制造新的武器装备了！也许你会对此感兴趣。' WHERE `Id` = 24150 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们已经拿下了港口，这艘船真的算是个不错的奖励。只不过她还不适合航海。$B$B对了，我得到命令去监视绿鳃海岸一带的纳迦。$B$B你觉得你能帮帮我吗？' WHERE `Id` = 24151 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你喜欢刺激，那可是我们船长最擅长的事了！我爱这份工作！' WHERE `Id` = 24161 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得好，$n。' WHERE `Id` = 24164 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你有多少净化过的金属，我就要多少。' WHERE `Id` = 24165 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '照这样下去，我们的人很快就会有最好的装备了。' WHERE `Id` = 24166 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你，$n！' WHERE `Id` = 24167 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你干得太棒了。你是不是以前当过铁匠？' WHERE `Id` = 24168 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有了纳迦的矿石和你提供的纯净金属，就可以铸造出一种几乎无懈可击的合金了。' WHERE `Id` = 24169 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你在这里所做的工作对我们有着不可估量的作用。' WHERE `Id` = 24170 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你帮我净化这些金属，$n。事情实在太多了，我根本没时间去做。' WHERE `Id` = 24171 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '准备靠港！' WHERE `Id` = 24236 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '先生，我的名字是……啊，算了……' WHERE `Id` = 24241 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '菲尔维兹先生，请你稍微慢点！' WHERE `Id` = 24242 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '顺便说一声，我的名字是考伯纳特！' WHERE `Id` = 24243 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '先生，你差点就把我的名字叫对了……' WHERE `Id` = 24244 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '先生，你几乎快要把我的名字说对了。' WHERE `Id` = 24245 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '先生，你至少得认清我的性别吧……' WHERE `Id` = 24246 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '铁鹰号是客船，并不是战舰！好吧，对我来说这仅仅是一份工作。只要王子肯付工钱，我就顺从那个喜欢自吹自擂的船长。$b$b不管怎样，欢迎上船。' WHERE `Id` = 24255 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我正在收集捐款，为那些在战争中牺牲的勇士们建造一座纪念碑。对我们来说，铭记这些为了取得胜利而牺牲的伙伴是非常有意义的。$B$B我们的目标完成率已经达到了百分之$3275w。' WHERE `Id` = 24267 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这座纪念碑不漂亮吗？对我们来说，铭记这些为胜利而牺牲的伙伴们非常有意义。我们永远都不能忘记战争的代价——即便是那些我们最终获胜的战争。' WHERE `Id` = 24268 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s大声地清了清喉咙。' WHERE `Id` = 24279 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '飞艇已经靠港。站好了！' WHERE `Id` = 24280 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的工作很辛苦吗？累得连我们靠港的时候你都没有力气站好？我是看着你的家族的面子上，才给了你这份差事。别让我后悔自己的决定。' WHERE `Id` = 24281 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎上船，$c。放下行李，享受你的旅程吧。在紫色公主号上，我们希望您心情愉快。如果你在船上有什么需要的话，船舱里有售货机可以为您服务。' WHERE `Id` = 24282 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '尽管从格罗姆高营地到幽暗城的航线平淡无奇，但是一路上的风景秀色宜人。可是这并不能成为工作时候睡着的理由。' WHERE `Id` = 24290 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要在还未准备好的时候就去战斗，$n。倘若你已经向我们证明了自己的能力……我就可以给你提供一些非常强大的装备。' WHERE `Id` = 24302 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别紧张。$n是来这里帮忙的，$g他:她;不是恶魔一伙的。' WHERE `Id` = 24309 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你没法保证自己能活下来，那么再强的武器对你来说也毫无意义，$c。' WHERE `Id` = 24354 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '火焰将在阴影中燃烧！' WHERE `Id` = 24423 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '萨洛拉丝向$n施放暗影新星。' WHERE `Id` = 24424 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '奥蕾塞丝向$n施放燃烧。' WHERE `Id` = 24426 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '铁锭快用光了！所以一块也不能浪费，明白吗？' WHERE `Id` = 24439 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊！这是谁啊，居然快把锡锭用光了？你们再浪费材料试试，别以为我是女人就不敢踢你们的屁股！' WHERE `Id` = 24440 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得不错。我们还在不断招募新兵，他们还等着用新武器呢。继续加油！' WHERE `Id` = 24441 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看上去不错嘛。挺好的。' WHERE `Id` = 24442 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '还不错。下次你在回火的时候可以试试我教你的窍门。' WHERE `Id` = 24443 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这样不行；冷却之后金属就会变脆。把它们熔了吧，还能做成弹药用用。' WHERE `Id` = 24444 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这就是技术啊！你一定要把其中的窍门告诉我。说定咯？' WHERE `Id` = 24445 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '奥蕾塞丝！你的火焰会在我心中燃烧下去！' WHERE `Id` = 24452 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿达尔，感谢您能给我这么一个说话的机会。我知道您的支持者们大多都厌恶我和我的手下对待穆鲁的方式。' WHERE `Id` = 24464 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但我认识到我们走上了一条错误的道路。那个被我们称为王子的男人背叛了我们。因为他对力量的渴望，他派出了魔血精灵攻击我们，还把穆鲁带去了太阳之井。' WHERE `Id` = 24465 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我……我不明白。您——和穆鲁——很久以前就知道会发生这一切？' WHERE `Id` = 24468 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我现在都明白了。从现在起，我不再效忠于逐日者家族的那个背信弃义的王子。' WHERE `Id` = 24474 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们会和您并肩战斗，阿达尔。' WHERE `Id` = 24477 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我以血骑士的佩剑起誓，击败基尔加丹，恢复银月城昔日的辉煌。' WHERE `Id` = 24484 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当他还是我们所敬仰的凯尔萨斯王子时，我们以为他的力量能引领我们的人民进入一个崭新的时代。' WHERE `Id` = 24485 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我还有一堆乱七八糟的事情要处理呢，但是我不会有丝毫抱怨。$B$B如果你还为自己身处部落自豪的话，就来帮我一把！' WHERE `Id` = 24540 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '灵魂在我们身边低语。你听见了吗，$r？' WHERE `Id` = 24547 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢不……他们禁锢了他的灵魂！' WHERE `Id` = 24683 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '先知！很高兴能与你重逢！' WHERE `Id` = 24686 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你准备好了，我就要进行下一阶段的训练了。' WHERE `Id` = 24700 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '菲兹兰克死命地催我，可我手里没有任何工具，这叫我怎么做事啊？！' WHERE `Id` = 24714 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '伙计，好啦。这台超级缩小射线枪原型机可供使用啦！' WHERE `Id` = 24715 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我……你是……$B$B<小穆图浑身颤抖。>$B$B你是来救我的吗？' WHERE `Id` = 24721 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你，$r。我……我知道如何才能回到父亲身边。请保护我，别让我受到伤害。' WHERE `Id` = 24746 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我能感觉到父亲的光环。他肯定就在这个方向……跟我来，$n。' WHERE `Id` = 24747 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '前方的迷雾出现了缺口。我们就要到了！' WHERE `Id` = 24748 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '爸爸！爸爸，我得救了！' WHERE `Id` = 24749 AND `Locale` = 'zhCN';
