UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，好啦。你瞧，这套战歌兽人伪装是不是很棒呢！它拥有完美的幻象效果，还散发着兽人那特有的气味！' WHERE `Id` = 24752 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '迷雾意味着死亡……它悄无声息，残酷冷酷。' WHERE `Id` = 24757 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '囚犯的鲜血都快抽干啦。马上给我抓些俘虏回来！' WHERE `Id` = 24794 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们得尽快塞满这些牢笼，否则玛里苟斯就会察觉！' WHERE `Id` = 24795 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我需要更多的俘虏！将艾泽拉斯世界那些毫无节制的施法者都干掉！别停手！' WHERE `Id` = 24796 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '往这些牢笼里塞满法师！这是玛里苟斯的命令！' WHERE `Id` = 24797 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的先祖懂得如何扰乱敌人的心智。我们可以利用这种能力找出天灾军团的弱点，或是杀死他们的指挥官。没有了首领的指挥，天灾军团很快就会败下阵来。' WHERE `Id` = 24800 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '慢点说，孩子。我还不熟悉你们的语言。' WHERE `Id` = 24804 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '请你小点声，$r。哈玛特老了，她需要休息。' WHERE `Id` = 24805 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会拿走的。怎么能让伟大的酋长被一堆兽皮吓得瑟瑟发抖呢。' WHERE `Id` = 24811 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是怎么回事呢？！' WHERE `Id` = 24812 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '回去做事！我已经摆平了来惹事的家伙。' WHERE `Id` = 24813 AND `Locale` = 'zhCN';
