UPDATE `broadcast_text_locale` SET `Text_lang` = '竟敢打扰我的工作？！胆小鬼，不敢露面吗！' WHERE `Id` = 24820 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '竟敢打扰我的工作？！胆小鬼，不敢露面吗！' WHERE `Id` = 24821 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好啦，$n。交叉手指，虔诚地祈祷好运降临吧！' WHERE `Id` = 24888 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '天哪，这玩意儿不行啊！我觉得有点……轻飘飘的。' WHERE `Id` = 24889 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '墨尔杜将转换器的输出装置修好了！' WHERE `Id` = 24952 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你知道自己在干什么吗？！' WHERE `Id` = 24953 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这台转换器是我们生存的关键。如果修不好它，我们就死定了！' WHERE `Id` = 24954 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是你不能让这玩意儿正常运转，我们就完蛋了！' WHERE `Id` = 24955 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我命令你服从号角持有者的意志！' WHERE `Id` = 24963 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好冷……' WHERE `Id` = 24964 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '所有人都死了……所有的生灵……' WHERE `Id` = 24965 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是厉害！你有没有觉得四肢无力？很虚弱吗？体内一阵潮热？' WHERE `Id` = 24992 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你，达拉然的朋友。' WHERE `Id` = 24995 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们不能在这里久留……靠近我，我们要转移到安全的地方去。' WHERE `Id` = 24996 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$r，处处小心啊。血孢平原生活着许多残忍的生物。' WHERE `Id` = 24999 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '把小鬼放出来！' WHERE `Id` = 25050 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你知道炼金师可以转化特定的宝石吗？玛尔娜和我讨论过这个问题。$B$B我深信只要能给她造好炼金台，就可以让她发挥自己的才干。这样一来我和她也就可以去制造那些被认为已经失传的宝石了。' WHERE `Id` = 25088 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们成功了，$n。玛尔娜已经学会一些非常特殊的宝石的转化方法了。我也已经知道了该如何好好利用它们。' WHERE `Id` = 25089 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个世界遭受了许多我们肉眼看不到的破坏。甚至是时间的通路都感觉有些异常。' WHERE `Id` = 25109 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你为我们做了很多。我来这里是为了执行一项重要的任务，不过如果你需要前往时光之穴的话，我很乐意带你去那里。' WHERE `Id` = 25110 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些石头应该是最后一批了。我们和耐普图隆部队的合作将会无懈可击。' WHERE `Id` = 25123 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的，猎潮者会对这项部署非常满意。火焰领主的威力将被削弱。' WHERE `Id` = 25124 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那么你们自己的准备做得怎么样了？冰霜之王会打开通往传送门的道路吗？' WHERE `Id` = 25126 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '卡希斯已经告诉我们了。我们已经进入了奴隶围栏，就等你们的冰术师了。' WHERE `Id` = 25127 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '盘牙水库的仪式将在埃霍恩完全准备好的时候唤醒它，炎魔之王和冰霜之王的冲突将会对这个世界的根基造成伤害。我们的最终目的终于就要实现了……' WHERE `Id` = 25128 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我现在只效忠于主人。' WHERE `Id` = 25195 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但我似乎迷失了……，我找不到回去的路。' WHERE `Id` = 25196 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '卡雷……卡雷？' WHERE `Id` = 25197 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噩梦结束了！法术被破除了！再见，亲爱的卡雷！' WHERE `Id` = 25198 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在让我们释放他们的灵魂，听一听他们要说些什么吧。' WHERE `Id` = 25204 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这消息太可怕了！' WHERE `Id` = 25211 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我绝不容许天灾军团将我们驱逐出这里！我们放弃了一切，准备在诺森德开始新的生活。$B$B我向你保证，我们会拼死抵抗的。' WHERE `Id` = 25212 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '等等，朋友们！送这只恶魔下地狱之前，我还有些事要问它。' WHERE `Id` = 25221 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '安薇娜在哪，恶魔？卡雷怎么了？' WHERE `Id` = 25226 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你必须说出他们的下落！' WHERE `Id` = 25227 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '说！我可不耐烦了！' WHERE `Id` = 25228 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '玛里苟斯大人……我……尽力了……' WHERE `Id` = 25229 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿加麦斯之门被攻破了！' WHERE `Id` = 25232 AND `Locale` = 'zhCN';
