UPDATE `broadcast_text_locale` SET `Text_lang` = '噢……$b$b我在哪儿？' WHERE `Id` = 25457 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '莱洛拉斯，很高兴能再见到你。' WHERE `Id` = 25463 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们得到了命运的青睐。玛里苟斯遭受了沉重的打击。当他清楚地认识到眼前的局势之后，肯定不甘心龟缩在相对安全的魔枢。' WHERE `Id` = 25466 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '莱洛拉斯，让他们做好准备吧。他们从未见识过玛里苟斯的力量。这次行动恐怕也只能暂缓他的计划。' WHERE `Id` = 25469 AND `Locale` = 'zhCN';
