UPDATE `broadcast_text_locale` SET `Text_lang` = '再见，莱洛拉斯。' WHERE `Id` = 25472 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '跟紧我，$n。我不能让你受到任何伤害。' WHERE `Id` = 25474 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '玛里苟斯！！' WHERE `Id` = 25475 AND `Locale` = 'zhCN';
