UPDATE `broadcast_text_locale` SET `Text_lang` = '你会成为部落出色的战士的。' WHERE `Id` = 25825 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们要夺回冰雾村，将阿努巴尔赶出我们的家园。' WHERE `Id` = 25826 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '最艰难的时刻已经过去了。我们很快就能推翻巫妖王的暴政。' WHERE `Id` = 25827 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '萨萨里安！你还活着！' WHERE `Id` = 25842 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我还以为……还以为你已经死了。' WHERE `Id` = 25843 AND `Locale` = 'zhCN';
