UPDATE `broadcast_text_locale` SET `Text_lang` = '凯尔多努斯，解决这场骚乱。将$n的徽记带回来给我。我要用$g他:她;的徽记装饰我的房间。' WHERE `Id` = 26025 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们已经洞悉了这场针对蓝龙军团的侵犯行动。很快，我就会吸干你体内涌动的生命能量！' WHERE `Id` = 26026 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你！' WHERE `Id` = 26056 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '和纳尔弗谈谈吧。让我们一次性解决这些傻瓜。' WHERE `Id` = 26078 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$c，你想回去？$B$B我可以派一条幼龙将你安全地送达目的地。' WHERE `Id` = 26099 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别小瞧我，我也能一箭射中野兽的眉心……而且是在两倍距离开外。' WHERE `Id` = 26110 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我宁愿死也不要变成你们那副模样！你们还是人吗？是……畜生！' WHERE `Id` = 26112 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你居然敢侮辱我的父亲。他比你勇敢得多。' WHERE `Id` = 26113 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$r。这是你首次踏上我们的圣地吧，让你目睹这样的情景真是抱歉。' WHERE `Id` = 26145 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '保护？为什么？那绝不是真理所在。不不不……要夺取！我现在终于明白了！' WHERE `Id` = 26176 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这帮铁矮人疯子！他们反复谈论要为“洛肯大人”效劳，但是据我所知，只有少数人接到他的指令而已。' WHERE `Id` = 26191 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那个没用的巨魔再度失败了。我的容忍已经到了极限！安希斯！给我打断他的腿！' WHERE `Id` = 26227 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我还没见过你如此迫切地想要给他人留下痛苦的回忆呢。这是进步呢……很好，去吧！' WHERE `Id` = 26229 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '殿下！请改派我去吧。' WHERE `Id` = 26230 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你……自作聪明的家伙……你想什么呢？打算夺取属于她的功劳吗？你以为她会被你蒙在鼓里？' WHERE `Id` = 26231 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '笨手笨脚的蠢货！' WHERE `Id` = 26273 AND `Locale` = 'zhCN';
