UPDATE `broadcast_text_locale` SET `Text_lang` = '%s叹了口气。' WHERE `Id` = 26278 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '对不起？就会说对不起？！我对你太失望了！' WHERE `Id` = 26279 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哎呀。我觉得这玩意儿起作用啦！真奇怪。' WHERE `Id` = 26280 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '凡人，当你在伊瑟拉的花园中走动时，请随时保持警惕。别轻易相信你所看到的一切。' WHERE `Id` = 26288 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '等我处理完收尾工作，就换个新助手！' WHERE `Id` = 26289 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你想获得永生吗？' WHERE `Id` = 26303 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$c，在这个黑暗的时代，我们必须铤而走险。' WHERE `Id` = 26317 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '黑暗就蛰伏在这片秀丽的山岭下。朋友，千万当心。' WHERE `Id` = 26323 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的食物和饮料储备已经出现短缺。恐怕我没什么能给你的。' WHERE `Id` = 26333 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你的帮助，$n。这些冰莓就当作你的劳动果实吧。' WHERE `Id` = 26334 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们不会忘记你的英勇行为，$n。你永远是暮冬城的客人。$B$B你愿意将这座旅馆当作自己的家吗？' WHERE `Id` = 26386 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小声点，$c。没瞧见我正穿着伪装为怨毒镇侦察吗？' WHERE `Id` = 26410 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你能带我离开这里吗，$C？' WHERE `Id` = 26438 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么叫我的日子到头了？！把话说清楚，不然我宰了你！' WHERE `Id` = 26449 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨，我在这儿！' WHERE `Id` = 26451 AND `Locale` = 'zhCN';
