UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，很快我们就明白了死亡在这片冰封之地意味着什么。诺森德弥漫着巫妖王的邪恶力量，这种力量甚至渗透每一寸土地！他唤醒了那些在战斗牺牲的将士，命令他们与我们为敌。$B$B复活的狮鹫骑士随同地面的亡灵大军对我们发动了枪林弹雨般的猛烈攻击。' WHERE `Id` = 26518 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你真贴心。喏，将这匹马牵到你的马厩去吧。' WHERE `Id` = 26521 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我整天都忙得不可开交。来，将这匹马牵到你的马厩去吧。' WHERE `Id` = 26522 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是一等一的好马呀。你要好好照顾它。' WHERE `Id` = 26523 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来，将这匹马牵到你的马厩去吧。替我向罗纳德问个好。' WHERE `Id` = 26524 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s迅速窜回了自己的洞穴……' WHERE `Id` = 26536 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '萨盖，蛛魔将要塞围得水泄不通啊。它们的数量简直无穷无尽。' WHERE `Id` = 26618 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没错……我昨天从采石场回收了一些军事物资，就是打算炸毁虫孔。' WHERE `Id` = 26620 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '希望能尽快埋好炸药。我们已经筋疲力尽了，只有炸毁虫孔，我们才能喘口气。' WHERE `Id` = 26621 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '萨盖，你瞧！是萨鲁法尔大王！他是布洛克斯的兄弟啊！他来帮助我们啦！' WHERE `Id` = 26623 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，不过这次希望你再当心一点！' WHERE `Id` = 26626 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小声点。别被那些野兽发现啦！' WHERE `Id` = 26635 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '萨盖，快瞧！是萨鲁法尔大王！他是布洛克斯的兄弟，他来帮助我们啦！' WHERE `Id` = 26690 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '等等！把刀放下。你为什么……为什么要听他们的呢。你和他们截然不同啊！' WHERE `Id` = 26719 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你。我……该离开啦。' WHERE `Id` = 26730 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要对敌人心存怜悯！港口是我们的！' WHERE `Id` = 26738 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要给联盟狗喘息的机会，杀光他们！' WHERE `Id` = 26739 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为部落的荣耀而战！' WHERE `Id` = 26740 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '畜生！快说！我的妹妹在哪儿，否则我不会放过你们的。' WHERE `Id` = 26884 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '安娅在哪儿？' WHERE `Id` = 26889 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '只剩最后一件事了。我必须知道阿鲁高的下落。' WHERE `Id` = 26890 AND `Locale` = 'zhCN';
