UPDATE `broadcast_text_locale` SET `Text_lang` = '保持警惕，$r。$b$b生命在这里显得尤其脆弱！' WHERE `Id` = 29866 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '飞船又不是因为我才坠毁的，为什么大家都朝我瞪眼？' WHERE `Id` = 29877 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '因格瓦尔！你这可耻的失败将警示所有巫妖王的仆从！你被诅咒了！站起来，重新执行主人的意志！' WHERE `Id` = 29980 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '多年来，血色十字军酿造的惨剧简直不尽其数。他们沦为了痛苦、狂热与谋杀的代名词。$B$B我不能再让这样的悲剧继续重演。你觉得呢？' WHERE `Id` = 30094 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s朝米克高维尔扑闪着大眼睛。' WHERE `Id` = 30121 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s哀怨地对米克高维尔叹了口气……又或者是对飞行器叹气？' WHERE `Id` = 30122 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s满怀希望地盯着飞行器……又或者她是在看米克高维尔？' WHERE `Id` = 30123 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '海德比武会是神圣的。获胜者将赢得终身陪伴托里姆的殊荣。' WHERE `Id` = 30125 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不知道元帅的下落。你去死吧！' WHERE `Id` = 30146 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你休想从我口中问出什么！' WHERE `Id` = 30148 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我要用你的内脏当早餐！' WHERE `Id` = 30149 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我要让你输得心服口服！' WHERE `Id` = 30151 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你可以杀了我，但是我绝对不会告诉你！' WHERE `Id` = 30152 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我是血色先锋军的一员！绝不会出卖自己的领袖！' WHERE `Id` = 30153 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你不过是黑锋骑士团的走狗。去死吧！' WHERE `Id` = 30154 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不知道他的下落。就算我知道，也不会告诉你——哪怕你杀了我！' WHERE `Id` = 30155 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我要用你的尸体装饰桅杆！' WHERE `Id` = 30157 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '被遗忘者在努力地研制治愈瘟疫的方法，希望以此拯救倍受侵害的联盟和部落成员；而我们则起誓消灭那些包围着各大主城的天灾军团浮空城。$B$B利用圣光的力量，我们能对巫妖王的造物造成重创，运气好的话，还能直接摧毁它们。' WHERE `Id` = 30159 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '越来越多的攻击者从加姆涌来。迅速埋设地雷！' WHERE `Id` = 30225 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '猛犸人越来越近了……' WHERE `Id` = 30226 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '已经能看见他们啦——停止埋设地雷！' WHERE `Id` = 30227 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们来了！炸死他们！' WHERE `Id` = 30228 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '还不错吧，但是多掌握点技巧总是没错的！你瞧，看我摆臀的动作……像这样！' WHERE `Id` = 30232 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '冰牙已经陪伴我经历过无数次战役。$b$b不要被她不穿护甲的表象迷惑了。她是我见过的最聪明的熊。' WHERE `Id` = 30259 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别再耽搁时间了！$b$b激烈的战斗在等待！' WHERE `Id` = 30260 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为布伦希尔达村的荣耀而战！' WHERE `Id` = 30261 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '冰牙非常勇敢，不穿盔甲也敢上战场。$b$b$n，或许她能让你鼓起勇气，面对即将到来的挑战。' WHERE `Id` = 30285 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的生命与灵魂中充斥着部落留给我的痛苦回忆。悲伤、绝望和牺牲已经成为历史。战争的怒火永远在我内心深处燃烧！' WHERE `Id` = 30327 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s一边做事，一边吹着口哨。' WHERE `Id` = 30328 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s幻想着王子与遥远的国度。' WHERE `Id` = 30329 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好啊！你想要购买渔具，还是学习垂钓的艺术？' WHERE `Id` = 30372 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别用那种眼神打量我。我理解你们的感受。但是卫兵还有平民始终向我投来怀疑的目光，这点令我难以忍受。$B$B为了履行对瓦里安的承诺，我却打算继续留在这里。他能以平等的态度看待我……联盟也应该用这种态度对待我的族人。$B$B天灾军团正在破坏暴风城的宁静，如果你看够了的话，不如去帮帮忙？' WHERE `Id` = 30390 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没时间闲聊了！如果船只被摧毁，联盟就只能在自己的家园与天灾军团作战，还怎么攻陷巫妖王的老巢！快去帮忙吧，杀掉那些亡灵！' WHERE `Id` = 30391 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我听说部落也在招募征战诺森德的军队。希望联盟和部落可以将矛头一致指向真正的威胁。你懂我的意思吧，我是说不要窝里斗。$B$B虽然以我的经验来看，实现真正的同盟不太可能。你们对我真是太“热情”了。$B$B<瓦莉拉生气地咕哝着。>' WHERE `Id` = 30392 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你敢？！斯利文男爵呢？我要和他说话！' WHERE `Id` = 30458 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是谁干扰了我的仪式？' WHERE `Id` = 30462 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '亲爱的将军，你的末日来临了！' WHERE `Id` = 30470 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得漂亮！到斯坦索姆的大门去，我会交给你下一项任务！' WHERE `Id` = 30509 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Casting kill credit at $n.' WHERE `Id` = 30520 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '举起' WHERE `Id` = 30585 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎你，$c。' WHERE `Id` = 30594 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '正在检索……造物主曾经亲自回来清除噬主共体生物所造成的感染。根据当时的评估，上古之神滋生所造成的危害非常严重。强行分离被感染部分将导致宿主损毁——' WHERE `Id` = 30603 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '正确。造物主决定中和寄生体的威胁，并将其封锁在宿主内部。之后，包括意志熔炉在内的各系统受命开始创造新的土灵。植入了新的安全机制，并任命了守护者。' WHERE `Id` = 30604 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '名称：艾塞尔与瓦尼尔。如果用通用语命名，则是风暴巨人与岩石巨人，最高领袖为哨兵洛肯。守护巨龙受命监管艾泽拉斯世界的进化过程。' WHERE `Id` = 30605 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '另有后台信息与你的问询关联：在艾塞尔和瓦尼尔的全面战争之后——' WHERE `Id` = 30606 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不详。数据显示，全面战争是由首席管理官洛肯发起的，他在此之后中和了所有残余的艾塞尔与瓦尼尔，结束了冲突。接着，他停止了包括土灵、巨人和维库人在内的数个源种生物的演化进程，并将他们全部封存在指定的封存仓内。' WHERE `Id` = 30607 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '本质上的确如此。' WHERE `Id` = 30608 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我要把你撕成碎片。' WHERE `Id` = 30661 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你想挑战？' WHERE `Id` = 30662 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你看上去并不强壮。' WHERE `Id` = 30663 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你觉得自己够格吗？' WHERE `Id` = 30664 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎你，我的姐妹。我能帮你找回失散的伙伴。' WHERE `Id` = 30666 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎你，我的姐妹。我能帮你看管宠物或是找回失散的伙伴。' WHERE `Id` = 30667 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '进来吧，我的姐妹。$B$B好好地吃上一顿，再睡个安稳觉，这样才能养足精力，全力备战！' WHERE `Id` = 30669 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '尝尝我的铁拳吧，小鬼！' WHERE `Id` = 30750 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '显然你输了。你还指望能怎么样呢？' WHERE `Id` = 30751 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别来打扰我。我正在研究那些“格斗者”的笨拙动作。$B$B我要将他们统统击败，然后我就会被提拔为巫妖王的部属了。' WHERE `Id` = 30752 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的，萨尔。时机已经成熟，我们要杀死阿尔萨斯。带上我的大药剂师同行吧。他的知识能帮助你解决天灾军团的麻烦。' WHERE `Id` = 30786 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '太好了……真是太好了。' WHERE `Id` = 30787 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里是神圣的献祭之厅！你们这些入侵者的结局只有死亡！' WHERE `Id` = 30789 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个绿皮肤的小鬼根本派不上用处。不过没关系，他可以在作战前充当热身的对象。' WHERE `Id` = 30805 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我什么都不怕——来吧！' WHERE `Id` = 30807 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '强者将获得胜利！' WHERE `Id` = 30808 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祝你好运……你需要的就是运气了！' WHERE `Id` = 30809 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你赢不了我的！' WHERE `Id` = 30810 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你不配与托里姆并肩作战！' WHERE `Id` = 30811 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '打得不错啊，小家伙。我输了。我们还会再见面的。下次我一定会做好充分的准备。' WHERE `Id` = 30821 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊！！！！我要宰了你！' WHERE `Id` = 30822 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你也想向巫妖王证明自己的实力吗？$B$B你不觉得这样的方式有点过时吗？非要争个你死我活吗？' WHERE `Id` = 30823 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，我认识你！我要感谢你把我送到这里。那次传送事故是我最美好的体验。$B$B如果你有机会回到北风苔原的话，告诉那个自以为是的复制品，我已经取得了相当大的成就！' WHERE `Id` = 30824 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真没意思！' WHERE `Id` = 30826 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '该谁说了算啊，嗯？' WHERE `Id` = 30827 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哟！！！' WHERE `Id` = 30828 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不再训练死亡骑士了，我受够了那些愚蠢的新兵和他们无穷无尽的提问。$B$B现在，请你走开。' WHERE `Id` = 30846 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们当中有谁愿意献身？' WHERE `Id` = 30862 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我曾经拥有一个温暖的家，它就坐落在奎尔萨拉斯苍翠的森林中。我还记得我的丈夫……还有孩子们的笑容。我曾经生活在这个美好的世界。眨眼之间，巫妖王夺走了这一切。$B$B虽然单凭我的力量根本不足以与他抗衡，但是总有一天，我要让他付出三倍的代价！' WHERE `Id` = 30919 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '还想活命的话，你最好小心说话。$B$B沉默？你真明智。去消灭天灾军团吧！' WHERE `Id` = 30929 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '萨尔想必对阿尔萨斯的行径倍感愤怒，但是比起我心中的怨恨来就微不足道了。如果他能体会被遗忘者的心情，我相信部落的大军会把怒火倾泻到诺森德，歼灭那片冰封荒野上的天灾军团。$B$B可惜我不是部落的领导者，不能下令开战。局势紧迫，萨尔却还在权衡利弊得失。不过，战争……已经到了一触即发的关头。' WHERE `Id` = 30930 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的遭遇全拜阿尔萨斯所赐。我要让他尝到被折磨的痛苦滋味。$B$B一直以来，我都盼望着被遗忘者能在诺森德与天灾军团决一死战，但是我们需要部落的支持。我们的军队数量严重不足，必须得到盟友的援助。$B$B阿尔萨斯对部落的这次进攻或许能让萨尔认清局势，最终决定对冰冠冰川宣战。那时，我会毫不犹豫地支持他。' WHERE `Id` = 30931 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s受到了黑女巫的拥抱的影响！' WHERE `Id` = 31019 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看看他们……他们一心只想超过别人。' WHERE `Id` = 31163 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你看，托里姆和这些鹰身人不同。他是近乎神的存在。$B$B他为泰坦们守护着奥杜尔和造物者圣台。$B$B直到他的妻子西芙被他的兄弟可鄙地杀害了。' WHERE `Id` = 31165 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '托里姆失去了理智。他将矛头指向了他的亲密战友，冰霜巨人。$B$B这导致了海德尼尔和霍迪尔之子至今仍在这片土地上互相攻伐……托里姆也因此离开了风暴神殿。' WHERE `Id` = 31167 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就算这些母狼和冰霜巨人天天对砍，那也不关我的事。$B$B不，不……我是想让托里姆振作起来，召集起所有的盟友夺回奥杜尔。$B$B如果他失败了，这个世界就会破碎的！$B$B当然了，我会支付给你足够的报酬的。' WHERE `Id` = 31169 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '男人——很难与他们相处，但是又离不开他们。好吧，也不是离不了……不过那样真的很无聊。' WHERE `Id` = 31175 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些矿洞真是太可怕了。幸好我不打算在这里待很长时间。' WHERE `Id` = 31176 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '熊是美丽的生物。野性、强壮、凶猛……就像我们一样。' WHERE `Id` = 31177 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谁在叫我……？' WHERE `Id` = 31190 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，伙计——很高兴有你陪在我身边！' WHERE `Id` = 31202 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，伙计——很高兴有你陪在我身边！' WHERE `Id` = 31203 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '伊尔斯卡领主，你接受了公平决斗的挑战，并且输了。' WHERE `Id` = 31215 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你显然还有所欠缺，并将受到制裁。站起来吧，被诅咒的伊尔斯卡领主！' WHERE `Id` = 31216 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '缝合场是天灾军团制造食尸鬼、憎恶和血肉巨人的中心。如果我们能摧毁这座工厂，巫妖王的力量就会被大大削弱。' WHERE `Id` = 31342 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们是托里姆的仆人。' WHERE `Id` = 31365 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '能在这片被遗弃的土地上见到你这样的英雄，真是令人愉快。我能帮你什么忙吗？' WHERE `Id` = 31369 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然可以！愿艾露恩祝福你。' WHERE `Id` = 31373 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨。我无意中听到了你们的谈话。请让我出一份力吧。' WHERE `Id` = 31380 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我正打算从达拉然返回银色前线基地。英雄，你愿意与我同行吗？' WHERE `Id` = 31381 AND `Locale` = 'zhCN';
