UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的道路是神圣的。我们宁愿死去，也不会背弃托里姆，与巫妖王同流合污。' WHERE `Id` = 32253 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '萨尔，出了什么事？国王正在备战……' WHERE `Id` = 32288 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '普罗德摩尔女士，酋长说的是实话。这是瓦里玛萨斯和大药剂师普特雷斯安排的诡计，并非部落的本意。' WHERE `Id` = 32290 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '自从联盟和部落进军天谴之门以来，幽暗城就发生了暴乱。瓦里玛萨斯和他的恶魔同党叛变了，残忍地杀害了数百名无辜的平民。我是好不容易才逃出来的。' WHERE `Id` = 32291 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会转告国王的，萨尔，但是……' WHERE `Id` = 32296 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '伯瓦尔与他情同手足。国王离开期间，是他维系着联盟的团结。在最艰难的日子里，他是人民的支柱。他监护着安度因，将其视如己出。' WHERE `Id` = 32297 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我担心国王克制不了心中的怒火，萨尔。希望我能说服他吧，但是我们必须做好最坏的打算……比如战争。' WHERE `Id` = 32298 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再见，酋长。希望下次见面时，我们能够成为盟友。' WHERE `Id` = 32299 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s吐丝结茧！' WHERE `Id` = 32303 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s朝四周喷射蛛丝！' WHERE `Id` = 32304 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '蛛网上爬出了小蜘蛛！' WHERE `Id` = 32305 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我能帮你什么忙吗？' WHERE `Id` = 32322 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我能为你做什么吗？' WHERE `Id` = 32325 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '战争的阴云已经迫近，$n。我们和部落都派了轰炸机进入轰炸船和失落希望之谷。你愿意参加这次行动吗？' WHERE `Id` = 32343 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n超乎寻常的作战技巧令龙骑士手忙脚乱起来。' WHERE `Id` = 32354 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '怎么回事？！' WHERE `Id` = 32355 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你战斗起来就像只野兽！' WHERE `Id` = 32356 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这一招你是从哪儿学来的？' WHERE `Id` = 32357 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哎呀！小声点，$n！怎么？你想把我们害死吗？！$B$B我当然知道你是谁！你的大名早就在联盟中传遍了！$B$B你觉得我的跳跃机器人怎么样啊？她是根据机械侏儒的原理设计的，运行起来非常流畅，是以空气为动力的！' WHERE `Id` = 32364 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s唱起歌来。' WHERE `Id` = 32427 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '该传送门通往时光之穴，它位于遥远的塔纳利斯沙漠地底。$B$B如果你要去那里的话，我可以将你传送过去。' WHERE `Id` = 32441 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '该传送门通往时光之穴，它位于遥远的塔纳利斯沙漠地底。$B$B但是你的力量还不够强大，我建议你不要去那里。' WHERE `Id` = 32442 AND `Locale` = 'zhCN';
