UPDATE `broadcast_text_locale` SET `Text_lang` = '好累！这些恶魔还真是顽固。' WHERE `Id` = 32991 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '*呼*我要喘口气……' WHERE `Id` = 32992 AND `Locale` = 'zhCN';
