UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢，这是我唯一能做的。我们需要同心协力。' WHERE `Id` = 35523 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我相信萨尔会管住他的部下……' WHERE `Id` = 35529 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这么长时间里，我们终于有机会研究散布在这里的废墟了……希望这些财迷不会先把这个地方毁掉' WHERE `Id` = 35678 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死吧，入侵者！' WHERE `Id` = 35680 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你不属于这里，$r！' WHERE `Id` = 35681 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的脚踏在神圣的土地上，$c……' WHERE `Id` = 35682 AND `Locale` = 'zhCN';
