UPDATE `broadcast_text_locale` SET `Text_lang` = '以黑暗之主的名义。为了巫妖王。你必死无疑。' WHERE `Id` = 35738 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们确认了你的力量，知道你正是我们需要的人。' WHERE `Id` = 35739 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '无能！' WHERE `Id` = 35740 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '天灾军团无人可挡……' WHERE `Id` = 35741 AND `Locale` = 'zhCN';
