UPDATE `broadcast_text_locale` SET `Text_lang` = '感谢你，传讯者，你的话真令我高兴。' WHERE `Id` = 35762 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愿圣光赐我力量，让我不负众望。' WHERE `Id` = 35763 AND `Locale` = 'zhCN';
