UPDATE `broadcast_text_locale` SET `Text_lang` = '狼人会消失。我们也会消失。$B$B只有大地和她的秘密会留存下来。你愿意学习吗，$n？' WHERE `Id` = 36059 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然，我会和你分享我的智慧。你可以借助这些智慧帮助我们击败狼人。' WHERE `Id` = 36068 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '教导你耗费了我很大力气。而为了让自己的心智适应奥术力量，你还需要经历许多个岁月的磨砺。' WHERE `Id` = 36069 AND `Locale` = 'zhCN';
