UPDATE `broadcast_text_locale` SET `Text_lang` = '这不可能！' WHERE `Id` = 36154 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们一定会复仇的！' WHERE `Id` = 36155 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，你做到了！实在是漂亮。' WHERE `Id` = 36161 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，$n，我们被困住了！' WHERE `Id` = 36192 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我想念科赞。我们还能再看到锈水码头吗，$n？' WHERE `Id` = 36193 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '和我一起坐一会儿。我们可以唱唱歌，在火上烤烤螃蟹。' WHERE `Id` = 36194 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我全都指望你了，但你怎样做才能让我们离开这座岛？' WHERE `Id` = 36195 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，很高兴再见到你。' WHERE `Id` = 36197 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你真可怕！我只想要妈妈！' WHERE `Id` = 36325 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是那种好狼人吗，$g先生:女士;？你有没有见到藏在外面棚屋里的辛西娅？' WHERE `Id` = 36326 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看看你周围，$c！$b$b这里难道不是非常美丽吗？' WHERE `Id` = 36332 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真的是你？我还记得这双眼睛。' WHERE `Id` = 36333 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你不会是认真的吧！难道你忘记了$n为我们做的一切？$g他:她;留下来……都是为了我们！' WHERE `Id` = 36335 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '无意冒犯，宝贝儿，但我的男朋友是奇普，而且现在我要听贸易大王的。$B$B赶快走吧，你挡住我的视线了。' WHERE `Id` = 36369 AND `Locale` = 'zhCN';
