UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，谢谢你救了萨尔。我们一直都找不到他。$B$B<阿格娜关切的看着酋长。>' WHERE `Id` = 36387 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，$n，你又救了我们！感谢你为我们消灭了那些恶棍！' WHERE `Id` = 36400 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '钩锤相信我能把事情做好。不能让这些琐碎的事情干扰他。' WHERE `Id` = 36404 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你准备好被缩小了吗？这也许有一点痛，还有一点烧灼感。不过疼痛和抽搐很快就会过去的。' WHERE `Id` = 36405 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '动作快一点， $n！几分钟之内，你就会回复到正常大小了。' WHERE `Id` = 36407 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别弄脏我的猫，你这个混蛋！' WHERE `Id` = 36421 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你必须要等候召见。' WHERE `Id` = 36446 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '敢来泰达希尔证明你还有些许勇气，上层精灵。但这里不欢迎你。上古之战的伤痛和那些战争背后的企图让我们铭心刻骨。' WHERE `Id` = 36447 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们不应该再次犯错。回到你的流亡族人中去吧。' WHERE `Id` = 36448 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要死盯着这月亮井，流亡者。井水中的能量不属于你们。' WHERE `Id` = 36449 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在回想你们的背叛吗？' WHERE `Id` = 36450 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小心点，上层精灵。' WHERE `Id` = 36451 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '等时机成熟吧。' WHERE `Id` = 36452 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$r。请不要太惊讶。我确实是在用你的语言与你交谈。$B$B虽然身为迅猛龙，但我的智力已经通过一系列试验得到了大幅增强。你可以称我为“九号实验品”，这是我的创造者们不久以前给我取的名字。不过现在他们要么消失要么挂掉了。也许你能帮我个忙？' WHERE `Id` = 36454 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '随着我认知能力的增强，我开始审视我们这个种族。我们的大部分精力都被用于捕捉猎物。我在想，为什么我们不能用这些时间驯服并圈养这些猎物，让它们成为我们稳定的食物供给？$B$B我认为人类是很好的食物来源——很快就能被养肥，而且味道鲜美，还能够进行训练，代替我们完成畜牧工作。嗯……' WHERE `Id` = 36455 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看样子你进行过不少冒险，$n。那些联盟软蛋手里可是有不少钱。' WHERE `Id` = 36477 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看样子你进行过不少冒险，$n。那些联盟软蛋手里可是有不少钱。$B$B想要进行训练吗？' WHERE `Id` = 36478 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨，$n。我很高兴能远离那些该死的猴子！' WHERE `Id` = 36479 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨，$n。我很高兴能远离那些该死的猴子！$B$B那么，想要对你的技艺进行一些磨砺么？' WHERE `Id` = 36480 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我要再重申一次，$n，我们之间工作关系的发展实在是令我感到高兴。在我的心智得到大幅度提升之后的几个星期里，我的地精恩人们开始了解到我的智力已经超越了他们。虽然他们仍然对此深表怀疑。$B$B很遗憾，正是由于我的祖先没能阻止最近这一系列的工业化“事件”，现在的我才能变得如此无所不能……' WHERE `Id` = 36486 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的心肝宝贝！' WHERE `Id` = 36487 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '永别了，艾泽拉斯。我离开了一个在大灾变中被污损毁坏的世界。' WHERE `Id` = 36489 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让我们点亮这根蜡烛！' WHERE `Id` = 36490 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '克拉伯尼克，你听到了吗？那些在门纳尔湖保卫战中牺牲的战士都是英雄。他们的无私也许拯救了全世界！我们应当郑重地纪念他们。' WHERE `Id` = 36494 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '克拉伯尼克？我希望你死了。被烈火烧成灰烬。' WHERE `Id` = 36495 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真高兴能再看到你，$n。而且一根毛都不缺。' WHERE `Id` = 36593 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎回来，$n。你很幸运。对于像你这样受到诅咒的人，克雷南的治疗方法并不总是有效的。' WHERE `Id` = 36618 AND `Locale` = 'zhCN';
