UPDATE `broadcast_text_locale` SET `Text_lang` = '奎尔德拉。' WHERE `Id` = 37484 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '巨龙铸造出奎尔塞拉，送给了卡多雷；而将奎尔德拉，送给了我们。' WHERE `Id` = 37485 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '国王将它赠予了我的朋友，萨洛瑞安·寻晨者。' WHERE `Id` = 37486 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但即使是萨洛瑞安的力量和奎尔德拉的魔力也无法从天灾手中拯救银月城。' WHERE `Id` = 37487 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为掩护族人逃生，萨洛瑞安在太阳之井的大门前壮烈牺牲。' WHERE `Id` = 37488 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '战后，我从战场上找回这把剑，为了我的王子，为了替我的族人复仇，我把它带到了诺森德。' WHERE `Id` = 37490 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿尔萨斯粉碎了我们，将我们最强大的战士变成他的爪牙，萨莱因。' WHERE `Id` = 37491 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '对萨洛瑞安的回忆已和他的剑一样冰冷。' WHERE `Id` = 37492 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是我将奎尔德拉带来，交给它的铸造者，只为打碎这把武器，消除它的力量。' WHERE `Id` = 37493 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '奎尔德拉只能有一个主人！' WHERE `Id` = 37494 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们这些蠢货胆敢闯入这里。诺森德的冰风将卷走你们的灵魂！' WHERE `Id` = 37511 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '躲到我后面来！快！' WHERE `Id` = 37540 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我以为他永远都闭不上嘴。但辛达苟萨让这个呱噪的家伙安静下来了。勇士们，向映像大厅前进！我能感觉到……目标已近。' WHERE `Id` = 37541 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s哭了起来。' WHERE `Id` = 37542 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s擦干眼泪，朝着瓦里安·乌瑞恩国王笑了笑。' WHERE `Id` = 37544 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没什么，陛下……我只是，为国王而自豪。' WHERE `Id` = 37546 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们没有时间可以浪费了，$c。为什么你在这停了下来？' WHERE `Id` = 37548 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们时间不多了，英雄。你需要些什么？' WHERE `Id` = 37550 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '站在这把杀害我的长剑面前……那种痛苦……仿佛又重新回来了。' WHERE `Id` = 37564 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是……不敢相信！霜之哀伤居然……无人看管，那个侏儒说的没错。来吧，英雄们！' WHERE `Id` = 37568 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就是这把剑终结了我的生命……那种痛苦……挥之不去。' WHERE `Id` = 37569 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不敢碰它。后退！后退，我要试着和这把剑交谈！也许我们的救赎就在其中……' WHERE `Id` = 37570 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '乌瑟尔……乌瑟尔·光明使者。怎么……' WHERE `Id` = 37571 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '巫妖王就在这里？那今天就是我完成使命的日子！' WHERE `Id` = 37572 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一定有办法……' WHERE `Id` = 37573 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谁能扛起这样的重担？' WHERE `Id` = 37574 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '冰封王座……' WHERE `Id` = 37575 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你别想轻易逃走，阿尔萨斯！我的仇一定要报！' WHERE `Id` = 37576 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这种刺骨的寒冷……血液好像都要凝结了。' WHERE `Id` = 37591 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看前面！那是什么！难道是？英雄们，到我身边来！' WHERE `Id` = 37592 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '霜之哀伤：正是它摧毁了我们的王国。' WHERE `Id` = 37593 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '后退！如果碰到这把剑，你的灵魂就会受到永恒的创伤！我必须试着与封印在霜之哀伤中的灵魂交谈。远离我，请再后退一点。' WHERE `Id` = 37594 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '乌瑟尔！亲爱的乌瑟尔！我……很难过。' WHERE `Id` = 37595 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿尔萨斯在这里？也许我……' WHERE `Id` = 37596 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但是，乌瑟尔，哪怕有一丝见到他的可能，我……我也要去。' WHERE `Id` = 37597 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '告诉我，乌瑟尔，我该怎样终结我的王子？我的……' WHERE `Id` = 37598 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是对的，乌瑟尔。原谅我。我……我不知道自己是怎么了。正在冰冠堡垒与天灾军团作战的国王和骑士们很快就会得到我们的报告。' WHERE `Id` = 37599 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谁能扛起这样的重担？' WHERE `Id` = 37600 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '也许还有希望……' WHERE `Id` = 37601 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你不能拒绝我，阿尔萨斯！我必须知道……必须明白……' WHERE `Id` = 37602 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你为什么要打断我，$c？' WHERE `Id` = 37618 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来吧，斩亡者。我会让主人知道，我们谁才配得上“勇士”之名！' WHERE `Id` = 37653 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '怎么选这种低能的盟友，科罗克！' WHERE `Id` = 37654 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是轻而易举的捕猎。希尔瓦娜斯一定会非常高兴的！' WHERE `Id` = 37672 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你怎么？！没关系，我不需要用陷阱来击败你。' WHERE `Id` = 37673 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在黑暗斥候击中你之前，使用贝瑞莎的护身符！$B$B|TInterface\\Icons\\inv_jewelry_talisman_10.blp:64|t' WHERE `Id` = 37674 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让塔多伦去安慰$n吧，就像达拉尼尔安慰那些因为受到诅咒，而放弃了平衡的信仰，变成野兽的德鲁伊一样。' WHERE `Id` = 37729 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿！过来，$n。' WHERE `Id` = 37731 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来吧，曼科里克，坐到我旁边来休息一下。' WHERE `Id` = 37740 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看看这片土地，曼科里克。部落和联盟之间争斗不休，也让这片土地满目疮痍。' WHERE `Id` = 37742 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这样的仇恨只会给我们带来毁灭。当你和那些野猪人作战的时候，我也能在你的眼睛里看到那种仇恨……你的愤怒只会让你变得衰弱。' WHERE `Id` = 37743 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你在毁灭你自己，曼科里克。' WHERE `Id` = 37744 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你在寻找的是逃避，不是光荣。这是自杀。' WHERE `Id` = 37746 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '因为……' WHERE `Id` = 37748 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '无论你是否在意，但这个世界里终究还是有人会因为你的死而伤心。' WHERE `Id` = 37749 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '求求你，曼科里克。放手吧，放下你的剑。' WHERE `Id` = 37751 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在……你不需要独自面对这一切。坐到我身边来，忘记你的困扰吧。哪怕一会儿也好。' WHERE `Id` = 37753 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果累了，就来我这里。' WHERE `Id` = 37754 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '凡间的勇士长久以来都在使用这些武器对抗着邪恶。我认为没有理由不让他们在这场战斗中使用这些剑。' WHERE `Id` = 37781 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '兄弟姐妹们，目睹太阳之井再度复苏的感受简直难以言表。' WHERE `Id` = 37809 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在那一刻，圣光为我揭示出我所犯下的种种罪过的真相。' WHERE `Id` = 37811 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的人民走上了一条黑暗的道路，而我在这条路上走得最远。' WHERE `Id` = 37813 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但圣光使我明白我并没有迷失。它帮助我找到力量，使我在经历许多后仍可幸存，即使我曾犯下如此重罪。' WHERE `Id` = 37814 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那是一种所有辛多雷成员共享的力量。我们需要这种力量来摆脱蹂躏我们人民的魔瘾。' WHERE `Id` = 37815 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这场将是我们遭遇过的最残酷的一场战斗，但我们的决心和太阳之井的力量将始终支撑我们重返巅峰。' WHERE `Id` = 37816 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当我们被像行李一样打包运到胶囊镇里的时候，他们对我们说的是我们将受雇前往艾萨拉的某地工作。这是艾萨拉吗？$B$B我问你：是谁搞出了胶囊镇，却又不在里面准备好足够的食物？！某个肮脏的变鸡器？！$B$B我们都知道机动战鸡的微型化是怎么实现的。' WHERE `Id` = 37854 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '安静点，蠢货。如果我要杀你，你早已经死了。' WHERE `Id` = 37894 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '元素混乱而且狂野。只有通过学习，我们才能保持和它们的联系并控制它们。' WHERE `Id` = 37932 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '暗矛巨魔在很久以前就和自然有着密切的联系，但直到最近，我们才了解到德鲁伊的技艺。 $n，你要尽量保持谦虚的态度。' WHERE `Id` = 37956 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在混乱的战场上，光与影的平衡将引领我们取得胜利。' WHERE `Id` = 37958 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要信任你的弓。当你需要它的时候，它绝不会辜负你。' WHERE `Id` = 37971 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当一切都已失去，自然仍然会指引你。' WHERE `Id` = 37972 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真聒噪……' WHERE `Id` = 37984 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愚蠢的凡人。你以为能轻易打败我们？萨莱因是巫妖王永生的战士！现在他们将合力撕碎你！' WHERE `Id` = 37997 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '去死吧！' WHERE `Id` = 38014 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '彻底毁灭吧！' WHERE `Id` = 38016 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '灵魂的汹涌不会被削弱！一切都只是徒劳。' WHERE `Id` = 38018 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看这深渊，那里有你的末日。' WHERE `Id` = 38020 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '对于所有反抗巫妖王的人来说这都是个伟大的日子！以银色盟约的名义，勇敢的$n已经拿起了古剑奎尔德拉。' WHERE `Id` = 38035 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '今天，一名真正的英雄来到了你们的面前，他是一名十字军战士、是一名斗士！银色盟约的$n，他已将古剑奎尔德拉取回，这象征着我们击败巫妖王的决心！' WHERE `Id` = 38039 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你做了一个……愚蠢的……决定。' WHERE `Id` = 38048 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就咬一小口……' WHERE `Id` = 38053 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我饿了！' WHERE `Id` = 38058 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死亡是逃不掉的！' WHERE `Id` = 38060 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死吧！' WHERE `Id` = 38061 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你受得了吗？' WHERE `Id` = 38062 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就要来了……' WHERE `Id` = 38063 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '多么的……不幸啊。' WHERE `Id` = 38064 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '对！吃吧，宝贝！你是我的了！' WHERE `Id` = 38065 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真的……？你就这点能耐？' WHERE `Id` = 38066 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是可怜。' WHERE `Id` = 38067 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一切都结束了！' WHERE `Id` = 38068 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是的……我们相处得……那么……好……' WHERE `Id` = 38069 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '站起来，兄弟们，消灭这些敌人！' WHERE `Id` = 38079 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '今天，一名真正的英雄来到了你们的面前，他是一名十字军战士、是一名斗士！夺日者的$n，他已将古剑奎尔德拉取回，这象征着我们击败巫妖王的决心！' WHERE `Id` = 38084 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '长官，这真是天才的主意。你的智慧总是让我感到吃惊！' WHERE `Id` = 38119 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这蛋可真大！掉转变鸡器的电极。我们得把它推进传送口里。' WHERE `Id` = 38141 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就这样吧。应该用不了多久……' WHERE `Id` = 38142 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '朋友们，帮帮我。让我们召唤卡尔加的幻像。' WHERE `Id` = 38159 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一切都结束了。' WHERE `Id` = 38179 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不敢相信这是真的——因为巫妖王已经愚弄我太多太多次了。' WHERE `Id` = 38180 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他对我们犯下累累罪行，现在他终于付出了代价。' WHERE `Id` = 38181 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愿艾泽拉斯不要忘记那曾因软弱和傲慢所付出的沉重代价。' WHERE `Id` = 38183 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但现在呢，英雄？那些摆脱了他的束缚，却无法摆脱凡尘俗世的人呢？' WHERE `Id` = 38184 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '退下。' WHERE `Id` = 38185 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的思绪很乱。' WHERE `Id` = 38186 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没有了血，阿迦玛甘将无法再次崛起！他的躯体在渴求祭品！' WHERE `Id` = 38188 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '走！去夺回我们的土地！当野猪人得到了一切，我们也将得到我们所要的。阿迦玛甘将再次崛起！' WHERE `Id` = 38189 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这就是他对我说的……去战斗！' WHERE `Id` = 38190 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我明白了……她在利用他操纵他们所有人……' WHERE `Id` = 38191 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是什么？' WHERE `Id` = 38201 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这……他还留着？一直以来，他还带着它？' WHERE `Id` = 38202 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我知道！' WHERE `Id` = 38203 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我还能感觉到他！饱受摧残……苦苦挣扎……啊，阿尔萨斯！' WHERE `Id` = 38204 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '也许……也许有一天，他会想起真正的自己。' WHERE `Id` = 38205 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '圣光啊，愿他摆脱那把魔剑的寒冷束缚，魂归故里。' WHERE `Id` = 38206 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你真弱，沃金，跟你的父亲一样弱。今天，我将结束这场久远的战争——暗矛巨魔将被彻底扫除干净！' WHERE `Id` = 38294 AND `Locale` = 'zhCN';
