UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$c。我们萨满祭司聚集在火石岗哨，照看这片土地，治疗它受到的伤害。' WHERE `Id` = 38312 AND `Locale` = 'zhCN';
