UPDATE `broadcast_text_locale` SET `Text_lang` = '我厌倦了你的把戏，阿尔萨斯！你的冰墙阻挡不了我！' WHERE `Id` = 38542 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们这些恶魔拦不住我们！挡住那些亡灵，我在努力摧毁冰墙！' WHERE `Id` = 38543 AND `Locale` = 'zhCN';
