UPDATE `broadcast_text_locale` SET `Text_lang` = '给食人魔喜欢的东西。给食人魔觉得有趣的东西。' WHERE `Id` = 38802 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s叹了口气。' WHERE `Id` = 38803 AND `Locale` = 'zhCN';
