UPDATE `broadcast_text_locale` SET `Text_lang` = '下士是个好人，但一执行命令就变得鼠目寸光。$B$B这地方好像有什么不对劲，$n。这片丛林不该出现在这里！' WHERE `Id` = 38963 AND `Locale` = 'zhCN';
