UPDATE `broadcast_text_locale` SET `Text_lang` = '是否做好开始的准备了？' WHERE `Id` = 39150 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好，跟着我。' WHERE `Id` = 39153 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在该是开始的时候了。' WHERE `Id` = 39154 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '代弗林·阿加曼德！听我说！' WHERE `Id` = 39155 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你在凡间的遗骸已经被收集完整，被放置在这个你渡过童年光阴的地方！' WHERE `Id` = 39156 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '代弗林，抵抗巫妖王的意志！到我们这里来吧！' WHERE `Id` = 39157 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我最好回到我的岗位上去。如果有需要，你可以在楼下找到我。' WHERE `Id` = 39158 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$c，现在我有一点忙……等我有空的时候再来找我吧。' WHERE `Id` = 39159 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你，$n！现在我可以开始最终的装配了……' WHERE `Id` = 39168 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好了……结构？确认。能量？确认。危险？双重确认。让我们发射我的杰作吧！' WHERE `Id` = 39169 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的装备在这里受到了真正的打击！' WHERE `Id` = 39170 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '胡说！微型化才是战争的未来。' WHERE `Id` = 39177 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我应该说一下。我翻转了变速箱，以适应变小的整体外形。' WHERE `Id` = 39179 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死者的鲜血依旧在呼唤着公正的到来。' WHERE `Id` = 39182 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '战斗之痕是一个危险的地方。当大地把一辆蒸汽坦克吞下去的时候，就算是全世界最好的护甲也保护不了它。' WHERE `Id` = 39190 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们要创造的是超越这个时代的东西，$n。$B$B看看这些蓝图！这就是世界的未来。' WHERE `Id` = 39191 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然，这里面还有不少的错误要解决。但微型坦克绝对是工程学上的一大奇迹。$B$B它只需要攻城坦克四分之一的制作材料，而且能够由任何人进行大规模生产！……呃，只要你有一双精巧的小手！' WHERE `Id` = 39192 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '记住我的话，锈水财阀终将在这里稳稳地扎下根来。' WHERE `Id` = 39193 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<克拉莉斯看着这具尸体，目光显得苍白而空洞。>$B$B我一得到消息，就从塞拉摩岛马不停蹄地赶到这里。$B$B约翰和我一直在讨论，等战争结束以后就定居下来。$B$B我觉得这场战争永远也不会结束，你觉得呢？' WHERE `Id` = 39194 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '也许这是岛上唯一凉快的地方了……虽然它就在火山的旁边！' WHERE `Id` = 39205 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你要到那里去？我可不打算回去了！' WHERE `Id` = 39216 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里本来是一个美好而又安全的地方。但前面那片空地上突然就出现了一支侏儒军队。$B$B如果我们让那些卑鄙的小个子在这里打赢我们，加里维克斯一定会要我的脑袋。' WHERE `Id` = 39226 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好了，我们现在要离开这座正在爆炸的火山，尝试和兽人们取得联系，对那个贸易大王发动最后的攻击。希望到时候能再见到你。' WHERE `Id` = 39240 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们必须在火山真正爆发之前救出所有人，并离开这里！' WHERE `Id` = 39258 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我有主意了！' WHERE `Id` = 39259 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是精彩！你学得很快，我的学生。' WHERE `Id` = 39264 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不——！' WHERE `Id` = 39297 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们可不是你的系统的一部分！' WHERE `Id` = 39312 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s看上去很虚弱！' WHERE `Id` = 39333 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '杀掉那个地精，赶快！' WHERE `Id` = 39341 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这么多数据……这么点时间……' WHERE `Id` = 39358 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '旋翼机全都起飞了。你准备好进行空中勘察了么？' WHERE `Id` = 39359 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真有趣，即使在距离震中如此遥远的地方，艾泽拉斯的外表还是彻底被撕碎了。' WHERE `Id` = 39361 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些都是什么？在上周进行勘察的时候，这片丛林还没有出现。贫瘠之地发生了什么？' WHERE `Id` = 39362 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是海水。海洋也被扯开了。你认为这道裂缝还在变宽吗？' WHERE `Id` = 39363 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '固守阵地。北方城堡的城墙被打破了！我们遭到了攻击！' WHERE `Id` = 39364 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '教练在这里？！他一定有办法的！' WHERE `Id` = 39365 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些伐木机是从哪里来的？' WHERE `Id` = 39389 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我已经厌倦在水里跋涉了。让我们给自己找点儿便利吧，好吗？流水之灵，快来帮助我们！' WHERE `Id` = 39452 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '瞧，这样不就好多了？' WHERE `Id` = 39453 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '拉格兰，我安全了。' WHERE `Id` = 39454 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那我们出发吧。带我去我的孙子拉格兰那里。' WHERE `Id` = 39456 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不！我——我的脚踝！我不确定自己是否能做到……我们已经走了这么远……' WHERE `Id` = 39457 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '空气之灵！快来帮我！' WHERE `Id` = 39458 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我想我们现在可以继续了。继续前进。' WHERE `Id` = 39459 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们其余所有人都在那下面！' WHERE `Id` = 39464 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可是，宝贝儿……？' WHERE `Id` = 39465 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的真诚很让人感动，德鲁伊。' WHERE `Id` = 39467 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不配受到如此尊重或敬仰，德鲁伊。我背叛了自己的土地。这片土地的疾患都是我的错。' WHERE `Id` = 39470 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '疾患来自翡翠梦境内部的梦魇，巨龙泰拉尔对其进行了散播。现在的他就是从前自己的癫狂镜像，要亲眼看着这片土地被吞噬殆尽。' WHERE `Id` = 39471 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不敢亲自去面对他。仅是靠近他，就有让同样的腐化再次将我打倒的危险。' WHERE `Id` = 39472 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '大地在因痛苦而啜泣。收集它的眼泪，用它们去封闭位于符印巨树的传送门。与梦境的联结必须被割断。' WHERE `Id` = 39474 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一定要勇敢，英雄们。' WHERE `Id` = 39475 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '暮光之锤是起决定性作用的力量。因为我们，死亡之翼自由了。因为我们，上古之神从大地深处重生。因为我们……海加尔在燃烧。$B$B你觉得你能为我们做什么？' WHERE `Id` = 39480 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在的整个局面都非常不利。你必须把贸易大王找回来，$n！' WHERE `Id` = 39483 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别担心我们，$n。你只要过去那边，确保解决掉贸易大王就可以了。' WHERE `Id` = 39484 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是来帮忙的吗，$c？这个山谷就是个天然的阻塞点。要是我们能扼住这条补给线，就能为我们在世界之树的同伴争取时间来发起反击。' WHERE `Id` = 39493 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不明白这些补给品是从哪儿来的。暮光之锤不知想出了什么办法，同时对整座圣山发起攻击……' WHERE `Id` = 39494 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你想要什么，$r？' WHERE `Id` = 39518 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '动作快，$n！萨尔需要你的帮助！' WHERE `Id` = 39527 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '戈杜尼食人魔已经破坏这片土地相当久了。我们来这里，就是要为部落夺回这片土地以及它丰富的资源！' WHERE `Id` = 39544 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '石槌部族效忠于部落！$B$B在奥格瑞玛建立期间，当我们的族人努力将卡利姆多改造成我们的家园时，英雄雷克萨击败了石槌食人魔部族的首领。$B$B从那时起，他们便发誓为部落效忠，我已经将他们召集至此，铲除戈杜尼部族。' WHERE `Id` = 39546 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看来就这样了，$g阁下:女士;。这真是我的荣幸。相信我们很快就会再见面。$B$B当你准备好动身前往奥格瑞玛时，告诉我一声。' WHERE `Id` = 39594 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这可真是个漫长的旅程啊，宝贝儿。谢谢你！$B$B现在让我们离开这座岛吧。' WHERE `Id` = 39600 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是位真正的$g大英雄:女英雄;，$n！是锈水财阀的偶像$g帅哥:美女;。$B$B我们的股价将一路飙升，而我也能得到加薪了！' WHERE `Id` = 39602 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '锈水财阀的未来看起来可不乐观。一点儿也不。$B$B你必须帮我们及早抽身，$n，否则我们不如直接跳进那边的火山里算了。' WHERE `Id` = 39603 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '喔天哪，你做到了，$n，你真的做到了！$B$B现在，根据我的估计，如果我们不在最短最短的时内里起航，那堆巨型火山石从天而降，把快艇击成碎片的可能性会越来越大。$B$B出发吗？' WHERE `Id` = 39604 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是一团糟！我该怎么旋转这个？$B$B这是真的吗？僵尸地精？！！' WHERE `Id` = 39607 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你知道你为我们节省了多少宝贵的时间和金钱吗，$n？这原本有可能成为一场彻底的灾难，而你单凭一己之力就拯救了整个财阀。$B$B你和萨尔就这么放过了加里维克斯真是太可惜了。我想你肯定能成为一位杰出的贸易$g大王:女王;！' WHERE `Id` = 39622 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没人能取得你的成就，$n。可我不明白为什么你没把加里维克斯拉下马。你本该接替他的职位。$B$B希望我们能顺利在艾萨拉安下新家。我盼望着能早点儿退休呢。' WHERE `Id` = 39623 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愿大地母亲时刻护佑你，$n。谢谢你的帮助。' WHERE `Id` = 39633 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看来就这样了，$g阁下:女士;。这真是我的荣幸。相信我们很快就会再见面。' WHERE `Id` = 39637 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没错，我曾在这里见过你！我怎么会忘记呢？$B$B如果你愿意的话，我可以立刻把你传送到斯坦索姆去。' WHERE `Id` = 39668 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '船长！右舷下方发现船骸，好像还有幸存者！' WHERE `Id` = 39672 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '彻底击败她们，兄弟姐妹们！' WHERE `Id` = 39696 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么？我甚至不知道你在说些什么！这太恐怖了！' WHERE `Id` = 39712 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，你们从狼神小径救出来的那些暮光奴隶进了营地，可他们无法讲明他们的身份，语言也含混不清。$B$B我原本以为暮光之锤是以古老的方式对待奴隶——你知道，就是鞭子和锁链那种——但很显然，他们还加入了洗脑的步骤……' WHERE `Id` = 39727 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '运气怎么样？试着和那些被解救的奴隶交谈真让我头痛不已。$B$B他们口齿不清的发着刺耳的噪音，然而还很押韵。' WHERE `Id` = 39736 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你的帮助，$n。' WHERE `Id` = 39737 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哨兵部队在卡利姆多各地阻挡部落的攻势。当灰谷与石爪山相继被战火席卷之时，这里也需要我们的帮助——我们要保护那些仅存的野生动植物，并阻止我们的敌人攻占更为纵深的据点。' WHERE `Id` = 39743 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为何来这里打扰我们，陌生人？' WHERE `Id` = 39753 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要害怕，$c。我们全心接受所有寻觅真相的人。' WHERE `Id` = 39754 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，我不能回奥格瑞玛。我也在为家人伤心，但他们已经做出了选择，我也做出了我的选择。我的未来在这里，在我的兄弟姐妹中间。' WHERE `Id` = 39760 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不会离开的。告诉我的家人，我在这里很好，也希望他们过得好。' WHERE `Id` = 39762 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有一天，我也会升华。' WHERE `Id` = 39763 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在这样一座大城市里，注意到元素发出警告的人却屈指可数，这真令我感到惊诧。' WHERE `Id` = 39764 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不认识你，你刚到这里吗？' WHERE `Id` = 39823 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，看来你是个新人。这些装置是我们主人改造世界计划的一部分。它会向整个世界释放出审判的烈火，并让我们得到永恒的生命。这是主人对我们许下的承诺。' WHERE `Id` = 39825 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你不属于这里，陌生人。别惹麻烦，赶快离开吧。' WHERE `Id` = 39826 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '泰拉尔并没有逃离菲拉斯。而是以自己的方式充当着连通恶梦的管道。' WHERE `Id` = 39828 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不会再逃离。到东边的山峰顶上找我。' WHERE `Id` = 39829 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我来这里是为了研究灵魂精华——野性魔法的作用方式。巫医尤克里派我来从森林里的低等生物入手。' WHERE `Id` = 39920 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在主人的烈焰中燃烧吧！' WHERE `Id` = 39925 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '擅闯者死！' WHERE `Id` = 39932 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '本该如此……' WHERE `Id` = 39933 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '海里昂会高兴的。' WHERE `Id` = 39934 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们向艾森娜发出的祈求没有得到回应。拉格纳罗斯麾下的燃烧爪牙已经将我们逼到了悬崖的边缘。如果我们不能在此终止他们的行径，世界之树将被大火烧得只剩下残桩断枝！' WHERE `Id` = 39953 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '生命的希翼已被斩断。$B$B梦游者一定会复仇的。' WHERE `Id` = 39954 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '走上前来，泰拉尔！我就站在你面前！' WHERE `Id` = 39956 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我回来只为了结这件事，泰拉尔。这片土地终将获得平静。' WHERE `Id` = 39959 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你到这里来是为了打扰我们吗？我们只想在静瑟中独处。' WHERE `Id` = 39960 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '多谢你，$c。$b$b我差一点儿死在那了。' WHERE `Id` = 39984 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是……' WHERE `Id` = 39986 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎你，$c。$B$B海加尔燃起了熊熊烈火，我耗尽毕生心血保护的世界已在毁灭的边缘。$B$B告诉我——你可曾听说过泰拉斯·黑角这个名字？' WHERE `Id` = 39998 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '十年前，在海加尔山的顶峰爆发了一场旷世之战。污染者阿克蒙德指挥恶魔大军攻占了世界之树，并将其力量据为己有。$B$B他的战败标志着燃烧军团入侵艾泽拉斯计划的终结……但他许多堕落的支持者却仍没有离开。' WHERE `Id` = 40007 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '既是又不是。他现在也许是个恶魔，可泰拉斯·黑角曾经是个暗夜精灵。就像他用恶魔军团许给他的权利去劝诱和转变的那些同胞一样。$B$B在主人战败后，他被俘获并关在这顶峰上，神圣能量缚住了他不朽的人形。$B$B可也许在他心中仍有最晦暗的灵魂火光在燃烧……我们至少要设法弄个明白。' WHERE `Id` = 40009 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不能回去了，我和他们之间发生过可怕的争执。抱歉，$n，我真的不能回去。' WHERE `Id` = 40044 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不能回去了。我已经知道了什么是真实。我的位置是在我新的兄弟姐妹中间。' WHERE `Id` = 40045 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，维林尼亚斯。你这可怜的傻瓜。你真该早点儿离开。' WHERE `Id` = 40058 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在想要阻止他们已经来不及了。让我给你看看他们的荣光……' WHERE `Id` = 40061 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不必担心，森金之子，岑塔布拉从来不会食言。' WHERE `Id` = 40085 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '元素也将与我们同在……' WHERE `Id` = 40087 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……就像这里的野兽。' WHERE `Id` = 40088 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '只要他在群岛上，就逃不出岑塔布拉的手心。' WHERE `Id` = 40114 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他就在西边，在操纵某种黑暗魔法。' WHERE `Id` = 40116 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的命运已经纠缠在一起，沃金，无论结局会是如何，我都会留下。' WHERE `Id` = 40128 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噩梦统御一切！' WHERE `Id` = 40130 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '生命的希冀……' WHERE `Id` = 40132 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '加入我们！加入我们！' WHERE `Id` = 40133 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '聆听他的声音……' WHERE `Id` = 40134 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我是第一批响应沃金的号召，投身军队的人之一。你愿意加入我们吗？' WHERE `Id` = 40165 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我原以为我的首次洋底冒险会是波澜不惊和令我大开眼界的。也许会有种与大自然融为一体的感觉？$B$B可这地方毫无自然之感。我们周围无所不在的元素们都在为复仇而呼号。' WHERE `Id` = 40200 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我在此需要用来证明自己的，就是我的爪子！' WHERE `Id` = 40241 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了珊蒂斯！' WHERE `Id` = 40261 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们花费了大量精力训练和照料我们的动物们，但这一切都是值得的。$B$B尽管如此，有额外的帮手总是好的。' WHERE `Id` = 40265 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然，$n。' WHERE `Id` = 40268 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '贸易大王的游艇就要扬帆起航了。所有人都到码头上去！把钥匙给我，老板。我来驾驶。做好出发准备以后就通知我一声。' WHERE `Id` = 40278 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '珊蒂斯女士正指望我呢。我不会让她失望的。' WHERE `Id` = 40288 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿你好啊，宝贝儿！你和$g小甜甜:奇普;的传闻是怎么回事？' WHERE `Id` = 40291 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '今天可真是个好日子，正适合开挖这世上仅存的卡亚矿石，你不这样认为吗，$n？' WHERE `Id` = 40292 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '卡亚矿石在几千年前把我们变得非常聪明，现在却对我们这些巨魔产生不了任何效果，这不奇怪吗？' WHERE `Id` = 40293 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '能想到用卡亚矿石蒸馏出卡亚可乐，你可真是个天才啊，$n。贸易大王这下要担心你要抢他的位子了！' WHERE `Id` = 40294 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我曾经是位女祭司，但我不变的身份却是学者。能够汲取上层精灵的学识，比施行无知的严律要宝贵得多。$B$B更重要的是，这里的大多数学徒，都是在第三次大战期间成年的年轻人。他们需要指引，需要智慧……$B$B我只希望那些曾把我当成朋友的人能明白这一点。' WHERE `Id` = 40310 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你在看着我……你能看见我吗？$B$B请你，帮帮我……' WHERE `Id` = 40311 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '帮帮我……求你，如果你能听见，请帮帮我……' WHERE `Id` = 40316 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你真是太好了，$n。因为维林尼亚斯，我被关在这儿太久了。那个年轻的精灵是我多年来尝到的第一个灵魂。' WHERE `Id` = 40317 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就算我把那形态给了他，他还是坚持要把我困住。他甚至还把所有灵魂都藏了起来，就是为了不让我得到……真是太顽固了。' WHERE `Id` = 40318 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我欠你个人情，宝贝儿……有一天我会回来偿还。' WHERE `Id` = 40319 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '暂时够了！' WHERE `Id` = 40320 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要这么惊讶。你的萨满朋友有着明察秋毫的眼睛，或者说，有着明察秋毫的青蛙。' WHERE `Id` = 40321 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们德鲁伊一直潜伏在这里，等待着，看沃金是不是会回来。' WHERE `Id` = 40322 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看样子，暗矛部族正在返回这些岛屿。也许我们现身的时候到了。' WHERE `Id` = 40323 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '回到沃金那里去，告诉他：岑塔布拉已经做好了和他并肩作战的准备。' WHERE `Id` = 40324 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为哨兵守住这片区域，将是我们守卫菲拉斯任务的最后一步。' WHERE `Id` = 40330 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '猛虎之灵，将你的力量借给$n，帮助我们找到答案吧！' WHERE `Id` = 40334 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '布洛格，我请求你立刻派些地精前往西岸峰，趁现在还来得及。' WHERE `Id` = 40336 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '化为废墟的千针石林沉没在数百尺深的水底。你能派些地精来帮助我们吗？' WHERE `Id` = 40338 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '大灾变把东部山脉碾碎。南海的水灌入并吞没了整个千针石林！你能在这紧要关头帮帮我们吗？' WHERE `Id` = 40339 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '拜托了。我们正在西岸峰展开救援工作。千针石林已经消亡了！' WHERE `Id` = 40340 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我明白大灾变也同样袭击了尘泥沼泽，但泥链镇看上去还相对安全。你愿意派些地精来帮忙吗？' WHERE `Id` = 40341 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是你不能派人前往西岸峰帮忙，那我们能把难民送到这儿来吗？' WHERE `Id` = 40342 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我担心要是援军不能尽快赶到千针石林的话，恐怖图腾就会开始行动了。我们无论如何都坚守不了多久。' WHERE `Id` = 40343 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是千针石林的舒哈鲁被击败，恐怖图腾部族很快就会出现在你家门口。现在是时候行动了，布洛格！' WHERE `Id` = 40344 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '布洛格。你不介意我这样称呼你吧？等等，我是在和哪个头说话？' WHERE `Id` = 40346 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们需要你和你的地精伸出援手。千针石林被毁了！萨兰纳尔已经沉在水底！' WHERE `Id` = 40347 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们现在谁是负责人？新萨兰纳尔现在需要你们的帮助！' WHERE `Id` = 40348 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们必须在这紧要关头向我们施以援手。对新萨兰纳尔的攻击已经迫在眉睫！' WHERE `Id` = 40349 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的，不会让你们白忙。' WHERE `Id` = 40350 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你不是戈多克或戈杜尼部族那边的，对吧？' WHERE `Id` = 40351 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '大灾变对千针石林造成的影响最大。拜托了，可以帮帮我们吗？' WHERE `Id` = 40352 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '兔子和小鹿？是的，我们有那些动物。你现在能来新萨兰纳尔帮我们了吗？等等……你为什么会问这个问题？' WHERE `Id` = 40353 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '大灾变毁了千针石林的西部山脉。南海灌入并淹没了峡谷。$B$B拜托了，$c，你必须来新萨兰纳尔帮帮我们！' WHERE `Id` = 40354 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '大灾变毁掉了千针石林，$c。你愿意在我们最危难的时刻来帮帮我们吗？' WHERE `Id` = 40355 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们的训练进行得很顺利，姐妹们。过不了多久，你们就能带领自己的人民，再不需要我的教导。' WHERE `Id` = 40356 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是时候让我瞧瞧你的领导力了。塔姆布莉，你将率军在萨尔多岛展开攻势。你一定能在那里为你的勇猛找到用武之地。' WHERE `Id` = 40359 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '西尔维亚，我要派你前往埃斯图兰之塔驱逐那些戈杜尼食人魔。看看你的外交手段和战略对策能否经受住考验。' WHERE `Id` = 40360 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '艾德娜，你必须出击至遥远的东边。我们的军队一定要夺回东部荒野，并观察那些从未见过的部落。愿你的判断力与你的枪法一样精准。' WHERE `Id` = 40361 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我很看好你。别让我失望。去吧！' WHERE `Id` = 40363 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '恐怖图腾出其不意地突袭了我们。我们就快要坚持不住了。' WHERE `Id` = 40386 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我认为符文图腾在这毁灭的中心地带设营是在鲁莽行事，可我并不会让大德鲁伊只身来此。$B$B他在酝酿着什么计划。大计划。' WHERE `Id` = 40401 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这群恐怖图腾畜生很快就要去见他们的造物主了！' WHERE `Id` = 40402 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '必须阻止冰霜领主埃霍恩。
现在他正在获得现实的躯体。暮光之锤的疯狂教徒们将它从元素牢狱中召唤了出来。
如果他完全进入我们的世界，他会用永恒的寒冬埋葬我们。' WHERE `Id` = 40424 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '菲兹尔与普兹克赛艇平台——我的小宝贝儿！是我造出来的！不是他们，不是拉泽瑞克！$B$B它应该叫做金吉赛艇平台才对！' WHERE `Id` = 40453 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的任务就是确保整个进攻行动像时钟一样准确地进行。$B$B大工匠梅卡托克已经到战场去了，但他正计划返回这里，再将更多的部队带上战场。$B$B他从不会迟到，所以你应该在这里等他。' WHERE `Id` = 40462 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的进度有一点落后了，但进攻仍然要按照计划，在$5071W分钟后开始。$B$B现在战前准备大致已经就绪，侏儒直升机、步行坦克和步兵都已就位。$B$B看样子，梅卡托克还在等待一些东西就位后才会下令开始进攻。让我们希望行动能够按时开始吧，否则我可就要丢工作了！' WHERE `Id` = 40463 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快点！你现在应该去找梅卡托克！如果我们不尽快开始进攻，我们就要耽误行动了。$B$B如果我们耽误的话，我们的首领可是要发火的！' WHERE `Id` = 40466 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '住手！大块头保安来了！' WHERE `Id` = 40497 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，快进来乘乘凉。$B$B我帮你弄点儿喝的吧？反正我在这儿也没其它事情可做。' WHERE `Id` = 40502 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '喔好的，我这儿还有几百万个没人要呢。' WHERE `Id` = 40518 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '文书已经准备好，就等你签字了，马林。我的人正等着你做个决定。' WHERE `Id` = 40536 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '天哪，诺格弗格先生，我知道你不希望和部落建立更为紧密的联系，怕因此损害你作为中立贸易实体的声誉！' WHERE `Id` = 40537 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这太可笑了。你知道和侏儒做生意是什么感觉。' WHERE `Id` = 40538 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，噢，我知道这个！这可比和那些失败的地精做生意要好多了，他们总是要乞求别人的帮助！' WHERE `Id` = 40539 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你这被辐射的小矮子为什么要……' WHERE `Id` = 40540 AND `Locale` = 'zhCN';
