UPDATE `broadcast_text_locale` SET `Text_lang` = '指挥他们的是一个名叫萨瑞瑟里安的残忍家伙。但我担心他背后还有更强大的力量。' WHERE `Id` = 40604 AND `Locale` = 'zhCN';
