UPDATE `broadcast_text_locale` SET `Text_lang` = '你总是一无是处。我真开心总算找到了一个真正的男人来满足我的购物欲。' WHERE `Id` = 40621 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就连我遇到的船上服务生都比你有男人气概。真没想到我居然在你身上耽误那么多时间……' WHERE `Id` = 40623 AND `Locale` = 'zhCN';
