UPDATE `broadcast_text_locale` SET `Text_lang` = '喔，谢谢你！' WHERE `Id` = 40777 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '魔法是个工具，有些人甚至会把它当作馈赠。可你永远不应该忘记它的本性。' WHERE `Id` = 40797 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '奥术魔法扭曲了我们世界的边界。它弱化了这个空间的自然定律，使原本不可能发生的事情变为了可能——就算只是在片刻。' WHERE `Id` = 40798 AND `Locale` = 'zhCN';
