UPDATE `broadcast_text_locale` SET `Text_lang` = '你们自以为很聪明，是不是，像这样联手对付我……好吧，准备面对——恐怖伐木机！' WHERE `Id` = 41001 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快点……' WHERE `Id` = 41002 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '呃……我原本打算光明正大的与你公平交手，可你却带来了帮手。好吧！来面对合金锤击者零式吧！' WHERE `Id` = 41003 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '姐妹！我……也……失——败了……' WHERE `Id` = 41007 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得好，$n！回到风剪要塞把部落的意图告知指挥官法罗米尔。我会冒险前往萨达拉瞭望台，通知我们的士兵们。' WHERE `Id` = 41009 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊！别打脸！' WHERE `Id` = 41010 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哇——！' WHERE `Id` = 41011 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一把叉子可不能阻止我再杀掉成百上千的敌人。' WHERE `Id` = 41014 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你以为你们都能勇敢面对我，是吗，钢烁？！那些猪尾巴阻挡不了魔锯的力量！' WHERE `Id` = 41037 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小心，$n！督军罗克托克就在附近。他随时都会出现！' WHERE `Id` = 41038 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很快，加兹瑞拉就能通过增宽的裂隙一举摧毁异教徒的城市了。她会把它们都碾成冰冷的碎石！' WHERE `Id` = 41039 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '瓦丝琪女士和她的母亲完全不同。毕竟她在很久以前就离开了这座城市。' WHERE `Id` = 41041 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗷！好烫！！' WHERE `Id` = 41045 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哎呦！哎呦呦……！' WHERE `Id` = 41046 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '疼！' WHERE `Id` = 41047 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就是它了。远古之神一定会站在我们这边。' WHERE `Id` = 41048 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '把其余的带去火焰之地孵化场！很快我们就将控制天穹。' WHERE `Id` = 41049 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '天空万灵之母，聆听我的祈祷，为你自己显现……一幕景象！这会是什么意思呢，$n？我要报告给欧穆隆。' WHERE `Id` = 41050 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让我们看看你口袋里那些炸药喜不喜欢KS-L10钢烁，梅格斯！' WHERE `Id` = 41051 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '呀！好疼！' WHERE `Id` = 41052 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Yeouuwch！！！' WHERE `Id` = 41053 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '抓到你了小家伙！你最好开口，别逼我动手。' WHERE `Id` = 41056 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不知道那是不是真有必要。' WHERE `Id` = 41057 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你从我这里什么都别想得到，$r！' WHERE `Id` = 41058 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<玛瑞恩一边大声喘叫一边瞪着你。>' WHERE `Id` = 41059 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们的城市将会陷落，$r。你们将消亡在新政权的黑暗之中！' WHERE `Id` = 41060 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '想做什么尽管去做。我的新主人将会在他们处死你之前，把我的名字刻进你的血肉里。' WHERE `Id` = 41061 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '等等，我要扮演好警察的角色？' WHERE `Id` = 41073 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们不必让欧穆隆知道这件事。' WHERE `Id` = 41074 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别急，朋友。我们还需要更多信息。' WHERE `Id` = 41075 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，别浪费时间。' WHERE `Id` = 41076 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这才刚刚开始，玛瑞恩！' WHERE `Id` = 41077 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '残忍！' WHERE `Id` = 41078 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '她要这些蛋。要把它们带到她在另一个王国的炽热孵化场。$B$B而其中一只蛋……很特别的一只……是她最想要的。' WHERE `Id` = 41092 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '她是天穹之主，也是黑暗之王。她是大地守护者的子嗣。她是不可战胜的！' WHERE `Id` = 41094 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愚蠢的$r！新的秩序已然建立。艾维娜已经死了。死了！再也不会回来了。$B$B回去告诉树林里的那群德鲁伊。$B$B塞西莉亚很快将成为新的天穹之主，而且有她在，艾维娜再也别想重生！蛋是塞西莉亚的了！$B$B你来的太迟了。' WHERE `Id` = 41096 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你自己决定，$n。当玛瑞恩攻击我们主人的圣殿时，就已经为自己惹上了麻烦。' WHERE `Id` = 41097 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '万岁，钳子先生！你回来了！你还记得怎么向敌人开枪吗？为什么不花点时间重新把战斗的技艺拾起来！以防万一。' WHERE `Id` = 41099 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是个比我更好的人，$n。可我认为这里的鹰身人只是爪牙而已。' WHERE `Id` = 41101 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一定要多加小心，水泡先生。要是你看到一大群地精，就用你的磁力对付他们！等你把他们全都吸过来之后，就送他们上西天！吖！' WHERE `Id` = 41102 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '抓住他们，水泡先生！' WHERE `Id` = 41103 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '打碎他们的骨头，水泡先生！' WHERE `Id` = 41104 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让他们后悔对你造成的伤害，水泡先生！' WHERE `Id` = 41105 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '吖！' WHERE `Id` = 41106 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让他们更痛苦！更痛苦！' WHERE `Id` = 41107 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可恶，可恶，可恶的部落！' WHERE `Id` = 41108 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，千万别，托尼。离我远点儿，我晚上还有约会呢！' WHERE `Id` = 41115 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '时间到了，玛瑞恩。' WHERE `Id` = 41128 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '冰淇淋！' WHERE `Id` = 41129 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '喂——这边！暂时别出现在视线之内……' WHERE `Id` = 41139 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '许多人把血魔法当作一门黑暗与失落的艺术，对其避之不及。从那以及许多其它方面来说，它与恶魔的法术有着某种共通的鲜明特性。在这里——在黑色沼泽恶魔肆虐的遗迹中，我们相信我们的血魔法一定能焕发光华。' WHERE `Id` = 41150 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让我看看那碎片，可以吗将军？我能感觉到它的能量正从洞穴的另一侧放射出来。' WHERE `Id` = 41152 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你。' WHERE `Id` = 41154 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '请帮帮我，要是这群懒虫能有一个叫得动，我就会让他回去工作，再把其它人打得鼻青脸肿！$B$B我们在这儿有工作要做！' WHERE `Id` = 41170 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你已进入兽人的地盘。你需要什么吗，$r？' WHERE `Id` = 41257 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎你，$g兄弟:姐妹;。' WHERE `Id` = 41258 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '戈德林是狼神先祖，在部落语中又被称作“洛戈什”。他有着传奇般的坚韧战力。$B$B为纪念他而建造的圣殿就位于世界之树西边的盆地那里，但它的看守人在那次攻击之后就变得杳无声息。我担心最坏的事情已经发生了。$B$B在我们继续前进之前，你必须确保圣殿安全无虞，查明狼神先祖的下落，击退他的敌人。' WHERE `Id` = 41317 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '艾森娜是自然之魂，也是我在这个世界和梦境中永恒的同伴。她位于海加尔西部的圣殿，就在暮光入侵的最前线，此刻应该已被战火席卷。$B$B$n，如果没有艾森娜的帮助，我们永远都别想重建海加尔山。确保她的圣殿免受大火的侵袭，并救救附近那些被烈焰威胁的生灵吧。要是我们做不到，就将失去这整座山。' WHERE `Id` = 41318 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '艾维娜是天穹的失落卫士，一万年前在与恶魔大军的对抗中不幸消亡的鸟之女神。为纪念她而建造的圣殿就在西南边，在一棵参天大树的虬枝之中。$B$B猛禽德鲁伊把那圣殿作为他们的大本营，而我们需要他们的支援。你必须前去帮助他们。同时也帮助艾维娜，愿她能找到回归这世界的通途……' WHERE `Id` = 41319 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我已经派大德鲁伊哈缪尔·符文图腾前往被烧得面目全非的玛洛恩庇护所。他在前线的后方——被称作烈焰之痕的焦枯之地。他正在寻找让我们挽回损失的办法，并调查龟神托尔托拉的下落。$B$B但在你前去帮他之前，你必须先确保西边艾森娜神殿的安全，还要保护那里的生灵免受烈焰的侵袭。否则我们将失去一切！先集中精力解决艾森娜林地的问题，然后他们会在适当的时候送你去大德鲁伊那里。' WHERE `Id` = 41320 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我已经想尽办法让这些矮人勤快起来，就差把他们暴打一顿了。$B$B你难道有更严苛的招数？' WHERE `Id` = 41325 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '扫清矿井！不留活口！' WHERE `Id` = 41326 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干掉最多敌人的杀手，将被邀请与领主同桌共餐！' WHERE `Id` = 41327 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '兄弟们，地狱咆哮之眼在注视着你们！' WHERE `Id` = 41328 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎来到远离家乡的家园，$c。希望我们能为您献上无比殷勤的款待。' WHERE `Id` = 41356 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在谷地里要多加小心，$n。四周到处都是敌人！' WHERE `Id` = 41357 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '想要做买卖吗？' WHERE `Id` = 41359 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '鲜血仪式已经完成……而且我现在能看到洛拉姆斯·萨里比迪斯正在何处等待着你。' WHERE `Id` = 41380 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好。退后……别弄得你满身都是。' WHERE `Id` = 41381 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '以拉瑟莱克护符内的强大力量……' WHERE `Id` = 41391 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……我将你缚于他的巢穴中！' WHERE `Id` = 41392 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '召唤咒语已经就绪，可我们是依靠纳萨林坩埚来汲取法术能量。必须找回这件圣物。' WHERE `Id` = 41395 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '马迪亚斯·肖尔亲自派我来协助暗夜精灵。' WHERE `Id` = 41396 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是谁，$c，要背负如此重担？' WHERE `Id` = 41397 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '动物的庇护者……屠龙者……远古之灵的勇士……' WHERE `Id` = 41398 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我最亲爱的老友诺尔度赠予了你一件伟大的礼物，$r。生命的礼物。' WHERE `Id` = 41399 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '而我会给予你一个更加伟大的责任。' WHERE `Id` = 41400 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '由你之手，这座圣山将再次繁茂。守卫它，便是你的责任。' WHERE `Id` = 41401 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '定要使它兴盛。驱逐意欲危害它的敌人，以我之名。' WHERE `Id` = 41402 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不会有第二次机会了，$r。' WHERE `Id` = 41403 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会派我的祭司来帮助你。尽快找到神器，这样我才能开始召唤援军，来应对即将到来的战争。' WHERE `Id` = 41457 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没错，我们也一样！' WHERE `Id` = 41486 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是什么，长者？我从没见过像这样的东西……就连泰达希尔染病时都没见过。' WHERE `Id` = 41501 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不知道，哨兵。我唯一能感受到的就是黑暗魔法的气息。绝对的邪恶。' WHERE `Id` = 41502 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是部落吗？腐化会是他们造成的吗？' WHERE `Id` = 41503 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，宝贝儿，这可比部落要邪恶得多。从石爪峰发散而出的黑暗力量非常古老。甚至比这个世界本身还要久远。' WHERE `Id` = 41504 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那我们要如何存活下去，长者？我们该怎样对抗部落和这古老的邪恶力量？' WHERE `Id` = 41505 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我也没有答案，孩子。' WHERE `Id` = 41506 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一股黑暗力量在席卷石爪峰。' WHERE `Id` = 41507 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯哼。别忘了炸弹，阿尔多。' WHERE `Id` = 41548 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让我看看那碎片，可以吗队长？我能感觉到它的能量正从洞穴的另一侧放射出来。' WHERE `Id` = 41618 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '无耻的怪物！' WHERE `Id` = 41656 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '滚出我们的土地！' WHERE `Id` = 41657 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要那么快！' WHERE `Id` = 41658 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快醒醒，气泡先生！' WHERE `Id` = 41667 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '所有好女孩都听爸爸的话！' WHERE `Id` = 41669 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你在吗，气泡先生！' WHERE `Id` = 41670 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快醒醒，气泡先生！快救救那些灵魂！' WHERE `Id` = 41671 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '乖乖隆地咚！' WHERE `Id` = 41673 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们这群白痴简直疯了！' WHERE `Id` = 41674 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '高贵的艾维娜——百鸟之神！艾泽拉斯的所有空中生灵曾经都对她效忠，尤其是猛禽德鲁伊。正是由于她的恩赐，我们才获得了变换形态和翱翔天空的能力。$B$B艾维娜集美丽与可怖于一身，就像那些被她甄选而打造成的强大猛禽一样。她曾住在耸入云天的母亲之树加尼尔的精神圣域，而每当她在艾泽拉斯出现时，她的形象总是一位长着双翼的女神。' WHERE `Id` = 41682 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<楚伦娜的脸色暗淡了下来。>$B$B一万年前，恶魔在上古战争期间闯入艾泽拉斯。艾维娜召集她的子嗣集聚天穹，在前线阻击恶魔军团。$B$B愤怒中的她所向披靡，千百个恶魔被她的利爪撕裂。可她最终还是陷入了末日守卫的包围，他们尖利的长矛从她身体两侧齐齐刺入……$B$B据说她的鲜血也仿佛有意志一般，向恶魔发起凶猛的攻击，烧灼他们的血肉，就像是她自己从天而降，把他们一举击溃。' WHERE `Id` = 41683 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '艾维娜在那天倒在了战场上，但凡间种族和其余的上古诸神最终还是取得了胜利。首批德鲁伊在遍地尸殍中找到了她的遗体，并将她埋葬在了这里——埋在了这高山之巅。$B$B她就永眠在这圣殿之外，在圣石圈起的圆环之中。$B$B人们用加尼尔的一颗种子种出了世界之树——这也是那圣域唯一的留存，否则整个圣域都会同艾维娜一同消亡。' WHERE `Id` = 41684 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们凡间种族对艾森娜知之甚少，她是在茂密的野性丛林中潜行的荒野之魂。她是森林之灵，是它跃动的心脉，是粉碎岩石、吞噬遗迹、将茂密的丛林用神秘与恐惧灌注的生命能量之源。艾森娜是生命之网的中心。$B$B暗夜精灵在卡利姆多各地都为她修建了圣殿。人们崇敬她……可并不了解她。$B$B你觉得要是我们能对这避世而强大的远古半神有少许了解，那会怎么样呢？' WHERE `Id` = 41685 AND `Locale` = 'zhCN';
