UPDATE `broadcast_text_locale` SET `Text_lang` = '我们必须不惜一切代价将世界之柱碎片重新拼合在一起。$B$B但首先，我们得先找齐它们。' WHERE `Id` = 42459 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你，$n。我们永远不会忘记你的慷慨相助。' WHERE `Id` = 42468 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '开饭啦！快来吃吧！' WHERE `Id` = 42469 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里的巨魔很能接受像我这样的人。毕竟，在被遗忘者还没出现时，他们就已经与死者交流了几个世纪。$B$B这是个很好的契机。' WHERE `Id` = 42494 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在我小时候，我的家人不许我研习萨满巫术。任性而愚蠢的我竟然从他们身边逃离，一个人学习了起来。有一天当我回到故乡，却发现父母都已不在。我的家园也已被毁。没人知道是谁下的手。
我耗尽毕生的精力，想要延展我萨满的视野来回望过去——查明在我家人身上究竟发生过什么，谁该对此负责。我一路走来历尽艰辛。现在我已学会将意念集中在于不久前发生的重大事件上，可要想获知发生在那么久之前的事，我还有很长的路要走。' WHERE `Id` = 42495 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '包在我身上，$n。' WHERE `Id` = 42531 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '爆头！' WHERE `Id` = 42532 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '门都没有。' WHERE `Id` = 42533 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小菜一碟。' WHERE `Id` = 42534 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他完了！' WHERE `Id` = 42535 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们已经成功牵扯了敌人的注意力。我们按计划继续。' WHERE `Id` = 42537 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们将在黎明之时把将军放出来。' WHERE `Id` = 42539 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '审判日很快就要到来了，赫利克斯。' WHERE `Id` = 42541 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '叫来我的人民。我想在黎明到来之前再对他们讲最后一次话。' WHERE `Id` = 42542 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是。就在今夜。' WHERE `Id` = 42544 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '过来，奴仆们！开始攻击！' WHERE `Id` = 42545 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别松懈！他正在变弱！' WHERE `Id` = 42546 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快要开始集结了！' WHERE `Id` = 42569 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '集合，兄弟姐妹们！所有人都过来，听好了！' WHERE `Id` = 42570 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '兄弟们。姐妹们。我们是被遗弃的——我们是暴风城的孤儿。' WHERE `Id` = 42571 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的“国王”高高坐在他那用黄金打造的宝座上，对我们的困境无动于衷。' WHERE `Id` = 42572 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '与此同时，我们的孩子们却正饿死在我们脚下的这些条街道上！' WHERE `Id` = 42573 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他的战争——并不是我们的战争，却夺走了我们幸福的生活。我们用自己与所爱的人的鲜血，换来了联盟的胜利！' WHERE `Id` = 42574 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '时机已经到来了，兄弟姐妹们，我们要让正义得伸！' WHERE `Id` = 42575 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '暴风城与整个联盟的执政阶级，必须为他们对我们犯下的罪行负责！' WHERE `Id` = 42576 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '今天，我们获得了新生！今天，我们是以男人和女人的身份屹立在这里，而不再是无名无姓的数字！' WHERE `Id` = 42577 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们守住了猎人高地！入侵者已经被彻底击退，撤退完成了！' WHERE `Id` = 42591 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '爸爸……' WHERE `Id` = 42604 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不管在别处正在发生着什么，铁炉堡没有忘记这片土地，也没有忘记卡兹莫丹的任何角落！' WHERE `Id` = 42618 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们这群混蛋要为自己的罪行付出代价。' WHERE `Id` = 42656 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '希望？当我看见父亲的头被你的手下砍掉时，我心里应该有这种感觉吗？' WHERE `Id` = 42658 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '希望就是个残忍的笑话，是这个严酷而冷漠的世界同我们开的一个玩笑。希望根本就是不存在的，存在的只有梵妮莎。梵妮莎·范克里夫。' WHERE `Id` = 42659 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '站起来吧兄弟会！破晓之日即将到来！' WHERE `Id` = 42660 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '把他们绑起来。' WHERE `Id` = 42661 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '长官，你的帽子。' WHERE `Id` = 42662 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让你们所见之处只留下灰烬，兄弟们！把哨兵岭烧光！' WHERE `Id` = 42672 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '至于你，$n，我会饶你不死。你帮了我们不少忙——尽管是在不经意间，但下一次我们再见面时，就只能用武器说话了。' WHERE `Id` = 42673 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我别无选择，中尉。他们认出了我。在这个世界上唯一知道我存在的人，从我在襁褓之时起就认得我的脸。' WHERE `Id` = 42676 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们的死亡令我也感到难过。' WHERE `Id` = 42677 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在可以肯定了。这些石头元素不久前才被唤醒。' WHERE `Id` = 42678 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '只有元素领主才有可能在短时间内唤醒这么多的元素。看来，我们面对的正是石母本尊……' WHERE `Id` = 42679 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愿元素保护我们。' WHERE `Id` = 42680 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '呀！' WHERE `Id` = 42723 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祭司了解很多与祖尔格拉布有关的事。$b$b祭司认为你需要她的帮助。' WHERE `Id` = 42751 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '到这儿来，你这傻大个儿！' WHERE `Id` = 42799 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '回到顶上找我。这个双头怪物有几个问题要回答！' WHERE `Id` = 42812 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊……玛法里奥·怒风。我原本希望能再把你多拖住一会儿。我的目标是要保证在我的盟友出击时，让你远离海加尔。看来我已经成功了。' WHERE `Id` = 42888 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我根本不用和你作战，因为我显然已经赢了。你不能在阻止我们攻击黑海岸的同时，还能救得了海加尔山！' WHERE `Id` = 42889 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '炮兵的双手沾满了黑色的火药粉。' WHERE `Id` = 42916 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看看这是谁，$n？' WHERE `Id` = 42927 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '准备作战！我们已经对邪枝部族忍无可忍！' WHERE `Id` = 43088 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '若想单凭我们的力量解决简直太难了。我已经送信到矮人主城铁炉堡，请求他们的支援。' WHERE `Id` = 43111 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有位来自烈酒村的信使今早抵达了这里。矮人们正派出一支巡山人小队来帮我们。' WHERE `Id` = 43117 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '准备好打斗了吗，$g小伙子:小姑娘;？' WHERE `Id` = 43120 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '多管闲事的虫子们！你以为你能轻易地打败我们？' WHERE `Id` = 43121 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好了，宝贝儿。快把你知道的都说出来，别逼我动手！' WHERE `Id` = 43166 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我是蛮锤部族的女儿，大地之环的萨满祭司。我的信条迫使我捍卫祖先与元素的荣耀。' WHERE `Id` = 43168 AND `Locale` = 'zhCN';
