UPDATE `broadcast_text_locale` SET `Text_lang` = '你可以从世界之柱碎片的下落开始说。带着你这个胖子飞了这么长的时间，我的狮鹫看上去有点儿累了。' WHERE `Id` = 43170 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你从来没有生命危险，宝贝儿。我朋友在下面会接住你的。你活着对我们的价值可太大了！' WHERE `Id` = 43177 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有趣。在这以前我还从来没听说过暮光议会。' WHERE `Id` = 43180 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '格雷戈，你这个懦夫！兽人的鲜血正泼洒在我们的海岸上。如果你毁灭了他们，你就把我们全都毁了。' WHERE `Id` = 43239 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，要知道，我们的“酋长”并不代表我们所有人的意志。我们之中有一些人希望看到龙喉氏族再次强大起来……并不再继续堕落下去。' WHERE `Id` = 43241 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的物资也就快要耗光了，队长。由于巨魔和雪人的袭击，一周之内我们的定额口粮就得减半。' WHERE `Id` = 43242 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '高阶祭司耶克里克就要痊愈了！' WHERE `Id` = 43297 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我又活了！' WHERE `Id` = 43303 AND `Locale` = 'zhCN';
