UPDATE `broadcast_text_locale` SET `Text_lang` = '我们知道的只是皮毛而已，$n。我可以向你担保。' WHERE `Id` = 43372 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你。' WHERE `Id` = 43373 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '埃鲁纳克，来看看这个。还记得我跟你说过的视象法术吗？这看起来像是个有力的证据。' WHERE `Id` = 43374 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那我这就准备施法。这也许总算能让我们对纳迦的手段和意图有所了解。' WHERE `Id` = 43375 AND `Locale` = 'zhCN';
