UPDATE `broadcast_text_locale` SET `Text_lang` = '快！抓住梯子！' WHERE `Id` = 43390 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎来到硬钳避世乐园！$b$b希望远离纷繁嘈杂的城市生活？那你可来对地方了！$b$b想要亲眼见证艾泽拉斯知名丛林的奇迹胜景？不用去别处了！$b$b想要购买新鲜出炉的生物燃料或武器级矿物？这里一定能满足你的需要，$c！' WHERE `Id` = 43410 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，老大。' WHERE `Id` = 43411 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '赶快，格索乌。解开$g他的:她的;镣铐。' WHERE `Id` = 43463 AND `Locale` = 'zhCN';
