UPDATE `broadcast_text_locale` SET `Text_lang` = '记住，$n。并非所有的龙喉成员都是你的敌人！' WHERE `Id` = 43467 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '世界闻名的诺格弗格药剂此处有售！$B$B由纯天然材料萃取炼制而成，只在加基森当地装瓶销售！而且口感顶呱呱——这是当然的！' WHERE `Id` = 43486 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个石头穴居人与赤红岩床的变数有关。$B$B我在这里感觉到一股奇怪的力量……多加小心。' WHERE `Id` = 43562 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们快点做个了断。' WHERE `Id` = 43580 AND `Locale` = 'zhCN';
