UPDATE `broadcast_text_locale` SET `Text_lang` = '追上他，快点！' WHERE `Id` = 43582 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '狡猾的石头穴居人。' WHERE `Id` = 43583 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '开玩笑吧……' WHERE `Id` = 43584 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死得好。' WHERE `Id` = 43585 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我留下来确认他们剩下的实体也被消灭了。' WHERE `Id` = 43611 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有贼！！' WHERE `Id` = 43624 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '随着奥妮克希亚体内电荷的增加，在她身体四周开始出现能量电弧。' WHERE `Id` = 43631 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '随着奥妮克希亚体内的电荷积聚到危险程度，电弧也在不断加强！' WHERE `Id` = 43632 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '微小的闪电灼烧着奥妮克希亚的皮肤。她体内的电荷已积聚到濒临迸发的阶段！' WHERE `Id` = 43633 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '放弃港口？莫格霍尔把你的理智都打没了吗？这次攻击是我们夺回命运掌控权的最好机会——等等！让我们先见见来自部落的$n！' WHERE `Id` = 43657 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '进攻！' WHERE `Id` = 43696 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '确保椽子的安全！' WHERE `Id` = 43697 AND `Locale` = 'zhCN';
