UPDATE `broadcast_text_locale` SET `Text_lang` = '需要我帮忙吗？' WHERE `Id` = 43741 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是，$g阁下:女士;。我们根据您的信号指示从北面发起攻击。 “急浪船帮”将荡涤藏宝海湾！喔啰！！！' WHERE `Id` = 43743 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '举起手来，绿皮人！乖乖照着指示做。你要是玩什么花样，就让你尝尝子弹的味道。' WHERE `Id` = 43817 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '剩下的人，跟我下去！' WHERE `Id` = 43818 AND `Locale` = 'zhCN';
