UPDATE `broadcast_text_locale` SET `Text_lang` = '那么你将对它的行为担负起责任来，石领主。当它的真实意图显露之后，你将必须给我一个解释。' WHERE `Id` = 43849 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '至于你，血肉之躯。考虑一下你现在的处境吧。你的身躯被重重岩石所包围，你脚下的大地屈从于我的意志。' WHERE `Id` = 43850 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你背叛了我们，你就将无路可逃。我会缓慢地摧毁你的身体，倾听你每一片骨头碎裂的声音。' WHERE `Id` = 43851 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这次谈话很愉快。' WHERE `Id` = 43852 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你正在尝试说服我，这些血肉之躯应该得到我的信任。' WHERE `Id` = 43857 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们就是堕落的化身，确是如此。他们的皮肤就说明了一切。' WHERE `Id` = 43858 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们只会寻求力量，与暮光别无二致。但你却信心十足的认为他们不会背叛我们。我养大了一个蠢货？' WHERE `Id` = 43859 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哼，它们杀掉了石头穴居人，你觉得这能打动我？这不算什么功绩。' WHERE `Id` = 43860 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的看法呢？博登，你怎么看这个“勇士”？' WHERE `Id` = 43861 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '也许你说的对。即使是蠢货也能有些用处。我不是照样留下了你。' WHERE `Id` = 43862 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '勇士归来了。' WHERE `Id` = 43869 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这么小。这么软。真好奇你是如何坚持到现在的，血肉之躯。' WHERE `Id` = 43870 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '或者说，这正显示出了你的能力？' WHERE `Id` = 43871 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你做的这些就只是为了世界之柱的碎片？你们这些萨满究竟想拿它做什么？' WHERE `Id` = 43872 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '然后呢？你们就会安静地离开深岩之洲？' WHERE `Id` = 43873 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你至少有些洞察力。' WHERE `Id` = 43874 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的提议是：我们会向暮光教派进军，将死亡之翼的名讳从这个世界中彻底抹消掉。你们大地之环，将随我而战。' WHERE `Id` = 43875 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你能做到，我就会派格尔西克将世界之柱的碎片送到神殿去。' WHERE `Id` = 43876 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '封印那道裂隙，然后离开。' WHERE `Id` = 43877 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '留着你的感谢。当我们的部队集结完毕之后就向暮光绝壁进军。我期待在战场上见到你。' WHERE `Id` = 43878 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '大地来夺你性命了，邪教！' WHERE `Id` = 43882 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的入侵将不会被原谅。死亡之翼不会再在这里庇护你了。' WHERE `Id` = 43886 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在即将吞噬你的大地之前畏缩吧！' WHERE `Id` = 43887 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得好，$r。返回神殿吧，格尔西克会在那儿等着你。' WHERE `Id` = 43888 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '塞拉赞恩终于攒足了勇气来挑战我们，是吧？' WHERE `Id` = 43910 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '靠近点，亲爱的。我有些小小的看法。' WHERE `Id` = 43911 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你意识到一切都毫无希望了，对吧？死亡之翼已经崛起了，你的世界注定毁灭。' WHERE `Id` = 43912 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '跟紧点，亲爱的。我值得你的追逐。' WHERE `Id` = 43913 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没那么容易，甜心。也许下一次。' WHERE `Id` = 43914 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的传说将在此终结，萨满。' WHERE `Id` = 43938 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死亡之翼会给尘世的所有秩序带来毁灭。到那一天，我将成为他的利刃！' WHERE `Id` = 43939 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈哈……' WHERE `Id` = 43940 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们毁掉你们的要塞时，你们就该接受警告的，异教徒。' WHERE `Id` = 43941 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '玛哈特，杀掉这些教徒。我会去对付那愚蠢的女祭司。' WHERE `Id` = 43942 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你敢回来就必死无疑。' WHERE `Id` = 43943 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '仪式几乎就要完成了！' WHERE `Id` = 43944 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '感谢你，石母。这是我的荣幸……' WHERE `Id` = 43945 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你证明了你所言不虚，大地治愈者。为此，你将免遭大地之怒。' WHERE `Id` = 43946 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的伤势愈合了，就离开吧，也算是感谢我。' WHERE `Id` = 43947 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，穿上你身后那套终极足球炸弹制服，到下方的码头那里去。帮助萨尔对付贸易大王！' WHERE `Id` = 43948 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈哈！这下可热闹了！' WHERE `Id` = 43954 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '亡者在乞求慰藉。他们的痛苦在风中回响。' WHERE `Id` = 43984 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们其中一名最好的哨兵前去追踪"他"——我们假设那是名男子——但她似乎暴露了。' WHERE `Id` = 43989 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '今天早上，她被我们的巡逻队发现了。她就在我们自己的城市里被谋杀了。' WHERE `Id` = 43990 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很难分辨谁能够信任。你刚到此地不久……对此一无所知。也许你能胜任这次调查。' WHERE `Id` = 43991 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '还有一件事。我们安排了一名自己的人随你一同调查。' WHERE `Id` = 43993 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这位是莉莉奥瑞伦。' WHERE `Id` = 43994 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '请叫我莉莉。' WHERE `Id` = 43995 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们之前提到的那位哨兵是莉莉的姐妹。她可以信任。' WHERE `Id` = 43996 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们会抓住那名叛徒的，女祭司。您无需担心。' WHERE `Id` = 43997 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我相信你会的，但请一定小心。' WHERE `Id` = 43998 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '…这看上去几乎没有搏斗的痕迹。' WHERE `Id` = 43999 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这很反常。当危险临近之时，她一定会全力一搏。' WHERE `Id` = 44000 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你认为那个杀手偷袭了她？即使她认为她发现了他的踪迹？' WHERE `Id` = 44001 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别放过任何细节。这里一定有什么线索能帮助我们捉到那个凶手。' WHERE `Id` = 44002 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你找到什么了？' WHERE `Id` = 44003 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一片沾泥的叶子……' WHERE `Id` = 44004 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s轻轻闻了闻那片叶子。' WHERE `Id` = 44005 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '翠羽树叶！真是好运。' WHERE `Id` = 44006 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在达纳苏斯只有一个地方长有这种树。也许我们要找的凶手就是在那里沾上这片树叶的。' WHERE `Id` = 44007 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们要找的那栋建筑就在工匠区。我们走。' WHERE `Id` = 44008 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '维罗拉比我要大上几岁。' WHERE `Id` = 44009 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '过去这几个月我们一同经历了一段困难的时光。我猜所有人都是。' WHERE `Id` = 44010 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是否有过这种体验，某件事情你明知十分重要，却怎么也想不起来？似乎自从玛法里奥回来之后，所有人都变成了这样。' WHERE `Id` = 44011 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有时候我的眼前会闪过恐怖的镜像。阴影在黑夜中吞噬我们。亲友反目，自相残杀。' WHERE `Id` = 44012 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些很难用语言形容。一切都应该变好的。玛法里奥回来了。泰达希尔终于得到了巨龙的祝福…某些巨龙的祝福。' WHERE `Id` = 44013 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但我总觉得……觉得我生命中的某些东西不见了，消逝了。仿佛梦境终于醒来。' WHERE `Id` = 44014 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不应当让这种失常影响到我。我……我应该比我的姐妹们要好受一些。' WHERE `Id` = 44015 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的懊恼到此为止。这就是那座建筑。让我们进去调查一下。' WHERE `Id` = 44016 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些房间通常会提供给造访城市的客人。任何人都有可能会居住在这里。' WHERE `Id` = 44017 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是一张黑海岸的地图。上面绘有从奥伯丁通往洛达内尔的小径……还有几条路通往其他的安全藏身处。' WHERE `Id` = 44018 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是某种攻击计划？奥伯丁已经被大灾变的动荡撕碎了。那儿能有什么价值？' WHERE `Id` = 44019 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我认为这些可能是逃跑路线。' WHERE `Id` = 44020 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这条穿过海滩的路线被圈了起来。我们赶快前往那个地方，看看能不能有什么发现。' WHERE `Id` = 44021 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会向泰兰德和玛法里奥报告我们的进展。我会尽快与你在海滩会合。' WHERE `Id` = 44022 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你最好径直过去，但千万留心。' WHERE `Id` = 44023 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '以艾露恩之名！他们都遭到了伏击…这是背叛…' WHERE `Id` = 44024 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那个叛徒策划了一切！他是这场屠杀的帮凶。' WHERE `Id` = 44025 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他受伤了。我想我能追踪这些血迹。' WHERE `Id` = 44026 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这边！跟着我。' WHERE `Id` = 44027 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这边有一些新鲜的痕迹，沿着森林的边缘一直延伸到了镇上。但很难讲是不是他留下的。' WHERE `Id` = 44028 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这儿！一块血迹。我们的方向是正确的。' WHERE `Id` = 44029 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就在守卫的眼皮下？自信的杂种…' WHERE `Id` = 44030 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哨兵！你有没有看到一个受伤的暗夜精灵经过？' WHERE `Id` = 44031 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的。朝瀑布那边去了。我劝他疗好伤再走，可他不听。' WHERE `Id` = 44032 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '过来，朋友，赶快！' WHERE `Id` = 44033 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在那里！他在和谁说话？' WHERE `Id` = 44034 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们行动！' WHERE `Id` = 44035 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……他们去了哪里？' WHERE `Id` = 44036 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们从地面上逃不掉，难道他们……' WHERE `Id` = 44037 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我希望你会游泳，狼人。' WHERE `Id` = 44038 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真高兴你成功了。' WHERE `Id` = 44039 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们就在头顶上。流水应该能掩盖我们接近的声音。当你准备好就告诉我。' WHERE `Id` = 44040 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让我们结束这一切。' WHERE `Id` = 44041 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会对付邪教徒。你处理那个叛徒。' WHERE `Id` = 44042 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别让他逃走了！' WHERE `Id` = 44043 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别动，让我结果他。' WHERE `Id` = 44044 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，莉莉，别杀他。' WHERE `Id` = 44045 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但…我…是的，我的女士，如你所愿。' WHERE `Id` = 44046 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '莉莉，请将这名犯人带给哨兵，我们将公正的对待他。' WHERE `Id` = 44052 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然，我的女士。' WHERE `Id` = 44053 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '还有你，我亲爱的狼人，今天你可帮了我们一个大忙。' WHERE `Id` = 44054 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '玛法里奥也许不会把他的想法挂在嘴边，但他却一直在关注着你的族人。' WHERE `Id` = 44055 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他非常了解你们所遭受的诅咒和它的可怕影响。对此他也对自己怀有几分自责。' WHERE `Id` = 44056 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我想今天你已经消除了他的疑虑。你显示出的高贵和自律也许已经超出了他期待。' WHERE `Id` = 44057 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真心地感谢你。' WHERE `Id` = 44058 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当你准备离开这儿时请一定告诉我。' WHERE `Id` = 44059 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很高兴再次见到你，朋友。' WHERE `Id` = 44060 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这位是格雷戈里。' WHERE `Id` = 44063 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他是我们的新盟友，从吉尔尼斯而来。很容易就能推断出他并未牵涉进此事，我们能够相信他。' WHERE `Id` = 44065 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '令人印象深刻，格雷戈里。我必须承认，我从未料想过你能如此克制。' WHERE `Id` = 44109 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '格雷戈里，请将这名凡人带给哨兵，我们将公正的对待他。' WHERE `Id` = 44111 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '至于你，我亲爱的朋友，今天你可帮了我们一个大忙。' WHERE `Id` = 44113 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要让我们信赖一位新人着实不易。你恰好在这个危急时刻造访了我们。' WHERE `Id` = 44114 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这真是我们的幸运，你显示出了高尚的荣誉感和奉献精神。' WHERE `Id` = 44115 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '毁灭他们！' WHERE `Id` = 44208 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在！放出海怪！' WHERE `Id` = 44211 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '跟着我，宠物们！耐普图隆的国度终于成了我们的掌中之物！' WHERE `Id` = 44213 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那个兽人……可真大。' WHERE `Id` = 44221 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '它要爆炸了！快跳上飞龙！' WHERE `Id` = 44222 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是人民真正的英雄，利亚姆。不像其他的贵族，我们将让他们付出代价。' WHERE `Id` = 44223 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们必须把敌人拖得更久一点。用不了多久，塞纳留斯就会回到我们中间。' WHERE `Id` = 44232 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快点……她就要挣脱束缚了！' WHERE `Id` = 44233 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这片土地的祝福与你同在。' WHERE `Id` = 44239 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '珊蒂斯弯弓对准了群星！' WHERE `Id` = 44251 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '艾露恩，指引我的箭矢！' WHERE `Id` = 44253 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '波涛之王，你的统治已经到头了！' WHERE `Id` = 44255 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再过不久，你宝贵的王座就会成为一片废墟！' WHERE `Id` = 44256 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你那章鱼脑袋将成为献给女王的战利品……' WHERE `Id` = 44257 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '搜查这个地方，我的军团！把猎潮者的陷阱找出来！' WHERE `Id` = 44262 AND `Locale` = 'zhCN';
