UPDATE `broadcast_text_locale` SET `Text_lang` = '不管暮光之锤的信徒们藏到哪里，我们都将击败他们。就连元素位面也不是他们安全的避风港。' WHERE `Id` = 44413 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$n！' WHERE `Id` = 44420 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好啊，$c。想要买点儿什么吗？' WHERE `Id` = 44426 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '古拉巴什已经灭亡，连同哈卡一起。我大多数的赞达拉同胞都回到了他们的故乡。$b$b现在，守卫祖尔格拉布的重任就落在了我，查巴尔和邦巴拉暗矛巨魔的肩上。' WHERE `Id` = 44436 AND `Locale` = 'zhCN';
