UPDATE `broadcast_text_locale` SET `Text_lang` = '选择成为法师就是选择走上一条布满荆棘的险途。许多人都不理解我们。就连我们自己人都在艰难地接受我们的艺术。' WHERE `Id` = 44478 AND `Locale` = 'zhCN';
