UPDATE `broadcast_text_locale` SET `Text_lang` = '我喜欢这些小精灵！真是太可爱了！' WHERE `Id` = 44521 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '安静点，伊莎娜。你的噪音快把我们吵死了。' WHERE `Id` = 44522 AND `Locale` = 'zhCN';
