UPDATE `broadcast_text_locale` SET `Text_lang` = '快醒醒你这傻瓜！我们被攻击了！' WHERE `Id` = 44524 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎来到守望堡，$c。你可以叫我“妈妈”，我会好好照顾你。' WHERE `Id` = 44525 AND `Locale` = 'zhCN';
