UPDATE `broadcast_text_locale` SET `Text_lang` = '暮光之锤极有可能在真主之门那里有了什么新发现。$B$B也许像你这么$g能干的:可爱的;$c刚好能帮帮我？' WHERE `Id` = 44871 AND `Locale` = 'zhCN';
