UPDATE `broadcast_text_locale` SET `Text_lang` = '你感觉到了吗，$n？黑暗在席卷我们。' WHERE `Id` = 45097 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '生命是毫无意义的。我们在死后才会面临真正的考验。' WHERE `Id` = 45098 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '通过我，女妖之王看得见一切……' WHERE `Id` = 45099 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他来了。准备好，兄弟们！' WHERE `Id` = 45100 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '向你的新主人俯首致敬吧！' WHERE `Id` = 45114 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '起来，摧毁我们的敌人！' WHERE `Id` = 45115 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不行了！你只能靠自己的力量打败他了！' WHERE `Id` = 45149 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '希望你的意志够强！穿越裂口的旅程可不适合弱者。' WHERE `Id` = 45169 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们正处在大漩涡的中心，这道裂隙分隔了深岩之洲和艾泽拉斯。看着它把你们的世界撕成碎片吧！' WHERE `Id` = 45170 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但愿我们进入裂隙之后萨尔他们能够维持住它！' WHERE `Id` = 45171 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要进去了！做好准备！' WHERE `Id` = 45172 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死亡之翼的污染，连同他的暮光教徒都将被彻底从深岩之洲中清除干净！' WHERE `Id` = 45173 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你成功了！很好！' WHERE `Id` = 45175 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是大地神殿。它是深岩之洲最重要的建筑物。' WHERE `Id` = 45176 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这儿曾经有块泰坦制造的石头，被称作世界之柱。如同其字面意思，它承载了深岩之洲世界所有的元素之力和磁吸引力。' WHERE `Id` = 45180 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死亡之翼冲破了穹顶，在两个世界间制造了裂隙，世界之柱也裂成了碎片。如果我们不能让世界之柱复原，那么整个深岩之洲都会崩溃。' WHERE `Id` = 45182 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '跑……' WHERE `Id` = 45184 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '跑啊！' WHERE `Id` = 45185 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '第一块碎片本应由一艘名叫风暴之怒的部落炮艇给我们送来。但它始终没抵达。' WHERE `Id` = 45186 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们控制了这座神殿，并在竭力抑制它受到的伤害。到神殿里和玛鲁特谈谈，下面由他负责。' WHERE `Id` = 45187 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们全都指望你了。' WHERE `Id` = 45191 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这边走，$n。我们要让他们大吃一惊。' WHERE `Id` = 45193 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我并非一直是女妖之王，$n。' WHERE `Id` = 45201 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的人民也并非一直是被遗忘者。' WHERE `Id` = 45202 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '曾经，这片土地属于北部王国洛丹伦，由泰瑞纳斯·米奈希尔国王统治。' WHERE `Id` = 45203 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '泰瑞纳斯有一个儿子，名叫阿尔萨斯。' WHERE `Id` = 45204 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿尔萨斯…单是说出他的名字就会让我的身体因愤怒而颤抖。' WHERE `Id` = 45205 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个幼稚的男人，阿尔萨斯，亲手拔出了一把名为霜之哀伤的邪剑。' WHERE `Id` = 45206 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '手持霜之哀伤，阿尔萨斯杀死了亲生父亲，并毁掉了这片土地和所有的生物。' WHERE `Id` = 45207 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿尔萨斯和他的军队肆虐了我的家园奎尔萨拉斯，杀死我的人民，并给我带来了死亡。' WHERE `Id` = 45208 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿尔萨斯的残忍没有止境，他将我的灵魂抽离了身体，把我变成女妖，以侍奉他的天灾军团。' WHERE `Id` = 45209 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '被天灾的战争机器杀死的每个人都遭遇了同样的厄运。' WHERE `Id` = 45210 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在这深渊的火焰中净化你的灵魂吧！' WHERE `Id` = 45211 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '忏悔吧，凡人们！在这无法阻止的大毁灭之前忏悔吧！' WHERE `Id` = 45212 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '拜服于强者脚下，你也许还能在这个渺小世界的毁灭中逃过一死！' WHERE `Id` = 45214 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '以萨格拉斯的名义！没有信仰的人只能成为祭品！' WHERE `Id` = 45215 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '伟大的君主萨格拉斯将看到你的背叛，你的欲望，还有你彻底的毁灭！' WHERE `Id` = 45216 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死后，我们变成了没有思想的亡灵。' WHERE `Id` = 45217 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但阿尔萨斯并非不可战胜！他的力量日渐衰竭，他对受诅者意志的掌控也弱化了。' WHERE `Id` = 45218 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在阿尔萨斯最虚弱的时候，我发起了进攻！' WHERE `Id` = 45219 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿尔萨斯赎罪的时刻眼看就要到来，但那只蛆虫逃脱了命运的制裁，回到了诺森德的冰冻废土。' WHERE `Id` = 45220 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '随着阿尔萨斯一同消失的还有他对洛丹伦众多亡灵的思想控制。我恢复了身体，并让剩下的天灾亡灵也获得了自由。' WHERE `Id` = 45221 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿尔萨斯后来成为了巫妖王，凭着对他的共同仇恨，被遗忘者诞生了。' WHERE `Id` = 45222 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的目的—我们唯一的目的便是毁灭巫妖王。我们加入了部落，并踏上了通往救赎的远征。' WHERE `Id` = 45223 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在，巫妖王被消灭了，我们回到了这片土地。' WHERE `Id` = 45224 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些人民将这片土地称为家园，生亦如此，死亦如此。' WHERE `Id` = 45225 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但联盟不承认我们的主权。他们声称这片土地属于他们，妄图将它从王国的创立者们手中夺走。' WHERE `Id` = 45226 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我绝不允许…绝不！' WHERE `Id` = 45227 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '洛丹伦永远属于被遗忘者，永远。' WHERE `Id` = 45228 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我提供的材料都是罕见而且强大的。' WHERE `Id` = 45229 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '库尔迪拉！你的女王在召唤你！' WHERE `Id` = 45245 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你这个傲慢的家伙。你以为我是个瞎子？看不见幽暗城外面发生的一切？' WHERE `Id` = 45247 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别想得到我的感谢。当我们击败天灾军团的时候，安多哈尔就已经应该属于我们了。' WHERE `Id` = 45249 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我知道你的秘密，库尔迪拉。我知道你和联盟死亡骑士萨萨里安之间的友谊。' WHERE `Id` = 45250 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿尔萨斯在创造死亡骑士的时候就已经必败无疑了。你还很软弱。' WHERE `Id` = 45252 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '幸运的是，我的部下可以帮助你……消除你的软弱。到到幽暗城下面去吧。' WHERE `Id` = 45253 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘘……安静，死亡骑士。当我了结你的时候，你的恐惧也将不复存在。' WHERE `Id` = 45255 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '到那时，你就会感谢我了。' WHERE `Id` = 45256 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好好看看，我有没有变漂亮些？' WHERE `Id` = 45262 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，能占用一下你的时间吗？' WHERE `Id` = 45273 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$c！' WHERE `Id` = 45293 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯，让我们瞧瞧。我听说魔导师毕斯普最近一直把自己关在塔顶，好像是在研究什么新法术之类的东西。$b$b德尔·盖罗恩正准备退休，回农场养老。事实上他可能已经离开了。$b$b喔，我还听说有个什么$r$c在城镇附近游荡，拉住人们问东问西！$b$b只是和你开个玩笑，宝贝儿。希望这些信息能帮到你。' WHERE `Id` = 45295 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真高兴能有机会喘一口气。谢谢你的帮助！' WHERE `Id` = 45355 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真高兴能再见到你！感谢你的帮忙。我再过一会儿就能站起来了。' WHERE `Id` = 45357 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看上去，战况好像对我们不利，但血色十字军终将取得胜利。我坚信，我们一定能彻底清除斯坦索姆的天灾怪物。虽然我不看好银色黎明，不过圣光兄弟会确实是一支能发挥作用的队伍。$B$B闲聊到此结束，$c。我们开始吧。' WHERE `Id` = 45427 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '跪倒吧，联盟！在被遗忘者强大的力量之前跪倒吧！' WHERE `Id` = 45449 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当大水涌入的时候，他们对我们发动了攻击！就好象他们早已知道了那场洪水的爆发。$B$B他们要为他们犯下的罪行付出代价。' WHERE `Id` = 45460 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你也将侍奉我！' WHERE `Id` = 45461 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是你愿意的话，除了训练之外，我还可以用自己的力量将天赋从你的头脑中抹去。我要警告你的是，你每经历一次这样的过程，执行这过程的难度就会增加一分，而且所需的费用也会随之上升。' WHERE `Id` = 45480 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这就是你们赢得战争的方法！真应该有人教导一下那个死亡骑士该如何运用军事策略。' WHERE `Id` = 45492 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '向你致敬，$c。愿好运伴随你。' WHERE `Id` = 45493 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我很快就会与你汇合。我们要让那些恐怖图腾的野人明白，什么是光荣。' WHERE `Id` = 45494 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '和我……共赴深渊吧。' WHERE `Id` = 45511 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有了适合的技术，你能修好任何东西，$n。当然，我总会会遇到各种故障、短路和不配合的病人。它们为我带来了不少乐趣。' WHERE `Id` = 45515 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了支援乱风岗的牛头人，击退恐怖图腾部族，我们有许多事情要做，却没有多少时间。$B$BTor ilisar''thera''nal！让我们的敌人知道恐惧！' WHERE `Id` = 45517 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<石母凝视着你。她的目光仿佛穿过你的肉体，正在望着你的灵魂。>$B$B我的女儿——瑟莱德丝，将自己隔绝在泰拉莫克水晶洞穴深处，终日为挚爱扎尔塔的离去而心伤。就在那里，突然闯进了一群没心没肺的畜生，将正沉浸在哀思之中的她杀死。$B$B要是有任何理由能让我对长着血肉之躯的凡人心存信任，这理由也已在那天消逝。而在你傲慢的态度里，我看到了坚持。$B$B总有一天，你也会变得毫无用处。' WHERE `Id` = 45521 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不必害怕。我不会让你掉下去的。' WHERE `Id` = 45525 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我能帮你些什么，$c？' WHERE `Id` = 45531 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯，你可以和那边的大地治愈者多罗斯谈谈……就是那名大个子的德莱尼。你可以在暮光营地的左侧找到他。' WHERE `Id` = 45534 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '把你打倒一定是一件令人愉快的事！' WHERE `Id` = 45548 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看看我们这里都有些什么人？一个被打败的懦夫和一个管闲事的外路人？' WHERE `Id` = 45549 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们很快就会学会该如何拜倒在恐怖图腾的脚下！不过我却不一定会让你们活到那个时候。' WHERE `Id` = 45550 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯，看样子你这种人还是有一点骨气的。' WHERE `Id` = 45551 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我能怎样帮你，$c？' WHERE `Id` = 45564 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些呆子在哪里？' WHERE `Id` = 45574 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愿大地母亲怜悯！' WHERE `Id` = 45575 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '吉德文，下次你可以和我一起坐在前面。' WHERE `Id` = 45594 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我在左边看到了一座塔楼。我们停下来休息一下如何？' WHERE `Id` = 45596 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里的路很难走，吉德文。我可不想冒失去一匹马的危险。' WHERE `Id` = 45598 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们到了！' WHERE `Id` = 45602 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们绝不能让女妖之王失望。' WHERE `Id` = 45645 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的职责不是问为什么。' WHERE `Id` = 45646 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '敢于反抗被遗忘者的，只有死路一条！' WHERE `Id` = 45647 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '高弗雷一定是个非常特别的人。主人付出了巨大的代价，只是为了让他回来。' WHERE `Id` = 45648 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '凡人……他们一直都让我感到惊讶。' WHERE `Id` = 45649 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些可怜的小狼崽不可能抵挡住被遗忘者的力量。' WHERE `Id` = 45650 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '女妖之王已经预见到了一切。' WHERE `Id` = 45651 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们已经完成了另外两个目标。高弗雷是最后一个了。' WHERE `Id` = 45652 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不！谢谢，也许将来有可能，也许过去也有可能，但绝不是今天。' WHERE `Id` = 45667 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很抱歉，我不行。我的任务是看守这个角鹰兽哨站。这些角鹰兽看上去很驯顺，但它们的确需要二十四小时看管。' WHERE `Id` = 45668 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好啊，$c。' WHERE `Id` = 45671 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这只是暂别。' WHERE `Id` = 45672 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你需要返回瓦丝琪尔吗？' WHERE `Id` = 45679 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你呢，贝尔蒙特？你要怎样回去？' WHERE `Id` = 45701 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就这样吧，再见，贝尔蒙特。' WHERE `Id` = 45706 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '天哪……抓紧！' WHERE `Id` = 45707 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么意思？' WHERE `Id` = 45730 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '即使是在达纳苏斯，我们都感到大地有些不对劲。' WHERE `Id` = 45732 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那就是你迁出来的原因吗？' WHERE `Id` = 45737 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '起来，文森特·高弗雷爵士，重生成为我复仇的工具吧！' WHERE `Id` = 45740 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '重生的你将效忠于我，高弗雷。我们将一起粉碎狼人的叛乱，为被遗忘者夺回吉尔尼斯。' WHERE `Id` = 45742 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的，当然……' WHERE `Id` = 45744 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让你的部队做好准备。吉尔尼斯解放阵线正在格雷迈恩之墙集结。他们的援军很快也会从暴风城赶到。我们不能再浪费任何一分钟了。' WHERE `Id` = 45748 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '盔甲、武器，你所需要的一切都能在我身后的供给站找到。现在，行动吧。' WHERE `Id` = 45750 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你再一次地令我震惊，$n。没有你的帮助，我们绝对不会取得这样的成功。欢迎与我同行……' WHERE `Id` = 45751 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然，鲁坎。给你。' WHERE `Id` = 45782 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你进入了红龙的统治领域。' WHERE `Id` = 45783 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不知道你是不是为了响应你的新龙喉盟友的号召来到这里。即使不是，我也不会信任你。' WHERE `Id` = 45784 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你很幸运，因为你的命运并不由我来决定。凯伦正在那棵树旁边等着你。' WHERE `Id` = 45785 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的龙会盯着你。记住，要谨言慎行，$r。' WHERE `Id` = 45786 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你和你的盟友曾经在格瑞姆巴托的大门前攻击我们。对于我们用生命保护的誓言，你们却毫无敬意。我不可能信任你。' WHERE `Id` = 45787 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '空间障碍物被打破了！现在，展开进攻！为了女妖之王！' WHERE `Id` = 45843 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '起来，法师！重生为被遗忘者吧！' WHERE `Id` = 45844 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '伊莉莎很美……真是很美……' WHERE `Id` = 45846 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '虽然我们想要组织人民进行迁移，但我不知道是否能做得到。我们已经接到报告，元素出现在各个地方，向我们发动袭击。无论城镇还是郊野，无一能够幸免。迁移也许不是个好选择。' WHERE `Id` = 45853 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '也许辛德拉的上层精灵也是因此赶来的。' WHERE `Id` = 45855 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '希望我们能尽快找到答案。这里的人民惊惧不已，而教徒们正在利用他们的恐惧。' WHERE `Id` = 45858 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是困难时期啊。对未知的恐惧会导致人们做出蠢事来。' WHERE `Id` = 45860 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我已经说过，凡是跟大地有关的事情都别跟矮人争。要是铜须家族的人相信这块石板能解决困扰大地的难题，那我们就该尽力支持他们。' WHERE `Id` = 45863 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '冒险者都是伪君子！难道你是刚刚在路边拣到了你的武器吗？' WHERE `Id` = 45864 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在奥格瑞玛的其它地方，你再也无法找到比这个更好的火器了。' WHERE `Id` = 45865 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '奥玛克告诉我，你会来的，$n。' WHERE `Id` = 45866 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你从影牙城堡拿出来的这些材料绝非凡品。它们能够让你的武器具有强大的力量。' WHERE `Id` = 45867 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的弓完成了，$n。希望它能为你建立伟大的功勋，就如同你为部落建立的伟大功勋一样。' WHERE `Id` = 45868 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '洛甘纳尔说你会从影牙城堡带来强大的宝物。一开始，我还在怀疑你能弄些什么东西出来。' WHERE `Id` = 45872 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当我看到这些物品的时候，我就感觉到了洛甘纳尔所说的那种强大力量。它们可以被做成一件适合于你的精良武器。' WHERE `Id` = 45876 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，天哪……这次的作品甚至远比我想象的更加强大。' WHERE `Id` = 45884 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '议会将这支法杖给你，就是将一件拥有强大力量的宝物放在你手中，$n。你要用它来守卫我们所信奉的原则。' WHERE `Id` = 45885 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们已经做出保证，要打开一个从暴风城前往高地的元素通道。但暮光堡垒的干扰让我们无法成功。$B$B他们到底在那里发什么疯？' WHERE `Id` = 45911 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '以风、水、地、火之力……我们将前往暴风城，$n！' WHERE `Id` = 45923 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '传送门打开了！感谢你的帮助，现在我们能够从暴风城迅速到达暮光高地了。' WHERE `Id` = 45924 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我刚喝下一瓶治疗药水！暂时无法再使用药水了！' WHERE `Id` = 46005 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '风行者女王亲自派我来，作为部落的使者与扎伊拉和龙喉氏族联系。女王和那位新酋长加尔鲁什正在试图修复他们的关系。$B$B不管怎样，我们必须彻底结束暮光的威胁。而最重要的是，我们必须阻止古加尔制造出他的终极武器。' WHERE `Id` = 46007 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真高兴又看到你了，$n。期待我们能再次并肩作战。' WHERE `Id` = 46015 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些暮光渣滓坚持不了多久了。龙喉氏族为此已经等待了太长的时间，$n。' WHERE `Id` = 46016 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看，柯丝温，我早就和你说过，我们可以依靠$n。' WHERE `Id` = 46017 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '龙喉氏族与部落并肩作战，这是我们共同的荣耀。暮光堡垒一定会被攻陷，$n！' WHERE `Id` = 46018 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '炎魔之王终将为艾泽拉斯带来末日！你们将成为他怒火中的灰烬，蠢货！' WHERE `Id` = 46019 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你在引发混乱之后，无法自行打开后门逃走。你可以选择的方案有：杀死酒吧客人，让卫兵打开后门；或者让罗克诺特下士喝醉，这样他会进行破坏；或者是看看普拉格的身上有没有钥匙！' WHERE `Id` = 46054 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我监视黑铁矮人已经有很长时间了……我谋划，期待，希望着能有机会驱逐他们，夺回我的家园。$B$B他们可以保留黑石山。我希望那座山会再次爆发，彻底毁灭他们。我想得到现在被称为燃烧平原的那个地方，那里本来是赤脊山脉中属于我的那一部分，却被他们的烈焰统治者摧毁了。$B$B$C，我要让全世界知道，我的国土上到底蕴含着怎样的力量。我会在他们留下的死亡与欺诈之上建立一个和平公正的王国。我的守望已经结束。现在我要奋勇作战，夺回应属于我的东西。$B$B为此，我将不惜牺牲自己的生命。' WHERE `Id` = 46062 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '女妖之王派遣了刺客？' WHERE `Id` = 46072 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '高弗雷？那么，那些传闻是真的了？' WHERE `Id` = 46074 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你真的要背叛你的王国？' WHERE `Id` = 46075 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈！那就先杀了我再说吧！去死吧！' WHERE `Id` = 46079 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s失去了知觉。' WHERE `Id` = 46080 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你在引发混乱之后，无法自行打开后门逃走。你可以选择的方案有：杀死酒吧客人，让卫兵打开后门；或者让罗克诺特下士喝醉，这样他会进行破坏；或者是看看普拉格的身上有没有钥匙！' WHERE `Id` = 46081 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这座要塞相当坚固，但我们的敌人从四面八方攻击我们。我们必须先在海岸上站稳脚跟，才能向内陆挺进。' WHERE `Id` = 46082 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看样子，他们已经找到了回家的路。我终于放心了。$b$b你也回来了！有兴趣加入我们吗？' WHERE `Id` = 46089 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '顺便说一句，马车里的物资随你使用……只要你在用完之后把它们拿回来！' WHERE `Id` = 46090 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我希望能有一天，在圣光之愿礼拜堂建起一座商店。我对战斗不在行，但这并不意味着我就不能帮上任何忙。' WHERE `Id` = 46091 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些男孩和我只是一同旅行了很短一段时间，但我已经无法想象没有他们相伴的生活了。' WHERE `Id` = 46092 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '希望你随意使用我的马车里的物品。只要不是我们正在使用的物品，你都可以借走。' WHERE `Id` = 46093 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为什么他会那样逃走？！' WHERE `Id` = 46094 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '向我保证，你一定会找到他，$n。' WHERE `Id` = 46095 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<菲奥拉显得非常不安，没有半点说话的心情。>' WHERE `Id` = 46096 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很高兴能再见到你，$n！' WHERE `Id` = 46097 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨，$n！你是来这里看望我们，还是要买些东西？' WHERE `Id` = 46098 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈哈，看看谁来了！' WHERE `Id` = 46099 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让T.A.D.单位对准优先目标！' WHERE `Id` = 46124 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '对准次级目标！' WHERE `Id` = 46125 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个怪物正在从恐怖图腾的先祖那里汲取能量！我们必须让那些逝者安息，才能真正打败这个怪物！' WHERE `Id` = 46127 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里还有点乱，我们还在收拾，请别介意。$B$B你可以尽情在这里享受！放松放松，消费一下……我们这里什么都有——兑钱商、洗衣店、异国美酒、钓鱼训练师，你可以享受到一流的服务。$B$B如果有人给你麻烦，就来找我，我会为你处理的。$B$B我是米达……大老板米达。' WHERE `Id` = 46135 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看看这里……这里的生意是多么兴旺啊！$B$B当加里维克斯还为他在艾萨拉荒地的花哨宫殿选墙纸的时候，我已经在为老大挣取双倍的利润了。$B$B听我说：数数这里的房子、货栈、各种建筑和维护设施；看看这里的战争工事和补给线……$B$B这一切都还只是刚刚开始！兽人能打仗，但他们不懂得后勤运输。我的人搞运输的速度比他们快两倍，成本却只有他们的一半！好吧……前提是运输途中不出意外。$B$B不管怎样！在这里你可以尽情享受。放松放松，消费一下……我们这里什么都有——兑钱商、洗衣店、异国美酒、钓鱼训练师，你可以享受到一流的服务。' WHERE `Id` = 46136 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，前进！我们会击退联盟狗，为被遗忘者占领洛丹伦！为了部落！' WHERE `Id` = 46139 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我要把你们的城市夷平，把你们碾碎！' WHERE `Id` = 46141 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '放下武器投降！' WHERE `Id` = 46142 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看看他们，$P。他们像老鼠一样来回奔窜，瞎着眼睛朝他们的末日冲过去。克罗雷和血牙肯定知道这是多么没有意义！' WHERE `Id` = 46143 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '格雷迈恩之墙！我们要把他们逼入绝境。' WHERE `Id` = 46144 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '克罗雷，你的部众已在我强大的军队面前落败了。你输了！' WHERE `Id` = 46188 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你鲁莽地葬送人民的生命，而你们的国王却端坐在由谎言铸成的王座上，连手指头都不曾动过一下。' WHERE `Id` = 46190 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '吉尔尼斯值得让那么多人失去生命吗？还有更多将要失去的生命？你赢不了的。' WHERE `Id` = 46191 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那你的女儿呢？你本可以救她……你本可以为她献出你的鲜血，可是你没有。为什么？' WHERE `Id` = 46194 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '暂时还没做什么……' WHERE `Id` = 46196 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我现在给你个选择的机会——这机会我可不曾获得过。' WHERE `Id` = 46197 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我要用罗娜的性命，换取你无条件的投降。' WHERE `Id` = 46198 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '仔细想想再回答我，克罗雷。如果你拒绝我，那么她就将变成我不死的奴仆——直到永远。' WHERE `Id` = 46199 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '把她带上来，高弗雷！' WHERE `Id` = 46200 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '放了她，高弗雷。' WHERE `Id` = 46206 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在你可以离开了，克罗雷，永远别再回来。' WHERE `Id` = 46208 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '洛丹伦属于被遗忘者。' WHERE `Id` = 46209 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '部落的战士们！我们胜利了！洛丹伦是……' WHERE `Id` = 46211 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s倒下了。' WHERE `Id` = 46212 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们束缚于她，姐妹们……' WHERE `Id` = 46220 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这会毁了我们的，姐妹们……' WHERE `Id` = 46221 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是我们神圣的职责。契约已经缔造，交易已经达成……' WHERE `Id` = 46222 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那就接受吧。' WHERE `Id` = 46223 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的眼前……只有黑暗。' WHERE `Id` = 46224 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '正当我朝着虚无漂移时，一道亮光出现了，然后又一道，再一道……我亲爱的瓦格里。' WHERE `Id` = 46225 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我现在明白了——并且坚信不疑——瓦格里是我们的未来。' WHERE `Id` = 46226 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们永远不会放弃洛丹伦。永远不会……' WHERE `Id` = 46227 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '即使是在克尔苏加德统治结束后这光明的日子里，在巫妖王战败之后——兄弟会仍生生不息。' WHERE `Id` = 46246 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '无数人将随我的死亡而倒下。重担……落到你们……肩上了。' WHERE `Id` = 46251 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '仆从们，信徒们，灭世者之子，我在此召唤你们！我们父亲的神圣大厅已经被玷污了！杀死入侵者！' WHERE `Id` = 46252 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '见证死亡之翼赋予我的强大力量吧！感受大地之怒！' WHERE `Id` = 46253 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '主人，请收下祭品。' WHERE `Id` = 46254 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个世界将在烈焰中重生！' WHERE `Id` = 46255 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '护送希尔瓦娜斯·风行者穿过战斗前线。' WHERE `Id` = 46257 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '因为你最勇敢，宝贝儿。' WHERE `Id` = 46271 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我知道我答应让你坐在前排，吉德文，可我们这儿有位年长的客人。真对不起。' WHERE `Id` = 46274 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你经常一个人走在这些路上吗？' WHERE `Id` = 46279 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然，我不仅会把你放下，海毕肯大人。我们还很乐意在这儿等你回来。' WHERE `Id` = 46292 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这不是你的错，塔伦纳。是他自己要跑的。我们谁都阻止不了他。' WHERE `Id` = 46297 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真的？这可是天大的好消息！' WHERE `Id` = 46304 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯，事实上，这是个相当坏的消息，不过总比死了好……' WHERE `Id` = 46305 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你不是只身一人，塔伦纳。你一路上结交了许多盟友。除此之外，你自己本身就是个技艺高超的圣骑士。' WHERE `Id` = 46309 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……可你却能始终与他齐头并进。在没有操练的情况下。' WHERE `Id` = 46311 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们两个的战斗技艺我都见过，塔伦纳。你有着与生俱来的天赋——在这一点上，吉德文永远也赶不上你。' WHERE `Id` = 46312 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们别拐弯抹角了，$r。我来这儿的目的只有一个——那就是消灭古加尔！$B$B你的任务就是阻止他造出终极武器。那可能是个灌注了上古之神力量的强大神器。' WHERE `Id` = 46318 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '准备发射高能炮弹！' WHERE `Id` = 46333 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '杀了那个工程师，别让她还击！' WHERE `Id` = 46334 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '把如此神圣的使命交给古加尔那种傻瓜真是太蠢了！我会亲自解决你们这些入侵者！' WHERE `Id` = 46340 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的孩子们会啃光你们的骨头！' WHERE `Id` = 46343 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真无能……' WHERE `Id` = 46344 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我已经厌倦了。看见你们立足的这片巢群了吗？我的力量正是滋养它们的活力。但这些生命力量永远属于我。面对这超越认知的力量吧！' WHERE `Id` = 46345 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们两个快一点。在一切完成之前，我还想再装满十二只桶呢！' WHERE `Id` = 46377 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，液体黄金。每一滴都要收集好！' WHERE `Id` = 46378 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我喜欢早晨的这种清新气味。当然，就是这种硫磺的酸气……这里全都是这种气味。闻起来就像是……金钱的气味。' WHERE `Id` = 46379 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来自于清水，被灌入桶中。赶快！时间就是金钱。' WHERE `Id` = 46380 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这就是我所说的利润精华。嗨！你漏掉了一些，就在那里。' WHERE `Id` = 46381 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我把附近残骸里能抢救的东西都抢救出来了，现在我已经坚持不住了……' WHERE `Id` = 46397 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '自从这场企业联合战争开始以前，我就在进行各种药剂混合工作了。我现在并不打算停止这行当。$B$B只要还有买家，芭芭就不愁没生意做！' WHERE `Id` = 46412 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们本可以用文明的手段解决这一问题，但我不打算这样！' WHERE `Id` = 46418 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再见。' WHERE `Id` = 46450 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这实在是太有趣了。' WHERE `Id` = 46451 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我猜，不算坏。' WHERE `Id` = 46452 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我要回去了。' WHERE `Id` = 46453 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的招式全是破绽。' WHERE `Id` = 46454 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '又少了一个邪教徒。' WHERE `Id` = 46455 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我知道你会来。没有人能与我对抗，即便是你也不行！' WHERE `Id` = 46463 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '护士莉莲叹了口气。' WHERE `Id` = 46470 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我永远都感谢你，$n。' WHERE `Id` = 46506 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会去对付那些龙。你只需要处理那些暮光垃圾就行了。' WHERE `Id` = 46507 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，是你吗？请帮我摆脱这些锁链。' WHERE `Id` = 46511 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '将军和他的部队正要去攻取一座已经由你进行过侦查的基地。你应该去与他们汇合。' WHERE `Id` = 46531 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊……来这里拜访我的人并不多。$B$B请多坐一会儿吧。' WHERE `Id` = 46538 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是来这里助战的吗？海加尔山必将燃起熊熊大火！' WHERE `Id` = 46543 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '爸爸让我射击！' WHERE `Id` = 46601 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，不，蠢$r……' WHERE `Id` = 46688 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没人能骑我的驼背淑女！' WHERE `Id` = 46689 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '顿沃德家族以刚强悍勇著称，但他们的脑子并不怎么灵光。我很担心我的兄弟们会把他们的名誉和生命浪费在一些不必要的地方。' WHERE `Id` = 46701 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们很担心你会被抓住，但我绝不想把你排除在传送门仪式之外。' WHERE `Id` = 46742 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '拿起这本书，完成仪式。每一个步骤都要完美无缺，否则元素就不会在正确的时间通过传送门。' WHERE `Id` = 46743 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在我要移去你眼前的迷雾。看着吧，我们的俘虏。' WHERE `Id` = 46757 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死亡之翼已经彻底被自己的疯狂征服了。而我们红龙必须趁这个机会把黑龙从他的眼皮底下偷走。我们要让黑龙恢复他们往日的样子，成为大地的守护者。' WHERE `Id` = 46758 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '士兵们，你们要学习$n，誓死保卫暴风城，抵抗敌人的进攻。' WHERE `Id` = 46768 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些邪教徒已经决意要毁灭暴风城。我们必须时刻保持警惕，守卫我们的城市和国王，就像$n所做的那样！' WHERE `Id` = 46769 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你终于回来了！我们已经开始担心你被逮捕了。' WHERE `Id` = 46773 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<当你靠近这座控制台的时候，它发出一阵“嗡嗡”声。>' WHERE `Id` = 46804 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这话别告诉别人，$r。让我们赶快把这里的问题解决掉。这样我就能去干掉古加尔了。' WHERE `Id` = 46838 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好。' WHERE `Id` = 46840 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很高兴能在这里又看到你，$n。我们已经有许多兄弟姐妹落在了酋长的手里。我们还以为永远也见不到你了。' WHERE `Id` = 46841 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有什么发现吗，$n？有没有被跟踪？' WHERE `Id` = 46842 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们需要尽快搞清楚古加尔到底在制造一种什么样的武器！' WHERE `Id` = 46843 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些暮光白痴根本不知道他们在制造什么样的灾难。' WHERE `Id` = 46844 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '古加尔一直藏在暮光堡垒里。真希望他能出来，好好和我们玩一玩。' WHERE `Id` = 46845 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '希望你已经为这个有去无回的任务做好了准备，$n。' WHERE `Id` = 46846 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们需要消灭所有邪教徒和他们的领袖，这样我们才能占领暮光堡垒。' WHERE `Id` = 46847 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '古加尔曾经用一个魔法咒语控制了我的心神，让我做了许多令我深感羞耻的事情。我要让他付出十倍的代价。而你要帮助我，$n！' WHERE `Id` = 46848 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不久之前，暮光之锤侵入了这片曾经质朴清澈的水域和它周围的岛屿。$B$B他们污染了我的湖水。我要彻底驱逐他们，这样我才能净化这片湖泊。' WHERE `Id` = 46924 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这片土地是兽人和人类第一次展开大规模战争的地方。南边不到一里远就是斯通纳德。兽人在那里首次集结，入侵我们的国土。$B$B就是在这里，他们在我们不知不觉间聚集起大规模的军队。就是在这里，他们攻击西边的联盟小镇，拉开了三次兽人战争的序幕。$B$B那是我的城镇，为了救我，我的父母都死在了那里。$B$B但我来这里不是为了复仇……我是要赢得一场战争。' WHERE `Id` = 46928 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨！以前没有见过你。你也失去了家园吗？如果你愿意，可以和我坐在一起。' WHERE `Id` = 46946 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，天哪！真的是非常感谢你。你不知道这对我有多么重要。你真是最好的人！' WHERE `Id` = 46947 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你肯定不是蛮锤的人。为什么要到这里来？不管怎样，你在这个时候跑到这里来，只能说是你的运气不好。' WHERE `Id` = 46948 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什……我的玫瑰？！是凯林告诉你的吗？真不知该怎样感谢你。我还以为自己再也闻不到家乡的气息了……' WHERE `Id` = 46949 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了锈水财阀！为了碎手军团！为了部落！' WHERE `Id` = 46954 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……' WHERE `Id` = 46966 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会把这个留在这里。' WHERE `Id` = 46974 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在该去找蛋了……' WHERE `Id` = 46975 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的小宝贝怎么样了？' WHERE `Id` = 46976 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不……是……是你！不！' WHERE `Id` = 46977 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的，只是……请饶过这颗蛋。' WHERE `Id` = 46981 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的痛苦是永恒的！' WHERE `Id` = 47019 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '伊瑟拉的幻象在你面前逐渐变得清晰真实。' WHERE `Id` = 47021 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，你释放了狼魂先祖，并击败了他的影子。你的行动已经在梦境中产生了反响，谢谢你。但你还有更多的事要去做……' WHERE `Id` = 47022 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<伊瑟拉的影像在你的眼前闪动，仿佛一切都是在梦中。再没有其他人看见她在这里。而那幻象显然也感觉到了你的存在。>' WHERE `Id` = 47023 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '托尔托拉已经在为我们而战了。你拥有巨大的智慧，$n。要赢得这位古老神祗的信任是非常困难的。而现在，他将成为我们可以依赖的力量。' WHERE `Id` = 47025 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '天空的守卫者再次展翅翱翔了！这真是令人振奋的消息，$n。但我们还有很多事要做。我们现在必须把注意力转到别的地方……' WHERE `Id` = 47026 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<伊瑟拉的幻象如同梦一般飘落在你面前。一开始，她的心思似乎并不在你身上。过了一会儿，她才注意到你。>$B$B许多年以来，艾维娜一直在我的梦境边缘闪动。我想知道，她会不会回来。但我也害怕她的灵魂因为过去那段岁月而变得黑暗……$B$B不管怎样，如果我们真的要拯救这座山脉，就必须关注一些更紧迫的事情。' WHERE `Id` = 47027 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里真不错。你不这样认为吗？$b$b也许是有一点热，但只是干热而已……' WHERE `Id` = 47052 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '向女王致敬！' WHERE `Id` = 47061 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不必怜悯弱者！' WHERE `Id` = 47062 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '海洋将完全属于我们，远大征程才刚刚开始。' WHERE `Id` = 47079 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当我到达斯通纳德的时候，我还带着赫格拉姆。在我严厉的教导下，他成为了一名比以前更优秀的追踪者……也是我唯一的同伴。$B$B我以为自己很强。我以为任何痛苦都不可能让我的灵魂倒下。但是，当我看到那些人类的刀剑刺穿赫格拉姆，杀死了我的同伴……我发现自己彻底错了。' WHERE `Id` = 47080 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '对于这个地下室，你有一种很不好的感觉……' WHERE `Id` = 47165 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这条路通向城市的更深处。继续朝南，向装载室走。' WHERE `Id` = 47191 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是令人惊讶！$b$b没想到今天会有人来……' WHERE `Id` = 47197 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里的风景真美，不是吗，$c？' WHERE `Id` = 47274 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '实在是太棒了！$b$b元首是如此自信，还有他的声音！必须承认，他的样子真是有魅力。$b$b你知道他结婚了吗？' WHERE `Id` = 47277 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有传闻说，这里的一些古物具有神秘的力量！$b$b他似乎已经对这些东西彻底着迷了……' WHERE `Id` = 47279 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很抱歉，$c。$b$b对此我真的没什么了解，所以我没什么可说的。' WHERE `Id` = 47281 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '巨龙峡口是联盟在荒芜之地建立的第一个立足点。虽然荒芜之地位于暴风城和丹莫罗中间，但在传统上，它一直是部落的势力范围。$b$b现在这一情况已经发生了改变，我们需要确立自己的权属地位。当然，那头龙对新卡加斯的进攻也不会干扰我们的计划。' WHERE `Id` = 47287 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你以为就这么简单？愚蠢！' WHERE `Id` = 47291 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '够了！汲取这力量之源将使几个月的努力白费。你们应该为自己担得起这份损耗而感到自豪！现在……死吧！' WHERE `Id` = 47292 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有什么需要吗？' WHERE `Id` = 47298 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要在舒适和安全方面浪费一个钱！' WHERE `Id` = 47336 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们把没用的废物都省掉了！' WHERE `Id` = 47337 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们一省再省。' WHERE `Id` = 47338 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你自己想一想：一个总是漏气的“安全”阀有什么用？我感觉这种东西一点也不安全。' WHERE `Id` = 47339 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '和他们说说引擎，老板。' WHERE `Id` = 47340 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们称它为“末日果汁”。' WHERE `Id` = 47341 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然，只是口头上说说。' WHERE `Id` = 47342 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了保证在失火时能够让全体船员迅速做出反应，燃料箱已经从船员区挪到了乘客舱室下方。' WHERE `Id` = 47343 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '飞艇落在海面上的可能性不大。不过，如果发生了这样的事情，请伸手到椅垫下面，你可以在那里找到一粒专门为您准备的氰化物胶囊。' WHERE `Id` = 47344 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了避免您对氰化物的杏仁味过敏，我们特意为胶囊添加了各种调味剂。' WHERE `Id` = 47345 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '您还能找到一袋免费赠送的花生。' WHERE `Id` = 47346 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '朝各个方向随机掷出熔融金属，只有这样才能让一支由易燃飞船组成的舰队确保绝对安全！' WHERE `Id` = 47347 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '非常愿意！' WHERE `Id` = 47348 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我能从这里击中我的房子！' WHERE `Id` = 47349 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不。' WHERE `Id` = 47350 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '也许。' WHERE `Id` = 47351 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '偶尔会。' WHERE `Id` = 47352 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们称它为“紧急无坡道离船装置”。' WHERE `Id` = 47353 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，天哪，不！这些东西都是死亡陷阱！' WHERE `Id` = 47354 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们留在锈水港的全体人员……' WHERE `Id` = 47355 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祝你有一趟刺激的高地之旅！' WHERE `Id` = 47356 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我赶了这么远的路，就是为了和著名的“龙喉先知”谈一谈。在毁灭古加尔之前，我想看清楚他的黑心里面到底有什么。$B$B但她没告诉我任何有意义的东西。我只得到了一堆谜语。也许你能帮助我。' WHERE `Id` = 47367 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我很清楚，出现在这座森林中的恶魔是因为我们一族犯下的错误。$B$B我应该不是第一个想要对此进行弥补的上层精灵。感谢翡翠议会能够不计前嫌，接受我的帮助。' WHERE `Id` = 47495 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要让偏见和古老的仇恨干扰我们的任务，卡多雷。等到我们把这里的事情做完，会有足够的时间争吵和怀疑。' WHERE `Id` = 47505 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '只有神圣遗物学会最高阶的成员知道我们的大殿堂在哪里。$B$B甚至有人说，大殿堂根本就不存在于这个位面……' WHERE `Id` = 47564 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我是否能请求你从那些海盗手中拯救我们，亲爱的$n？！' WHERE `Id` = 47572 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快一点。' WHERE `Id` = 47581 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看到我了吗，古加尔？我是来找你的！我要在你眼前砍掉你的头！' WHERE `Id` = 47586 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了希尔瓦娜斯！' WHERE `Id` = 47590 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '闻起来像……黄金！' WHERE `Id` = 47623 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不久前，我看见他们向那些船上运送了一些古物。$b$b我还从没有见到过那么多黄金被堆在一起！' WHERE `Id` = 47625 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要高傲地昂起头，$n。不能允许这些小矬子们给你制造任何麻烦。让他们知道，谁才是老板！' WHERE `Id` = 47658 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我看见有个家伙过来了！看上去像个真正的胜利者。保持冷静，$n。保持冷静。' WHERE `Id` = 47659 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些新的被遗忘者实在是有些……嗯……愚蠢。他们还需要一段时间适应。' WHERE `Id` = 47666 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，好啊……这个也不是。我知道这个兽人。他不做什么正经事，只是在这里四处晃荡，靠敲诈欺凌为生。别让他吓唬了你。' WHERE `Id` = 47667 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在只能希望他永远不要回来了。也许他会淹死？' WHERE `Id` = 47680 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，废物。你要自己对付这个家伙了，$P。' WHERE `Id` = 47681 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别……别碰我……$b$b出了什么事？！' WHERE `Id` = 47748 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不！我当然不好！$b$b以前我从没见过尸体……' WHERE `Id` = 47750 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他就从那座兵营里跌跌撞撞地爬了出来。$b$b我尖叫着寻求援助，但那些卫兵甚至不看我一眼！' WHERE `Id` = 47752 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的。$b$b听起来像是个好主意。' WHERE `Id` = 47754 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没问题，头儿。呃……我要把它插在哪儿？' WHERE `Id` = 47790 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好。趁那家伙处于虚弱状态，完成对它的控制。' WHERE `Id` = 47823 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '告诉我，你用的是什么魔法？' WHERE `Id` = 47824 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在龙骑士与部落的支持下，我们可以对暮光堡垒发起攻击。' WHERE `Id` = 47830 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再敢口出妄言，我就会送你到你该去的地方，纳克拉尔。' WHERE `Id` = 47831 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '纳克拉尔！要是你想挑战我，就在这儿解决。不要把我们的兵力浪费在愚蠢的征讨上。' WHERE `Id` = 47832 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '多谢你让我重获自由，$n。$B$B现在让我们看看能不能救出玛加萨，并终结暮光之锤在千针石林的罪恶行径。' WHERE `Id` = 47833 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿你好啊。这下面没问题了。' WHERE `Id` = 47834 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会把我们的话语封存在悲泣的紫罗兰中……就算是在加德纳尔和暗影堡的最深处，也能听到我们的声音。' WHERE `Id` = 47844 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没什么新鲜事。' WHERE `Id` = 47887 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯，还不错。' WHERE `Id` = 47888 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们很好。我们现在都很好，谢谢你。你怎么样？' WHERE `Id` = 47889 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我没有担当领袖的经验。我应该预见到纳克拉尔的叛逆。而我却只能收拾他留下的烂摊子。$B$B我不知道加尔鲁什·地狱咆哮是如何做到的。他一定具备过人的力量，才能将如此多样化的部落大军凝聚在一起……我愿意更加深入地了解他。' WHERE `Id` = 47896 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他来了，$n！把他打败，让我用恶魔之链控制住他。' WHERE `Id` = 47917 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '继续战斗，$c！恶魔之链一定能制服他。' WHERE `Id` = 47918 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他的意志——太强大了！' WHERE `Id` = 47944 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那你就去死吧。' WHERE `Id` = 47948 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧。结束了。' WHERE `Id` = 47949 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '到咽喉洞与我见面，$n。向西飞，飞过那条河，然后沿着山脊寻找一个小山洞……' WHERE `Id` = 47950 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '马上，长官。呃……我找不到插孔？' WHERE `Id` = 47968 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<这名演员面无表情地看着你。>' WHERE `Id` = 47992 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '巫婆长老揉搓着她的手腕，露出牙齿向你笑了笑。' WHERE `Id` = 48029 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们竟然能做到这个地步，我很惊讶。' WHERE `Id` = 48032 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我想，我应该感谢你救了我。我们很快就会知道你的这个决定是否明智。' WHERE `Id` = 48035 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '沿这条路向东走，我们在暮光凋零法阵外碰头。' WHERE `Id` = 48037 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '找到密码，把我从这些恶魔骨头中放出来！' WHERE `Id` = 48040 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些洞可都是鬼窟，伙计。里面全都是最可怕的魂能。$B$B当暮光之锤盘踞在这座山顶的时候，那些被他们淘汰的人都被扔进了这些山洞。成为了以这些山洞为巢穴的黑龙的食物。$B$B这些洞里从没有活人走出来，就连那些灵魂也逃不出来。' WHERE `Id` = 48046 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$c！' WHERE `Id` = 48047 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，原来是你抢在我前面了。通过这个传送门离开吧……' WHERE `Id` = 48054 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要害怕坏魂能，$g甜心:女孩;。' WHERE `Id` = 48084 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我听不见低语声了，$n。洞里发生了什么事？' WHERE `Id` = 48096 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你想看着千针石林彻底毁灭吗？$B$B不想？$B$B那就照我说的做。' WHERE `Id` = 48097 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们就是在这儿集合幸存者，准备对他们进行净化。距离地表没多远了！' WHERE `Id` = 48099 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '怎么会有人能把整条赛艇弄丢呢，$n？' WHERE `Id` = 48109 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是你所想出的最低能……最愚蠢……最可笑的计划，巴德！' WHERE `Id` = 48114 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可这恐怕是我们唯一可用的计划。' WHERE `Id` = 48115 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我还能怎么办呢？' WHERE `Id` = 48116 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没人能骑我的驼背淑女！' WHERE `Id` = 48121 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '闭上你的臭嘴，巴德。闭上！！' WHERE `Id` = 48122 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '长久以来，我们都仍希望能挽救大地看守者和他的子嗣。在某些时候，我们必须要明智地意识到，任何程度的弥补都抵不过这些巨龙对这个世界所造成的伤害。$B$B在某些时候，我们被迫要插手。' WHERE `Id` = 48153 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '喔……我真希望我没到这儿来！' WHERE `Id` = 48163 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这太难以承受了。$b$b真希望我有勇气……<啜泣>。' WHERE `Id` = 48167 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我可不能每次都为别人从他们的坐骑上摔落而负责。我不知你是怎么盖到官方印章的，但请你拿上酬劳走开吧，别再来质疑我的马匹了！' WHERE `Id` = 48186 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我那晚肯定是喝醉了，才会答应给你一匹小马。拿着你的钱，别难过，好吗？' WHERE `Id` = 48192 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们这是派谁来了？回去告诉那裁缝，最好用从我这儿拿走的钱，把我的礼服做得完美无缺。' WHERE `Id` = 48219 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我真不敢相信你竟然在这儿卖那些东西。我会顺路拜访厨师来把它们带走。' WHERE `Id` = 48220 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '非常感谢！我生铁锅的保修期能再延长一个月，这太令人高兴了。' WHERE `Id` = 48224 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的……兄弟死了？我真不敢相信自己居然从未见过他。拿着这些钱，好好安葬他吧。' WHERE `Id` = 48225 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的……姐妹死了？我真不敢相信自己居然从未见过她。拿着这些钱，好好安葬她吧。' WHERE `Id` = 48226 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的……叔叔死了？我真不敢相信自己居然从未见过他。拿着这些钱，好好安葬他吧。' WHERE `Id` = 48227 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的……阿姨死了？我真不敢相信自己居然从未见过她。拿着这些钱，好好安葬她吧。' WHERE `Id` = 48228 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '桑德玛尔是蛮锤的最后一处堡垒了。我们狭小的城镇中挤满了难民，而我的兄弟此时正在奋力作战。' WHERE `Id` = 48253 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小心，牛头人先生！角鹰兽来了！' WHERE `Id` = 48256 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '猫咪……猫咪！我真的很抱歉，猫咪！快回来！别这样离开我！' WHERE `Id` = 48258 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别断……千万别断……' WHERE `Id` = 48271 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '该死！那是我最后一把开锁器了！' WHERE `Id` = 48272 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '守卫来了，$n！干掉他！' WHERE `Id` = 48273 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得好！我正准备要动手帮你呢！但看来你已经都搞定了。' WHERE `Id` = 48274 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '锁在后面的那只像猫一样的家伙好像有话要说。也许他能帮到我们……但一定要小心。' WHERE `Id` = 48275 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '吃吧，孩子们！尽情享用他们肥美的躯壳吧！' WHERE `Id` = 48282 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们这群愚蠢的杂种！我真该用鞭子把你们全都抽死！' WHERE `Id` = 48319 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们这群蠢货毫无用处！毫无用处！' WHERE `Id` = 48320 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们这些卑劣的杂种最好尝尝我鞭子的滋味！' WHERE `Id` = 48321 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我要让你们鲜血四溅，你们这群没用的瘦皮囊！' WHERE `Id` = 48322 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别在呜咽了，没用的东西！' WHERE `Id` = 48323 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊！我……我动不了了！' WHERE `Id` = 48325 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不……不……让它们离我远点儿！' WHERE `Id` = 48326 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不！啊——！！！' WHERE `Id` = 48327 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不！伊利丹，你怎么可以？' WHERE `Id` = 48358 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '也许你没有听到我的话。我说了，让我摆脱这些链子！' WHERE `Id` = 48472 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小心说话，死亡之翼的奴才。你以为我是个傻瓜吗？' WHERE `Id` = 48498 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '泰拉莫克是我的家园，而不是我的牢狱。造就它的正是我曾经钟爱的一切。' WHERE `Id` = 48499 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不过不必失望，食人魔。我会继续帮助你和你的……教派。' WHERE `Id` = 48500 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '毕竟，我很喜欢在上面的世界造成冲突与战争……我喜欢震撼，粉碎，吞噬和摧毁……' WHERE `Id` = 48501 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……但我会留在这里，永远如是。' WHERE `Id` = 48502 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '走吧。' WHERE `Id` = 48503 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的敌人将要毁灭！' WHERE `Id` = 48513 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我已焕然一新！' WHERE `Id` = 48514 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '洛丹伦是我们的了！' WHERE `Id` = 48515 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是辉煌而美丽的力量啊！' WHERE `Id` = 48516 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '胜利属于被遗忘者！' WHERE `Id` = 48517 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你可真是位骁勇善战的勇士。那怪物已经被解决了。我们离开这里吧。' WHERE `Id` = 48521 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我听说过你。你来此拯救你的世界，从我们这里学习知识。盖亚安祖母命我指导你，因此，你必须听我的话，古伊尔。' WHERE `Id` = 48564 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯，我知道，古伊尔。萨尔是部落的领袖，可你并非以那样的身份来到这里。看看你自己——看看你这身打扮……' WHERE `Id` = 48566 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你说你是来寻求知识与理解，可你却身穿战甲。因此，我质疑你与你的意愿——你是否已准备好完成必须完成的任务。' WHERE `Id` = 48567 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那矮人说得没错。如果你希望与元素交流，你就必须具备发自内心的诚意。' WHERE `Id` = 48570 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是你的心，是你对家园与人民的热爱把你引到了这里。不是你的战甲，也不是你的武器。' WHERE `Id` = 48571 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '古伊尔。你不能继续在酋长与萨满这两种身份间徘徊。总有一天，你必须让自己做出选择。这一天很快就会到来。' WHERE `Id` = 48574 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们聚集在西边海中的赎罪岛上。我们要去那里见他们，将军。' WHERE `Id` = 48639 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这股气味……*巴琳达用力抽抽鼻子*，我想它应该是从那里来的……' WHERE `Id` = 48640 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是，将军！' WHERE `Id` = 48647 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '去死吧，兽人！' WHERE `Id` = 48660 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别想碰到我的镇子，兽人！' WHERE `Id` = 48661 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你就弄到了这些！？' WHERE `Id` = 48662 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你想得到范妮？你不能碰范妮！' WHERE `Id` = 48663 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，你一离开了龙，就什么也不是了，对不对？' WHERE `Id` = 48664 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来吧！让我狠狠给你一下子，兽人！' WHERE `Id` = 48665 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没错，兽人。我要把你的魂打飞！' WHERE `Id` = 48666 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会让你闭嘴，兽人。我会把你埋进土里！' WHERE `Id` = 48667 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果我们不尽最大可能提高生产效率，部落也许就要输掉这场战争了。如果部落输了，我们可就死定了。$B$B我不想打碎你的幻想。但你在语风林地听到的那些美妙的玩意可救不了我们……能救我们的只有勤奋的工作。' WHERE `Id` = 48674 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '自从月神的镰刀第一次来到这里后，我们之中很少的一部分人住到了这个地方。他们大都承受了吉尔尼斯沉沦的劫难。$B$B我们一直居住在这片森林中，学习自然之道，并致力于维持它的平衡。在这片被诅咒的土地上，我们被诅咒的族人已经找到了一条新的人生之路。' WHERE `Id` = 48729 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '喔！' WHERE `Id` = 48735 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n？你在这里干什么？你在听从科甘·焰须的命令？' WHERE `Id` = 48736 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在享受美好时光吗？' WHERE `Id` = 48737 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们有些不安分，所以我要处理一下。好了，我已经忙完了。' WHERE `Id` = 48738 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一定要迈格拉夫一家人谈谈。他们就在庇护所里。他们会在那里安排这场仪式的。' WHERE `Id` = 48775 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为什么地面在颤抖，$n？！' WHERE `Id` = 48861 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，不，你不能那样！' WHERE `Id` = 48866 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我没想到这里还会有人。你打算作我的同伴，还是只想找一条路出去？' WHERE `Id` = 48894 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '晚上好。' WHERE `Id` = 48949 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '希望我的人能够给予你适当的欢迎。这是个艰难的时代，恐怕没有多少人还会在乎礼貌和优雅了。' WHERE `Id` = 48950 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你曾经承诺过会还我的人情。现在，我只能让你履行你的承诺了。' WHERE `Id` = 48952 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在洛达内尔，我们的一座与鲁瑟兰隔水相望的村子里出现了一些很糟糕的情况。' WHERE `Id` = 48953 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '希望你能支援我们一些人手。在卡利姆多爆发的战争正逐步蚕食着我们。' WHERE `Id` = 48954 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '泰兰德大人！没想到你会来。晚上好。' WHERE `Id` = 48957 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们就要离开了。再次欢迎你们所有人。' WHERE `Id` = 48958 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是我的了！' WHERE `Id` = 48962 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '女妖之王已经对你做出了计划，人类。' WHERE `Id` = 48963 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你无处可逃了！' WHERE `Id` = 48964 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死亡只是开始。' WHERE `Id` = 48965 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧…………这里的全都属于你。没关系，无论是有生命的、岩石的，还是……' WHERE `Id` = 48996 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你让两只眼睛对起来，将拇指伸向天空，用力按过去……' WHERE `Id` = 48998 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '魂精就有可能出现！就像这样。' WHERE `Id` = 48999 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是一个女孩所能梦想的最英俊的男朋友。所有女孩都会为你神魂颠倒，甜心！' WHERE `Id` = 49012 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你最好快上楼去，老板。贸易大王加里维克斯正在等你。' WHERE `Id` = 49015 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，你必须加紧行动，把你的钱从银行里拿出来！' WHERE `Id` = 49016 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他能给我们弄到更多的卡亚可乐吗？如果我们不能让自己的头号商品摆满货架，又怎么能让你成为贸易大王？！！！' WHERE `Id` = 49018 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，我想你会喜欢这个的，老板！' WHERE `Id` = 49019 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们在这里！好了，你们三个今天来帮$g他:她; ，在聚会开始之前，$G他:她;要做的事情可是不少呢！' WHERE `Id` = 49020 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '王牌、小静、大胖，你们三个要跟着$n，帮助他处理那些坏家伙！' WHERE `Id` = 49021 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一定要从那个银行里拿到足够的钱。我可不希望你还去买你平时喜欢穿的那种廉价衣服。这可是个重要的聚会！' WHERE `Id` = 49023 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你所要做的就是学习暗言术：痛，并使用在附近的训练假人身上！' WHERE `Id` = 49030 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会教你如何施展刺骨技能。然后，你可以到巴姆正在射击的那些训练假人那里去，用影袭技能攻击其中的一个，再用刺骨技能干掉那个假人。' WHERE `Id` = 49031 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你到了那幢小屋之后，我会将帽子设置成自动状态。小心一定要躲开那些猪！' WHERE `Id` = 49035 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '想要驰骋一番吗，$g坏家伙:甜心;？来吧，我们要去沼桨镇。这可是一次单程旅行。' WHERE `Id` = 49048 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这么多美好的回忆，这么多丰厚的利润。我可不能袖手旁观。' WHERE `Id` = 49071 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别喊了，霍巴特，我就在这里。嘘！' WHERE `Id` = 49102 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '给你，一只“微型机动战鸡”。我一直都不明白，你是怎么想出这些怪名字的。' WHERE `Id` = 49103 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '格瑞里叹息着，眨了眨眼。' WHERE `Id` = 49105 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是，钩锤博士。' WHERE `Id` = 49106 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '助手摇了摇头。' WHERE `Id` = 49109 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '格瑞里咳嗽了一声。' WHERE `Id` = 49113 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '呃，没错，霍巴特，一切都在你的掌控之中。' WHERE `Id` = 49114 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你在想什么？霍巴特，这只微型机动战鸡很不稳定。它在剧烈膨胀！' WHERE `Id` = 49121 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就是最右边的那个！赶快，霍巴特！它就要爆炸啦！' WHERE `Id` = 49123 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么？！！！' WHERE `Id` = 49126 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们还活着，钩锤博士，全靠你的努力。' WHERE `Id` = 49128 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你脸上那是鸡蛋吗？' WHERE `Id` = 49131 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好了，告诉我，“你一直都是爱我的”是什么意思，钩锤？' WHERE `Id` = 49132 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在这一点上，我们可以达成共识，博士。' WHERE `Id` = 49134 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨，你还好吗，老板？霍巴特和我正在努力确保当卡亚矿石资源枯竭时，你还会有足够的库存产品。$B$B现在矿脉中的卡亚矿石只有这么多了，如果它们都被开采干净，我害怕卡亚可乐也就没有了。' WHERE `Id` = 49135 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看样子，这就是最后了，如果你有足够的胆量，那我也就有，$n。' WHERE `Id` = 49139 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么？你想要什么？' WHERE `Id` = 49174 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不和废物说话！' WHERE `Id` = 49175 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你和我不是一伙儿的，甜心。' WHERE `Id` = 49176 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我没有劝你回学校，现在我也不打算这么干。' WHERE `Id` = 49177 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真有趣……我说的是你穿的这身“行头”。' WHERE `Id` = 49178 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的，我要再来一杯。快一点。' WHERE `Id` = 49179 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是贸易大王的聚会，甜心。只有受邀请的人才能参加！' WHERE `Id` = 49180 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，是你吗？送你一句话：不要让贸易大王抓住你。他知道你在盯着他的位子。$B$B所有人都知道。' WHERE `Id` = 49181 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '蠢货？！我可不和如此无礼的人说话。你怎么敢这样！' WHERE `Id` = 49182 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们应该管你这种家伙叫什么？蛮子？巨怪？$B$B我可受不了你这种人。赶快离开这里。' WHERE `Id` = 49183 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你又大又强壮。但你需要好好洗个澡。赶快跳到池子里去吧。' WHERE `Id` = 49184 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，不，别和我说话！' WHERE `Id` = 49185 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里是什么气味？哦，是你啊。$B$B快给我躲远点！' WHERE `Id` = 49186 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的名字叫什么？$B$B也许你这种蛮子还是当个哑巴比较好。否则我就只能向贸易大王投诉，告诉他你是多么令我讨厌。$B$B现在，离我远一点！' WHERE `Id` = 49187 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再碰我一下，我就让他们送你去安德麦！' WHERE `Id` = 49188 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，你可真让人讨厌！为什么来找我的总是你这种丑家伙？！' WHERE `Id` = 49189 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我愿意。' WHERE `Id` = 49215 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不必为霍巴特担心，老板。他只是有一点精神崩溃。$B$B对他来说，这场大灾变来得可以说非常不是时候。他就要完成微型机动战鸡的制造了。' WHERE `Id` = 49240 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好的，博士。图纸，检查完毕。牙刷，检查完毕。' WHERE `Id` = 49241 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会的，我会的。但霍巴特，你必须先平静下来。你的血压已经很高了！你全身都变成深绿色了！' WHERE `Id` = 49242 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯，我应该是在这里见过它，但你确定吗？那东西并不只是会将使用者的外形放大百分之五十，而是会把使用者变成怪物，然后还会让使用者爆炸！' WHERE `Id` = 49243 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你不冷静下来，你就要爆炸了！难道你不认为这样会比较方便吗？当足球炸弹最终被踢进卡亚罗山，胜负已定的时候，那头龙恰好飞过天空。' WHERE `Id` = 49244 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会立刻做好胶囊实验室在艾萨拉展开的标记。我会把她的小软垫和她放在一起。她是那么聪明可爱！' WHERE `Id` = 49245 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '从技术上说，这是不现实的，博士。那是从卡亚罗山火山口中喷出的岩石，也就是火山喷出物，而不是天空。那些都是液化岩石和火山灰。它们会在降落时逐渐冷却，变成熔岩炸弹。这才是恰当的解释，不是吗？' WHERE `Id` = 49246 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那是一场真正的聚会，而且我的确受到了邀请。为什么总是有意外发生，让我永远也无法走开？我应该好好喝上一杯的。' WHERE `Id` = 49247 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '霍巴特，你正戴着它呢。' WHERE `Id` = 49248 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看吧，哭泣吧。' WHERE `Id` = 49258 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看到了吗？什么也无法阻挡我的战锤的力量。' WHERE `Id` = 49259 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们完了，$n！我现在和奇普在一起了。' WHERE `Id` = 49306 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '离我远点儿，你这怪物！' WHERE `Id` = 49334 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '亡灵是艾泽拉斯的腐蚀之源！你们这些家伙都该被毁灭！' WHERE `Id` = 49335 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不。你在撒谎！父亲会保护我的！' WHERE `Id` = 49337 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是你的大型见面会。我们要让你成为贸易大王，$n！$B$B出去显示你的权威吧！' WHERE `Id` = 49355 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '海盗？！你得来解决一下，长官！他们正在毁掉派对！' WHERE `Id` = 49356 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这看起来可不怎么样，长官。' WHERE `Id` = 49360 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '老板，我们会想尽一切办法为你集齐一万亿杏仁币的！' WHERE `Id` = 49362 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们得尽快结束这里的事情，把你送到码头，趁贸易大王还没把我们大家甩在身后！' WHERE `Id` = 49363 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨，宝贝儿。呃……我们得谈谈，不过不是现在。$B$B好吗？' WHERE `Id` = 49364 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '市场营销搞得再好也没办法把我们从这座岛上弄出去。我们唯一的希望就是弄到一万亿杏仁币！$B$B你最好赶紧弄到那笔钱并且送到码头去！' WHERE `Id` = 49366 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '暮光之锤吓不倒我。尽管来吧！' WHERE `Id` = 49401 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '蛮——锤！' WHERE `Id` = 49402 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '抓住它！杀了它！' WHERE `Id` = 49403 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '凡人，我希望你能见证这一切，不过为了你的安全，站远一点。凯伦，你也是。' WHERE `Id` = 49429 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要浪费你的生命，凯伦。一旦我失败，那么世界的命运将落在你的肩上。' WHERE `Id` = 49430 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这令我痛苦，奈萨里奥——但我必须终结你，就像我终结玛里苟斯一样。' WHERE `Id` = 49431 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '曾经的伟大盟友只剩这具空洞的金属躯壳，真是浪费泰坦的恩赐。' WHERE `Id` = 49432 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '奈萨里奥！看看你自己。残缺。扭曲。你已支离破碎。' WHERE `Id` = 49433 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '大地的守卫者……他死了。' WHERE `Id` = 49434 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '黑龙守护者之血受到了诅咒。但凡所溅之处，一万年都长不出任何东西。' WHERE `Id` = 49435 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿莱克丝塔萨痛苦的喘息着。' WHERE `Id` = 49436 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但是都结束了，终于可以将他带来的恐惧尘封起来了。' WHERE `Id` = 49437 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这不可能！' WHERE `Id` = 49438 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '凯伦，不！' WHERE `Id` = 49439 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不！' WHERE `Id` = 49440 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿莱克丝塔萨很快就会到来。来吧，让我们做好准备。' WHERE `Id` = 49464 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为殒落已久的生命燃起烈焰，他们的魂灵与所有鲜活的生命同在。' WHERE `Id` = 49465 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为即将降临的生命燃起烈焰，懵懂的灵魂在母体中苏醒。' WHERE `Id` = 49466 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为新诞的生命燃起烈焰，青春盛放的热情与蓬勃不息的活力。' WHERE `Id` = 49467 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为正值盛年的生命燃起烈焰，奋力缔造和重塑这个世界。' WHERE `Id` = 49468 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为即将凋零的生命燃起烈焰，他们的使命也许将要完成，但他们的贡献却会成为永恒。' WHERE `Id` = 49469 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '生命的循环已经完成。一切都已就绪。' WHERE `Id` = 49470 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊——阿莱克丝塔萨来了。' WHERE `Id` = 49471 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '从舱门上方传来一阵响声！' WHERE `Id` = 49476 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你知道，我已经等了很久了。' WHERE `Id` = 49477 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '等待属于我的时机，建立我的军队，分析敌人的心理。' WHERE `Id` = 49478 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '肉搏战从来不是我的强项。我和我父亲不同。' WHERE `Id` = 49479 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但我总是擅于施毒。' WHERE `Id` = 49480 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '尤其是影响心智的剧毒。' WHERE `Id` = 49481 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '梵妮莎向你体内注入了噩梦药剂！' WHERE `Id` = 49483 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我明白，阿莱克丝塔萨已经对死亡之翼做出了判决。也许这场磨难终将在这里结束？' WHERE `Id` = 49514 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会留下，想办法释放这些蜘蛛。谢谢你的帮助，$n。' WHERE `Id` = 49549 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是来帮忙的，$c？让我们暂时待在一起。' WHERE `Id` = 49550 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '以后再庆祝吧，指挥官。暮光巨龙正在逼近！' WHERE `Id` = 49560 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '异教徒！你要为你的罪行受到惩罚！' WHERE `Id` = 49585 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '使你获得真理启迪的途径只有一条，那就是死亡！' WHERE `Id` = 49586 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '浸沐在主人的力量中！化作主人怒火的使徒！' WHERE `Id` = 49587 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了主人，我万死不辞，万死……' WHERE `Id` = 49588 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '恭喜你，冒险者。' WHERE `Id` = 49640 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你已经径直走进了我的陷阱！' WHERE `Id` = 49642 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一张便笺掉在了地上！' WHERE `Id` = 49658 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '黑丝洞就在北面。多加小心，那里近来危机四伏。' WHERE `Id` = 49665 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '月亮井在东北面，在水池另一侧的山上。' WHERE `Id` = 49666 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '通往奥达希尔的梯道就在那边。盘旋而上就能找到特纳隆。' WHERE `Id` = 49667 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '埃沃隆身上的毒素已经散去，但还需要一些时间才能复原。' WHERE `Id` = 49668 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '腐坏的种子已深植在他体内。' WHERE `Id` = 49669 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们当然已是无可挽回，但看着他们死去，还是令人感到心如刀绞。' WHERE `Id` = 49670 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我亲爱的朋友们……我很抱歉……' WHERE `Id` = 49671 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他的躯体在渴求死亡，可他的灵魂却在渴求怜悯。' WHERE `Id` = 49672 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '腐化的程度远非这些蜘蛛力量能及。我担心真正的源头并不在这洞穴之中。' WHERE `Id` = 49673 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我为我们犯下的这些罪行而哭泣。简直令人难以忍受。' WHERE `Id` = 49674 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如此程度的腐化不可能源自外部。' WHERE `Id` = 49675 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他体内的腐化仿佛是与生俱来的。' WHERE `Id` = 49676 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我已经没有新东西要教你了。现在继续向东，前往治愈者营地吧。当安多哈尔之战打响之时，你将受到召唤。希望库尔迪拉没有等太久……' WHERE `Id` = 49677 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '恐怕我们并没有时间优势，伊尔萨莱恩。如果我们不尽快开始行动，就连泰达希尔也将难逃战火的席卷。' WHERE `Id` = 49682 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们会让你继续你的训练，伊尔萨莱恩。在这方面你才是行家。' WHERE `Id` = 49683 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好好学习吧，$n。在下个月满之夜到来之前，我们可能会需要你协同作战。' WHERE `Id` = 49684 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '交给我吧。' WHERE `Id` = 49691 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个图腾正在腐蚀这些蛋！这后面很可能隐藏着一个更加巨大的威胁。瘤背一族仍然在遭受某种极端邪恶的污染。' WHERE `Id` = 49697 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '赫格拉姆！' WHERE `Id` = 49699 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '坚强些，尼卡。我会注视着你……' WHERE `Id` = 49704 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可怜的格拉布托克。他每次施法都会烧掉自己的住处。' WHERE `Id` = 49715 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在他的灵魂深处，令他最为惧怕的就是……他自己。' WHERE `Id` = 49716 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '许多盗贼喜欢把自己藏在阴影中，赫利克斯是个例外。' WHERE `Id` = 49723 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你永远不知道黑暗中潜藏着什么。' WHERE `Id` = 49724 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你能想象一台机器的生命吗？' WHERE `Id` = 49725 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一个小小的火花就决定了生……或是死。' WHERE `Id` = 49726 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死亡之翼！我失败了……血脉……保不住了。' WHERE `Id` = 49729 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '灌注在巢群中的力量将由我自己收回！' WHERE `Id` = 49730 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '受苦吧！' WHERE `Id` = 49732 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '感受我的憎恨！' WHERE `Id` = 49734 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来吧，暮光之子！' WHERE `Id` = 49738 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们的母亲在召唤！' WHERE `Id` = 49739 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '撕心狼并非天生凶残嗜杀。他甚至拥有过自己的家庭。' WHERE `Id` = 49742 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他曾被称作詹姆斯·哈林顿。悲剧的三部曲。' WHERE `Id` = 49745 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不会重蹈父亲的覆辙！你的传说就此终结！' WHERE `Id` = 49748 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这只是第一个。' WHERE `Id` = 49749 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你真以为我会只身一人前来作战？' WHERE `Id` = 49750 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '蠢货！整艘船上都布满了炸药！在烈焰中去见死神吧！' WHERE `Id` = 49751 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我就算是死，也要拖上你们所有人！' WHERE `Id` = 49752 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '够了！你休想亲手杀死我！' WHERE `Id` = 49753 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的命运属于我自己！' WHERE `Id` = 49754 AND `Locale` = 'zhCN';
