UPDATE `broadcast_text_locale` SET `Text_lang` = '你做了最好的选择，古伊尔！战胜那些怀疑！他们在吞噬你的心！' WHERE `Id` = 52106 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '打起精神——另一波又来了！' WHERE `Id` = 52108 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是古伊尔，杜隆坦与德拉卡之子！名正言顺的部落酋长！你还赢得了我的心！记住你是谁！' WHERE `Id` = 52110 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '平静下来，我的爱人。冷静心绪。你成了使命的奴隶。但只有直面内心，你才能继续履行使命……为了你的人民……也为了我。' WHERE `Id` = 52112 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '暮光爪牙出现在魔枢……$b$b这真是危急万分的时刻，$r。' WHERE `Id` = 52143 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，不！离开这里！我只想独自怀念我的姐妹！' WHERE `Id` = 52144 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我劝过你离开的！' WHERE `Id` = 52145 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我发誓要保护这个地方！' WHERE `Id` = 52146 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈！你不过是个无聊的玩物！' WHERE `Id` = 52147 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '分担我的痛苦！' WHERE `Id` = 52148 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '感受我的痛楚！' WHERE `Id` = 52149 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个身体已经没用了……' WHERE `Id` = 52150 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看那边，漩涡中有一个幻象！那就是古伊尔长久以来的期望吗？和平……摒弃敌意，结束连绵不绝的战争？' WHERE `Id` = 52189 AND `Locale` = 'zhCN';
