UPDATE `broadcast_text_locale` SET `Text_lang` = '另一个幻象！那是古伊尔，但……另一个人……是我。我是他最深的渴望？一个伴侣，能够分享他的生命，分享他的负担和喜悦？' WHERE `Id` = 52191 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '最后一个幻象！先祖啊……难道那是……我和他的孩子？他最深的渴望……是成为父亲？' WHERE `Id` = 52192 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '拥有自己的家庭……和我一起……？古伊尔从未见过他的父母……他几年前才找到自己的族人……我早该知道这就是他最深的渴望。' WHERE `Id` = 52193 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '先祖们，赐予我力量！漩涡的引力在增加！他的渴求之力……太强大了！' WHERE `Id` = 52194 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在阿格娜被卷入漩涡前找到并救出她！' WHERE `Id` = 52196 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我……和这个世界……都如此的需要他。但他却总是将其他人的需要凌驾在了自己之上。他究竟将自己的情感和渴望……压抑了多久？' WHERE `Id` = 52198 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '古伊尔！' WHERE `Id` = 52200 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快，凡人。$b$b我们在魔枢里汇合！' WHERE `Id` = 52201 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别担心，我会保护好火红鞭笞者的。但在我们熟悉它的习性之前，它恐怕只能留在火焰之地了。' WHERE `Id` = 52223 AND `Locale` = 'zhCN';
