UPDATE `broadcast_text_locale` SET `Text_lang` = '我们在此恳求您，炎魔之王！' WHERE `Id` = 52332 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '目睹他的力量！' WHERE `Id` = 52333 AND `Locale` = 'zhCN';
