UPDATE `broadcast_text_locale` SET `Text_lang` = '<暗影守望者静静地看着你。>' WHERE `Id` = 52335 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们还不能休息，孩子。海加尔还没有沦陷。但如果我们在炎魔之王的门前踯躅，仍有可能一败涂地。愿远古半神的力量与我们同在。' WHERE `Id` = 52338 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '风暴乌鸦很难在这种高密度的空气中飞行，可那边山脊上的火鹰翱翔起来却好像很轻松。$B$B它们和这片火焰平原上的其他生物一样狂野，但它们的形态却十分美丽。' WHERE `Id` = 52339 AND `Locale` = 'zhCN';
