UPDATE `broadcast_text_locale` SET `Text_lang` = '噢喔，你脸上好像有东西！' WHERE `Id` = 52343 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们能否赢得这场战争？只有天知道。' WHERE `Id` = 52344 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里可真闷热。有人让他们升高温度了吗？' WHERE `Id` = 52345 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我喜欢你！青出于蓝啊。' WHERE `Id` = 52347 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有人说我很土，可我觉得自己还挺睿智的。' WHERE `Id` = 52348 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，又是你呀！你觉得，我们能召集到足够的部队吗？' WHERE `Id` = 52349 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你关于守望者的一切疑问，都将在战场上找到答案。' WHERE `Id` = 52353 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '守望者是什么人？我们是精密的杀戮机器。' WHERE `Id` = 52354 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '守望者是什么人？我们是播撒死亡的旋刃。' WHERE `Id` = 52355 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '守望者是什么人？我们是无声的暗影。' WHERE `Id` = 52356 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '用你的眼睛去看。你看到了什么？你感觉到了什么？' WHERE `Id` = 52363 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在我们准备进攻火焰之地的时候，炎魔之王派出了手下爪牙来拦截我们。我们在这里的据点绝对不能陷落，我们已经是保卫世界之树的最后一道防线了。' WHERE `Id` = 52366 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎你，$n。你是来参加对火焰之地的进攻的吗？' WHERE `Id` = 52367 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们暂时还无力反攻火焰之地。首先，我们得重整部队，建立补给线。你愿意帮助我们吗？' WHERE `Id` = 52368 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '眼前所发生的一切与我们所有人都息息相关。每一分力量都是宝贵的。大家必须同心协力对抗入侵。' WHERE `Id` = 52369 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有小动物吗需要我救助吗？$B$B<米露恩两眼放光。>$B$B我要立刻去抱抱小兔子！' WHERE `Id` = 52370 AND `Locale` = 'zhCN';
