UPDATE `broadcast_text_locale` SET `Text_lang` = '你好啊！园艺可是我的强项！要打听本地的植物环境吗？' WHERE `Id` = 52400 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没有什么比花朵的绽放更能振奋人心的了！' WHERE `Id` = 52401 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的古伊尔……被大海吞噬了。在他自己的欲望中煎熬！' WHERE `Id` = 52409 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '循环又开始了！古伊尔变成了活生生的石头！我们必须到深岩之洲的洞穴里去找他。$b$b在亲眼看到大地之环拯救了她的国度之后，塞拉赞恩应该更愿意帮我们救他了。如果她不肯，那位石母必将付出代价！' WHERE `Id` = 52410 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的，凡人，你们的萨尔就在这里。他的心和灵魂都已经和石头融合了。' WHERE `Id` = 52423 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '作为血肉凡人，他的灵魂十分强大。他令我惊奇……我不想放弃他。' WHERE `Id` = 52424 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但我能听到哭泣的心声，遥远地回响在两个世界间的无尽迷宫里。这是为爱人哭泣的心声……伟大的塞拉赞恩并没有忘记爱是什么……' WHERE `Id` = 52425 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的救世萨满就在下面的玄武岩森林里。但他已经变成了这无尽岩石大厅的一部分。' WHERE `Id` = 52426 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他也许不想离开，无论是谁在呼唤他。' WHERE `Id` = 52428 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '带着我的祝福……去找他吧。' WHERE `Id` = 52429 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '感谢您，石母。' WHERE `Id` = 52433 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快一点，朋友。古伊尔应该就在下方。' WHERE `Id` = 52434 AND `Locale` = 'zhCN';
