UPDATE `broadcast_text_locale` SET `Text_lang` = '一定得让这些入侵者知道，我们的土地不是那么好侵占的。我很乐意给它们上这一课。' WHERE `Id` = 52439 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '随时待命，队长。' WHERE `Id` = 52443 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '早就迫不及待了。' WHERE `Id` = 52445 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没问题，伙计。我们赶紧动手吧。' WHERE `Id` = 52446 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我来奶吧，兄弟。我可是有特殊形态的哦。' WHERE `Id` = 52459 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '感觉到空气中的魔法能量了吗，$c？' WHERE `Id` = 52460 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在这个季节，空气中弥漫着强大的法力，$c。' WHERE `Id` = 52462 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '火焰。我的爱人变成了火焰。我害怕的事发生了。我们必须进入拉格纳罗斯的火焰领地寻找他。' WHERE `Id` = 52470 AND `Locale` = 'zhCN';
