UPDATE `broadcast_text_locale` SET `Text_lang` = '我的獠牙很大吧？这还多亏了你。' WHERE `Id` = 52513 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '滚回烈焰中去吧，混蛋。' WHERE `Id` = 52517 AND `Locale` = 'zhCN';
