UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你。我能自己去村子里。注意安全……' WHERE `Id` = 53475 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在进入竞技场的是：$n！' WHERE `Id` = 53476 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在……战斗开始！' WHERE `Id` = 53477 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就快胜利了，$n。加油！' WHERE `Id` = 53478 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你就要赢了，$n！' WHERE `Id` = 53479 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祝贺$n赢得这场战斗！' WHERE `Id` = 53480 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祝你下次好运，$n。你可以试着用一些能够同时打击多名敌人的技巧！' WHERE `Id` = 53488 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '出什么事了？$b$b我——我们在哪儿？' WHERE `Id` = 53503 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '去村里……重整队伍……我想我能坚持下去。' WHERE `Id` = 53505 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '将军决心在这里扎营。$b$b但愿他知道自己在做什么……' WHERE `Id` = 53509 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '进入乱斗比武场并燃放焰火。然后，做好同时面对几名对手的准备吧！在乱斗比武场中，一切皆有可能。' WHERE `Id` = 53579 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不久之前，魔古族还只是在树林里伏击一下过往的行人而已。但这次袭击不同，这次行动是有组织……有目的的。' WHERE `Id` = 53635 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是第一个穿过那座大门后没有被吓坏、或是受伤，或是又伤又怕的。$B$B但愿你能帮上我们的忙。' WHERE `Id` = 53636 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然是一座禅院！$b$b天禅院的武僧专门教授像我一样的年轻熊猫人如何战斗。所有的战斗大师都是在这里诞生的：剑仙宇明、铁布衫梁……甚至连伟大的帝王少昊都是在这座寺院学习的。$b$b或者至少传闻是这么说的。' WHERE `Id` = 53644 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎来到我们在群山中的家园，$r。' WHERE `Id` = 53645 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好啊！欢迎你！' WHERE `Id` = 53646 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '呃！青玉巫婆！我得躲起来！' WHERE `Id` = 53684 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……解决了那东西，你和这群乌合之众就是我的下一个目标。唔，我还以为你们根本到不了这儿！' WHERE `Id` = 53751 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们已经在这里困守了好几天了。大家都已经濒临崩溃的边缘了，不过依然在努力保持斗志。' WHERE `Id` = 53760 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些……猴子……攻击我们……$b$b我击退了他们，可……他们很快就会回来……带着更多的人手……' WHERE `Id` = 53764 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '住手！你休想把我的朋友们变成可笑的雕像！' WHERE `Id` = 53786 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好啊，孩子。' WHERE `Id` = 53799 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '无论发生了什么事——我们都必须专注于我们来的目标。' WHERE `Id` = 53819 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你觉得你能逃到哪儿去，小蜥蜴？' WHERE `Id` = 53825 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没那个必要。我会跟着你们的。' WHERE `Id` = 53883 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，苏利。我的伤没事。现在，我们必须去找白卒。' WHERE `Id` = 53885 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '利尔的情况不妙。我们再停下休息一会儿。' WHERE `Id` = 53897 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好主意，小卢。去看看是谁住在那里。把苏利也带上。' WHERE `Id` = 53900 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没错……还有浣熊。我会照顾好指挥官的。' WHERE `Id` = 53902 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿信想要反悔，可我们都故意打赌说他肯定不敢去，他就没法反悔了。' WHERE `Id` = 53905 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '于是其他孩子，不是我，挑唆阿信去敲青玉巫婆的前门。他不肯去，结果有个人，不是我，故意说他肯定是没胆子。$b$b阿信想反悔，结果有个人，我发誓不是我，是别人在一旁煽风点火。阿信受了挑唆。$b$b他去敲了门，但我们没有看到发生了什么事。青玉怪物冲出来攻击我们，我们就跑了。$b$b我真不该去挑唆阿信的。' WHERE `Id` = 53906 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好很好，一个年轻的访客。$B$b你是来祭扫我丈夫的神龛的吗？你知道，他可是个大英雄。一个玉雕大师，战斗高手。据说，他的名字会被人们永远铭记。$B$b你喜欢我的雕像吗？这些都是我用特殊方法制作的，只有最精良的作品，才能留下来陪伴和保护我的丈夫。' WHERE `Id` = 53907 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这年头还能有人关心赶路的单身旅客可真不容易。我丈夫一定会很喜欢你的。我们一直都想要几个孩子。' WHERE `Id` = 53909 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我没见过这个孩子。' WHERE `Id` = 53945 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个不是阿信。不过它看上去真是活灵活现。' WHERE `Id` = 53946 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '呃。那个小鬼长得真滑稽。' WHERE `Id` = 53947 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '而你，有着英勇的品质。我丈夫的神龛……正需要像你这样出色的守卫。' WHERE `Id` = 53959 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是浪费。' WHERE `Id` = 53971 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '利尔，拜托……省点力气。苏利会把之后的事告诉$n。' WHERE `Id` = 53989 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是，长官。' WHERE `Id` = 54007 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这边，苏利！我找到一个很好的地方。' WHERE `Id` = 54008 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我就躲在这片阴影里。如果你遇到麻烦，就用灯光指出目标，我来对付他们。' WHERE `Id` = 54009 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '长官，我们在本月内就能集齐整支第七舰队——' WHERE `Id` = 54055 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个地方很特别。$B$B我正在引导魔法，以修复魔网。虽然这么做会将我撕成碎片，可我还是觉得很不可思议！' WHERE `Id` = 54072 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看看这个……一个锦鱼人和……这是什么东西？一个胡子精吗？' WHERE `Id` = 54089 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个胡子精一定能成为一个很不错的家族藏品！' WHERE `Id` = 54091 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊哈哈哈哈！！' WHERE `Id` = 54095 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他知道了我们的计划。时间不多了，他的恶魔遍布了整片森林。' WHERE `Id` = 54108 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '月亮母亲，请您指引我们走出这黑暗。' WHERE `Id` = 54110 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '伊利丹，那个瓶子里装的是什么？你在干什么？' WHERE `Id` = 54114 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我打不中他们了！这是什么恶魔邪法？' WHERE `Id` = 54120 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '失去一只浣熊微不足道。我们最担心的是那个石化的兽人……以及它背后的意义。剩下的事就让我来说吧。' WHERE `Id` = 54129 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '利尔……伤得很重。$b$b<密探吉尔妮用力地捶了地面一拳。>$b$b他快死了，$n！可我们对此却无能为力！' WHERE `Id` = 54130 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，我们没有找到白卒。$b$b不行，我不能把白卒的身份告诉你。' WHERE `Id` = 54131 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们在山里扎营。小卢照看利尔。' WHERE `Id` = 54132 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我走到了山顶，手里端着狙击枪。' WHERE `Id` = 54133 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如你所愿，指挥官。' WHERE `Id` = 54135 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我发现苏利就等在村子外面。' WHERE `Id` = 54136 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我聚精会神，好不容易看清他的口型，他说：' WHERE `Id` = 54137 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '苏利埋下了一些火药桶，让我来开枪引爆。' WHERE `Id` = 54140 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不出我所料……部落也来到了潘达利亚，还和一群猴子结了盟。' WHERE `Id` = 54144 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们得把这个消息带回珠鳍村……但首先，让我们收拾几个肮脏的兽人。' WHERE `Id` = 54145 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但愿青玉巫婆没把我的朋友们都抓走。她超级恐怖的。' WHERE `Id` = 54173 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会紧紧跟着你的。你就是我的保镖了！' WHERE `Id` = 54174 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你真勇敢。你能教我怎么变勇敢吗？' WHERE `Id` = 54175 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这可不是什么小岛，$n。这是一片足以媲美诺森德的大陆！$b$b至于它为什么一直没有被发现，现在我们还不得而知。' WHERE `Id` = 54179 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '带上个猢狲向导恐怕不是什么好主意。' WHERE `Id` = 54180 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是什么东西啊？$b$b<熊猫人停顿了一下，睁大了眼睛。>$b$b天呐……看看那碧绿的皮肤！' WHERE `Id` = 54186 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不行。' WHERE `Id` = 54193 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好，这个布景的变换肯定很漂亮。' WHERE `Id` = 54200 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在这里没必要带那么沉的水。' WHERE `Id` = 54201 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '能放松一天可真不错。' WHERE `Id` = 54202 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '多么欢乐的活动啊。' WHERE `Id` = 54204 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好！我是酒仙影斟的徒弟，他就是那个被称为疯酒师的熊猫人。$b$B他无视安全、不计后果追求酒香的行为，已导致了不计其数的伤害和疾病。现在，就连当地的野生动物都察觉到他的疯狂酿酒行为了。他是个罪人，我需要你的帮助来阻止他。' WHERE `Id` = 54205 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这一点都不像闪光平原。' WHERE `Id` = 54206 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里可比赛艇平台上休闲多了。' WHERE `Id` = 54207 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '至少在这里我就不用担心被晒伤了。' WHERE `Id` = 54208 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，这看上去真有趣！' WHERE `Id` = 54209 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我来对付这些恶魔。艾露恩，请您指引我的箭矢！' WHERE `Id` = 54227 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '艾露恩之光，救救我！' WHERE `Id` = 54229 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我可以暂时击退他们！' WHERE `Id` = 54231 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<科拉丝塔萨在你和附近的尸体间来回踱步，她的眉头因为担心而皱了起来。>$B$B我很抱歉，$n。这是红龙军团的私事。$B$B请你先出去帮帮其他人。' WHERE `Id` = 54232 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不见了。被偷了！这是一个可怕的打击。可怕的打击！' WHERE `Id` = 54237 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们很不走运，没能追踪到丢失的黑龙蛋。$B$B你那儿有什么发现吗，$n？' WHERE `Id` = 54238 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你和已故的巨龙瑞亚丝塔萨熟悉吗？那家伙有点不正常。她经常以普通地精的形象在荒芜之地出没。$B$B瑞亚丝塔萨提出了窃取一颗黑龙蛋，并将之净化的计策，以切断它与黑龙军团，以及堕落的大地守护者，死亡之翼间的联系。' WHERE `Id` = 54244 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '伊利丹，我的箭用光了！月亮女神，请庇护我们不受黑暗的侵袭，保佑我们见到明晚的月光！' WHERE `Id` = 54258 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '伊利丹……你不能这么做！' WHERE `Id` = 54262 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不！伊利丹！' WHERE `Id` = 54265 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '玛法里奥，他成功了！传送门崩溃了！' WHERE `Id` = 54270 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来吧，琪麟。去解决点女士的私事。' WHERE `Id` = 54313 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '问题？哈！啊哈哈哈哈！' WHERE `Id` = 54320 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你，“兽人”，一定能成为很不错的家族藏品！' WHERE `Id` = 54321 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '部落一定是在谋划着什么。他们以前从没直接攻击过我们的运输工具。' WHERE `Id` = 54334 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不管你信不信，她的计划真的成功了。她弄到了一颗蛋——我现在都不知道她到底用了什么办法——而且她声称已经切断了这颗蛋和那个堕落的军团之间的联系。$B$B死亡之翼发现了这件事。$B$B他将瑞亚丝塔萨困在荒芜之地的一个洞穴里，杀害了她，并且毁掉了她的一切努力。至少他是这么认为的。其实，瑞亚丝塔萨是牺牲了她自己的蛋，骗过了死亡的化身。$B$B那颗净化过的黑龙蛋已经被秘密地送走并藏了起来！' WHERE `Id` = 54336 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<科拉丝塔萨又打量了你一下。>$B$B你！？你帮助过瑞亚丝塔萨？居然还能活到现在？$B$B我真是低估你了，$r。难怪阿弗拉沙斯塔兹指挥官会把你派来给我。$B$B那你肯定还记得后来发生的事：死亡之翼杀害了瑞亚丝塔萨，但由于她的牺牲，那颗净化过的黑龙蛋被秘密地送走并藏了起来。' WHERE `Id` = 54338 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那就是你被派来的原因，$n。那颗蛋原本一直被藏在这里的朱红庇护所内。可几天前，它却突然消失了。$B$B不管这是谁干的，但他们确实骗过了我们最精锐的守卫。其中一个小偷在行动中被我们打死，可我现在认为，那个家伙只是个转移我们视线的幌子而已——那颗蛋就这么不见了。$B$B在他的尸体上，我们发现了这张纸条。上面有我们目前唯一的线索，可它是用一种复杂的密码写成的，我们必须先破解它。' WHERE `Id` = 54340 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们已经清理残骸好几天了，陛下。没有找到与海军上将泰勒或他舰船有关的任何线索。' WHERE `Id` = 54345 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，这就是我们找到的密信残片。你能看懂吗？' WHERE `Id` = 54349 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '等等！' WHERE `Id` = 54355 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们得等狂风平息下来，然后突破大厅的屏障。' WHERE `Id` = 54356 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '等待另一个机会。我会在远处等你。' WHERE `Id` = 54357 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好了，里克，$n听够了。后面的事让琪麟说吧。' WHERE `Id` = 54359 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '部落的战舰拦住了我们，他们的士兵冲上勇者号的甲板。他们夺走了想要的一切，杀死了那些拒绝合作的硬骨头。我们简直寡不敌众……' WHERE `Id` = 54360 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '大风！出什么事了？你怎么躲在这里？' WHERE `Id` = 54362 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们一直向南走到天黑。夏琪亚就说：' WHERE `Id` = 54365 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我在口袋里找到一些烟雾弹，肯定能派上用场。$b|TInterface\\Icons\\ability_rogue_smoke.blp:32|t$b' WHERE `Id` = 54366 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果我遇到敌人的话，就可以用烟雾弹砸他们。夏琪亚的狙击枪会对付他们的。' WHERE `Id` = 54367 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = 'UNUSED' WHERE `Id` = 54369 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我是在北部神龛找到他的：一个骨瘦如柴的人类士兵。' WHERE `Id` = 54370 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我带着俘虏返回了营地。夏琪亚一定会很满意的。' WHERE `Id` = 54371 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，琪麟。' WHERE `Id` = 54376 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '里克。' WHERE `Id` = 54377 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们马上就扎营。但首先，我们要趁天黑侦察一下周围的环境。' WHERE `Id` = 54378 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好主意。我去侦察前面那片区域。' WHERE `Id` = 54379 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，里克。你留下。这次可别再出人命了。' WHERE `Id` = 54381 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这边，琪麟。' WHERE `Id` = 54383 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我就在这里掩护你。天很黑，你得帮我标出目标。' WHERE `Id` = 54384 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '侦察完毕在这里汇合。' WHERE `Id` = 54385 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别动，人类。你逃不了了。' WHERE `Id` = 54386 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我没痛下杀手就算你走运了……你看着很好吃。' WHERE `Id` = 54389 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那封密信是我们手中唯一的线索了。' WHERE `Id` = 54425 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看，正前方——联盟的轰炸机！' WHERE `Id` = 54433 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我看见了，夏琪亚。我去看看。' WHERE `Id` = 54434 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你不要跟过去，里克。别再把事情搞砸了。' WHERE `Id` = 54435 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什——救命！救命啊，夏琪亚！里克！' WHERE `Id` = 54438 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '里克，你……你救了我的命。' WHERE `Id` = 54440 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然。等我把面具摘了……' WHERE `Id` = 54442 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果这个陷阱是锦鱼人设下的，他们很快就会回来的。$b$b<琪麟震惊地看着远处的地平线。>$b$b黑暗女王在上……他们来了。快跑啊，里克！' WHERE `Id` = 54447 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '重点在于，联盟和锦鱼人结成了联军。过来跟我谈谈，$n。我来把最后一部分报告说给你听。' WHERE `Id` = 54457 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '殿下，在$n的帮助下，我已经完成了对勇者号上所发生事情的调查。' WHERE `Id` = 54460 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '部落确实攻击了舰船，使其无法顺利抵达泰达希尔。但那仅仅是开始……' WHERE `Id` = 54461 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '兽人的船队开始了对卡利姆多海岸线的封锁。所有旅行者都无法抵达那片大陆，我们商人的货运也被迫中止了！' WHERE `Id` = 54462 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会立即着手安排，国王陛下。我认识几位船长，也许能说服他们帮忙应对这次封锁……' WHERE `Id` = 54467 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们在山上扎营，可以俯瞰锦鱼人村子。' WHERE `Id` = 54469 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在没人看管囚犯的情况下，我必须确保他……没有逃跑的能力。' WHERE `Id` = 54470 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我拿过狙击枪，瞄准了锦鱼人的村子。' WHERE `Id` = 54472 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '琪麟到锦鱼人村子去了。我看见她在村外的灌木丛里潜伏着。' WHERE `Id` = 54473 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我使劲看才看清了她的口型，她说的是：' WHERE `Id` = 54474 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '杀光那些守卫，好让我继续前进！' WHERE `Id` = 54475 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得太棒了！再来一次！' WHERE `Id` = 54476 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来看看我的猢狲毒药对锦鱼人有没有用吧！别误伤了我，夏琪亚！' WHERE `Id` = 54477 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们肃清了锦鱼人的村子。为防万一，琪麟埋下了一些炸药，由我射击引爆。' WHERE `Id` = 54478 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就给跟我们作对的联盟和锦鱼人留个难忘的教训吧！我们走！' WHERE `Id` = 54479 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '夏琪亚，他们发现我了！掩护我！' WHERE `Id` = 54480 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '海滩已被肃清。琪麟开始逃跑。' WHERE `Id` = 54481 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '该死，又是锦鱼人的网！我们差一点就成功了……' WHERE `Id` = 54482 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我感到村子东部起了骚乱。' WHERE `Id` = 54483 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '里克……' WHERE `Id` = 54486 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哎哟！' WHERE `Id` = 54488 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没错，我们抓到了一个联盟战俘……可我们付出了什么样的代价呢？' WHERE `Id` = 54504 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了部落，$n。' WHERE `Id` = 54505 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的俘虏很奇怪。他没有带武器，而且他的服装很……怪异。$b$b他可能是某个贵族。如果走运的话，我们或许抓住了个大人物！' WHERE `Id` = 54508 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '里克是……呃，他是我目前见过的最成熟的猢狲，这就不用多说了。$b$b他真的没有夏琪亚想的那么糟。事实上，我觉得他挺可爱的……以猢狲的方式。' WHERE `Id` = 54509 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你这么快赶到，$n。' WHERE `Id` = 54531 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '火里的草药好像已经把这只动物治好了。谢谢你！' WHERE `Id` = 54576 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，你应该知道那最后十六名新兵……' WHERE `Id` = 54577 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '指挥官，前方收到联盟发出的呼救信号。' WHERE `Id` = 54583 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们开火了，长官！' WHERE `Id` = 54584 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '拉升高度！' WHERE `Id` = 54585 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '交给我们了，长官。一定带那孩子回来。' WHERE `Id` = 54589 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '听着苏利，我们回去之后得好好喝一杯，到时候把与他有关的一切都说给我听。' WHERE `Id` = 54591 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们数量太多了！' WHERE `Id` = 54609 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '系统受损，指挥官！我控制不了这飞机！' WHERE `Id` = 54612 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊！遭到攻击！' WHERE `Id` = 54616 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$p！我点了一堆清心焰。如果你想吸口新鲜空气，可以来找我。' WHERE `Id` = 54619 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '打败影斟之后，他的酒仙之位就传给了我。现在，我必须去挽救他对这座山谷造成的伤害了。' WHERE `Id` = 54623 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n叹了口气。' WHERE `Id` = 54632 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n摇摇头，叹了口气。' WHERE `Id` = 54633 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n用手捂住脸，长叹了一口气。' WHERE `Id` = 54634 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你，立刻去港口与指挥官夜风会面。' WHERE `Id` = 54647 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，一个客人。我这里的客人可不多。$B$B饿了吗？我做了很多好吃的东西，亲爱的。$B$B不不，不是鱼。只有在我抓不到什么好东西的时候，才会拿鱼出来充数。' WHERE `Id` = 54664 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么？那是…陆地？' WHERE `Id` = 54676 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '灵魂已经为乌克金祝福了这个远航图腾。它们将随他一同去对抗我们的敌人。' WHERE `Id` = 54690 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些小熊猫有点意思。我想我或许可以改进一下酒仙影斟的配方，让酿出的酒不再致命。' WHERE `Id` = 54756 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我或许可以用兰花和净水开发出一种终极佳酿的配方。但我们必须去酒仙影斟的蒸馏室才能把他酿造出来。为此，我们必须在他的强项上打败他。' WHERE `Id` = 54757 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们可以用你收集的兰花来净化疯酒师山谷的湖水。但我们需要帮助。$b$b我的朋友浅浅是个水灵，曾帮我酿造过一些酒。在净化水体时，他是很有帮助的。他应该知道怎么分配这些草药才最合适。' WHERE `Id` = 54758 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '又是一群死亡之翼的信徒？我保证你们会死得特别痛苦。' WHERE `Id` = 54769 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '玉石俱焚！' WHERE `Id` = 54770 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '而你的故事也结束了。' WHERE `Id` = 54772 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看着吧，邪教徒，死亡降临了！' WHERE `Id` = 54773 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这不是……我想要的……结局。' WHERE `Id` = 54774 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哼。好吧。这比我想象中的还要容易！' WHERE `Id` = 54820 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你……比我想象中……更出色……' WHERE `Id` = 54821 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗬！这么快？' WHERE `Id` = 54822 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但愿你的朋友们能表现得好些。' WHERE `Id` = 54823 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯，太有趣了！' WHERE `Id` = 54824 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '晚安……' WHERE `Id` = 54825 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再见。' WHERE `Id` = 54826 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一个惊喜。' WHERE `Id` = 54827 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在你看见我了……' WHERE `Id` = 54828 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '走吧，陈叔！我们还等什么呢？' WHERE `Id` = 54926 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我是想“享受”旅程，可那也得先“出发”才行！' WHERE `Id` = 54928 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '能走了吗？啤酒喝完了吗？' WHERE `Id` = 54929 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那现在呢？' WHERE `Id` = 54931 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '出发吧！整个大峡谷等着我们去探索呢，可是你却只盯着杯底那点儿啤酒。' WHERE `Id` = 54932 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那我自己去。别以为我只是随口说说。我可不需要某个臭哄哄的大叔牵着我。' WHERE `Id` = 54934 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我还真担心！' WHERE `Id` = 54936 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们好不容易才回到故土，有生以来第一次踏上这片土地，你难道只想在养猪场里休息吗？' WHERE `Id` = 54937 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这……你说的都是废话！你这么说都是因为你又老又懒！' WHERE `Id` = 54939 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再这么磨蹭，我们哪儿都不用去了！走啦！我们得到谷中去探险！' WHERE `Id` = 54993 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '难怪你花了这么长时间。你一直坐着的话，什么收获也不会有。' WHERE `Id` = 54995 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '陈叔，我知道你为什么喜欢这儿了。' WHERE `Id` = 54996 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '因为那两个家伙让你感觉自己很苗条。' WHERE `Id` = 54998 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '遇见你是我们这几天来唯一走运的事。很高兴能得到你的帮助。' WHERE `Id` = 55002 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我好像听到花园里有小孩子在捣乱。我们去找找看吧。' WHERE `Id` = 55022 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '能走了吧？啤酒喝完了吗？' WHERE `Id` = 55070 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那现在呢？' WHERE `Id` = 55072 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '走吧，陈叔！我们还等什么呢？' WHERE `Id` = 55073 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我是想“享受”旅程，可那也得先“出发”才行！' WHERE `Id` = 55075 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘘！' WHERE `Id` = 55121 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '滚开，土拨鼠！' WHERE `Id` = 55122 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '离我们的庄稼远点！' WHERE `Id` = 55123 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘘，嘘！' WHERE `Id` = 55124 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果我们任由季这么干的话，他可能会害死神真子的！$p，跟我来，快！' WHERE `Id` = 55140 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '安度因的朋友就是我们的朋友，$c。要不是他，我父亲也不可能站在这里。' WHERE `Id` = 55158 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '苏利！你怎么就这样让他跑了？' WHERE `Id` = 55166 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愚蠢的矮子，他用了精神控制！现在他跑了！' WHERE `Id` = 55168 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你还是想想怎么跟泰勒上将解释吧！' WHERE `Id` = 55169 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谁会想到这些怪物还能跟你讲道理呢？' WHERE `Id` = 55172 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会做好准备的。$b$b能暂时摆脱这些野蛮人就再好不过了。' WHERE `Id` = 55174 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你看，当你了解之后，就会发现这些小家伙也不是那么坏的……' WHERE `Id` = 55178 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然了。他要不选我那才是笨呢。$b$b谢谢你，$r。我立刻就准备出发。' WHERE `Id` = 55180 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有人需要医疗救助吗？' WHERE `Id` = 55214 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '锦鱼人看上去可能不太友好，但我相信我们已经表达出了善意。' WHERE `Id` = 55215 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '医生总得忙个不停。' WHERE `Id` = 55216 AND `Locale` = 'zhCN';
