UPDATE `broadcast_text_locale` SET `Text_lang` = '开始！冲啊！' WHERE `Id` = 57294 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '只有最迅捷的骑手才会赢得最终的奖励！骑上你们的云端翔龙！' WHERE `Id` = 57308 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你表现出了极大的潜力，$n，但你必须依靠戒律来磨砺你的天赋。' WHERE `Id` = 57320 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '幼年翔龙是非常脆弱的。许多坏习惯就是在这时期养成的。但良好的训练能改变这一切。' WHERE `Id` = 57322 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '幼年翔龙要比成年翔龙顽皮得多。' WHERE `Id` = 57323 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '翔龙骑士的道路漫长而艰险，但你将和你的翔龙伙伴一路同行。$B$B如果你们能互相扶持走到终点，你就将收获一个终生不渝的忠实朋友。' WHERE `Id` = 57324 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好了，莱莎，我需要你用力推。你准备好了么吗？' WHERE `Id` = 57327 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s点了点头。' WHERE `Id` = 57328 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '推！' WHERE `Id` = 57329 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊啊啊！嗯嗯嗯！' WHERE `Id` = 57330 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哇啊啊啊！' WHERE `Id` = 57331 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好，干得不错。你现在可以休息一下。我再去给你端点热水来。' WHERE `Id` = 57332 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你已经投入了大量的时间、耐心还有爱心，$n。现在来看看你的翔龙吧。' WHERE `Id` = 57338 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '德兹科……好疼……好……啊啊啊！' WHERE `Id` = 57340 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不太对劲。婴儿的胎位不正。' WHERE `Id` = 57341 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '德兹科，你在哪？！' WHERE `Id` = 57342 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '亲爱的……不管发生什么事……你都必须保护我们的……我们的孩子……' WHERE `Id` = 57344 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哇啊啊啊！' WHERE `Id` = 57347 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '今天，你终于通过了云端翔龙骑士团的考验。今天，一位新骑士加入了我们的行列。' WHERE `Id` = 57348 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '今天，你与你的云端翔龙建立了永恒的联结。' WHERE `Id` = 57349 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '飞天越海，我们比肩翱翔。' WHERE `Id` = 57351 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '穿越飓风，穿越潮汐，我们一起翱翔。' WHERE `Id` = 57352 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你再也不会孤独飞翔。' WHERE `Id` = 57353 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '带着荣耀与勇气飞翔吧。现在……化身为翔龙骑士！' WHERE `Id` = 57355 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我现在没空聊天，我很忙。' WHERE `Id` = 57372 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你能稍后再来吗？我正在忙着训练我的云端翔龙。要是我想击败对手，就必须得加把劲。' WHERE `Id` = 57373 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我并不担心我的比赛，因为我知道我赢定了。' WHERE `Id` = 57374 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我唯一担心的就是奎陆，他总在自己的设备上搞些花样。' WHERE `Id` = 57375 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你想跟我一较高下？哈！你只能看着我的翔龙尾巴，望尘莫及。' WHERE `Id` = 57376 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是我一直站着陪你聊天，就无法击败对手了。' WHERE `Id` = 57377 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦耶，我给安离长老带去了许多玛瑙翔龙蛋。我每给她一枚，就使自己在骑士团中的地位得到了提升。' WHERE `Id` = 57378 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是我不努力，就会被别人甩在身后。' WHERE `Id` = 57379 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨！你好吗？' WHERE `Id` = 57388 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '需要帮助的话，尽管找我！' WHERE `Id` = 57389 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你要尽量记住那些检查点的位置。一旦搞清楚该去哪儿收集那些旗帜，你便可以制定出最短的飞行路线。' WHERE `Id` = 57390 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '穿越那些云之环是提升速度的最好办法。有时候为了提升速度而偏离一下航线还是很值得的！' WHERE `Id` = 57391 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '四处找找看有没有新路线，有时候最快捷的路线并不是那么显而易见的！' WHERE `Id` = 57392 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我听其他受训者说，在临风岛上能找到玛瑙翔龙蛋。我找啊找啊，可却一个都没找到！' WHERE `Id` = 57393 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '技巧很重要，但归根结底有时候还得看运气。' WHERE `Id` = 57394 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别担心，就算你最后一个冲过比赛终点，我也会为你呐喊助威的！' WHERE `Id` = 57395 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '照顾幼年翔龙可是一门精细活儿。' WHERE `Id` = 57398 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '除非你愿意帮我清理龙穴，否则你最好让我回去工作。' WHERE `Id` = 57399 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我一半的时间花在这座图书馆上，另一半的时间则花在照顾这些雏龙身上了。' WHERE `Id` = 57400 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你了解翔龙骑士的历史吗？那是个非常有趣的故事。' WHERE `Id` = 57401 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我希望有一天能增进我们的古老知识，其中绝大多数都在历史的长河中遗失了。' WHERE `Id` = 57402 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '等你将来见识过更多世面之后，记得回来跟我谈谈。我会把有关翔龙骑士的一切都告诉你。' WHERE `Id` = 57403 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你想加入到我们的行列，就去跟安离长老谈一谈。' WHERE `Id` = 57404 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎来到百木园，旅行者。$B$B这里是云端翔龙骑士团的家园。我们与我们的云端翔龙都将誓死守护翡翠林。$B$B你也可以加入我们的行列。但在开启这段旅程之前，你还需要更丰富的经验。$B$B在这片土地上游历一番，当你更加强大时，再回来找我吧。' WHERE `Id` = 57407 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再没有比骑在作战翔龙的背上翱翔更加精彩的体验了。' WHERE `Id` = 57408 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你很稚嫩，未经考验，榜上无名。只能独自飞翔。$B$B如果你想改变这一切，就去西边找安离长老谈一谈吧。' WHERE `Id` = 57409 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '抱歉，我不想把时间浪费在陌生人身上。' WHERE `Id` = 57412 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨，你好啊！$B$B在你加入我们之前，还有几季的课程等着你去学呢。' WHERE `Id` = 57414 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '第一名？哇！$B$B对像你这么年轻的弟子来说，这已经很不错了。' WHERE `Id` = 57420 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，第二名也不赖。你下次就能超过他们啦。' WHERE `Id` = 57421 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '能进入前三名已经很不错了。名列前茅总比排名倒数要体面嘛，对吧？' WHERE `Id` = 57422 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '第四名。嗯，不算很出色。不过没关系。你可以再试一次。' WHERE `Id` = 57423 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '第五名？好歹你不是最后一名。' WHERE `Id` = 57424 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，你是最后一名。$B$B硬着头皮也得上啊，不是吗？' WHERE `Id` = 57425 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我为此已经训练了整整一周！' WHERE `Id` = 57453 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会在终点线那边等你们的！' WHERE `Id` = 57454 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '比赛结束后，我一定会带你去看看我所有的冠军奖杯！' WHERE `Id` = 57455 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我趁我爸没注意的时候溜出来了，去半山市集找我！
——迪娜·泥爪' WHERE `Id` = 57543 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '把鱼带到市集，半山见！
——玉儿' WHERE `Id` = 57544 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你发现这张字条，那我不是死了，就是在半山市集。$B$B但愿我能暂时放下工作，到镇上喝一杯热乎乎的麦芽酒。或许你该去确认一下，以防万一。$B$B如果我真的没能完成任务，请把我的爱意和私人物品转交给我远在朱家堡的家人。
——阿烁' WHERE `Id` = 57545 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '外出一天，人在半山市集。
——艾拉' WHERE `Id` = 57549 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我父亲来这里是为了寻找青春之池，我来这里是奉了泰兰德·语风之命。' WHERE `Id` = 57552 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的哨兵曾经面对过比这丛林还要糟糕的境况。' WHERE `Id` = 57553 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看来这片土地上的某些东西影响了我们小队的士气。' WHERE `Id` = 57554 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '和奥丹姆干燥的沙漠环境相比，这片丛林既潮湿又宜人。' WHERE `Id` = 57555 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '泰兰德钦定我来执行这个任务。$b$B她说这是因为她看到了幻象，但我猜真正的原因是因为说服她批准这个任务的人，是我父亲。' WHERE `Id` = 57556 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这片土地简直就是猎人的乐园，因为这里充满了危险。' WHERE `Id` = 57557 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你拯救了我的哨兵，英雄。我会永远地感激你。现在我们可以继续执行任务了。' WHERE `Id` = 57558 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '父亲，我们先要对付部落的斥候。' WHERE `Id` = 57562 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然了，$n！我们是名副其实的好友。$B$B难道你忘了你从山地猢狲手里把我救出来那事了吗？后来我们还为此痛饮一番，醉得连裤子都找不着了。' WHERE `Id` = 57575 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这……这是一个陷阱……' WHERE `Id` = 57629 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '既然我们已经是熟人了，$n，那我就给你点提示吧。这附近的村民能帮你装扮农场，但你得先跟他们成为朋友才行。你可以帮他们完成日常任务，或送他们些小礼品——就像你刚才给我的那个，这样就能和他们建立友谊。' WHERE `Id` = 57633 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们……不知道从哪儿冒出来的。我中了埋伏。' WHERE `Id` = 57694 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '灰烬会把我带回先遣营地。拜托了，$p，带上那些毒刃。' WHERE `Id` = 57696 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那么，你到底想干嘛，陌生人？我还要经营市集呢。' WHERE `Id` = 57697 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你来对地方啦，陌生人！半山市集有你需要的所有东西。' WHERE `Id` = 57698 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '陌生人，你在找食物和酒？半山市集里就有。' WHERE `Id` = 57699 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别光傻站在那儿啊，陌生人！不想过来跟我聊聊吗？' WHERE `Id` = 57700 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '陌生人，你是来买，还是要卖？请随便看看吧。' WHERE `Id` = 57701 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这有什么好说的？你喜欢谁，就送一些他们喜欢的东西呗。' WHERE `Id` = 57704 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有谁不喜欢收到礼物呢？$B$B我——我喜欢花。' WHERE `Id` = 57705 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你应该把漂亮的花送给漂亮的女士，比如我。' WHERE `Id` = 57706 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这附近长着很多漂亮的花，而我最喜欢的是泽地百合。可惜，那种美丽的花很难找到。' WHERE `Id` = 57707 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你知道我最想要的是什么吗？一大碗迷雾汤。那一定很好喝。' WHERE `Id` = 57708 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你知道他们怎么说吗——帮助你的邻居，你的邻居也会帮助你。$B$B当然，你可以偶尔帮他们做一些杂事，但礼物能更快地让你们成为朋友，你不觉得吗？' WHERE `Id` = 57709 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '从哪儿能找到礼物？你有没有在田地里找过？$B$B你永远也不知道你会在这些农田里找到什么。$B$B说不定你甚至能在自家地里刨出些东西来！' WHERE `Id` = 57710 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在田里劳作一整天会让人胃口大开。$B$B别说是我告诉你的，这里的家伙胃口大到能把一个女人都吞下去。$B$B大多数人都会有一道最喜欢的菜。如果你会烹饪的话，他们会很乐意尝尝你的手艺。' WHERE `Id` = 57711 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<布兰琪的吼声震彻风暴。>$B$B你成功了！锅炉和酒桶都到位了……现在我们就等着大自然显现神迹吧。$B$B你觉得呢？准备好来点烟火吗？' WHERE `Id` = 57713 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我可以告诉你镇上每一个人的住处，你想找谁？' WHERE `Id` = 57717 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '艾拉住在农田的最西边，就在风暴烈酒酿造厂的北边。$B$B她的父母死后她就一直独自生活，可怜的孩子。' WHERE `Id` = 57728 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '老农山掌住在西北边的山上，他的农场就在山的南边。$B$B那个可怜的老人自从儿子死后就再也不和人交往了。' WHERE `Id` = 57729 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '吱吱的农场在西北边，就在山上不远处。$B$B那个可怜的家伙总是被疾病缠身。' WHERE `Id` = 57730 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那个奇怪的女孩阿烁总是在山上转来转去。$B$B没人知道她从哪儿来，但她受过杀手的训练。$B$B以前帮我们对付猢狲时露过一两手。她是个好女孩，但是话不多。' WHERE `Id` = 57731 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，玉儿？那个可爱的女孩住在北边码头。$B$B我在她还是个小姑娘的时候就认识她了。$B$B她总是在泥里挖来挖去，或在湖里游来游去，或在林间上串下跳。她父母还真给她起对名字了，因为她就像鱼一样滑溜。' WHERE `Id` = 57732 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我父亲住在田地中间的农舍里，就在那座古旧的仙鹤雕像东边。$B$B他拥有山谷里几乎所有的肥沃土地，而且他从不让任何人忘记这一点。$B$B这就是我离家出走的原因。因为他觉得所有东西……所有人，都是属于他的。' WHERE `Id` = 57734 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的姐姐和我父亲一起住在田地中间的农舍里，就在那座古旧的仙鹤雕像东边。$B$B我很希望能时不时地见到我姐姐，但她这些天来总是忙于梳妆打扮，好引起那些路过这里的农场小伙的注意。' WHERE `Id` = 57735 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，贾古……他很有可能醉倒在摊位后面了。只要往酒吧南边走上几步就能找到他。$B$B他不久前流浪至此，然后再也没离开过。$B$B这里人人都喜欢他，他可是个预测收成的行家。' WHERE `Id` = 57736 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有些人你找不到？好吧，他们只可能出现在三个地方。$B$B要么在市集里，要么一整天待在家里，要么在日歌农场里。$B$B如果这三个地方还找不到他们，那你就该去检查下你的眼睛了！' WHERE `Id` = 57737 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在失落的王朝的废墟见，$p。' WHERE `Id` = 57740 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '农夫老方住在镇子北边，就在水塔附近。$B$B算我倒霉，我跟他很熟。' WHERE `Id` = 57741 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你在找谁？把地图给我，我帮你标出来。' WHERE `Id` = 57742 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你这蠢货，你要找的人就是我！你以为你在跟谁说话啊！？' WHERE `Id` = 57743 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里的树是我这一路上所见过最漂亮的。' WHERE `Id` = 57744 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '博学者瓦尔德林坚信他可以找到青春之池。$b$b想象一下，如果成功的话，那将为我们的人民带来什么啊，我们将再次获得永生……' WHERE `Id` = 57745 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '高阶女祭司泰兰德曾对批准此任务犹豫不决。$b$b她似乎觉得瓦尔德林的研究来源是一把双刃剑。$b$b在那个奥法地牢度过许多时日后，我开始认为她或许是对的。' WHERE `Id` = 57747 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '康说魔古是一群暴徒和强盗。$b$b根据我们迄今为止的观察，我认为他们也许会成为熊猫人种族最大的威胁。' WHERE `Id` = 57749 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '呃！你好……$B$B<艾拉的脸红了，她害羞地低下头。>' WHERE `Id` = 57750 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '幸运的是，地牢已被关闭，我们在传送门另一端的盟友可以把补给品传送过来了。$b$b不幸的是，我们还未能解除这个阻止我们通过传送门回传物品的封印。' WHERE `Id` = 57751 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阿……阿丽娜在负责指挥。' WHERE `Id` = 57752 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的血……在燃烧。' WHERE `Id` = 57753 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '泰兰德警告过我……她……她说在光明之前将会是……一片黑暗。' WHERE `Id` = 57754 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你送我这么可爱的礼物，$n。我最喜欢猫啦！' WHERE `Id` = 57765 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '吃芜菁可真让我不舒服。' WHERE `Id` = 57766 AND `Locale` = 'zhCN';
