UPDATE `broadcast_text_locale` SET `Text_lang` = '呃，这么说我们要收集一些甲虫和一些鸟的羽毛？没问题！' WHERE `Id` = 57828 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真好玩，$p。这比和一个无聊的大叔一起出门有趣多了。' WHERE `Id` = 57829 AND `Locale` = 'zhCN';
