UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，这一切真的很酷，也很惊险，不过我们现在应该回泥盏那儿了吧？' WHERE `Id` = 57884 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那么……嗯……$p？我还在这儿呢。' WHERE `Id` = 57885 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '到处跟着你，到现在已经好一会儿了。' WHERE `Id` = 57886 AND `Locale` = 'zhCN';
