UPDATE `broadcast_text_locale` SET `Text_lang` = '呦，风暴比我想的还要猛烈！小心！' WHERE `Id` = 58146 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '说你呢！别光站着不动，解决掉这些召唤者！' WHERE `Id` = 58148 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '关键在于那些酒桶——别让它们起火！' WHERE `Id` = 58150 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快把酒桶的火扑灭！' WHERE `Id` = 58151 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这场风暴已经肆虐得失去控制了！保护酒桶……' WHERE `Id` = 58152 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你将他们的灵魂喂给他们的同族？恶心。' WHERE `Id` = 58200 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我永远也不会放过你的同类，死灵法师。永远。' WHERE `Id` = 58201 AND `Locale` = 'zhCN';
