UPDATE `broadcast_text_locale` SET `Text_lang` = '不，父亲，我会的。罗甚至愿意为了我去挑战族长，连$p都支持我们，他们不会不同意的。' WHERE `Id` = 58210 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你会为多嘴付出代价。' WHERE `Id` = 58211 AND `Locale` = 'zhCN';
