UPDATE `broadcast_text_locale` SET `Text_lang` = '跑吧……死灵法师……等我喘过气来，你就死定了。' WHERE `Id` = 58213 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你稍事休息，让我把桶准备好。' WHERE `Id` = 58238 AND `Locale` = 'zhCN';
