UPDATE `broadcast_text_locale` SET `Text_lang` = '花点时间仔细瞧瞧这座宏伟的雕像吧，它可是耗费了近百年的人力所创造出来的奇迹。' WHERE `Id` = 58404 AND `Locale` = 'zhCN';
