UPDATE `broadcast_text_locale` SET `Text_lang` = '我……不会让你……' WHERE `Id` = 58423 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不能……和他战斗……' WHERE `Id` = 58424 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '结果他！快！趁他还没有……' WHERE `Id` = 58425 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '跟土地精拼酒的诀窍就是不能停。幸运的话，他们总会在你之前醉倒。' WHERE `Id` = 58447 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '太好了！瞧瞧它，花了整整一百年的时间才建起如此宏伟的青龙雕像。现在，你也为这个杰作贡献了一份力量。' WHERE `Id` = 58449 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快了，快了，很快就要完成了。' WHERE `Id` = 58450 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在燃烧……我的灵魂……在燃烧！！！！' WHERE `Id` = 58492 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好啊，$c。你们的人在里面。但我能不能先请你帮我个忙？' WHERE `Id` = 58493 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你试过我们家传跌打酒的功效吗，$c？' WHERE `Id` = 58494 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '战士们报告说是你救了他们。谢谢你，$n。' WHERE `Id` = 58495 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '见到你总是很高兴，$n。近来好吗？' WHERE `Id` = 58496 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你感觉怎么样，$c？要再来点跌打酒吗？' WHERE `Id` = 58497 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你竟然对我们大家如此无私和仁慈，这令我感到很惊讶。' WHERE `Id` = 58498 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的朋友们怎么样了，$n？' WHERE `Id` = 58499 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$g他:她;在那儿。这里随时欢迎你，$n。' WHERE `Id` = 58500 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要在这里待上一阵子吗，$n？你一定给我讲讲你最近的壮举哦。' WHERE `Id` = 58501 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你经历了那么多次冒险，现在该好好休息一下了，年轻的$g先生:女士;。' WHERE `Id` = 58502 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我刚才还在念叨你呢，$n。' WHERE `Id` = 58503 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '外乡人？从你的打扮来看，还是个老练的$c。很好！也许你能帮我们脱离困境。' WHERE `Id` = 58508 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的计划取决于你能否从战场上给我们带来尽可能多的箭矢，$c。' WHERE `Id` = 58509 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看来你弄到的这些已经绰绰有余了。快，$n，我想我已经在地平线上看到了铺天盖地的野牛人援军。' WHERE `Id` = 58510 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '向昆莱小径的英雄——$n致敬！' WHERE `Id` = 58514 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很高兴再次见到你，$n。想再好好教训这群野牛人渣滓一顿吗？' WHERE `Id` = 58515 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不用管我们。我们正在清理最后的余孽。应该用不了多久了。' WHERE `Id` = 58516 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '能请你喝一杯吗，$g帅哥:美女;？' WHERE `Id` = 58517 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你弄清究竟是什么把这些野牛人赶出螳螂高原的了吗？' WHERE `Id` = 58518 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '射击时小心点。别打到$n！' WHERE `Id` = 58519 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这真是莫大的荣誉，$n。也许我们稍后能找个机会一起坐坐，听你给我讲讲你最近的义举？' WHERE `Id` = 58520 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '送它们下地狱，$n！' WHERE `Id` = 58521 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……' WHERE `Id` = 58522 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '死吧，死灵法师！' WHERE `Id` = 58527 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '求你……让我……独自……死去……' WHERE `Id` = 58528 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$C，我得请你帮个忙。' WHERE `Id` = 58533 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '被骗了！我们每个星期都到这儿来。他们看上去就像是普通的生意人。
可现在……这些鱼人却一边用长蹼的手跟我们打招呼，一边握紧了藏在背后的刀子，想趁我们转身时捅我们一刀！' WHERE `Id` = 58538 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会消灭他们的。没必要继续待下去了！' WHERE `Id` = 58540 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$p，如果斥候向你报告有关魔古首领的任何消息，你知道该怎么做。' WHERE `Id` = 58541 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s咕哝着表达着她的赞美。' WHERE `Id` = 58547 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '听着，陌生人，我刚才已经跟那位尊贵的游学者说了，我现在再跟你重复一遍……$B$B<孟一边说一边走了过来，她的眼睛突然瞪得很大。>$B$B我！没！有！玉！石！' WHERE `Id` = 58572 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '通常我们都能轻松完成周卓的要求。这里的玉石矿脉贯穿大地，就好像……$B$B<孟挠了挠头，似乎在思考。>$B$B呃，就好像某些东西体内的血管。$B$B你瞧，我又不是诗人。$B$B重点在于：我们遇到麻烦了。' WHERE `Id` = 58575 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '多亏了你，采石场总算没事了。$B$B看来我得让小伙子们放个假……$B$B哈哈！我哄谁呢？瞧我自己也一本正经的样子。$B$B我们还有活儿要做呢！' WHERE `Id` = 58576 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这还远远不够！$B$B在潘达利亚的黑色泥土里埋藏着五件稀世珍宝：红宝石碎片、可爱的苹果、玉猫、蓝色羽毛以及泽地百合。$B$B只要你能将其中一件收入囊中，就能在附近找到愿意接受它们的人。$B$B找到其中一件并交给你喜欢的人，就有机会赢得他们的好感！每个人都会有他们最喜欢的东西，所以要跟他们多聊聊才能知其喜好。$B$B还有，这儿的人都很爱美食！说实话，谁不爱呢？如果你会做菜，那就再好不过了！$B$B关于礼物我就知道这些了。祝你好运！' WHERE `Id` = 58602 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我自然有办法。瞧瞧这个。' WHERE `Id` = 58609 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，陌生人！' WHERE `Id` = 58667 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我老爸无数次跟我说起过那个故事！$B$B大旱那段期间日子非常难过。农夫们都在用唾沫浇灌庄稼了，因为太干了。整个村子又饿又渴！$B$B所以农夫老愚的祖父在夜里收拾好自己的货车。$B$B然后骑着穆山兽直奔昆莱山脚下的湖泊。他在货车上装满了几百桶清水，然后立即返乡。$B$B他马不停蹄、日夜兼程！他如何能停下脚步？整个村子的人都快渴死了！当他赶着涨裂的货车回到田里时，穆山兽当场就累死了！$B$B但我们村子有了足够的水，并且还完成了春耕。$B$B泽被半山众生，老愚的祖父就是这样的人！' WHERE `Id` = 58669 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我去拿些工具来，待会在农夫老愚的田里跟你碰头。我打赌一定能赢你！' WHERE `Id` = 58670 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们这些城里人都这么没耐心？' WHERE `Id` = 58671 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这货车可不会自己把自己修好的。' WHERE `Id` = 58672 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要不这样吧。你接着嚎，我不干了。' WHERE `Id` = 58673 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我既会园艺，又能打铁。我老爸把我教成了一个万能修理匠。' WHERE `Id` = 58674 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s舔了舔自己的手指，举了起来。她嗅着空气，双眼扫视着天空。' WHERE `Id` = 58712 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '气压计的读数迅速下滑，是时候启动牵引装置了！' WHERE `Id` = 58714 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '旅途愉快，$r！$B$B这天气现在看起来不错，但翡翠林的上空会伴随着风暴迅速阴沉下来。你能感觉到空气在变化吗？也许你想帮我酿造一些我传说中的闪电陈酿？' WHERE `Id` = 58717 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '进来坐坐，别老站着……我肯定你在外面跑了一整天了。$b$b那么，我有什么可以效劳的？' WHERE `Id` = 58780 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '今天外面挺暖和的，对吧？' WHERE `Id` = 58781 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎来到半山，邻居。' WHERE `Id` = 58782 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那是当然！谢谢你能来。这些是我付的钱。' WHERE `Id` = 58783 AND `Locale` = 'zhCN';
