UPDATE `broadcast_text_locale` SET `Text_lang` = '我明白，我欠你钱。如果能还我肯定还了，但是……$b$b我急需这笔钱。我们的小店已经年久失修。如果我没钱付维修费的话，我不仅会失业……而且家庭也要垮了。' WHERE `Id` = 58785 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我明白了，这是我的欠款。很抱歉占用你这么长时间，$g先生:女士;。' WHERE `Id` = 58787 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是位心地善良的$g先生:女士;，$n。我们不会忘记你的这份恩情。' WHERE `Id` = 58789 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '知己知彼，方能百战百胜，这就跟战斗的道理是一样的。' WHERE `Id` = 58812 AND `Locale` = 'zhCN';
