UPDATE `broadcast_text_locale` SET `Text_lang` = '踏岚掌门，我们此处的据点已经稳固了。我们应该第一时间出击。' WHERE `Id` = 60308 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们已将他们逼入防御态势了。眼下，他们的人数也在减少。' WHERE `Id` = 60309 AND `Locale` = 'zhCN';
