UPDATE `broadcast_text_locale` SET `Text_lang` = '我们当然需要稳健的战术。但在能直捣黄龙时，为何要断臂自保呢？' WHERE `Id` = 60311 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '班，趁他们的注意力都集中在昆莱山，我们得先发制人。' WHERE `Id` = 60327 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是不是忘了，他们抓走了我丈夫！我们已经没时间了！' WHERE `Id` = 60328 AND `Locale` = 'zhCN';
