UPDATE `broadcast_text_locale` SET `Text_lang` = '嗤！踏岚为什么会选你做指挥官？你只会让我们缩在床单里，等着野牛人打上门来！' WHERE `Id` = 60349 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '成功了！伤口正在愈合！' WHERE `Id` = 60365 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不——！！！！' WHERE `Id` = 60381 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '林，亲爱的！不，拜托，不要！怎么会这样！' WHERE `Id` = 60382 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是班肯听我的就好了！我能早来一步就好了！' WHERE `Id` = 60383 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘘，亲爱的。现在，安静地睡吧。' WHERE `Id` = 60384 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我绝不会放过杀害你的凶手。' WHERE `Id` = 60385 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我发誓。' WHERE `Id` = 60386 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我丈夫在几天前被野牛人抓走了。$B$B在我们说话的时候，他正处在危险之中。' WHERE `Id` = 60402 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我现在恐怕帮不上什么忙，$n。$B$B我太担心我丈夫了。' WHERE `Id` = 60404 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '林正深陷险境，我无法坐视不理。' WHERE `Id` = 60405 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，不，不。林，我亲爱的丈夫，你不能死。' WHERE `Id` = 60406 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他这么冷，这么无助，毫无生气。' WHERE `Id` = 60408 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我早就说了！我早跟班说了应该出击！这都是他的错！' WHERE `Id` = 60409 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他几天前才跟我告别。我的眼前至今还晃动着他的脸。他怎么可能死了呢？' WHERE `Id` = 60410 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<孙娜前后摇晃着，凝望着天空。她没有回答。>' WHERE `Id` = 60430 AND `Locale` = 'zhCN';
