UPDATE `broadcast_text_locale` SET `Text_lang` = '我不喜欢这个地方，$r。这里有点诡异。' WHERE `Id` = 60478 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个村子里有种让我毛骨悚然的气息。' WHERE `Id` = 60479 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在完成任务之前，我们不能休息。' WHERE `Id` = 60480 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是让土拨鼠看到你毁了它们的地洞，一定会气疯的。先把它们解决掉，然后就好办了。' WHERE `Id` = 60484 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿！看你把东西都溅到哪儿了。' WHERE `Id` = 60503 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么，我们已经干完了！？' WHERE `Id` = 60504 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你终于不用再继续站在这恶心的水里了吗？' WHERE `Id` = 60505 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '或许我们可以找些更古怪更肮脏的瓶子来装泥水。' WHERE `Id` = 60506 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我最喜欢的就是你把泥水溅到我眼睛里。' WHERE `Id` = 60507 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我可没在嘲笑你。' WHERE `Id` = 60508 AND `Locale` = 'zhCN';
