UPDATE `broadcast_text_locale` SET `Text_lang` = '祝你好运！' WHERE `Id` = 60528 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '跟着我。我们要用这些图腾来净化大地。' WHERE `Id` = 60529 AND `Locale` = 'zhCN';
