UPDATE `broadcast_text_locale` SET `Text_lang` = '班，你看起来很担心。' WHERE `Id` = 60680 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '她肯定是对她丈夫的死太伤心了。' WHERE `Id` = 60681 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '或许吧，但这并不是谁的错。' WHERE `Id` = 60682 AND `Locale` = 'zhCN';
