UPDATE `broadcast_text_locale` SET `Text_lang` = '看来我们压制住了煞魔……但只是暂时的。' WHERE `Id` = 60752 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我简直不敢相信。你压制住了自己的恨意。' WHERE `Id` = 60753 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '踏岚和班都是战略和后勤学大师。相比计划，我更喜欢战斗。' WHERE `Id` = 60772 AND `Locale` = 'zhCN';
