UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎，$c！务必要抽出时间欣赏景色啊！' WHERE `Id` = 60779 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你以为你是谁？一个$c或者什么别的玩意儿？' WHERE `Id` = 60812 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '起泡沫的黄啤酒是给懦夫和土地精准备的。' WHERE `Id` = 60813 AND `Locale` = 'zhCN';
