UPDATE `broadcast_text_locale` SET `Text_lang` = '下一次你可没那么容易全身而退了。' WHERE `Id` = 60817 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这一回是你赢了，可等我们下次相遇时，我会拿出更好的佳酿。' WHERE `Id` = 60818 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我今天本可以打败你的，你知道吗。我只要更快地切换到“醉酒姿态”就行了。' WHERE `Id` = 60819 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '尽情享受胜利的滋味吧，只是暂时的。下次我们交手时，你会尝到被击败的滋味。$b$b事实上，我会把我接下来要酿的酒起名叫“失败苦酒”——口感不会太糟，但会让喝得人沉浸在失败的痛苦中不能自已。' WHERE `Id` = 60820 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '试试你的力量！' WHERE `Id` = 60831 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有勇无谋，亦是枉然。' WHERE `Id` = 60832 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，不用为他担心。$B$B我那个白痴丈夫只是脑袋上挨了一下，睡一觉就好了。' WHERE `Id` = 60904 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有朋自远方来，不亦乐乎。是来送给养的吗？' WHERE `Id` = 60911 AND `Locale` = 'zhCN';
