UPDATE `broadcast_text_locale` SET `Text_lang` = '无论如何，陌生人，你千万不要向我的丈夫打听他的鸡蛋面秘方。否则那将会成为你经历过的最冗长的一次谈话。' WHERE `Id` = 60914 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '危险？哈！我才不怕什么危险！$B$B难道你不知道最美味的食物也是最难获得的吗？' WHERE `Id` = 60950 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你需要什么？我这里有最烈的老酒。你敢试试吗？' WHERE `Id` = 60958 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让换我班的人知道有多少螳螂妖试图从主通道悄悄溜进来，这个岗位可马虎不得。' WHERE `Id` = 60996 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '比给养还要好——休息。我觉得我一时半会还不会离开这里。' WHERE `Id` = 60998 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我感觉平静多了。发生什么了？' WHERE `Id` = 61009 AND `Locale` = 'zhCN';
