UPDATE `broadcast_text_locale` SET `Text_lang` = '这老家伙……我没法朝他发火。$B$B谢谢你，陌生人。' WHERE `Id` = 61026 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '又少了一只躲在封锁线后的害虫。' WHERE `Id` = 61027 AND `Locale` = 'zhCN';
