UPDATE `broadcast_text_locale` SET `Text_lang` = '嗨！你跟我那死鬼丈夫真是一样的顽固！' WHERE `Id` = 61029 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，要想挑战幻影女士可是需要很大勇气的。那么，就让我看看你们有什么本事吧！' WHERE `Id` = 61034 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '灰飞烟灭，跟我一起堕落吧！' WHERE `Id` = 61035 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，小心点，别把血滴在地毯上了，亲爱的。' WHERE `Id` = 61036 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祝你下次走运！' WHERE `Id` = 61037 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '呃……死亡……痛楚？都是假象……' WHERE `Id` = 61039 AND `Locale` = 'zhCN';
