UPDATE `broadcast_text_locale` SET `Text_lang` = '那些废墟真吓人。它们太古老了……' WHERE `Id` = 62929 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看看那些船！它们从哪而来？' WHERE `Id` = 62930 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦不！看看那些小屋！ 他们为什么要攻击手无寸铁的村民？' WHERE `Id` = 62931 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的村庄在受到攻击！我希望家人都安好。' WHERE `Id` = 62932 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看起来我父亲也错了。即使是在卓金也会是危险的！' WHERE `Id` = 62933 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我要去看看我的家人。请帮帮我们！' WHERE `Id` = 62934 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '等等……那是什么？！那些小屋都是从哪里冒出来的？！' WHERE `Id` = 63006 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你总是那么消极啊，侯！' WHERE `Id` = 63294 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那也许不是真的，侯。游学者似乎很有信心。你的保护要让我们付出什么代价？' WHERE `Id` = 63295 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '非常好。如果你能帮我们击退赞达拉，我们就告诉你该怎样找到先知。' WHERE `Id` = 63296 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你打算怎么帮我们，游学者？' WHERE `Id` = 63313 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你想成为“闷水壶”的船员？那你恐怕得像其他人那样，从头做起。' WHERE `Id` = 63416 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '骑兵逼近！' WHERE `Id` = 63441 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我要出发了。我们到另一边再见…但愿如此。' WHERE `Id` = 63517 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们赶快吧？' WHERE `Id` = 63520 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看来他只是失去意识了。我应该能把他叫醒。' WHERE `Id` = 63628 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让我们回到节日中来吧，$p。到我家坐坐，我正在做一些特别的东西！' WHERE `Id` = 63629 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '酒仙！在村外发现了巴塔里侦察小队！' WHERE `Id` = 63630 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里的空气真干净。' WHERE `Id` = 63635 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我是在迷踪岛上长大的。那里空间有限。没地方让我们狩猎，也没有什么值得一提的凶禽猛兽。$b$b可这里……这里有大块头的穆山兽，有野狼，还有各种各样的食肉动物。这里简直是让猎手美梦成真的乐园。' WHERE `Id` = 63636 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '头一次来潘达利亚？我也是。我还记得他们讲述的关于这个地方的故事。真令人兴奋！' WHERE `Id` = 63637 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我最早是在荆棘谷遇见奈辛瓦里的成员的。在那之后，我就陆续跟他们见过几次面。终于在他们的远征队里找到了自己的一席之地！' WHERE `Id` = 63638 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢！我想我认识你。你是从迷踪岛来的是不？$b$b身处潘达利亚的感觉很奇妙吧？$b$b我一直以为这地方不过是传说罢了。真不敢相信，它竟然真实存在着！' WHERE `Id` = 63639 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里生机盎然，一望无垠。$b$b迷踪岛上地方狭小，猛兽根本没空间茁壮成长，供猎人捕杀。' WHERE `Id` = 63640 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，很好！你找到远征队了。要是没有点旅行天赋，很容易在丛林里迷失方向。$b$b那些魔古族没完没了地妨碍我狩猎。' WHERE `Id` = 63641 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '喝下去，$p。在你把脚趾头伸进海里之前，我要看那瓶子变空。' WHERE `Id` = 63644 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可以出发了。味道像是混合了海草和热垃圾，是吧？' WHERE `Id` = 63645 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎光临北风酒馆。' WHERE `Id` = 63646 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好啊朋友！想找个房间过夜吗？' WHERE `Id` = 63647 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再次感谢，$p！我会立刻把它交给酒仙布夫。' WHERE `Id` = 63654 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '又见面了，迷雾之外的陌生人。' WHERE `Id` = 63656 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这场战争代价高昂。就连我也要若干年后才能重生。' WHERE `Id` = 63657 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有所领悟吧！' WHERE `Id` = 63658 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不知道迷雾为何一分为二，但其中一定有原因。' WHERE `Id` = 63659 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你显然不是要将战争带到这儿来。在潘达利亚潜藏着黑暗——你已经亲眼见到了！' WHERE `Id` = 63660 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但我能肯定你就是迷雾分开的原因。弄清你来这里的意图吧。' WHERE `Id` = 63661 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你能从四风谷了解到许多与这片土地有关的事。' WHERE `Id` = 63662 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '还有另一位迷雾之外的访客。叫“陈·风暴烈酒”，是个熊猫人，但却来自不同的故乡。' WHERE `Id` = 63663 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '和陈一起在这片土地上走走。跟这里的住民交交朋友。你终究会找到答案的。' WHERE `Id` = 63664 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '后会有期。希望我们下次碰面时能成为“朋友”。' WHERE `Id` = 63665 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '救命！' WHERE `Id` = 63668 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '它们要吃掉我！' WHERE `Id` = 63669 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '把它们从我身边赶走！' WHERE `Id` = 63670 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我还年轻，我不想死！' WHERE `Id` = 63671 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不是食物！' WHERE `Id` = 63672 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快来人救救我！' WHERE `Id` = 63673 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '救命！救命！' WHERE `Id` = 63674 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊——！' WHERE `Id` = 63675 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你，$p！它们要吃掉我！' WHERE `Id` = 63678 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '兔妖把粮食都吃光了！' WHERE `Id` = 63679 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n，你能帮我解决掉这些兔妖吗？' WHERE `Id` = 63680 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '抓住那些兔妖！' WHERE `Id` = 63681 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘘！' WHERE `Id` = 63682 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '离开那儿！' WHERE `Id` = 63683 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '救救粮食吧，$p！' WHERE `Id` = 63684 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '抓住那些兔妖，$p！' WHERE `Id` = 63685 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是巢穴主母！小心，$p！' WHERE `Id` = 63686 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '粮仓里还有兔妖！你能帮我赶走它们吗，$p？' WHERE `Id` = 63689 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看那些兔妖再敢吃我！' WHERE `Id` = 63796 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我得把粮食交给酒仙，然后我们就能欢庆节日啦！回头见，$p！' WHERE `Id` = 63797 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '四个至尊天神统治着这片土地。$B$B青龙玉珑，东方的生命赋予者。$B$B朱雀赤精，南方的希望。$B$B白虎雪怒，他的力量维护着北方的和平。$B$B玄牛砮皂，他屹立在西方的天际。$B$B最近，随着煞魔的蠢蠢欲动，杂念已经开始席卷各个寺院。他们需要我们的帮助，$r。' WHERE `Id` = 63813 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '从古代王国的黑暗时期开始，我们熊猫人就开始依靠神秘的酿造工艺保持充沛的精力和体力。$B$B甚至在我们谈话的时候，我们的酒仙仍然在周游世界，寻找罕见和充满力量的成分来酿造最好的酒。$B$B找到这些行踪不定的酒仙并且帮助他们的人，可以得到香甜可口的美酒。至少，你能喝个够！' WHERE `Id` = 63836 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '金莲教肩负着守卫锦绣谷的重任。$B$B如果你想帮助我们，就去打败那些目前占据着锦绣谷的敌人吧。$B$B你也可以去残阳关卫戍营的训练场找安济·秋光，获取下一步的任务。' WHERE `Id` = 63842 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '告诉我，$r，你对钓鱼心怀向往吗？$B$B如果答案是肯定的，那你应该去卡桑琅丛林找垂钓翁。' WHERE `Id` = 63844 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你一定是$n。$b$b我一直在等你。' WHERE `Id` = 63890 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '还有那么多精彩的故事等着我们去探寻。那么多历史。难道不使人着迷吗？' WHERE `Id` = 63914 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '能看到禅院外面的世界，真好。' WHERE `Id` = 63968 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我就知道你会做到的！' WHERE `Id` = 63993 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让我们喝一杯吧！' WHERE `Id` = 63995 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不这么认为。' WHERE `Id` = 64008 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$p，如果你在村庄的防务方面需要帮助，请告诉我！' WHERE `Id` = 64053 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们这儿有来自潘达利亚各地的造访者，他们肯定可以帮助我们解决这些掠夺者。' WHERE `Id` = 64054 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '卡桑琅荒原啤极其易爆，$n！我们可以将酒桶放在野牛人的必经之路上，然后点火。拿上酒桶，我会做好标记，告诉你应该把它们放在哪里。' WHERE `Id` = 64067 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '布莱瓦·肖是投掷啤酒桶的高手，$n。他可以把酒桶扔到空中，然后让酒桶在野牛人中间摔碎！我今天上午在旅馆附近看到过他。去看看他是否愿意帮忙吧！' WHERE `Id` = 64068 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的小镇上到处都有用于庆祝节日的大桶烟火。$n。把它们放在正确的位置，给它们来个恰到好处的打击，让它们可以造成各种各样的破坏。带上一桶烟花，我会在放置烟花的地方做标记。' WHERE `Id` = 64069 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小镇上有天禅院弟子在庆祝酿月祭，$n！他们可以用学到的技艺帮助我们。和他们谈一谈，看他们是否可以阻止那些野牛人！' WHERE `Id` = 64070 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '旅馆后面的仓库里有一些破损的大炮，$n。如果你可以修复这些大炮，村民们就可以用它们击退野牛人！' WHERE `Id` = 64071 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小镇上有一些锦绣谷神射手，他们在这里过夜休息，$n。他们用迫击炮在残阳关和螳螂妖战斗了很多年。你看一下能不能叫醒他们！' WHERE `Id` = 64072 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小镇上有来自天禅院的天禅院织雾者，$n。他们在制造迷雾方面的能力可以帮助我们战斗得更久。请他们在战斗中帮助我们。' WHERE `Id` = 64073 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小镇上有一些快活的村民，他们说他们制造了一种能够让所有事情更加顺利进行的头盔。虽然我表示怀疑，但戴上头盔又没有什么损失，你说呢？和他们谈一谈，看他们是不是愿意借你一个。' WHERE `Id` = 64074 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '齐延姿每年都来祝福我们的节日，$n。他不会参加战斗，但或许可以帮我们做一些其他事情。问问他是否能帮我们做些事情。' WHERE `Id` = 64075 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '雪怒执盾手每年都会从白虎寺来到山下，$n。他们或许可以阻止野牛人的入侵，以免野牛人进入村庄。和他们谈一谈，看他们是否可以帮助我们。' WHERE `Id` = 64076 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '迪嘭迪嘭时不时地来到镇上，向我们出售在昆莱山附近搜集到的奇怪的小玩意儿。和他谈一谈，看他有没有可以给我们当做武器的东西。' WHERE `Id` = 64077 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '滨岸渔民闭着眼睛都可以用渔网捉到醉醺醺的猢狲，$n。他们当然也可以帮我们捉一些野牛人了。和他们谈一谈帮助我们保卫村庄的事情吧！' WHERE `Id` = 64078 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你要告诉我遗迹藏在哪里！' WHERE `Id` = 64119 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我欠你的，所以我要告诉你。我会和我的父亲说，让你们加入阡陌客。' WHERE `Id` = 64147 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们跟随着风的指引四处游荡，好心的$r。你愿意倾听一会儿吗？' WHERE `Id` = 64151 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在旅途中，我们唱过很多的歌曲，但还有很多歌曲没有唱。' WHERE `Id` = 64152 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '德兹科派我们来侦察这片地区。我们也许已经找到了莱莎幻像中出现的伟大治疗之力。' WHERE `Id` = 64167 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当地人坚称，我们要找的伟大治愈之水不过是……风暴烈酒而已。我们得调查下这种说法的真实性。' WHERE `Id` = 64168 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这巨魔抱怨食物不好吃，但他吃的比谁都多。' WHERE `Id` = 64169 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你看到西面的长城了吗？我在想长城的外面有什么呢？' WHERE `Id` = 64170 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里所有的东西……都那么……那么……不同！' WHERE `Id` = 64171 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我就是喜欢听柯谈论他那些美味的食谱。我从不知道竟然有那么多种烤肉的方法。' WHERE `Id` = 64176 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你有没有尝过柯的厨艺？我好像怎么都吃不够。' WHERE `Id` = 64177 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他经常告诉我说他喜欢我的口音，我就一直问他，什么口音？' WHERE `Id` = 64178 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们不要让杀戮席卷这片净土，$G兄弟:姐妹;。' WHERE `Id` = 64192 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们一路搜寻，跨越了千山万水，可却偏巧在这里狭路相逢。看来不管走到哪里，我们的冲突都是难以避免的啊。' WHERE `Id` = 64193 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我一直在观察你，$r。' WHERE `Id` = 64194 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿够了，这可不是打架的地方。不然谁也别想吃到这美食。' WHERE `Id` = 64197 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '音乐对人的心灵、身体和灵魂都有好处！' WHERE `Id` = 64199 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我告诉过我的儿子，我告诉过迪恩，下雨时不要将牦牛带到牧场。然后他做了什么？他在雨天将牦牛带到牧场。$B$B现在我们的牦牛生病了，这并不奇怪！$B$B唉呀！我怎么会生出这样一个愚蠢的儿子？' WHERE `Id` = 64209 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的儿子吃的不多。看看他！骨瘦如柴！我要多给他吃点儿。' WHERE `Id` = 64210 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为什么我的儿子就得是个矮子？我想要高大、强壮的儿子。$B$B在他小的时候，我就告诉他，不要在室内撑雨伞。我说，这样你会长不高！$B$B然后他做了什么？他总是打着雨伞玩！在房子里面！' WHERE `Id` = 64211 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的儿子迪恩说，妈妈做的饺子是全谷最好吃的！$B$B噢哈哈哈。真是我的好儿子。' WHERE `Id` = 64212 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '妈妈喜欢吃橙子，但在谷里很难找到橙子。$B$B我给我的儿子一些铜钱，让他去市集上买一些橘子。$B$B然后他做了什么？他买了一些豆子！$B$B我们又不是农民！我们是放养牦牛的牧民！我问你，我该怎么处理这些愚蠢的豆子？' WHERE `Id` = 64213 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的儿子迪恩整天在牧场。他这么努力工作。妈妈很自豪。' WHERE `Id` = 64215 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你来看妈妈吗？噢，坐一会儿！$B$B我告诉你，几天前，我听到一些流言。$B$B我听说吉娜·泥爪和她的父亲郝瀚·泥爪合不来！$B$B他想把她嫁给农夫老方，但她不愿意！她说她想经营她的市集。$B$B唉呀！现在的年轻姑娘们是怎么了？不想嫁给英俊的小伙子，不想成家吗？$B$B特别是老方……他这么抢手！人长得好看，又种出这么大棵的蔬菜。$B$B我的儿子怎么就没那么年轻英俊？！' WHERE `Id` = 64218 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，我的儿子什么时候能遇见一位年轻漂亮的女子？他整天围着牦牛转！$B$B哪个女孩愿意嫁给臭烘烘的牦牛牧人啊？唉呀，妈妈真担心……' WHERE `Id` = 64219 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，你好，$r！$B$B这是保留我们所有耕种历史和知识的地方。$B$B我们记录当地的天气，以及相应的收成，详细到谷里的每一粒种子和每一棵植物，甚至我们可能会不断种植的一堆种子。$B$B这些知识对我们而言是神圣的。即使有一天灾难会降临到这片土地上，我们也必须要保存这些种子。' WHERE `Id` = 64220 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '难道你只喜欢看着鸟儿吗？我真想我也能飞。' WHERE `Id` = 64223 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '农民祈求降雨，但我不！雨天对做生意来说非常糟糕。看看我的市集！湿透了！' WHERE `Id` = 64224 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '今天得在雨中做牦牛和穆山兽生意！好吧，无论天晴下雨，我都要经营这个市集。' WHERE `Id` = 64225 AND `Locale` = 'zhCN';
