UPDATE `broadcast_text_locale` SET `Text_lang` = '万岁！我们找到了！我们找到了！老农阿蓟的秘密宝藏！哦天哪哦天哪哦天哪！！！' WHERE `Id` = 64251 AND `Locale` = 'zhCN';
