UPDATE `broadcast_text_locale` SET `Text_lang` = '从镇上到香里拉有很长一段路，但走路对精神有好处。这肯定有助于让小艾黎到户外活动。' WHERE `Id` = 64262 AND `Locale` = 'zhCN';
