UPDATE `broadcast_text_locale` SET `Text_lang` = '我总对这里的锦鱼人感到奇怪。但他们知道如何捕鱼，而且技术比我们更高，所以我有什么资格去评判呢。' WHERE `Id` = 64289 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，这太令人兴奋了！现实版的寻宝！' WHERE `Id` = 64292 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那件事看上去太可怕了！你救了我们的命，$n！' WHERE `Id` = 64296 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那么……想谈谈这个事儿吗？' WHERE `Id` = 64299 AND `Locale` = 'zhCN';
