UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，你看起来很瘦，$r。你必须吃些东西。坐下，我给你拿些吃的东西。' WHERE `Id` = 64894 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在金色神灯，大家吃喝不停，这里是客流不断！你想要些什么吗？' WHERE `Id` = 64895 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎光临谷里最好的旅店——金色神灯。如果有人想跟我争，我就让他尝尝我的拳头。' WHERE `Id` = 64896 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我这里有最柔软的羽毛床，千里难寻。你想试试吗？' WHERE `Id` = 64897 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你吃饱了吗，$r？请记得要好好照顾自己。' WHERE `Id` = 64898 AND `Locale` = 'zhCN';
