UPDATE `broadcast_text_locale` SET `Text_lang` = '哇！真响！' WHERE `Id` = 64935 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '康诺，我饿了。' WHERE `Id` = 64937 AND `Locale` = 'zhCN';
