UPDATE `broadcast_text_locale` SET `Text_lang` = '看看那位！他看起来……怪怪的。' WHERE `Id` = 64940 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哎呀……对不起。' WHERE `Id` = 64942 AND `Locale` = 'zhCN';
