UPDATE `broadcast_text_locale` SET `Text_lang` = '他是谁？' WHERE `Id` = 64945 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '它看起来像一条大鱼！' WHERE `Id` = 64947 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果他是鱼，他为什么不在水中游泳呢？' WHERE `Id` = 64948 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '康诺，我们能乘坐风筝吗？' WHERE `Id` = 64953 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这场混乱毁掉了……一切。毁了所有人。' WHERE `Id` = 64955 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '绝对不能让部落找到聚焦之虹。消灭他们军队的所有残余力量，我会保护好神器。' WHERE `Id` = 64956 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我必须在传送前调校好聚焦之虹。保护我！' WHERE `Id` = 64957 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的族人都是卑劣的懦夫，兽人。你们都会像疯狗一样被消灭，别想得到聚焦之虹。' WHERE `Id` = 64958 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '对怜悯吐口水？那你就得不到怜悯了。你想要杀戮？那就让加尔鲁什给你收尸吧。' WHERE `Id` = 64959 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '怎么所有的男人都不急着约女人出来？' WHERE `Id` = 64971 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我觉得他喜欢我，但我不确定。你是怎么想的，$r？' WHERE `Id` = 64972 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，不，如果他认为我太多毛了呢？如果他不喜欢黑白相间的女子呢？' WHERE `Id` = 64973 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我使出浑身解数调情，但我想他没收到讯息！' WHERE `Id` = 64974 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他总是谈论扳手和超载电容器。他肯定知道哄骗女孩。嗷！' WHERE `Id` = 64975 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我当然喜欢他漂亮的脸蛋。' WHERE `Id` = 64976 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '想看些你喜欢的护甲吗，$r？只有你在潘达利亚最具挑战性的地牢中证明自己的价值，你才能获得这些罕见的护甲套件。$B$B你必须寻找这些地牢，并步行进入。以足够快的速度赢得挑战的人们应得到我们大铸甲师的尊敬，也许还会在邮件中收到一个罕见护甲礼物。' WHERE `Id` = 64979 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我向来擅长算数！$B$B当地人见识了我心算加、减和微分方程的速度后，他们立马就聘用了我！' WHERE `Id` = 64998 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎，$r！留下来听一会。' WHERE `Id` = 65002 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎光临夜莺旅馆，$c。今天我们可以为你做些什么？' WHERE `Id` = 65003 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们被这里的景色吸引。但是，即使是这样的景色，也无法与四风谷的美景相比。' WHERE `Id` = 65043 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '旅行者，你想吃点什么吗？' WHERE `Id` = 65048 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '出售食物和饮料！' WHERE `Id` = 65049 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来份点心怎么样，$r？' WHERE `Id` = 65050 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '野牛人侵占了我们的家园！但这个地方……这个地方为我们提供一个新的开始。' WHERE `Id` = 65054 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很抱歉，我们需要在这里呆一会儿。部落保护着我们的安全。' WHERE `Id` = 65064 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好！你想和我宠物决斗吗？' WHERE `Id` = 65065 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$r。我也许比较小，但是在宠物的战斗中身材大小并不重要！' WHERE `Id` = 65066 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$c！你不觉得我的宠物很可爱吗？' WHERE `Id` = 65067 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，亲爱的。你一直都在战场上吗？' WHERE `Id` = 65068 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有什么我可以帮你吗？' WHERE `Id` = 65069 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '锄头是忠实的$G男人的:女人的;武器。' WHERE `Id` = 65070 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好啊，$n。汇风岭附近发生的一切我都已经了然于胸了，宝贝儿。活到我这把年纪，总会交到几个大嘴巴的朋友。' WHERE `Id` = 65071 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我相信我们最终可以找到我父亲的青春之池。我们可以为泰兰德提供尽可能多的信息。' WHERE `Id` = 65130 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '因为我们来到这片新的土地，所以我的哨兵面临许多危险。我们准备好迎接任何挑战。' WHERE `Id` = 65131 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在进入四风谷后，我军的士气有所提高。' WHERE `Id` = 65132 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '四风谷真是个的天堂。' WHERE `Id` = 65133 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '亲眼见到这个地方是我父亲的梦想。我必须在这里完成他的心愿。' WHERE `Id` = 65134 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在收集我们所要的信息之前，我们都在这个谷里休息。然后，我们必须想方设法回家。' WHERE `Id` = 65136 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们能在这个四风谷遇见还真巧。' WHERE `Id` = 65138 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '加尔鲁什的狂妄摧毁了锦绣谷。这是无法治愈的创伤。' WHERE `Id` = 65139 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '泰兰德派我们来这里寻找圣光。' WHERE `Id` = 65140 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这里的树比我在南部丛林见过的都更漂亮。' WHERE `Id` = 65141 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我从来没有见过像这样的地方。' WHERE `Id` = 65142 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这山谷里的池水莫非就是传说中的“青春之池”？也许我们可以再次掌握永生……' WHERE `Id` = 65143 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们已经听说了魔古族遍布四风谷的消息。他们不会胜过我们的。' WHERE `Id` = 65144 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们在研究池水的同时，还会巡逻城市的边界，保护这里的人。' WHERE `Id` = 65145 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '说实话，我起初并不相信瓦尔德林看见的幻像。但这地方确实散发着不同寻常的魔法之力——难道这就是传说中的“青春之池”？' WHERE `Id` = 65146 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我每天都存入各种新旧资料。有时是古老的智慧书卷，有时则是某位墨水大师创作的山谷写生图。$b$b我们保存着这些知识，以便让后人能从我们的成功……和失败中借鉴一二。' WHERE `Id` = 65274 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这群小子可真麻烦。' WHERE `Id` = 65293 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我答应带他们在这儿野餐，可这里太危险了。就在几天前，我听说有几个像你一样的陌生人打了起来。$b$b还有个从……龟背上来的人。$b$b我一直以为那海龟只是个传说。' WHERE `Id` = 65294 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们这里并不常遭遇掠食者。有时，如果下雨的话，蜥蜴人会出现。可他们只在电闪雷鸣的暴风雨来袭时才会来。' WHERE `Id` = 65295 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '够了。你们俩简直是一对猢狲！' WHERE `Id` = 65305 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是你们不听话，我就马上结束野餐，带你们回家。你们愿意这样吗？' WHERE `Id` = 65306 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '泰，别说你哥哥坏话了。刘，你也别给你弟弟说坏话的理由。' WHERE `Id` = 65307 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们两个都给我住手。别弄得自己傻乎乎的。你们就不能像聪明的锦鱼人一样好好相处吗？还是说，你们就乐意毛毛躁躁地像个猢狲？' WHERE `Id` = 65308 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我一直以为巨魔只在古老的故事中存在。' WHERE `Id` = 65313 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你，$p！是你的勇气激励着我们战斗。' WHERE `Id` = 65314 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是一场艰苦的战斗。我们从前只需要提防蜥蜴人突袭者和偶尔前来捣乱的饥饿猢狲。$b$b那些巨魔……他们作战的方式很不一样。' WHERE `Id` = 65315 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些巨魔在找什么？' WHERE `Id` = 65316 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$c。我并无恶意。$B$B我在这以血色十字军成员的身份出现，是因为他们已经无可救药地堕入了腐化与邪恶。$B$B我需要你的帮助，彻底终结他们的罪孽。' WHERE `Id` = 65342 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我是听着白虎的传说长大的。他是潘达利亚人民的英雄。很荣幸能来此受训。' WHERE `Id` = 65362 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '给，拿上这些补给品吧。你在任务中会用得上。' WHERE `Id` = 65369 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我想我们差不多干完一半了，对吧？已经解决了血色大厅，还剩下血色修道院。$B$B要是我突然消失了你可别吃惊——我得快点赶到那里。' WHERE `Id` = 65383 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是尸横遍地啊。干得不错，$p。' WHERE `Id` = 65384 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你拿到书典了吗？' WHERE `Id` = 65385 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '蒙面的十字军战士跪下来检查织焰者的尸体，同时在寻找着什么。' WHERE `Id` = 65386 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我为成功守住我们的村庄而感到骄傲。' WHERE `Id` = 65393 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '父亲，我再也不是让你担忧的无助孩童了。' WHERE `Id` = 65394 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我愿意继续训练，使自己能永远守护我们的家园。' WHERE `Id` = 65395 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会确保这村庄的安全，让你能安心地卸下武器。' WHERE `Id` = 65396 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是你让我成长了许多！' WHERE `Id` = 65445 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愿我们能再次相见！' WHERE `Id` = 65446 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '也许下一次就轮到我救你了！' WHERE `Id` = 65447 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我已经为世界做好了准备，可不知世界准备好了没有！' WHERE `Id` = 65448 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有这么多值得高兴的事，我们不能只想着消极的方面。' WHERE `Id` = 65455 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些困难都会过去，我们会因此变得越发强大。' WHERE `Id` = 65456 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我相信你能帮助我们。' WHERE `Id` = 65457 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是你帮这村庄找回了力量！' WHERE `Id` = 65458 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不会只有我们一个村庄挺身对抗雷电之王！' WHERE `Id` = 65459 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '和渔夫交朋友总是好事。你永远也不会挨饿！' WHERE `Id` = 65460 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个村庄一向宁静怡人。' WHERE `Id` = 65467 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '改变是难以避免的，即便是对于像杜术这样的老顽固来说也是一样。' WHERE `Id` = 65468 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的女儿浑身充满了志气和坚毅！她比我丈夫还让我省心。' WHERE `Id` = 65469 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '完成了。你做到了，$p！' WHERE `Id` = 65470 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欺骗到此为止吧。' WHERE `Id` = 65471 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，我叫莉莉安。你不会介意我拿走这两柄利刃，对吧？' WHERE `Id` = 65472 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '蒙面的十字军战士凝视着检查官被刀片刺穿的尸体。' WHERE `Id` = 65473 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很高兴再次见到你，$n。我还担心你不会来。$B$B让我们完成这个任务吧？血色十字军已经证明，它不会自行了结。' WHERE `Id` = 65482 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好，这些利刃无坚不摧。它们仿佛从始至终都是为我存在的。' WHERE `Id` = 65518 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '飞雪选择|cFFFF0000$n|r，作为用|cFFFF0000|Hspell:106706|h[钢铁漩涡]|h|r追踪的目标！' WHERE `Id` = 65522 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '飞雪正在用|cFFFF0000|Hspell:|h[钢铁漩涡]|h|r追赶你！在她选中其他人之前，离她远点！' WHERE `Id` = 65523 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '|TInterface\\Icons\\inv_sword_24.blp:20|t飞雪使出了|cFFFF0000|Hspell:106706|h[钢铁漩涡]|h|r的招数！' WHERE `Id` = 65524 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当她从怀特迈恩的尸体上将刀刃拔出时，刀刃变换了。' WHERE `Id` = 65567 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你能相信这个小土地精的胆量吗？这个精明的小谈判者马上就能以他的价格把我搞破产。' WHERE `Id` = 65568 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是第一位熊猫人探险者——刘浪之歌。' WHERE `Id` = 65583 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这首歌是由古文写成，那是皇帝和学者们使用的语言。现在几乎已经没人会说了。' WHERE `Id` = 65584 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '歌曲描绘了他的冒险之旅。' WHERE `Id` = 65585 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '勇敢的刘浪骑在海龟背上，出发去探索这个世界。' WHERE `Id` = 65586 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有人记得那只海龟的名字吗？尹记得吗？' WHERE `Id` = 65587 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没错，那只海龟被称作神真子。一开始，他的大小只容得下刘浪一人坐在上面。' WHERE `Id` = 65588 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '后来他越变越大，大得惊人，所以现在有些人叫他“迷踪岛”。' WHERE `Id` = 65589 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有问题吗，昊？' WHERE `Id` = 65590 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的，昊——我们的家就在神真子的背上。' WHERE `Id` = 65591 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '刘浪在探索世界的过程中有许多发现——噢——怎么了，昊？' WHERE `Id` = 65592 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个问题问得好。历代以来，没人和神真子说过话。他只对刘浪开口。' WHERE `Id` = 65593 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可我相信，神真子知道我们在这儿。而且他在乎我们每一个人！' WHERE `Id` = 65594 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '尤其是昊！刘浪曾经说过：“频频提问的人最为可贵。”' WHERE `Id` = 65595 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '“我们都该表现得像个孩子，因为世界才是长者，有很多东西要教给我们。”' WHERE `Id` = 65596 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '弟子们！弟子们！集中精神。' WHERE `Id` = 65597 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有人知道刘浪多久回潘达利亚一次吗？' WHERE `Id` = 65598 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈哈，不是的，尹。刘浪走到哪儿就吃到哪儿。' WHERE `Id` = 65599 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他每隔五年返回潘达利亚的主大陆一次。' WHERE `Id` = 65600 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你说得对，尹。它被藏起来了，藏在迷雾后面。' WHERE `Id` = 65601 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有人记得刘浪总是如何找到它的吗？楠？' WHERE `Id` = 65602 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没错！刘浪总能设法回到家乡。每隔五年他就会回去，带走更多的探险者。' WHERE `Id` = 65603 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的，昊！只有最勇敢的熊猫人才会爬上龟背，与刘浪一同外出探索世界。' WHERE `Id` = 65604 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '神真子很久没有上岸了。可那也没能阻止某些熊猫人外出探险。' WHERE `Id` = 65605 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是的，就像陈和丽丽！他们出去探索世界了。也许有一天，你们也会。' WHERE `Id` = 65606 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很高兴你提出了这个问题，尹。刘浪一生都在探索世界，还在迷踪岛上养育了许多子女。' WHERE `Id` = 65607 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '最后他变得非常老迈，最后一次造访了潘达利亚。' WHERE `Id` = 65608 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但却没有其他人愿意和他一同探险。于是他离开了。' WHERE `Id` = 65609 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '神真子再也没有返回潘达利亚。' WHERE `Id` = 65610 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '疲惫不已的刘浪告别了神真子——这位与他交情至深的老朋友。' WHERE `Id` = 65611 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '然后，刘浪去了禅杖林，身上背着那柄随他四处游历的竹伞。' WHERE `Id` = 65612 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他撑开竹伞，把伞柄插进地里，坐在伞下乘凉。' WHERE `Id` = 65613 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他闭上双眼，与大地融为一体。然后——你们知道发生了什么吗？' WHERE `Id` = 65614 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他的竹伞……发芽了！生根，开花，变成了一颗树！' WHERE `Id` = 65615 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯，是真的。要是你去禅杖林，就能看见了。' WHERE `Id` = 65616 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些在我们之前到来的长者，他们的禅杖也已生根发芽，那里已经长出参天密林。' WHERE `Id` = 65617 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这不是个难过的故事！刘浪自己说过：“生时精彩，死亦无憾。”' WHERE `Id` = 65618 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在我看来，刘浪的人生无比精彩。我们的一切都得益于刘浪——这位熊猫人探险者始祖。' WHERE `Id` = 65619 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们讲述他的故事，是为了让他能够被永远铭记。' WHERE `Id` = 65620 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '洛林，谢谢你！你的歌喉美极了。' WHERE `Id` = 65621 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你能再唱一遍吗，唱给那些刚刚到来的弟子听？' WHERE `Id` = 65622 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那首歌是关于什么的？' WHERE `Id` = 65634 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '神真子！' WHERE `Id` = 65635 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘘，昊。你一直都没注意听吗？' WHERE `Id` = 65638 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '甚至是昊？' WHERE `Id` = 65641 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '得了！我宁可从这桥上跳下去。' WHERE `Id` = 65644 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……每当他饿了的时候？' WHERE `Id` = 65645 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可潘达利亚不是被藏起来了吗？没人能找到它！' WHERE `Id` = 65646 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '因为海龟总会返回他们出生的海岸！' WHERE `Id` = 65647 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可我们现在不怎么探险了，对吧？' WHERE `Id` = 65649 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就像陈和丽丽·风暴烈酒！' WHERE `Id` = 65650 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不行。到处都是巨魔。' WHERE `Id` = 65652 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '游学者！刘浪后来又遇到了什么事？' WHERE `Id` = 65654 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么？什么？' WHERE `Id` = 65656 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真令人难过！' WHERE `Id` = 65658 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，$n！我正在为节日酿制某种特饮。晚些时候再来吧，我请你喝上几杯。' WHERE `Id` = 65705 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好了！我把它放在桌子上面了。' WHERE `Id` = 65706 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '外面在吵什么？' WHERE `Id` = 65707 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '效果不太好，$n。你还是别试了。' WHERE `Id` = 65708 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么？不！' WHERE `Id` = 65799 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那不可能。' WHERE `Id` = 65800 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '消灭他们！' WHERE `Id` = 65801 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们不行了！乘胜追击！' WHERE `Id` = 65802 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得好！你真是个像样的战士。' WHERE `Id` = 65803 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '打完一场漂亮的仗，感觉总是很美妙。' WHERE `Id` = 65804 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让我们庆祝吧！' WHERE `Id` = 65805 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我恨你们所有人！' WHERE `Id` = 65835 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为什么？为什么非得是他？' WHERE `Id` = 65836 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会讨回公道！' WHERE `Id` = 65837 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '以命偿命！' WHERE `Id` = 65838 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '出发前别忘了跟非离谈谈。她的技能会有力地帮你对付我们的敌人。' WHERE `Id` = 65839 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哎呀，我自己正要吃呢！好吧，要是艾拉想要，我就不能不给。接着，拿去吧！' WHERE `Id` = 65906 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我本该向你收取买那个桃子的一大笔钱，但考虑到艾拉是我最好的顾客，这个就免费送给你。仅此一次，听到了吧！' WHERE `Id` = 65909 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有句话是这么说的——“你的脸朝向太阳，阴影将落在你身后。”$b$b我希望你能发现光明的未来，$n！' WHERE `Id` = 65910 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯，自从……风暴烈酒酿造厂的黄金时代过后……我就没有尝到过口感如此醇厚清冽的美酒！无论是谁酿的，他都是一个真正的人才。' WHERE `Id` = 65914 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎光临，$n！$b$b这是“云游节”，我们都聚集在海滩上眺望大海，以纪念第一个熊猫人探险家的事迹。$b$b笼罩潘达利亚的迷雾曾经非常浓密，那时你甚至看不到近海处的大岩石。现在再看看这里，多么美丽的夜晚啊！我很高兴你能来这里参加这个盛会。' WHERE `Id` = 65947 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '游学者周卓！我很高兴你能和我们一起度过这一周。' WHERE `Id` = 65948 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你可以为我们唱刘浪之歌吗？' WHERE `Id` = 65949 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的声音太动人了。有时我甚至觉得能在你的歌声中听到整支乐队的美妙乐音！' WHERE `Id` = 65950 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '游学者，谢谢你！' WHERE `Id` = 65951 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哇，不可思议！快看这些灯！$b$B你觉得那是什么？骑在海龟背上的那个家伙是谁？$b$b等等，那是刘浪吗？$b$b那只海龟肯定就是神真子了。没错！那座雕像就是一座微缩的迷踪岛！$b$B陈叔，我们回到家了！$b$b嗯，几乎算到家了。' WHERE `Id` = 65954 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看来你已经在跟翔龙宝宝练习接球了，$n。你每次只能跟一条翔龙玩接球。$B$B在跟其他翔龙练习之前，请先完成你当前的训练课程。' WHERE `Id` = 65963 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '潘达利亚的子民们，迷雾已经散去。无论如何，这片土地都将对外开放。' WHERE `Id` = 65970 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让我们团结一致，重建这片神圣的土地，向治愈这个破碎的世界迈出第一步。' WHERE `Id` = 65971 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，不，不要起来。这里没有战争，士兵，你需要休息。' WHERE `Id` = 65979 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会成为插入敌人咽喉的那把利刃。' WHERE `Id` = 66004 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没有人敢和影踪派作对。' WHERE `Id` = 66006 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，当然。' WHERE `Id` = 66021 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '耐心地寻找你的力量。' WHERE `Id` = 66022 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哇！嗯，太有趣了！' WHERE `Id` = 66023 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '只有集中精力，才能直面任何考验。' WHERE `Id` = 66028 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '只有冷静的头脑能够做好战斗的准备。' WHERE `Id` = 66029 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你喜欢神奇的冶金技术、奥妙的熔炼技艺、优美的合金秘法吗？' WHERE `Id` = 66030 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我明白，土水派之道并非通向智慧之门的唯一途径。但，有些选择依然令人无法接受，有些风险仍然令人难以承担，有些决定始终让我难以原谅……$B$B现在，是我离开神真子的时候了。我敬重德罗娜·莱因哈特的信心和勇气，她口中有关联盟的故事对她的人民赞誉有加。我还不知道自己是否能在那里找到归宿，但是无论我的道路通向何方，我都会找到一个方法来帮助迷踪岛之外的世界。$B$B无论如何，我很喜欢我们共处的这段短暂时光，$n。我希望你可以和我一起走，但我明白做这个决定并不容易。' WHERE `Id` = 66037 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的家族以制作玉石和宝石为生，这门手艺已经传承了将近十代人。我能传授给你的技艺可能会令你大吃一惊。' WHERE `Id` = 66055 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我不得不承认，这非常有趣！' WHERE `Id` = 66056 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看来你交到了一位新朋友。' WHERE `Id` = 66057 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他真难对付……' WHERE `Id` = 66058 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<艾莎似乎正沉浸在她的功课中。>' WHERE `Id` = 66068 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊！一个药剂爱好者？酒仙们知道如何调配化合物，但却常常遗漏药剂或疗法的精细配方。' WHERE `Id` = 66072 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你只是向神器中注入了魔力，并不意味着那些魔力将永远留存在其中。' WHERE `Id` = 66087 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这片陌生的新土地上长满了各种草药和药石，但你要先学会如何去寻找它们。' WHERE `Id` = 66156 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得好，$n。多亏了你我们才能做到这一切。' WHERE `Id` = 66234 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '野牛人从四面八方包围过来了，$n！快，保卫村庄，别让他们烧了它！' WHERE `Id` = 66235 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎来到天禅院。' WHERE `Id` = 66329 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很高兴见到你，$n！我和我的学生来品尝酒仙布夫酿造的美酒，顺便庆祝酿月祭！' WHERE `Id` = 66331 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '作为织雾者，我们必须始终为需要帮助的人提供保护。' WHERE `Id` = 66332 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '织雾者年云也许有些严厉，但实际上是个心地善良的老师。' WHERE `Id` = 66333 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '姐妹们，村庄需要我们的援助。到前线上去，治疗伤员！' WHERE `Id` = 66334 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是，夫人！' WHERE `Id` = 66335 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我在我们的训练场地看到一个宠物斗士。云端翔龙无论做什么都一样表现出色，包括与其他宠物战斗！要获得雏龙的关键在于与一只成年翔龙建立良好的关系。只要你在骑士团中的声望达到崇拜，就可以在百木园的各个角落找到它们。' WHERE `Id` = 66346 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '船长！请让船员安全待在船上。一旦遭到攻击，我们会保护舰船！' WHERE `Id` = 66562 AND `Locale` = 'zhCN';
