UPDATE `broadcast_text_locale` SET `Text_lang` = '他们来了，哈特斯！做好准备！' WHERE `Id` = 66572 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祝你好运，$r。你在这里能找到潘达利亚所有阵营的代表。当你经验再丰富些时，就回来与我们交谈吧。伟大的冒险和丰厚的奖励在等着你。' WHERE `Id` = 66589 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愿幸运之星照耀着你，$c。你在这里能找到潘达利亚所有阵营的代表。与他们交谈，看看你是不是他们要找的勇敢冒险者。' WHERE `Id` = 66590 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎你，旅行者。如果你愿意，就把这里当成自己的家吧。楼上有银行和城市传送门。出售各种商品的小贩都已经在这座建筑附近摆摊开店了。请随意选购。' WHERE `Id` = 66597 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '能给我们一些宠物吗，芬克斯维奇小姐？拜托了。' WHERE `Id` = 66636 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，不，小家伙们。你们还太小了！' WHERE `Id` = 66637 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哼。我可能比她还高呢。' WHERE `Id` = 66641 AND `Locale` = 'zhCN';
