UPDATE `broadcast_text_locale` SET `Text_lang` = '你们两个都给我闭嘴！' WHERE `Id` = 66680 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '普利波先生在教我如何做一位标本剥制师。我个人觉得他的思想过于陈旧了，应该从侏儒工程学中找点儿灵感。' WHERE `Id` = 66728 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你认为这些是长在树上的？' WHERE `Id` = 66754 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你这有没有什么冒气泡的能量饮料？' WHERE `Id` = 66755 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '萨娅·茗流在洗手。' WHERE `Id` = 66756 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '萨娅·茗流叹了口气。' WHERE `Id` = 66757 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们哪位还要再来一杯么？' WHERE `Id` = 66758 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这么多伤患……' WHERE `Id` = 66759 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '呦，该休息了！' WHERE `Id` = 66760 AND `Locale` = 'zhCN';
