UPDATE `broadcast_text_locale` SET `Text_lang` = '呀！我要走了！回旋式多彩隐形装置启动！' WHERE `Id` = 66766 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我从没见过这样的根！' WHERE `Id` = 66767 AND `Locale` = 'zhCN';
