UPDATE `broadcast_text_locale` SET `Text_lang` = '今天有收获吗？你还是什么都没带回来呢。' WHERE `Id` = 67050 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我见你又在钓鱼了……运气有没有比昨天好一点？' WHERE `Id` = 67051 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是一个好运之吻，相信会对你有所帮助。' WHERE `Id` = 67052 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是你能多抓几条鱼回来，我也不会怪你终日虚度光阴。' WHERE `Id` = 67053 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '还好我当初不是因为你的钓鱼技术才嫁给你的……' WHERE `Id` = 67054 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，这些孩子永远是精力旺盛！' WHERE `Id` = 67063 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是摔倒了，擦破膝盖，可别跑来对着我哭鼻子！' WHERE `Id` = 67064 AND `Locale` = 'zhCN';
