UPDATE `broadcast_text_locale` SET `Text_lang` = '记住，在真实比赛中，你要与骑士团的其它受训者同场竞技。' WHERE `Id` = 67074 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这就是终点线。在你飞过所有10个检查点之后，从下方穿过终点线，以锁定排名。' WHERE `Id` = 67075 AND `Locale` = 'zhCN';
