UPDATE `broadcast_text_locale` SET `Text_lang` = '我真是毫无头绪。旋翼机之击？' WHERE `Id` = 67115 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为什么……为什么是他？我们只是淳朴的农民……怎么竟然这么倒霉？' WHERE `Id` = 67116 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '旋……翼……' WHERE `Id` = 67117 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我丈夫想去看看水边发生了什么事。就在那时……那时……$B$B<苏云长老泣不成声。>' WHERE `Id` = 67119 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……机……' WHERE `Id` = 67120 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一枚该死的炸弹朝我们袭来。我没死，可……我丈夫……' WHERE `Id` = 67122 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么字？噢，你是说盖子上的那些？可能只是别人随手乱写的。没什么深层含义。' WHERE `Id` = 67128 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '呜哇！！' WHERE `Id` = 67129 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别搞笑了。那只是一罐虫子。对我来说简直不堪入目。' WHERE `Id` = 67130 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '胡说！看，这就是我们不该离开村子的原因！' WHERE `Id` = 67131 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '随便你。我敢说，它会带你绕上一个大圈子，然后害你一无所获！' WHERE `Id` = 67133 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小心那东西，军军！一阵狂风就能把你卷到海里去！' WHERE `Id` = 67135 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '天哪，杜宇。你喂那东西吃了什么？' WHERE `Id` = 67137 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '也许我们该把你喂给那条鱼！' WHERE `Id` = 67138 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '杜宇是鱼食！哈哈！' WHERE `Id` = 67139 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '对于心怀和平的人来说，那可真是永生难忘的武器，陌生人。' WHERE `Id` = 67141 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎你，$r。不必拘束，就像在自己家里一样。这里有好酒好饭，楼上还有卧床供你休息。
<茂林热情地对你微笑。>' WHERE `Id` = 67146 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你可真了不起。我认输。' WHERE `Id` = 67152 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的村庄不大，但我家世代都在这片山上酿造潘达利亚最优质的苹果酒。$B$B我现在只想平安回去，好收割庄稼，与孩子们团聚。' WHERE `Id` = 67164 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的攻击力很强，可我的防守更强！' WHERE `Id` = 67166 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你得集中精神。再来一次！' WHERE `Id` = 67167 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '难道不美么？如此优雅地在空中起舞。希望有一天，我也能拥有鹤般的美好气韵。' WHERE `Id` = 67169 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '吉斯坦大师跑去附近的青龙雕像处寻求治疗。拖住她，在她伤愈前将她击败！' WHERE `Id` = 67173 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '愿先祖保佑我们免受这些外来者和他们暴力行径的侵扰。' WHERE `Id` = 67177 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，$n，我现在正忙着呢。我得集中精神！' WHERE `Id` = 67182 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我感到浑身充满了力量。来吧！' WHERE `Id` = 67183 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '该死，我输了！哎呦……真累啊……' WHERE `Id` = 67184 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '想跑？看来我可真是够吓人的！' WHERE `Id` = 67185 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈！这回合苏琪赢了。' WHERE `Id` = 67186 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我正忙着让这菜鸟尝尝我拳头的滋味！' WHERE `Id` = 67187 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让我们瞧瞧谁才是更强的翔龙骑士。' WHERE `Id` = 67188 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '跑了？等你鼓起勇气时再来面对我吧。' WHERE `Id` = 67189 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么？我……我输了？啊！我得多加努力，一定要打败你！' WHERE `Id` = 67190 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不出所料。你根本不是我的对手！' WHERE `Id` = 67191 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '瞧瞧你，简直瘦得皮包骨头！你得多吃点！' WHERE `Id` = 67209 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你是否值得我们信赖，不是我说了算。在村长作出相反的判定以前，我都当你是朋友。' WHERE `Id` = 67210 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就在不久前，我们还过着只知道酿造可口苹果酒的简单生活。在这么短的时间内，一切都变了。' WHERE `Id` = 67211 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谁也不知道变幻之风会带来什么，也许是可怕的风暴，也许是盛大的丰收。看来这次带来的是你。$B$B现在，我想问问，你究竟是风暴还是丰收？' WHERE `Id` = 67214 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '妹妹，我们必须行动起来！否则，我们所有的收成都会赔在这场自己无份参与的战斗中！' WHERE `Id` = 67215 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们只能尽力而为，亲爱的妹妹。我们不是战士，无法赶走外来者。' WHERE `Id` = 67216 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '楚在干嘛？他怎么还在道场里训练？他应该保护我们！' WHERE `Id` = 67217 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要是我们陷入更大的危机，楚一定会挺身而出。他向来如此。' WHERE `Id` = 67218 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我真心希望你是对的。' WHERE `Id` = 67219 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎来到坡东村，异乡人。我不知你是为何而来，但你看起来需要休息。$B$B不如坐下喝杯可口的苹果酒，将烦恼丢到一边，怎么样？' WHERE `Id` = 67220 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你不明白。部落都是怪物！我们跟他们可不一样。' WHERE `Id` = 67225 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我就知道你能做到！' WHERE `Id` = 67231 AND `Locale` = 'zhCN';
