UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你想提升自己的烹饪技能，我正好有些知识要与你分享。' WHERE `Id` = 68293 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我只能说，那个巨大的漂浮堡垒近来让许多旅行者却步难行。' WHERE `Id` = 68294 AND `Locale` = 'zhCN';
