UPDATE `broadcast_text_locale` SET `Text_lang` = '同时进场的还有来自泰罗卡森林的驭风鸦人，奇拉瓦克！' WHERE `Id` = 68863 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了地狱咆哮的荣耀！' WHERE `Id` = 68951 AND `Locale` = 'zhCN';
