UPDATE `broadcast_text_locale` SET `Text_lang` = '联盟的渣滓！' WHERE `Id` = 68953 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这座堡垒会比加尔鲁什尔前哨站更难攻破。但它们迟早会被攻破的。部落必将败落。' WHERE `Id` = 69036 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '要不是一位熊猫人织雾者在战后为我疗伤，我早就死在翡翠林了。$b$b这些熊猫人都是好人，我们应该保护他们免遭联盟奴役。' WHERE `Id` = 69063 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别担心，我马上就治好你！' WHERE `Id` = 69071 AND `Locale` = 'zhCN';
