UPDATE `broadcast_text_locale` SET `Text_lang` = '不！别过来……！你……你太危险了。我只要召唤召唤恶魔就满足了，可你……' WHERE `Id` = 69355 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……你竟然想把自己变成恶魔！' WHERE `Id` = 69356 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你究竟有什么邪恶的目的……？' WHERE `Id` = 69363 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这种知识毫无用处……你究竟想要什么，坎雷萨德？' WHERE `Id` = 69368 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '多么奇怪的生物。燃烧军团都离开了，它们为什么还一直留在这里？' WHERE `Id` = 69379 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦？' WHERE `Id` = 69382 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，可他也死了……它们为什么还留在这里？' WHERE `Id` = 69383 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，我花了几个星期的时间，想要弄明白怎么召唤这些家伙。如果你知道什么诀窍又愿意跟我们这些“下等”凡人分享的话，我会十分感激的。' WHERE `Id` = 69385 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '相比之下，它们根本不算什么！它们根本就不是一个档次的。' WHERE `Id` = 69387 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '它们有点……奇怪……有些不对劲……' WHERE `Id` = 69388 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，天呐……' WHERE `Id` = 69389 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那是什么声音？' WHERE `Id` = 69419 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '外面有人吗？' WHERE `Id` = 69420 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '出来！' WHERE `Id` = 69421 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯？那是什么？' WHERE `Id` = 69422 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '安度因，我知道他想要什么。噢，看看谁来了。' WHERE `Id` = 69445 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没人比我更恨加尔鲁什。愤怒每天都折磨着我。' WHERE `Id` = 69446 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '跟我来——四处看看吧。' WHERE `Id` = 69447 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '塞拉摩陷落以后，我的第一反应就是要血洗奥格瑞玛——把城里的男女老幼全都杀光。' WHERE `Id` = 69448 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我很惭愧。后来，我和卡雷苟斯就力量的使用进行了一次长谈。' WHERE `Id` = 69449 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '肯瑞托向来不乏滥用力量之徒。克尔苏加德把魔法知识用在了死灵法术上。' WHERE `Id` = 69451 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '另一个背叛我们的人，凯尔萨斯·逐日者也曾在这里学习。' WHERE `Id` = 69452 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '安度因，你比别人更清楚，应该将部落及其人民区别开来。' WHERE `Id` = 69453 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我每天都自问：“什么才是对的？”' WHERE `Id` = 69454 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '夺日者也在这里活动。联盟和部落相互合作。' WHERE `Id` = 69455 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果我们穷兵黩武，整个世界的希望就将破灭。' WHERE `Id` = 69456 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我将这座城市视为一盏指路的明灯。' WHERE `Id` = 69457 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '只有对彼此充满信任，这份希望才能留存。' WHERE `Id` = 69458 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我将这座城市视为一盏指路的明灯。' WHERE `Id` = 69459 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '只有对彼此充满信任，这份希望才能留存。' WHERE `Id` = 69460 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你，安度因。' WHERE `Id` = 69461 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你来晚了，$n。
我们就直奔主题吧。我们最近的侦查表明夏柯希尔的残余部队就躲在这座岛屿的中心。他们守护着一座加尔鲁什下令夺取的大型武器库。问题是他们激活了岛上的防御工事，一座覆盖整个扎尼维斯的大型护盾。
这就是你的任务了。我要你去乘坐一艘炮艇并击毁护盾发生器。只要它们还在运转，我们的部队就无法到达武器库。' WHERE `Id` = 69473 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这……太神奇了……一种未被开发原始奥术能量。' WHERE `Id` = 69505 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '想想吧，只要有一小部分这种力量，我们能召唤出什么样的恶魔来啊！' WHERE `Id` = 69506 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '所以，伊利丹就是靠这种办法役使了大量的恶魔……' WHERE `Id` = 69509 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么？？你这种说法毫无根据。' WHERE `Id` = 69513 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……你为什么要说这么多，坎雷萨德？' WHERE `Id` = 69515 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……噢，拜托，你该不是又要跟我讲你那些恐怖故事了吧？' WHERE `Id` = 69519 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……' WHERE `Id` = 69521 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你听到了吗？！那些灰舌恶狗要过来了。我们快点开始仪式吧！' WHERE `Id` = 69523 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s开始施放|cFFFF0000|Hspell:113134|h[群体复活]|h|r！' WHERE `Id` = 69536 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，不，不！圣钟！' WHERE `Id` = 69605 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我已经彻底封锁了整个达纳苏斯！我抓住了所有那些试图潜入城市的笨贼和想要靠传送法术躲过陷阱的半吊子法师！' WHERE `Id` = 69606 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们不可能通过……这可是内部机密。某个在城里的人带着圣钟，除非……不……' WHERE `Id` = 69607 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = 'UNUSED' WHERE `Id` = 69608 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '跟我来。' WHERE `Id` = 69609 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些传送门通往达拉然。就是说肯瑞托……我的肯瑞托里……有人在助纣为虐。' WHERE `Id` = 69610 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我绝不容忍又一次背叛！那些罪人必将受到惩罚！' WHERE `Id` = 69611 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '艾萨斯·夺日者！' WHERE `Id` = 69612 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你背叛了肯瑞托，夺日者。是你让加尔鲁什的军队进入我的城市。' WHERE `Id` = 69613 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你都不敢看我。我的城市不再欢迎你和你那些不服管束的同党。' WHERE `Id` = 69614 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈！我明白了。那我就用武力驱逐夺日者。' WHERE `Id` = 69617 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你，艾萨斯，跟我走一趟吧。' WHERE `Id` = 69618 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '肯瑞托内部出了叛徒。我已经控制了局势。' WHERE `Id` = 69620 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我将部落逐出了达拉然。你的目的达到了，陛下：肯瑞托将属于联盟。' WHERE `Id` = 69622 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我记得我说的话。可我信错了人。' WHERE `Id` = 69623 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '投降的人将被送去紫罗兰监狱。而选择对抗的人，我不保证他们的性命。' WHERE `Id` = 69626 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '怎么管理肯瑞托是我的事。' WHERE `Id` = 69628 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那是他们自己选的路。' WHERE `Id` = 69630 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是自欺欺人。一入部落，再难回头。我现在明白了。我正在动员肯瑞托。' WHERE `Id` = 69632 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要劝我了，瓦里安。' WHERE `Id` = 69634 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '安度因！' WHERE `Id` = 69638 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '陛下！这里有我们需要的一切：木材、石料和……' WHERE `Id` = 69706 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '托德曼元帅和几个斥候追击一支部落小队去了海滩，至今还没回来。' WHERE `Id` = 69708 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '遵命，陛下！' WHERE `Id` = 69712 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '探险者协会前来报到，陛下！' WHERE `Id` = 69719 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '大量的石头。但这里没有发现大型铁矿。' WHERE `Id` = 69721 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '还有更好的东西。史无前例！一个强大的远古遗物！' WHERE `Id` = 69723 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真的？！噢，我得到了国王陛下批准！真想看看布莱恩知道后的表情！我保证在下次日落前搞定采石场！' WHERE `Id` = 69725 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '陛下！部落躲在西边的一座寺院里。许多暗夜精灵游侠已经包围封锁了那里……' WHERE `Id` = 69741 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那可是历史的瑰宝。' WHERE `Id` = 69744 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我能感到这个……东西散发着强大的黑暗力量。消灭它，马上！' WHERE `Id` = 69759 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '陛下，我们应该好好研究它。把它变成我们的武器。部落在潘达利亚的军力已经超过了我们。我们需要利用一切可能的条件。' WHERE `Id` = 69762 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '加尔鲁什会利用手头的一切武器。难道我们不应该争取公平竞争的机会吗？' WHERE `Id` = 69766 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们必须防止部落侵占潘达利亚……可我们同时还要尽力减少我们造成的伤害。' WHERE `Id` = 69785 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哎哟！
我们要在这里同时对付幽灵和神圣遗物学会？！我再也想不出比这更糟的了！' WHERE `Id` = 69788 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你也是亲爱的瓦里安国王派来请求协助的吗？' WHERE `Id` = 69829 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不用着急，古伊尔。如果沃金相信他的人民正处在危险之中，那你最好尽力帮助他们。' WHERE `Id` = 69845 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的另一边，则是雷电之王的狂热追随者，瓦安！' WHERE `Id` = 69848 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '另一位进入竞技场的是：血角！他会用你的鲜血染红他的角！' WHERE `Id` = 69849 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们还要欢迎广受痛苦爱好者追捧的：地下城主韦沙斯！' WHERE `Id` = 69850 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿嘿！请看我们今日为大家带来的……布拉特！' WHERE `Id` = 69851 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '五对一看来似乎不太公平，可拜托……那只是一群半死不活的侏儒而已。欢迎我们的麻风侏儒五人组！' WHERE `Id` = 69852 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '同时进场的还有——巴特隆！当然，他不是由地精制造的……可他依然有着致命的威胁！' WHERE `Id` = 69853 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '另一边进场的是……嘿，看呐！那是我的好兄弟，法兰！他还带来了他的坐骑！' WHERE `Id` = 69854 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们还要欢迎人见人爱的白色小伙伴：帝皮！' WHERE `Id` = 69855 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们在希利苏斯的法阵里发现了这个钻洞的家伙。当时他已经被人打得半死。他就是，伊克西！' WHERE `Id` = 69856 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '同时进场的还有——位元毁灭者……以及他那滑稽的侏儒全息投影仪！' WHERE `Id` = 69857 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再看这边！他怒气冲冲。他所向披靡。他还有点小可爱。他就是来自不息山的压路者！' WHERE `Id` = 69858 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没错，她穿着裙子，她的脚关节还是反着长的，可她照样能痛扁你一顿。她就是多米尼卡！' WHERE `Id` = 69859 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '下面这位，或许是我见过的最无能、最丑陋、最没天分的拳手。它就是又笨又臭的侏儒，米莉·沃特！大家来点嘘声吧！' WHERE `Id` = 69860 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们在索拉查盆地花了数天功夫才找到这家伙。欢迎来到丛林！他就是，玛扎伦！' WHERE `Id` = 69861 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们中的一些老兵或许还记得这家伙。没错，他是有点支离破碎的，可他也能砸扁你！他就是，阿卡玛！' WHERE `Id` = 69862 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '同时进场的还有——大家最喜爱的、12英尺高的神奇僵尸，弗琼！我没读错吧？' WHERE `Id` = 69863 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '呃！又是侏儒？这一位似乎是自称米尔豪斯·法力风暴。快来干掉他吧！' WHERE `Id` = 69864 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们在奥金顿找到了这位在风暴中嚎叫的家伙。大家鼓掌欢迎——伊坎·伊祖！' WHERE `Id` = 69865 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '大家一起来跳舞吧！迪肯来啦！' WHERE `Id` = 69866 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们还要欢迎来自雷霆崖的恐怖牛头人——斯马什·重蹄！' WHERE `Id` = 69867 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '另一边进场的是，长着无数眼睛的兹恩沙尔！下次还会有什么呢，一个会打架的鼻子吗？' WHERE `Id` = 69868 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们的搭档完全是一个意外。事实上我对此颇为厌恶。他们就是，GG工程公司组合！' WHERE `Id` = 69869 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '同时进场的还有：黑暗召唤师。哇，他连真名都没有。真恐怖！' WHERE `Id` = 69870 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '接下来，正是我们最喜闻乐见的场面！拜托，再多来几条恐龙吧！有请，库拉卡大王！' WHERE `Id` = 69871 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嗯。接下来这位是名符其实的工程学杰作。下面是，干涉者时间！' WHERE `Id` = 69872 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈哈哈！你可真够倒霉的！是普罗波库斯！啊哈哈哈！我敢出25个金币打赌，你肯定会被烧死的！' WHERE `Id` = 69873 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '各位，请安静……我们可不想激怒它。请屏息静气地欢迎我们的杀人鹿，乌古洛克斯！' WHERE `Id` = 69874 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '怎么了，$n？不敢动手了吗？来吧，让竞技场沸腾起来吧！' WHERE `Id` = 69884 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没有什么是永恒的，$p。' WHERE `Id` = 69905 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这不是我的战斗，$p。' WHERE `Id` = 69907 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好，$p。向我证明你自己，然后我才会帮你作战。' WHERE `Id` = 69909 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我现在没空管这些，$p。别来打扰我。' WHERE `Id` = 69911 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '放马过来吧，$p！' WHERE `Id` = 69912 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '遵命，摄政王。' WHERE `Id` = 70005 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '精彩的战斗，$p，你证明了你的力量。' WHERE `Id` = 70034 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '褐石大师和他的那些手下因为时常在工作中偷懒睡觉而臭名昭著。' WHERE `Id` = 70041 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我得确保那些懒鬼有在好好干活儿并且把那段防御工事给造起来。' WHERE `Id` = 70042 AND `Locale` = 'zhCN';
