UPDATE `broadcast_text_locale` SET `Text_lang` = '这可是个重大发现！' WHERE `Id` = 70047 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的身体归于大地……' WHERE `Id` = 70050 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '去告诉其他人，林木有刺！' WHERE `Id` = 70051 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '帮我喂饱它们吧。' WHERE `Id` = 70052 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小心，部落又来了！' WHERE `Id` = 70055 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我从没想过这一天会真的到来！竟然是达纳苏斯的女勇士！快用力拍你的手，把最热烈的掌声献给莉安娜·地风！' WHERE `Id` = 70056 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '另一位是……肉弹！' WHERE `Id` = 70057 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好了，褐石，该干活儿了！' WHERE `Id` = 70062 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，我认识你！你以前在竞技场里比试过！你这是又回来参赛了？' WHERE `Id` = 70101 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欢迎回来，斗士。准备好比赛了？' WHERE `Id` = 70102 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，$g老大:甜心;。你想要打一场吗？' WHERE `Id` = 70103 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '欲罢不能，对吧？' WHERE `Id` = 70104 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '瞧瞧，瞧瞧……有大人物回来参赛了！' WHERE `Id` = 70105 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$n！我能为你效劳吗？' WHERE `Id` = 70106 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这不是拳手$n本人吗？你又来欺负我的怪物了？' WHERE `Id` = 70107 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这儿是不是热起来了？' WHERE `Id` = 70130 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘘，伙计们！得赶快了！' WHERE `Id` = 70131 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '动起来！快一点！' WHERE `Id` = 70132 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '时间就要到了！' WHERE `Id` = 70133 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊呃……我闻到烟的味道了……' WHERE `Id` = 70134 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '火要烧起来了！' WHERE `Id` = 70135 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，好吧，有观众离场了，你懂的。' WHERE `Id` = 70136 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我觉得吧，这场无聊的闷战我们已经看够了。对吧？' WHERE `Id` = 70137 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '瓦里安把你也派来了？好吧，我都快在自己的城市里被你们包围了！$b$b<吉安娜佯装生气地眨了眨眼睛。>$b$b让我们换个方法来讨论这件事。假设你正处于我的立场，想象一下，你就是肯瑞托的领袖。$p！艾泽拉斯最有影响力的大法师！$b$b你会怎么做？' WHERE `Id` = 70169 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哈，不愧是忠实可靠的联盟$c！相信我，我理解这种情绪。$b$b接下来，作为肯瑞托的领袖，与此同时还是忠实的联盟成员，你会如何处置夺日者？诚然，他们是部落的支持者，但在过去的两千年中，他们也是肯瑞托的重要成员。这座城市也是他们的家园。$b$b你会驱逐他们吗？' WHERE `Id` = 70172 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<吉安娜的眼神有些悲伤。>$b$b所以说……你要肃清这座城市？你要把夺日者，那些曾经帮助人类洞悉魔法奥秘的人，赶出他们自己的家园？$b$b显然，你我持有不同的观点。我很明白我应该扮演的角色——以及肯瑞托的任务——和你的希望有所不同。我的心意已决。你想听听我的想法吗？' WHERE `Id` = 70174 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<吉安娜轻轻拨弄着眼前的一缕金发，陷入了沉思。>$b$b你对你们的事业无比热忱，并且意志坚定。但相信我，夺日者和你是一样的。部落是他们的家人。$b$b并不是所有的部落都支持加尔鲁什，但他们不会抛弃自己的人民……我不能驱逐他们，这样会让肯瑞托分裂。$b$b对我来说，肯瑞托是一个神圣的词。我们必须团结一致。' WHERE `Id` = 70178 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<吉安娜露出了微笑。>$b$b要是我们能够分享你的力量和信念就好了！老实说。我每一天都在挣扎。每一天。$b$b但你说的没错，肯瑞托高于你我，高于联盟。我有责任去维持肯瑞托的舷窗，并且明智地使用它的力量。$b$b看上去，你我能达成共识，但我怀疑暴风城国王是否也能认同这一点。不过……你觉得我们能说服安度因吗？' WHERE `Id` = 70180 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊！真是个勇敢的决定，特别是在现在这样的时代。你的诚实令人耳目一新！$b$b告诉我，肯瑞托的领袖，如果部落杀死了你的朋友，夺走了你的家庭，摧毁了你拥有的一切，请问，你是否还能保持你的信念，大法师$p？' WHERE `Id` = 70181 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<吉安娜的语气立马变得热情起来。>$b$b你我有同样的灵魂！感谢你，$p，感谢你的诚实。你似乎能理解我的挣扎。没错，我每一天都在挣扎，这是艰难的决定。每个夜晚都是梦魇……$b$b但我有责任维持肯瑞托的现状。我很高兴，你和我持有同样的观点。但暴风城国王一定不会这样想。你觉得我们能和安度因解释吗？' WHERE `Id` = 70182 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘘！你会让我的伪装暴露的！' WHERE `Id` = 70199 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '最好不要把坏的一面暴露给那些帮你准备食物的人。但这位老主顾似乎完全没有好的一面……' WHERE `Id` = 70222 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '都说眼睛是灵魂的窗口。如果这是真的，那我猜这位客人还有他的灵魂都藏起来了。' WHERE `Id` = 70223 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这位客人穿戴有爱人的遗物。看来人们说的没错：每一段爱情都有荆棘，正如每个夜晚都会迎来黎明。' WHERE `Id` = 70224 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我怎么可能会点这个？！' WHERE `Id` = 70234 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你怎么敢这样！' WHERE `Id` = 70235 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你以为你是谁？！胆子好大！' WHERE `Id` = 70236 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '终于来了！我还以为我的酒压根不会送来了！' WHERE `Id` = 70237 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当然，这就是我点的！这种酒其实是我发明的！' WHERE `Id` = 70238 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那还能是谁点的？你那滑稽的表情是怎么回事？你看起来就像是我会揍你一样！' WHERE `Id` = 70239 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '趁我还没向你吐口水赶紧滚出去！' WHERE `Id` = 70246 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真是大胆！' WHERE `Id` = 70247 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你看看我这样子像是会点这种东西的人吗？' WHERE `Id` = 70248 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别搞笑了。这当然是我的酒！' WHERE `Id` = 70249 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我就在想，你和我的酒差不多该出现了！' WHERE `Id` = 70250 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你还真是够快的！' WHERE `Id` = 70251 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '难道妹子就不能顺顺利利地拿到自己的酒？' WHERE `Id` = 70252 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有时候看着其他人以命相搏真是令我感动！' WHERE `Id` = 70253 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我能要点喝的吗？' WHERE `Id` = 70255 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '肯瑞托向来不乏滥用力量之徒。克尔苏加德把魔法知识用在了死灵法术上。' WHERE `Id` = 70258 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们把他们堵在了寺院里。应该立刻进攻！' WHERE `Id` = 70299 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那就更该净化它了。' WHERE `Id` = 70300 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你在浪费宝贵的时间。' WHERE `Id` = 70301 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是浪费时间，应该冲进去厮杀！' WHERE `Id` = 70302 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你太犹豫了，瓦里安。如果你想领导联盟，就得果断点。' WHERE `Id` = 70303 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们为什么不直接进攻？' WHERE `Id` = 70304 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们在寺院里嘲弄我们。' WHERE `Id` = 70305 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的工事完成了。' WHERE `Id` = 70306 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '换了我会直接进攻，而我那样冒进的话可能会牺牲更多人。' WHERE `Id` = 70307 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我明白了。请领导我们，陛下。愿它成为一个好的开端。' WHERE `Id` = 70308 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '保持警惕，英雄。这地方封闭了数百年。天知道里面会有什么东西。' WHERE `Id` = 70383 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就是它，英雄！圣钟！' WHERE `Id` = 70384 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那是什么？不管了。谁敢来妨碍我们就打倒他。' WHERE `Id` = 70385 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们必须把它送到安全的地方。哨兵，我们动手吧。' WHERE `Id` = 70386 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '部落。真可惜，你们来晚了。圣钟归我们了。游侠们！出击！' WHERE `Id` = 70387 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊！我的弓箭手应该阻止你的！哨兵！进攻！' WHERE `Id` = 70388 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好。我将亲自对付你。为了联盟！' WHERE `Id` = 70389 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '呃……我的死……不算什么。圣钟已经被送到了达纳苏斯。肮脏的部落……永远得不到它！' WHERE `Id` = 70390 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '天空之子，进攻！' WHERE `Id` = 70391 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你必将死在我的剑下！' WHERE `Id` = 70392 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我从阴影中出击！' WHERE `Id` = 70393 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '安静受死吧，夺日者！' WHERE `Id` = 70400 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '肯瑞托绝不容忍叛乱。' WHERE `Id` = 70401 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是你们自找的，夺日者。' WHERE `Id` = 70402 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你放弃了逃跑的机会。' WHERE `Id` = 70403 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没有你们，达拉然会更好。' WHERE `Id` = 70404 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你们以为自己不用付出代价吗？' WHERE `Id` = 70405 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '肯瑞托在你们心中还不如那个酋长。' WHERE `Id` = 70406 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '瓦里安派我在你建造防御工事的时候留意寺庙附近的情况。
耐心一点，除非瓦里安下达命令，否则不要靠近寺庙。' WHERE `Id` = 70423 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，朋友。' WHERE `Id` = 70424 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来吧孩子们。愿艾露恩指引我们今日的行动。' WHERE `Id` = 70427 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在寺庙西边和我们碰头，$rt。我们需要你的帮助。' WHERE `Id` = 70429 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来吧，姑娘们。这是你们今天的肉。' WHERE `Id` = 70559 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '吉安娜靠武力夺走了我的家园？我会记住这一切的……' WHERE `Id` = 70563 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，$n。' WHERE `Id` = 70566 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哎呦！今天我真是激动死了。就刚才我从那堆火里炼了八块铁。' WHERE `Id` = 70575 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '希尔达把所有的文件都给我了。你知道吗，我们每找到一个神器，我就要填六份表格！我想知道，这些该死的文件到底有什么用！？' WHERE `Id` = 70576 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好像嫌我手头的麻烦事儿还不够多似的，那帮矿洞里的矮人最近迷上了一种叫咔啡的新饮料。$B$B他们一定要让我每天早上给他们带去新鲜的咔啡！$B$B他们知道我应该上哪儿去弄那些咔啡豆吗？行行好吧！' WHERE `Id` = 70577 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我在执行行政管理的时候得穿上漂亮的短裤，但是其他的呢？能来点儿有新意的吗？' WHERE `Id` = 70578 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦天呐，是你吗？你一定就是那个每个人都在谈论的英雄。' WHERE `Id` = 70579 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '喔，在这种东西上飞行，你们是怎么做到的？圣光在上！你们这小手艺可太拉风了！' WHERE `Id` = 70580 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '抱歉，我在这儿还有点事情要做。' WHERE `Id` = 70581 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我姐姐希尔达告诉我你会来。' WHERE `Id` = 70582 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '她不让我下挖掘场，所以我就成了私人助理和司机。' WHERE `Id` = 70583 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不管怎样，我遇到了那个退役的军情七处特工。' WHERE `Id` = 70584 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '特工康奈利，对不？那个男的很有魅力……还很有胆量！他的甜言蜜语让我的脸羞得比铁炉堡的铁砧还红！' WHERE `Id` = 70585 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他现在正在任务现场等着你。' WHERE `Id` = 70586 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不过我们的目的地离一个部落营地很近，所以你一定要多加小心。' WHERE `Id` = 70587 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '代范妮向康奈利问好！' WHERE `Id` = 70588 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你想要去达拉然？我听说吉安娜·普罗德摩尔正想见你！这条路直走，穿过那个法师传送门吧。' WHERE `Id` = 70589 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好吧，我们又见面了。' WHERE `Id` = 70590 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我想你过得还不错？' WHERE `Id` = 70591 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你听说雄师港最近闹得沸沸扬扬的传闻了吗？' WHERE `Id` = 70592 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '听说部落掌握某种远古魔古族神器的信息……一个名叫圣钟的东西。' WHERE `Id` = 70593 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那口钟能够把普通的军队变成杀戮机器！' WHERE `Id` = 70594 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没人知道那个神器被藏在哪里，但是部落正在动用一切力量，想要先下手为强。' WHERE `Id` = 70595 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '神圣遗物学会正在魔古岬努力搜寻这口钟的下落。' WHERE `Id` = 70596 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们可不是没用的笨蛋，一定要打败他们！' WHERE `Id` = 70597 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我只是希尔达的助理，能力有限。但是你能做的有很多。希望你能发现他们的动向。' WHERE `Id` = 70598 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们到了。' WHERE `Id` = 70599 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好好教训那些部落！' WHERE `Id` = 70600 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我将要把你送往七星殿。' WHERE `Id` = 70601 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '年轻的安度因王子正在等你。' WHERE `Id` = 70602 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '探险者协会在魔古岬完成勘探任务之后，他们把发掘出来的东西都带回了锦绣谷的城市里。' WHERE `Id` = 70603 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们正在研究那些被血精灵偷走的古物。' WHERE `Id` = 70604 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '本来这事儿我不应该告诉任何人的，但是你的脸长得就像矮人酒桶这么可爱，一定是个好人，所以我相信你！' WHERE `Id` = 70605 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些魔古族属于一个叫做寇茹的部族。' WHERE `Id` = 70606 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '寇茹部族好像在数千年以前就效忠于雷电之王……比熊猫人统治这片土地更早。' WHERE `Id` = 70607 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们钻研暗影法术，然后……通过某种方法，他们开始能够控制煞能。' WHERE `Id` = 70608 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果寇茹部族真的拥有这种能力，那就不难设想加尔鲁什为何要获得他们的知识了！' WHERE `Id` = 70609 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '想象一下，那个凶狠难缠的加尔鲁什在挥动他的大斧子的时候还能运用煞能，接下来会发生什么。' WHERE `Id` = 70610 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我想到就会发抖。' WHERE `Id` = 70611 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你已经到了。祝你好运！' WHERE `Id` = 70612 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好，今天过得怎样？' WHERE `Id` = 70613 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '自从上次我把你送到之后，我听说一些在七星殿的士兵们被煞能感染了。' WHERE `Id` = 70614 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你和安度因王子不在那儿的话，他们可能就会自相残杀，我们最好的战士们可能就会被他们自己的愤怒击败！' WHERE `Id` = 70615 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我还听说，瓦里安国王发誓不会利用煞能做不光彩的事。' WHERE `Id` = 70616 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但愿他不是因为没吃到葡萄就说葡萄是酸的！我们的国王能有这样的表态就很不错啦。' WHERE `Id` = 70617 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不管怎样，特工康奈利托口信让我送你到昆莱山去见他。' WHERE `Id` = 70618 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '听上去部落就快要找到那口圣钟的地点了，那可不是什么好事。' WHERE `Id` = 70619 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你最好在任务现场和他碰面，看看加尔鲁什在干什么。' WHERE `Id` = 70620 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祝你好运！' WHERE `Id` = 70621 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快上风筝！' WHERE `Id` = 70622 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们没时间可以浪费了。' WHERE `Id` = 70623 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了找到你在那个魔古族记忆里看到的场景，我们找遍了昆莱山，最终，我们发现了那个隐蔽的寇茹部族处所。' WHERE `Id` = 70624 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果我们不能抢先得到那口圣钟，那个坏心眼的疯子加尔鲁什就会把它占为己有。我无法想象控制邪恶煞能的部落打起架来有多厉害。' WHERE `Id` = 70625 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '指挥官天剑已经在挖掘场和一小队探险者协会的考古学家开展工作了。' WHERE `Id` = 70626 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们将派出精英部队，那也包括你。' WHERE `Id` = 70627 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们到了。没时间可以浪费了。' WHERE `Id` = 70628 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祝你好运！' WHERE `Id` = 70629 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我可不会乘着风筝去达拉然！我都不知道吉安娜把那城市飘到哪儿了！你最好使用那边那个传送门。' WHERE `Id` = 70630 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我可不会乘着风筝去达纳苏斯！那东西要飞过山脉都很难，你还指望它飞过整片海域？你最好使用那边那个传送门。' WHERE `Id` = 70631 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿，泰勒上将让我载你一程，把你送到帝皇谷。' WHERE `Id` = 70632 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你真幸运，我是安度因王子手下最能干的姑娘。我们是好朋友，但是可别把这告诉特工康奈利。' WHERE `Id` = 70633 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那个男人肯定会非常嫉妒，而我可不想他为了我和王子闹矛盾。' WHERE `Id` = 70634 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不管怎样，我知道王子躲藏在哪里，我会把你送到他那儿去的。' WHERE `Id` = 70635 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '虽然我不赞成让那个男孩子到处自个儿乱跑，但我能理解他的想法。' WHERE `Id` = 70636 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我还是无法相信，我们在达纳苏斯做好了完全的准备，部落竟然还是偷走了圣钟。' WHERE `Id` = 70637 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '听说吉安娜女士到现在还在对这事儿震惊不已。' WHERE `Id` = 70638 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '她已经准备好原谅部落在塞拉摩的所作所为。' WHERE `Id` = 70639 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '她已经准备好为肯瑞托创造一个崭新的未来，让部落的夺日者和联盟的银色盟约能够在一起和平共处。' WHERE `Id` = 70640 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我亲耳听到她说，达拉然将向世界展示一个部落与联盟和平共处的典范。' WHERE `Id` = 70641 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '然后夺日者竟然背叛了她的信任，在她的城市里直接开启传送门，通往安放那口圣钟的地方！' WHERE `Id` = 70642 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '她当然会感到气愤啦。她当然有权利把那些卑鄙的夺日者赶出达拉然。' WHERE `Id` = 70643 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '然而我仍然不由地觉得部落不会就此善罢甘休。' WHERE `Id` = 70644 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在加尔鲁什已经得到了圣钟。他随时就会对我们发动攻击！' WHERE `Id` = 70645 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '希望安度因心中已有打算。' WHERE `Id` = 70646 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祝你好运。' WHERE `Id` = 70647 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '是你该登场的时候了。末日正在逼近。' WHERE `Id` = 70648 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '加尔鲁什正在昆莱山的北侧扩充他的军队。' WHERE `Id` = 70649 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他将会使用圣钟的力量，如果我们不能及时阻止他，那只能祈求圣光保佑我们了。' WHERE `Id` = 70650 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '安度因已经先走一步了。那个冒冒失失、莽撞性急的小笨蛋！' WHERE `Id` = 70651 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这孩子天真的以为他可以说服部落，拯救世界……可是……他只是个孩子。' WHERE `Id` = 70652 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你要么阻止那孩子，要么就帮帮他……二选一！' WHERE `Id` = 70653 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们正在集结军队来对抗加尔鲁什，但是那需要时间，而王子可能已经身处险境。' WHERE `Id` = 70654 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，为什么这风筝不能飞快点儿呢？' WHERE `Id` = 70655 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快，他们还没发现我们。' WHERE `Id` = 70656 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我回去呼叫援军。' WHERE `Id` = 70657 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '无论今天你成功与否，英雄，你做得一切都是为了联盟。' WHERE `Id` = 70658 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '该我们登场发挥了，把暴风城踩烂吧！' WHERE `Id` = 70664 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这地方已经挤满了！我们应该组起队伍，往瓦里安漂亮的小脸蛋儿上来上几脚！' WHERE `Id` = 70665 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你如此渴望鲜血，为什么不组起队伍，把暴风城砸烂？' WHERE `Id` = 70666 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '传送门就在这儿！穿过这门，告诉他们部落是怎么打架的！' WHERE `Id` = 70667 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我开启了一道通往暴风城的传送门。穿过它，猛踹联盟的屁股！' WHERE `Id` = 70668 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '传送门准备好了！快进去！' WHERE `Id` = 70669 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我早就想和夺日者划清界限了，只是一直在等待这样的机会。我曾向我过世的丈夫提过将他们赶出达拉然，但是他决意要把肯瑞托放在绝对中立的位置。$b$b他是个睿智的人，但是远见不足。肯瑞托的命运就应当如此：效忠联盟。' WHERE `Id` = 70704 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了夺日者！' WHERE `Id` = 70713 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '所以必须做个了断了，对吧？' WHERE `Id` = 70714 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '能请我喝一杯吗？' WHERE `Id` = 70720 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没错，布鲁姆就是我的爱人，我们俩就像是一个豆荚里的两颗豆子，即使他是轻量级选手，我也一样爱他！' WHERE `Id` = 70721 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你有话和我说？没问题，你负责说，我负责喝！' WHERE `Id` = 70722 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你最好别相信我说的任何话。算了，当我没说过。' WHERE `Id` = 70723 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，没错，那些关于我的谣言满天飞，可惜都是假的。什么我小时候是暗月马戏团的吉祥物，五岁生日那天杀了六个恶魔——用的还是一把勺子——我最喜欢这段了。但事实上，我只是个普通的金发姑娘。人们就喜欢相信那些有的没的。' WHERE `Id` = 70724 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我喜欢这个地方。在别的地方，那些人总是叫我“暴力孤僻女”。好吧，其实在这儿他们也这么叫我，不过至少他们是当着我的面，并且面带着微笑地叫这个名字。' WHERE `Id` = 70725 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我总是为血角欢呼。那头愤怒的铲齿鹿看似娇小，却总是能让那些大块头吃尽苦头。' WHERE `Id` = 70729 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '城市生活会改变一名德鲁伊。上周我生平第一次使用了公共飞行路线……感觉真是不错啊。' WHERE `Id` = 70730 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '大多数德鲁伊都很古板，不过我是个例外，我是个真正的聚会动物。我的笑话说完了。你该笑了。' WHERE `Id` = 70731 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，对不起，我不能请你喝酒了。我最近有点小穷，但我相信我会时来运转的。' WHERE `Id` = 70735 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这地方看起来很硬派，但这里的人其实内心里都是软蛋。' WHERE `Id` = 70736 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哦，没错，我刚到奥格瑞玛不久。这不明摆着的吗？' WHERE `Id` = 70737 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你应该排队参加搏击——这样我就能笑上好一阵了。' WHERE `Id` = 70738 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '继续瞪着我。我喜欢尴尬的沉默。' WHERE `Id` = 70739 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '弱者才穿鞋。' WHERE `Id` = 70740 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '上一回我在竞技场里把对手打到边哭边逃。按说对手打架打到一半就逃这不算什么稀奇事儿，但这可是我头一回看到鳄鱼流眼泪。' WHERE `Id` = 70741 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '“娜丽，把这东西举起来！”，他们总是这么冲我嚷嚷。为什么不能说“娜丽，能跳支舞吗？”我可是个伟大的舞者。' WHERE `Id` = 70742 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '斯特林顿公爵就是个渣渣。他吹牛吹得厉害，但连自己的剑都拿不起来。啊，没错，他的名字也是瞎编的，我相信你肯定猜到了。' WHERE `Id` = 70743 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '苏利，快下来！' WHERE `Id` = 70850 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '苏利，我真希望你再掉进那滩泥里！' WHERE `Id` = 70851 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$p，来得正好！我们需要你的帮助！' WHERE `Id` = 70852 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '情况危急，$p。
部落计划夺取在扎尼维斯之心附近的一个螳螂妖武器库。我不知道他们的意图是什么，但我可不会在这儿空等。
我需要你穿过笼罩整座岛屿的护盾，并赶在部落之前拿到那些螳螂妖武器。去驾驶一架旋翼机，现在就出发，前往那座岛屿。当你接近岛屿时我会再发送下一步的命令给你。' WHERE `Id` = 70853 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我从阴影中出击！' WHERE `Id` = 70878 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你必将死在我的剑下！' WHERE `Id` = 70879 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '天空之子，进攻！' WHERE `Id` = 70880 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '整座岛屿都被声波护盾所保护，$p。' WHERE `Id` = 70892 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '根据斥候的报告，这座岛屿上有几部护盾发生器，它们为护盾提供能量。' WHERE `Id` = 70893 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我需要你赶在部落冲垮我们的防线之前摧毁这些发生器。' WHERE `Id` = 70894 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你接近第一座发射塔了！炸掉它！' WHERE `Id` = 70895 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '打得好，$p！护盾的能量在衰退！' WHERE `Id` = 70896 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我这就将下一座发射塔的坐标发送给你。' WHERE `Id` = 70897 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '护盾消失了！赶快前往滩头！' WHERE `Id` = 70898 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阻止那些部落！他们在抢占这座岛屿！' WHERE `Id` = 70899 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '烟雾太浓，空中的视线被阻挡了。
我看不清海滩上的情况，无法狙击。' WHERE `Id` = 70930 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我会掩护你。' WHERE `Id` = 70932 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了治疗这些伤者，我已经尽了全力。能救的我都救了。
我要留下来保护这些受伤的士兵……除非你有更好的计划？' WHERE `Id` = 70933 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '该行动了。' WHERE `Id` = 70942 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你终于来了，$n。什么都不做可赢不了这场战斗！' WHERE `Id` = 70958 AND `Locale` = 'zhCN';
