UPDATE `broadcast_text_locale` SET `Text_lang` = '我们侏儒的新陈代谢很快，$p。别让我们的食物存量见底了！' WHERE `Id` = 71130 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你可以从野生动物身上找到肉，或者从兽人身上找到军粮。我们从不挑剔食物。' WHERE `Id` = 71131 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '嘿$p，如果能帮我们找到足够的金属，我们的工作效率能提高不少。这附近的卡桑利铁矿石就不错。' WHERE `Id` = 71132 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '注意寻找那些油腻的蛇，$p。它们很容易捕捉。把那些蛇油放进大锅里能让我们的工作速度变快。' WHERE `Id` = 71133 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些蜥蜴怪身上可能带有各种各样的东西。别放过他们！' WHERE `Id` = 71134 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为我们提供充分补给能让我们以最高效率工作。' WHERE `Id` = 71135 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '注意我们这边的情况，$p！我们是建造师，不是战士。如果有敌人攻击，我们需要你帮我们防守！' WHERE `Id` = 71136 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '蛇油，卡桑利生铁，还有食物……记得帮我们小组寻找这些有用的物资！' WHERE `Id` = 71137 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你可以为我们提供相同的道具补给来获得额外的特效。尽量保持这些特效，别让它们过期了。' WHERE `Id` = 71138 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '保证我们随时都有足够的补给，$p。别让这些效果过期，否则你又要从头开始了！' WHERE `Id` = 71139 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '进你可能提高你的效率，$p！总有一天，时间会成为决定性的因素……' WHERE `Id` = 71140 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '<静电噪音>请回答，$p，我是空军上将罗杰斯。' WHERE `Id` = 71141 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '情况非常顺利，朋友。感谢你的援助。' WHERE `Id` = 71142 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你的帮助非常重要，$p。我们已经接近完工了，请继续帮助我们。' WHERE `Id` = 71143 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们的资源储量充足，感谢你的帮助。请继续保持如此良好的势态。' WHERE `Id` = 71144 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们已经习惯于使用小精灵来进行体力劳动了。请带一些食物来帮助我们保持动力。' WHERE `Id` = 71146 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们特别不适应把野兽的肉当作食物，但在如今的特殊情形下，我们也只能勉为其难了。' WHERE `Id` = 71147 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '请为我们带一些木材回来，我们可以用来强化基地里的树苗，$p。这片区域里的根茎能够派上用场。' WHERE `Id` = 71148 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '附近的精怪身上携带有灵吻之水，这些水能够滋养我们的树苗。装满一次之后，你就不再需要去补充它们了。' WHERE `Id` = 71150 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不要灰心，朋友。帮我们寻找补给，我们的工作很快就能完成。' WHERE `Id` = 71151 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '帮助我们，$p。我们并不擅长战斗。一旦遭遇攻击，我们需要你来保护我们。' WHERE `Id` = 71154 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '木材，蛇油，食物还有水能够加快我们的进度，$p。请尽你所能帮助我们。' WHERE `Id` = 71156 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为我们的营地提供补给之后，请保持补给品的存量，不要让特效消失。' WHERE `Id` = 71157 AND `Locale` = 'zhCN';
