UPDATE `broadcast_text_locale` SET `Text_lang` = '我们对下方墓地和城镇的持续进攻取得了成效。无论是魔古族还是赞达拉巨魔都已无力反攻了。' WHERE `Id` = 71704 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看到中央那座塔了吗？闪电一直在击打它。我们怀疑这场风暴就源自于宫殿内部。' WHERE `Id` = 71705 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '集合点就在前面。我们已经召集了一支精锐部队——什么？' WHERE `Id` = 71706 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Anar’alah！天空背弃了我们——这里不安全了！' WHERE `Id` = 71707 AND `Locale` = 'zhCN';
