UPDATE `broadcast_text_locale` SET `Text_lang` = '勇士，你还好吧？' WHERE `Id` = 71709 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们一直在等着我们。部队被打散了，我们得靠自己了。' WHERE `Id` = 71710 AND `Locale` = 'zhCN';
