UPDATE `broadcast_text_locale` SET `Text_lang` = '快行动——那可不是普通的赞达拉巨魔！' WHERE `Id` = 71715 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们在保护那个面具。那一定是屏障的源头。摧毁它！' WHERE `Id` = 71716 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快摧毁灵魂面具，解除屏障！' WHERE `Id` = 71717 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他守护着面具。杀了他！' WHERE `Id` = 71718 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '加油，他们开始溃散了！' WHERE `Id` = 71719 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '护盾——消失了！我们成功了！' WHERE `Id` = 71720 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '吉安娜选对了人。你挽救了这个任务……还有我的生命。' WHERE `Id` = 71721 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这就是联盟的精神——勇往直前！' WHERE `Id` = 71722 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '温蕾萨，去建防线。茉德拉，设下真视之眼。纳莱丝，把帐篷和补给运过来。' WHERE `Id` = 71723 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '所有人，各就各位！我们周围都是敌人！千万不能够浪费时间了。' WHERE `Id` = 71724 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '勇士，你的成就已经超出了我的预期。你所表现出的勇气与决心巩固了我们的根基。现在，真正的工作开始了。' WHERE `Id` = 71725 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得好，英雄。我们前进吧。' WHERE `Id` = 71726 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不出我所料。' WHERE `Id` = 71727 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '以肯瑞托之名！' WHERE `Id` = 71728 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我喜欢你的风格，英雄。' WHERE `Id` = 71729 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '令人印象深刻！' WHERE `Id` = 71730 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '起爆器到位了。英雄——这份殊荣属于你。' WHERE `Id` = 71737 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好，你来了。' WHERE `Id` = 71754 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '摄政王阁下！人员已经就位了，影踪派也进去了，可是……' WHERE `Id` = 71755 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '联盟就在庭院的那头等着我们。' WHERE `Id` = 71756 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '雷电之王的宫殿就在前面。在发动进攻前，我们必须在岛上建立一个据点。' WHERE `Id` = 71771 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '摄政王——矿洞那边的赞达拉又冲过来了！' WHERE `Id` = 71772 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些祭司正在对那些侍卫灌注神灵之力！必须阻止他们！' WHERE `Id` = 71784 AND `Locale` = 'zhCN';
