UPDATE `broadcast_text_locale` SET `Text_lang` = '你剥夺了它的力量。现在，取走它的性命吧！' WHERE `Id` = 71788 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些祭司正在对那些侍卫灌注神灵之力！必须阻止他们！' WHERE `Id` = 71793 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '守卫的力量正在增长！快阻止他们！' WHERE `Id` = 71794 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你必须尽快行动！' WHERE `Id` = 71795 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '守卫醒过来了！快摧毁它！' WHERE `Id` = 71796 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你剥夺了它的力量。现在，取走它的性命吧！' WHERE `Id` = 71797 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊！英雄，我们正谈到你呢。' WHERE `Id` = 71808 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果想要打倒雷电之王，我们就必须先攻破船坞。现在应该采取行动了！' WHERE `Id` = 71810 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '勇士，听我说：我们将在夜里，利用你驯服的这头神奇的野兽袭击船坞。' WHERE `Id` = 71811 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '进去之后，我们要破坏赞达拉的船只，并趁着混乱溜进庭院，从内侧打开大门。' WHERE `Id` = 71812 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '好主意！头脑总能胜过蛮力。' WHERE `Id` = 71813 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '谢谢你，祝掌门。我不会让你失望的。' WHERE `Id` = 71815 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '准备好就告诉我一声！' WHERE `Id` = 71816 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我看到六……不，七个守卫在天上巡逻。' WHERE `Id` = 71821 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '有一个比其他人飞得都高……他一直独自在海面上盘旋。他脱队了。这是个机会。' WHERE `Id` = 71822 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们得干掉他，并利用他的航线。动手！' WHERE `Id` = 71823 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再靠近一点……' WHERE `Id` = 71824 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '呀！' WHERE `Id` = 71825 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '赞达拉比我预想得还要警觉。看下面——全是巡逻兵。' WHERE `Id` = 71826 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '那些弓箭手密切监视着港区。' WHERE `Id` = 71827 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们的萨满用岗哨图腾拉起了一张警戒网。' WHERE `Id` = 71828 AND `Locale` = 'zhCN';
