UPDATE `broadcast_text_locale` SET `Text_lang` = '我们得破坏对着船头的攻城武器，然后到甲板下面去找船长。' WHERE `Id` = 71836 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '放松点……靠过去，放倒他们。' WHERE `Id` = 71837 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我来对付那个丑八怪。' WHERE `Id` = 71838 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没我想得那么安静，但还是成功了。' WHERE `Id` = 71839 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '巨魔一旦触发它们，就会得到一个意想不到的惊喜。我们继续。' WHERE `Id` = 71840 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '庭院的大门就在那座山上。' WHERE `Id` = 71847 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '记住，躲开那些岗哨图腾。' WHERE `Id` = 71848 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们走。' WHERE `Id` = 71849 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '等等……' WHERE `Id` = 71850 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '走！' WHERE `Id` = 71851 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们好像发现那个小礼物了。' WHERE `Id` = 71852 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '过来！到烟雾里来！' WHERE `Id` = 71853 AND `Locale` = 'zhCN';
