UPDATE `broadcast_text_locale` SET `Text_lang` = '我同伴出色的战斗技巧已经迅速在影踪派中传开了。' WHERE `Id` = 71869 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '确实如此。我们送你们回去吧。多亏你们，雷神现在已经四面楚歌了。' WHERE `Id` = 71870 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '游侠们——破坏铰链。把门打开！' WHERE `Id` = 71871 AND `Locale` = 'zhCN';
