UPDATE `broadcast_text_locale` SET `Text_lang` = '摄政王一定想听听完整的报告。我们送你回去吧——你该休息了。' WHERE `Id` = 71873 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你相信吗？当我着手研究掩盖体味的魔法时，还受过嘲笑。大法师们都觉得我的研究不切实际，而且浪费时间。$b$b看看，现在站在魔暴龙的上风口笑的人又是谁？哈！' WHERE `Id` = 71874 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真可惜，我只能掩盖我们自己的气味，却没办法驱散赞达拉巨魔和他们那些畜生身上的恶臭。' WHERE `Id` = 71875 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我向来不喜欢野外工作，尤其是牵涉到一大群巨魔的工作。' WHERE `Id` = 71876 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '%s开始治疗她的姐妹！' WHERE `Id` = 71884 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阴影将成为我们的盟友。' WHERE `Id` = 71893 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你总在我们最需要的时候出现，英雄。该去踢开雷电之王的前门了。' WHERE `Id` = 71902 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '做好出击的准备后，请告诉我一声！' WHERE `Id` = 71903 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好，你来了。' WHERE `Id` = 71904 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '普罗德摩尔女士！人员已经就位，影踪派也进去了，但是……' WHERE `Id` = 71905 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可是什么？' WHERE `Id` = 71906 AND `Locale` = 'zhCN';
