UPDATE `broadcast_text_locale` SET `Text_lang` = '他们当然会来。一个个来，温蕾萨。' WHERE `Id` = 71908 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '全体前进！' WHERE `Id` = 71909 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '……如果有谁遇到艾萨斯·夺日者这个叛徒，记得把他留给我……' WHERE `Id` = 71910 AND `Locale` = 'zhCN';
