UPDATE `broadcast_text_locale` SET `Text_lang` = '普罗德摩尔女士——码头上的赞达拉巨魔又冲过来了。' WHERE `Id` = 71912 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们想袭击我们的侧翼。守住这里！' WHERE `Id` = 71913 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祝掌门！联盟——部落——这里马上就要乱作一团了！' WHERE `Id` = 71920 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '掌门……你伤得很重！' WHERE `Id` = 71923 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '交出大法师，这样，我或许还能放你一条生路，洛瑟玛。' WHERE `Id` = 71925 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你所谓的同胞都是些战俘。他们居然敢在我的城市里策划袭击了达纳苏斯——' WHERE `Id` = 71927 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们破坏了我们每一次的和平努力！' WHERE `Id` = 71933 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '吉安娜深吸了一口气。' WHERE `Id` = 71937 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阁下！' WHERE `Id` = 71940 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好。我们可以撤退。' WHERE `Id` = 71942 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们杀了我丈夫！' WHERE `Id` = 71943 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这也不能让他活过来。' WHERE `Id` = 71944 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但记住，“血”精灵：只要地狱咆哮还是部落酋长，我们就谈不上和平。' WHERE `Id` = 71945 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '吉安娜的表情柔和了下来。' WHERE `Id` = 71947 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '阁下。' WHERE `Id` = 71948 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '大家回营地休整。我们的任务完成了。' WHERE `Id` = 71951 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '祝掌门！' WHERE `Id` = 71952 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们得送你回禅院。' WHERE `Id` = 71954 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '雅丽亚，保护祝掌门。' WHERE `Id` = 71956 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '英雄，击败暴风领主纳拉克就靠你了。你得集结一支小部队。' WHERE `Id` = 71957 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但以我今天的所见所闻，我对你有信心。' WHERE `Id` = 71958 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '与你并肩作战是莫大的荣幸。谢谢你。' WHERE `Id` = 71959 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我相信你，英雄。将我的法杖放到雷电之王的平台上，它会搞定一切。敢接受这个任务的都是勇士。祝你好运！' WHERE `Id` = 71960 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你成功了！不可思议！熊猫人游学者会传颂你的事迹的！' WHERE `Id` = 71961 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我感觉……雷电之王的力量在我的法杖中流过。' WHERE `Id` = 71962 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '尤其是，你彻底破坏了雷电之王的恐怖机器，没有让部落将它们据为己有。' WHERE `Id` = 71963 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果有机会的话，我会用这根法杖炸毁奥格瑞玛的城墙，让它砸到加尔鲁什·地狱咆哮的头上。' WHERE `Id` = 71964 AND `Locale` = 'zhCN';
