UPDATE `broadcast_text_locale` SET `Text_lang` = '这边——赞达拉撤退了！' WHERE `Id` = 72718 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '快进去！注意那些牧师——他们正在强化其他人！' WHERE `Id` = 72719 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '圣光在上——他们做了什么？' WHERE `Id` = 72720 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我受伤了——别后退。' WHERE `Id` = 72721 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '杀了那家伙！' WHERE `Id` = 72722 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '它死了！你激励了我们的士气！' WHERE `Id` = 72729 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没什么。我很好。' WHERE `Id` = 72732 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了部落！！' WHERE `Id` = 72735 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我受伤了！别管我——去干掉它！' WHERE `Id` = 72736 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '蜥蜴人让我很感兴趣。$b$b他们是怎么在明显占优的敌人的阴影下存活了那么长时间的？' WHERE `Id` = 72751 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我是来处理邪刃蜥蜴人造成的疾病和瘟疫的。$b$b虽然我从没见过这种瘟疫，但它们肯定有一些相似之处。' WHERE `Id` = 72752 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '虽然我们的目标是消灭魔古族，但也不能忽略我们的侧翼。$b$b虽然部落和蜥蜴人都在与我们一同攻击魔古族，但这两者随时都有可能对我们倒戈相向。' WHERE `Id` = 72756 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '蜥蜴人很卑劣，但他们或许还有用处。$b$b如果我们能煽动他们反抗魔古族，或许就能把他们的注意力从我们的人身上移开。' WHERE `Id` = 72758 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '让我们快点搞定这件事，好早点回家去。' WHERE `Id` = 72761 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '打得好，$r。' WHERE `Id` = 72762 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很高兴你能来！普罗德摩尔急需援军。你准备好出发了吗？' WHERE `Id` = 72763 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '熊猫人对“雷电之王”的归来深感不安。可我更担心部落的威胁。我们飞行途中再谈。' WHERE `Id` = 72764 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '一万两千多年前，“雷电之王”雷神建立了古老的魔古帝国。' WHERE `Id` = 72765 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他统一魔古族，征服了其他熊猫人种族，并建立起了延续数千年的帝国。' WHERE `Id` = 72766 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '传说雷神拥有强大的力量，他为自己建造了一座宏伟的堡垒。我们应该很快就能看见了……' WHERE `Id` = 72767 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '就是那里！传说中的雷神岛。部落已经像饥饿的猛禽一样包围了它。' WHERE `Id` = 72768 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果不能打败雷电之王，潘达利亚就会遭殃。可是如果让部落得到他的力量，那全世界都得付出代价。' WHERE `Id` = 72769 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哇——小心！我们要着陆了。这里简直没法飞行！' WHERE `Id` = 72770 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '吉安娜·普罗德摩尔女士希望尽快见到你。' WHERE `Id` = 72771 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这真是我这辈子最糟糕的一年：塞拉摩被摧毁了。肯瑞托又出了叛徒。' WHERE `Id` = 72772 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '多么深刻的教训。以后，我要先发制人。' WHERE `Id` = 72773 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在下面的海岸上，部落正在寻找驻扎地点。' WHERE `Id` = 72774 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他们也想打败雷电之王，但不是为了保护潘达利亚，而是想攫取他的力量。' WHERE `Id` = 72775 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '可这次，我们领先了一步。' WHERE `Id` = 72776 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '部落休想在这片海滩上占得便宜。等雷神被击败后，熊猫人就会明白，在紧急关头，是联盟的英雄与他们并肩作战。' WHERE `Id` = 72777 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这场战斗需要倾力而为。但愿你做好了准备。' WHERE `Id` = 72778 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你来了！摄政王特地问起了你。你准备好出发了吗？' WHERE `Id` = 72780 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '熊猫人的传说中提到过“雷电之王”雷神。他是一万两千多年前魔古帝国的野蛮创立者。' WHERE `Id` = 72781 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他统一魔古族，击败了其他熊猫人种族，并靠他征服的奴隶建立起了辉煌的帝国。' WHERE `Id` = 72782 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他在帝国边境上建立了一座宏伟的要塞。我们很快就能看见了……' WHERE `Id` = 72783 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看！就在前面：雷神岛。' WHERE `Id` = 72785 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '熊猫人害怕这位前皇帝会试图重建他的帝国，并再次奴役他们。' WHERE `Id` = 72786 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '而我们自有协助他们的理由。还是让洛瑟玛来解释吧。' WHERE `Id` = 72787 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊！小心——我们简直没法飞近这座岛！' WHERE `Id` = 72788 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '记得去跟摄政王谈谈。他就在船头等你。' WHERE `Id` = 72789 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不能再浪费时间了。在我们说话的时候，联盟正在雷神岛上不停推进呢！' WHERE `Id` = 72832 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不能再浪费时间了。在我们说话的时候，部落正在雷神岛上不停推进呢！' WHERE `Id` = 72834 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '魔古族和赞达拉正在将新一批的宝藏从雷神的陵寝运往他的王座。我们必须在他的部队抵达前快速出击，尽力多抢一些宝藏。你的时间有限，我们会准时把你拉出来，所以你得注意效率，$n。
我们只有一次机会，所以好好珍惜吧。
你准备好之后，就把钥匙给我，我来打开大门。' WHERE `Id` = 72877 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '在里面找到什么好东西了吗？' WHERE `Id` = 72881 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '雷神归来才没多久，就在麾下聚集起了这么多盟友，这可真叫人沮丧。我们得趁他不在时多消灭一些。' WHERE `Id` = 72883 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这座岛上到处都是敌人，新老都有。如果没有流血牺牲的觉悟，我们是无法在这里立足的。' WHERE `Id` = 72884 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的船经过一番斗争才得以靠上这片海岸。我一定会让他们为她船体上的每一条伤疤付出代价的。' WHERE `Id` = 72885 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我很乐意帮忙！' WHERE `Id` = 72969 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '爸爸说，不要跟陌生人说话。' WHERE `Id` = 72970 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我可以一直数到“九——十”哦。听好了！$B$B<米莉开始掰手指头和脚趾头。>$B$B一，二，三，五，六，嗯……七，八，九——十！$B$B等等，我漏了一个……' WHERE `Id` = 72971 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别把种子塞进鼻子了。爸爸会很生气的！' WHERE `Id` = 72972 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我喜欢海龟。' WHERE `Id` = 72973 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '数数最好玩了！' WHERE `Id` = 72974 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '干得好，时间刚刚好。我们发现了一把钥匙，应该能打开其中一个箱子。现在它归你了。' WHERE `Id` = 72982 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们差点就没法把你拉出来了。你真是走运，居然还活着。' WHERE `Id` = 72983 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '雷电之王的宫殿就在前面。在发动进攻前，我们必须在岛上建立一个据点。' WHERE `Id` = 72993 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊！坚持住！' WHERE `Id` = 72994 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他代表着一切正直、正义以及其他的无聊品质。他就是德莱尼圣骑士，阿霍鲁！' WHERE `Id` = 73075 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '各位，快拿出你们的铲子吧！明格斯·迪格斯将给我们上一堂考古课！' WHERE `Id` = 73076 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '喔哟哟……看看是谁大摇大摆地回来了。它就是肿着嘴的大鸟，帝皮！这次，它不是一只鸟在战斗！' WHERE `Id` = 73077 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '遵命，长官！' WHERE `Id` = 73084 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我正在装填最后一批炸药，长官！' WHERE `Id` = 73090 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '炸药装填完毕，你们准备好之后，就赶紧按下引爆装置吧！' WHERE `Id` = 73091 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '同时进场的还有：豪爽的布姆布姆大师！就是那位扔炸药的猢狲武僧！' WHERE `Id` = 73111 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你在看什么呢，小鬼？该干活儿了！' WHERE `Id` = 73120 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '休想煮了我，你这愚蠢的巨魔！' WHERE `Id` = 73124 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '尝尝这个，你这蓝皮巫婆！' WHERE `Id` = 73125 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '想烤了我吗，你这暴牙狗？！我会好好教训你的！' WHERE `Id` = 73126 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这上面的视线确实更好，而且还不会被血溅到。' WHERE `Id` = 73133 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我总会为机器人们欢呼。' WHERE `Id` = 73134 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你刚才说话了吗？抱歉，每次有人被干掉时，我总会兴奋过头，从而忘了听别人说话。' WHERE `Id` = 73135 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '什么？死亡骑士就不能偶尔打扮一下吗？' WHERE `Id` = 73139 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '真不敢相信，我居然跟她撞衫了。真是太尴尬了。' WHERE `Id` = 73140 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你要敢再那么看我一眼，我就把你从船上推下去。' WHERE `Id` = 73141 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$g嘿，帅哥。比赛结束后去别处坐坐怎么样？就我们俩？:滚开，烂货。我正想搞搞气氛呢，都被你搞砸了。;' WHERE `Id` = 73145 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我已经戴够拳手戒指了。最近，我正想找个别的戒指戴戴。' WHERE `Id` = 73146 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '$g嘿，陌生人。我随时都可以跟你打一场。而且我保证，战斗不会超过2分钟。
<希尔加魅惑地眨了眨眼。>:我看到你对那边的哈尔抛媚眼了。那个牛头人是我的。
你干嘛不顶着你那张拜金的丑脸到其他飞艇上去？;' WHERE `Id` = 73147 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你好啊，$pr$pc$p' WHERE `Id` = 73190 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '闪光岭。我知道霜鬃巨魔就窝在那片白雪皑皑的山头上。' WHERE `Id` = 73200 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这场风暴害我们损失了许多巡山人，这可能是巨魔在搞鬼。' WHERE `Id` = 73201 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没错。我真不想派人过去，那儿净是埋伏和腐臭。' WHERE `Id` = 73202 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果他们能阻止风暴，我就亲自率领熔炉卫士上去。' WHERE `Id` = 73203 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我也要多谢你，瓦里安。你在大厅上的话很有道理……' WHERE `Id` = 73204 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没错。有了这些勇士的协助，黑铁矮人就能终结赞达拉对丹莫罗的威胁。' WHERE `Id` = 73205 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们回头见，暴风城国王。' WHERE `Id` = 73206 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '此时此地，我们将用自己的鲜血向议会、铁炉堡和联盟证明自己的忠诚。' WHERE `Id` = 73211 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '三锤议会的内讧必须终止。' WHERE `Id` = 73212 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不管是什么邪恶力量引来了这场风暴，快去阻止它吧。这样，熔炉卫士就能攻上山头，并扫清那里的霜鬃和赞达拉巨魔。$B$B去找我的巡山人，或者任何被巨魔俘虏的人，他们能为你指路。' WHERE `Id` = 73213 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢，刚才好险呐，多谢了！' WHERE `Id` = 73254 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '幸存者很少；没被吃掉的人都被杀死在西北边的祭坛上。' WHERE `Id` = 73255 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '如果你们动作快，或许能救下几个！抱歉，我就知道这么多……' WHERE `Id` = 73256 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '训练服务已经暂停。你想学习烹饪？去别处学吧。' WHERE `Id` = 73259 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不，现在不行。' WHERE `Id` = 73260 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我这里没有房间了，$n。我的旅馆已经被库卡隆征用，成为临时兵营了。' WHERE `Id` = 73264 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '今天不举行拍卖，$r。以目前的局势看，拍卖恐怕要暂停一阵了。' WHERE `Id` = 73266 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你最好去别处做生意吧，$r。我可不想惹麻烦。' WHERE `Id` = 73267 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '今天不卖东西。太危险了。' WHERE `Id` = 73268 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我今天不卖东西。' WHERE `Id` = 73270 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '抱歉，$c。我这里没有你要的东西。' WHERE `Id` = 73273 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '传送门都关闭了。我听说兽人在暗影裂口下还保留了一座通往诅咒之地的传送门。' WHERE `Id` = 73283 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这些都是从锦绣谷的挖掘场运来的。加尔鲁什到底想在那里找什么？' WHERE `Id` = 73450 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '国王的勇士们成功了：风暴停止了！前进，黑铁矮人！向着战场前进！' WHERE `Id` = 73458 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '为了铁炉堡！为了联盟！' WHERE `Id` = 73459 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '以烈焰为心，钢铁为志！站起来吧！消灭他们！' WHERE `Id` = 73460 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '确实如此，瓦里安国王。我还想说，愿为联盟效劳。' WHERE `Id` = 73464 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '还是庆幸他们不用派族人来这里送死吧。我们只想守护家园，表达忠诚而已。' WHERE `Id` = 73465 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '废止？！' WHERE `Id` = 73642 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '见鬼，你要池塘小马干什么？' WHERE `Id` = 73645 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '酋长会生气的。他把宝贵的军队都拿来抵御那些可悲的起义军了。' WHERE `Id` = 73652 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我没想到会有这么多军队……' WHERE `Id` = 73653 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我以前也卷入过不少麻烦，但这也太荒唐了！' WHERE `Id` = 73654 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们只要专心执行任务就好，肯定能够全身而退的。' WHERE `Id` = 73655 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '钟摆？！醒醒！' WHERE `Id` = 73667 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他快死了，需要马上送医！' WHERE `Id` = 73675 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你最近有找到什么稀有卡牌吗？把它们带给我，我可以把它们加入我的藏品里去。' WHERE `Id` = 73713 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '接下来这位，他无需刀剑与魔法就能打败敌人。我们的下一个挑战者，海克索斯，使用强大的几何之力克敌制胜的战士！' WHERE `Id` = 73715 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '虽然他就像是一只大公鸡，但他仍然要奋勇战斗。他就是，泰森·山德士！' WHERE `Id` = 73716 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他有两种模式，每一种都被贴上了“屠夫”的标签。让我们欢迎，T440！' WHERE `Id` = 73717 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但愿大家都喜欢自己的拳手特脆饼干！现在进场的是，硬煤！！' WHERE `Id` = 73718 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '还有什么能比一场大爆炸更刺激呢？那当然是，很多很多大爆炸！这边进场的是，大型雷震天！！' WHERE `Id` = 73719 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '噢……看看这条可爱的小蛇，噬人蛇！上啊，让它咬一口你的脚趾。让我们看看会发生什么事。' WHERE `Id` = 73720 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他不是真正的医生，但他将要给他的下一个对手做点整容手术。让我们欢迎，铁拳医师！' WHERE `Id` = 73721 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '擦亮你的幸运符吧，你会用得上它的。接下来进场的是，老爹土笛子！' WHERE `Id` = 73722 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '接下来这对挑战者难以用语言来形容。就请大家自己好好欣赏吧，巨熊与淑女！' WHERE `Id` = 73723 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '扔掉你的武器，拿起拳套吧。接下来将有一场精彩的传统拳击赛。做好被泰塔尔击倒的准备吧！' WHERE `Id` = 73724 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他可能是我们搏击俱乐部有史以来最危险的拳手。遗憾的是，他的元素好像有点不够用了。请大家举杯欢迎，锋齿！' WHERE `Id` = 73725 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '搏击俱乐部的老手们可能还记得那个能自我复制的软泥怪，布拉特。今天，我们将迎来他这位更卑鄙、更丑陋的姐姐：斯普拉特！' WHERE `Id` = 73726 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这是谁啊？布鲁斯回来了！一个更好、更快、更强的布鲁斯！他就是，机甲布鲁斯！！！' WHERE `Id` = 73727 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他是一位战略大师，他甚至都没有脑袋，也没有肘子。他就是，猜拳手！让我们为他拍拍手吧！' WHERE `Id` = 73728 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '想知道我们是怎么处理报废机器人的吗？当然是把他们送到血腥的竞技场来送死了！现在进场的是，布林顿3000！' WHERE `Id` = 73729 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '他从未见过战胜不了的对手。啊，小小地纠正一下：应该说，他从未见过对手。他就是，盲眼英雄！' WHERE `Id` = 73730 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '啊，巨龙之子和他的英雄。你们俩必将成就伟大的事业。' WHERE `Id` = 73748 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '告诉我，巨龙之子：什么是智慧？' WHERE `Id` = 73749 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这口气真像巨龙的后裔。总想着改变世界。' WHERE `Id` = 73750 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但真正的智慧源于了解何为大义。有时，无为也是种智慧。' WHERE `Id` = 73751 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '当你领悟真正的智慧之时。' WHERE `Id` = 73752 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '来吧！我将给你们我的祝福。' WHERE `Id` = 73753 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我的挑战，如果你们接受的话，将测试你们在遭到生命危险时的机智和手段。' WHERE `Id` = 73754 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '开始挑战吧！英雄，你要在战斗中击败黑王子。' WHERE `Id` = 73765 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你，黑王子，将被蒙上眼睛。' WHERE `Id` = 73766 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我们将会看到，失去指引的力量会有怎样的局限。' WHERE `Id` = 73767 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '开始！' WHERE `Id` = 73768 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '利用你的移动优势。别让巨龙之子靠近。' WHERE `Id` = 73770 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '注意周围的环境。' WHERE `Id` = 73771 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别让元素缠住你！' WHERE `Id` = 73772 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '停手！' WHERE `Id` = 73779 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '勇士，你要预判敌人的动作，并始终抢先一步。胜利就在你手中！' WHERE `Id` = 73780 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '很好——停手！' WHERE `Id` = 73781 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '看到了吗？缺乏指引的力量只会带来混乱和毁灭。' WHERE `Id` = 73783 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '找出真正的敌人！别被假象迷惑了！' WHERE `Id` = 73880 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '元素是不灭的！在它们复活前，利用好你的时间！' WHERE `Id` = 73881 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '年轻的王子，请记住这一课。' WHERE `Id` = 73882 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你做的很好，$n。看来部落内部已经矛盾重重了。加尔鲁什有一整支巨魔起义军要对付了。' WHERE `Id` = 73896 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '没错。这正是联盟的大好机会。我们要利用巨魔为联盟主舰队的集结打掩护。你明白我的意思吧，苏利？' WHERE `Id` = 73898 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '沃金已经没有退路了。有了我们的帮助，他就能成为破开地狱咆哮堡垒的那把“暗矛”。就让我们的敌人去自相残杀吧，我们只需在一边等待出击的机会即可。' WHERE `Id` = 73900 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '等等！放下你们的武器。我认识这个家伙。' WHERE `Id` = 73904 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '去告诉沃金，我带来了一位来自联盟的特使。' WHERE `Id` = 73905 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '跟我走，$r。' WHERE `Id` = 73906 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别让你的手离开我们的视线。最近大家都有些神经质。我们正在进行一场战争，一场与酋长本人的战争。' WHERE `Id` = 73907 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '地狱咆哮已经派人来刺杀过沃金了。呵呵，巨魔可不是那么容易杀死的。' WHERE `Id` = 73908 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你问他干了什么？他激起了整个暗矛部族的怒火。' WHERE `Id` = 73909 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '地狱咆哮本以为沃金已经死了，结果他却出现在森金村。然后酋长又试图绞杀起义军，但我们早有准备。我们已经在森金村击退了库卡隆，然后又攻占了剃刀岭。哈，就在酋长的鼻子底下打了个大胜仗！' WHERE `Id` = 73910 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '现在，我们已经将目光投向了最终的战场——奥格瑞玛。' WHERE `Id` = 73911 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '联盟想在奥格瑞玛开辟第二战线？可以。你们需要帮助，而我们需要物资：石料、木材、原油和肉食。只有这样，我们才有可能去攻打那座坚城。' WHERE `Id` = 73912 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个任务可不适合胆小鬼，陌生人。但如果你帮助我们，沃金或许会慢慢信任你们。无论如何，你们总能削弱酋长对他自己领土的控制力。软趴趴的联盟能做到这一点吗？啊哈哈哈哈！' WHERE `Id` = 73913 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '你休想用那套猫皮伪装骗过老岑塔布拉。我会记住你的，$r。' WHERE `Id` = 73966 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '联盟愿意帮助暗矛部族？我从未想过自己能活着看到这一天。' WHERE `Id` = 73968 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我要感谢你，$r。我不会忘记你所做的一切。' WHERE `Id` = 73969 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '小心背后……' WHERE `Id` = 74056 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '多么愚蠢。' WHERE `Id` = 74057 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '但愿你喜欢疼痛。' WHERE `Id` = 74058 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '哼。轻而易举。' WHERE `Id` = 74059 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '不！' WHERE `Id` = 74060 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '这个世界将在酋长的力量下燃烧！' WHERE `Id` = 74066 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '再往火里添点儿柴。' WHERE `Id` = 74067 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '别被烧焦了……' WHERE `Id` = 74068 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '唔，一股烧焦的肉味儿……' WHERE `Id` = 74069 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '尘……归尘……' WHERE `Id` = 74070 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '只要我一开口，整个海洋都将颤栗。恐惧吧，地狱咆哮之敌。' WHERE `Id` = 74071 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '我要把你冲到海里去。' WHERE `Id` = 74072 AND `Locale` = 'zhCN';
UPDATE `broadcast_text_locale` SET `Text_lang` = '水流都臣服于我！' WHERE `Id` = 74073 AND `Locale` = 'zhCN';
